struct ProfileStage {
    name: &'static str,
    start: Instant,
    enabled: bool,
}

impl ProfileStage {
    fn new(name: &'static str) -> Self {
        Self {
            name,
            start: Instant::now(),
            enabled: profile_enabled(),
        }
    }
}

impl Drop for ProfileStage {
    fn drop(&mut self) {
        if self.enabled {
            let elapsed = self.start.elapsed();
            eprintln!(
                "profile_stage: name={} elapsed_ns={} elapsed_ms={:.3}",
                self.name,
                duration_ns(elapsed),
                duration_ms(elapsed)
            );
        }
    }
}

fn profile_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| std::env::var("FONTDONE_UNIFIED_PROFILE").is_ok())
}

fn duration_ms(duration: Duration) -> f64 {
    duration.as_secs_f64() * 1000.0
}

fn duration_ns(duration: Duration) -> u128 {
    duration.as_nanos()
}

#[test]
fn unified_fixture_parity() {
    enable_rasterizer_trace_coverage();
    let _profile = ProfileStage::new("unified_fixture_parity.total");
    assert_oracle_cache_key_tracks_asset_identity();
    let input_cases = {
        let _profile = ProfileStage::new("load_global_input_cache");
        read_all_case_files()
    };
    {
        let _profile = ProfileStage::new("preload_global_fixture_caches");
        preload_global_fixture_caches(input_cases);
    }
    {
        let _profile = ProfileStage::new("assert_explicit_input_model");
        assert_unified_inputs_use_explicit_model(input_cases);
    }
    {
        let _profile = ProfileStage::new("assert_manifest_cases_cover_fixture_inputs");
        assert_manifest_cases_cover_fixture_inputs(input_cases);
    }
    {
        let _profile = ProfileStage::new(
            "assert_manifest_font_variability_cases_cover_declared_fixture_folder",
        );
        assert_manifest_font_variability_cases_cover_declared_fixture_folder(input_cases);
    }
    {
        let _profile = ProfileStage::new("report_explicit_input_cases");
        report_explicit_input_cases(input_cases);
    }
    {
        let _profile = ProfileStage::new("assert_unified_fixture_cases_match_runtime_c_oracle");
        assert_unified_fixture_cases_match_runtime_c_oracle(input_cases);
    }
}

fn assert_unified_fixture_cases_match_runtime_c_oracle(all_cases: &[InputCase]) {
    let manifest = {
        let _profile = ProfileStage::new("runtime.load_manifest_cache");
        read_manifest()
    };
    let runtime_selection = {
        let _profile = ProfileStage::new("runtime.select_runtime_cases");
        select_runtime_cases(all_cases)
    };
    assert_explicit_runtime_filter_matched(&runtime_selection);
    let pending_report = format_operation_counts(
        &runtime_selection.unsupported_operations,
        operation_counts_limit("FONTDONE_UNIFIED_PENDING_LIMIT", 12),
    );
    if selection_only_enabled() {
        eprintln!(
            "runtime_cases: runnable={} pending={} pending_reasons={}",
            runtime_selection.executable.len(),
            runtime_selection.model_only,
            pending_report
        );
        print_pending_samples(&runtime_selection);
        return;
    }
    let runtime_model_only = runtime_selection.model_only;
    let runtime_case_count = runtime_selection.executable.len();
    print_pending_samples(&runtime_selection);
    let cases = runtime_selection.executable;
    let mut passed = 0usize;
    let mut failures = Vec::new();
    let mut runtime_failures = FailureSummary::default();
    let mut backend_profile = BackendProfile::default();
    let mut face_prewarm_profile = FacePrewarmProfile::default();
    let mut slow_cases = SlowCaseSummary::default();
    let mut axis_profile = AxisProfileSummary::default();
    let mut covered = BTreeSet::new();
    let mut valid_cases = Vec::new();

    {
        let _profile = ProfileStage::new("runtime.validate_cases_and_assets");
        for case in &cases {
            if !manifest.has_case(&case.subject, &case.case) {
                failures.push(format!(
                    "{} references unknown manifest case {}::{}",
                    case.case_id, case.subject, case.case
                ));
                continue;
            }
            if case_requires_asset_validation(case)
                && let Err(err) = validate_assets(case)
            {
                failures.push(format!("{} asset validation failed: {err}", case.case_id));
                continue;
            }
            valid_cases.push(case);
        }
    }

    if failures.is_empty() {
        match compare_backend_outputs_with_oracle_cache(&valid_cases) {
            Ok(result) => {
                passed = passed.saturating_add(result.passed);
                covered.extend(result.covered);
                runtime_failures.extend(result.failures);
                backend_profile.extend(result.profile);
                face_prewarm_profile.extend(result.face_prewarm);
                slow_cases.extend(result.slow_cases);
                axis_profile.extend(result.axis_profile);
            }
            Err(err) => {
                failures.push(format!("runtime oracle comparison failed: {err}"));
            }
        }
    }

    let total_failures = failures.len().saturating_add(runtime_failures.count);
    eprintln!(
        "runtime_cases: runnable={} pending={} pending_reasons={}",
        runtime_case_count, runtime_model_only, pending_report
    );
    eprintln!(
        "runtime_parity: passed={} failed={} total={} covered_manifest_cases={} failure_buckets={}",
        passed,
        total_failures,
        cases.len(),
        covered.len(),
        format_operation_counts(
            &runtime_failures.buckets,
            operation_counts_limit("FONTDONE_UNIFIED_FAILURE_BUCKET_LIMIT", 12),
        )
    );
    if profile_enabled() {
        eprintln!(
            "profile_backend_totals: rust_ns={} c_abi_ns={} wasm_ns={} compare_ns={} rust_ms={:.3} c_abi_ms={:.3} wasm_ms={:.3} compare_ms={:.3}",
            duration_ns(backend_profile.rust_ffi),
            duration_ns(backend_profile.c_abi),
            duration_ns(backend_profile.wasm_abi),
            duration_ns(backend_profile.compare),
            duration_ms(backend_profile.rust_ffi),
            duration_ms(backend_profile.c_abi),
            duration_ms(backend_profile.wasm_abi),
            duration_ms(backend_profile.compare)
        );
        if face_prewarm_profile.cases > 0 {
            eprintln!(
                "profile_face_warmup: chunks={} cases={} opened_face_handles={} total_ns={} rust_ns={} c_abi_ns={} wasm_ns={} total_ms={:.3} rust_ms={:.3} c_abi_ms={:.3} wasm_ms={:.3}",
                face_prewarm_profile.chunks,
                face_prewarm_profile.cases,
                face_prewarm_profile.opened_face_handles,
                duration_ns(face_prewarm_profile.total),
                duration_ns(face_prewarm_profile.rust_ffi),
                duration_ns(face_prewarm_profile.c_abi),
                duration_ns(face_prewarm_profile.wasm_abi),
                duration_ms(face_prewarm_profile.total),
                duration_ms(face_prewarm_profile.rust_ffi),
                duration_ms(face_prewarm_profile.c_abi),
                duration_ms(face_prewarm_profile.wasm_abi)
            );
        }
        for sample in &slow_cases.samples {
            eprintln!(
                "profile_slow_case: case_id={} operation={} total_ns={} rust_ns={} c_abi_ns={} wasm_ns={} compare_ns={}",
                sample.case_id,
                sample.operation,
                duration_ns(sample.total),
                duration_ns(sample.rust_ffi),
                duration_ns(sample.c_abi),
                duration_ns(sample.wasm_abi),
                duration_ns(sample.compare)
            );
        }
        let mut axis_entries = axis_profile.groups.iter().collect::<Vec<_>>();
        axis_entries.sort_by(|(left_group, left_stats), (right_group, right_stats)| {
            right_stats
                .total
                .cmp(&left_stats.total)
                .then_with(|| left_group.cmp(right_group))
        });
        axis_entries.truncate(axis_profile_sample_limit());
        for (group, stats) in axis_entries {
            eprintln!(
                "profile_axis_group: group={} count={} total_ns={} avg_ns={} min_ns={} max_ns={} rust_ns={} c_abi_ns={} wasm_ns={} compare_ns={}",
                group,
                stats.count,
                duration_ns(stats.total),
                stats.avg_ns(),
                duration_ns(stats.min),
                duration_ns(stats.max),
                duration_ns(stats.rust_ffi),
                duration_ns(stats.c_abi),
                duration_ns(stats.wasm_abi),
                duration_ns(stats.compare)
            );
        }
    }
    if !failures.is_empty() || !runtime_failures.is_empty() {
        for failure in &failures {
            eprintln!("{failure}");
        }
        for failure in &runtime_failures.samples {
            eprintln!("{failure}");
        }
        if runtime_failures.count > runtime_failures.samples.len() {
            eprintln!(
                "... omitted {} additional runtime parity failures",
                runtime_failures
                    .count
                    .saturating_sub(runtime_failures.samples.len())
            );
        }
        panic!("{total_failures} unified fixture cases failed");
    }
}

fn assert_unified_inputs_use_explicit_model(cases: &[InputCase]) {
    let mut failures = Vec::new();
    for case in cases {
        if case.schema == "scalar" {
            failures.push(format!("{} uses migration schema scalar", case.case_id));
        }
        if case.schema.ends_with("_matrix") {
            failures.push(format!(
                "{} uses legacy matrix schema {}",
                case.case_id, case.schema
            ));
        }
        if case.operation.ends_with("_matrix") {
            failures.push(format!(
                "{} uses legacy matrix operation {}",
                case.case_id, case.operation
            ));
        }
        if case
            .inputs
            .params
            .as_object()
            .is_some_and(|params| params.contains_key("load_flags_matrix"))
        {
            failures.push(format!(
                "{} uses load_flags_matrix; use load_flag_sets",
                case.case_id
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "legacy fixture model entries:\n{}",
        failures.join("\n")
    );
}

struct RuntimeSelection {
    executable: Vec<InputCase>,
    model_only: usize,
    unsupported_operations: BTreeMap<String, usize>,
    pending_samples: Vec<String>,
}

fn assert_explicit_runtime_filter_matched(selection: &RuntimeSelection) {
    let case_filter = case_filter();
    let operation_filter = operation_filter();
    if case_filter.is_none() && operation_filter.is_none() {
        return;
    }

    assert!(
        !selection.executable.is_empty() || selection.model_only != 0,
        "explicit runtime filter matched no fixture cases: case_filter={case_filter:?} operation_filter={operation_filter:?}"
    );
}

fn flag_value(value: &Value, key: &str) -> Result<i32, String> {
    let raw = match value {
        Value::Array(items) => {
            let mut flags = 0i64;
            for item in items {
                flags |= i64_value(item, key)?;
            }
            flags
        }
        _ => i64_value(value, key)?,
    };
    i32::try_from(raw).map_err(|err| format!("{key} does not fit i32: {err}"))
}

fn validation_flags_param(value: &Value) -> Result<FT_UInt, String> {
    let Some(raw) = value.get("validation_flags") else {
        return Ok(0);
    };
    let flags = flag_value(raw, "validation_flags")?;
    FT_UInt::try_from(flags).map_err(|err| format!("validation_flags does not fit u32: {err}"))
}

fn build_dependent_runtime_reason(case: &InputCase) -> Option<&'static str> {
    if case.expectation.is_build_dependent()
        && case.operation == "ftsnames.get_sfnt_name"
        && lifecycle_handle_param(&case.inputs.params, "face") == Some("non_sfnt")
    {
        return Some("non-SFNT face fixture must open before FT_Get_Sfnt_Name");
    }
    None
}

fn unrouted_slot_state_runtime_reason(_case: &InputCase) -> Option<&'static str> {
    None
}

fn classify_runtime_case(case: &InputCase, operation: &str) -> RuntimeReadiness {
    if case.route_evidence == RouteEvidence::PendingRoute {
        return RuntimeReadiness::Pending {
            reason: format!(
                "{operation}:{}",
                case.route_pending_reason
                    .as_deref()
                    .unwrap_or("public route is not executable")
            ),
        };
    }
    if let Some(reason) = unrouted_slot_state_runtime_reason(case) {
        return RuntimeReadiness::Pending {
            reason: format!("{operation}:{reason}"),
        };
    }
    if let Some(reason) = build_dependent_runtime_reason(case) {
        return RuntimeReadiness::Pending {
            reason: format!("{operation}:{reason}"),
        };
    }
    if !case.expect_error
        && runtime_operation_requires_resolved_declared_asset(operation)
        && !has_no_font_assets(case)
        && !assets_are_runtime_resolved(case)
    {
        return RuntimeReadiness::Pending {
            reason: format!("{operation}:declared runtime font asset is unresolved"),
        };
    }
    if operation == "ftoutln.outline_decompose"
        && !outline_decompose_runtime_case_supported(&case.case_id)
    {
        return RuntimeReadiness::Pending {
            reason: format!(
                "{operation}:pending-core outline callback trace route not implemented"
            ),
        };
    }
    if !is_supported_runtime_operation(case, operation) {
        return RuntimeReadiness::Pending {
            reason: operation.to_string(),
        };
    }
    match oracle_args(case) {
        Ok(_) => RuntimeReadiness::Runnable,
        Err(err) => RuntimeReadiness::Pending {
            reason: format!("{operation}:{err}"),
        },
    }
}

fn select_runtime_cases(cases: &[InputCase]) -> RuntimeSelection {
    let filter = case_filter();
    let operation_filter = operation_filter();
    let limit = case_limit();
    let mut executable = Vec::new();
    let mut model_only = 0usize;
    let mut unsupported_operations: BTreeMap<String, usize> = BTreeMap::new();
    let mut pending_samples = Vec::new();
    let pending_sample_limit = pending_sample_limit();

    for case in cases {
        if !operation_matches_filter(case, operation_filter.as_deref()) {
            continue;
        }
        if !case_matches_filter(case, filter.as_deref()) {
            continue;
        }
        let operation = case.operation.clone();
        match classify_runtime_case(case, &operation) {
            RuntimeReadiness::Runnable => {
                executable.push(case.clone());
                if limit.is_some_and(|limit| executable.len() >= limit) {
                    break;
                }
            }
            RuntimeReadiness::Pending { reason } => {
                model_only = model_only.saturating_add(1);
                if pending_samples.len() < pending_sample_limit {
                    pending_samples.push(format!("{} {}", reason, case.case_id));
                }
                let count = unsupported_operations.entry(reason).or_default();
                *count = count.saturating_add(1);
            }
        }
    }

    RuntimeSelection {
        executable,
        model_only,
        unsupported_operations,
        pending_samples,
    }
}

fn is_supported_runtime_operation(_case: &InputCase, _operation: &str) -> bool {
    // Accept ALL operations. oracle_args is the sole gating mechanism.
    true
}

fn runtime_operation_requires_resolved_declared_asset(operation: &str) -> bool {
    !matches!(
        operation,
        "constant"
            | "constant_map"
            | "record_layout"
            | "abi_type_probe"
            | "abi_type_map_probe"
            | "abi_function_probe"
            | "abi.compile_alias_probe"
            | "abi.value_echo"
            | "macro_eval"
            | "macro_compile_probe"
            | "ftdriver.interpreter_version_property"
            | "ftmodapi.inspect_module_flags"
    )
}

fn first_glyph_index_arg(params: &Value) -> Result<u32, String> {
    // Accept either glyph_index (singular) or glyph_indices[0] (plural array)
    if let Ok(index) = glyph_index_param(params) {
        return Ok(index);
    }
    if let Some(indices) = params.get("glyph_indices").and_then(Value::as_array) {
        if let Some(first) = indices.first() {
            match first {
                Value::Number(n) => {
                    if let Some(val) = n.as_u64() {
                        return u32::try_from(val).map_err(|e| e.to_string());
                    }
                }
                _ => {}
            }
        }
    }
    glyph_index_param(params)
}

fn glyph_transform_setup_params(params: &Value) -> &Value {
    params.get("source_setup").unwrap_or(params)
}

fn glyph_transform_indices(params: &Value) -> Result<Vec<u32>, String> {
    let setup = glyph_transform_setup_params(params);
    let indices = if let Some(values) = setup.get("glyph_indices").and_then(Value::as_array) {
        values
            .iter()
            .enumerate()
            .map(|(index, value)| u32_value(value, &format!("source_setup.glyph_indices[{index}]")))
            .collect::<Result<Vec<_>, _>>()?
    } else if let Some(value) = setup.get("glyph_index") {
        vec![u32_value(value, "source_setup.glyph_index")?]
    } else {
        vec![glyph_index_param(setup)?]
    };
    if indices.is_empty() {
        return Err("glyph_transform requires at least one glyph index".to_string());
    }
    Ok(indices)
}

fn glyph_transform_indices_arg(params: &Value) -> Result<String, String> {
    Ok(glyph_transform_indices(params)?
        .into_iter()
        .map(|index| index.to_string())
        .collect::<Vec<_>>()
        .join(","))
}

#[derive(Debug, Clone, Copy)]
struct GlyphTransformSpec {
    matrix: Option<FT_Matrix>,
    delta: Option<FT_Vector>,
}

fn glyph_transform_specs(params: &Value) -> Result<Vec<GlyphTransformSpec>, String> {
    let values = params
        .get("transforms")
        .and_then(Value::as_array)
        .ok_or_else(|| "glyph_transform requires transforms array".to_string())?;
    if values.is_empty() {
        return Err("glyph_transform requires at least one transform".to_string());
    }
    values
        .iter()
        .enumerate()
        .map(|(index, value)| {
            let matrix = match value.get("matrix") {
                Some(Value::Null) | None => None,
                Some(matrix) => Some(FT_Matrix {
                    xx: i64_value(
                        matrix
                            .get("xx")
                            .ok_or_else(|| format!("transforms[{index}].matrix.xx is missing"))?,
                        &format!("transforms[{index}].matrix.xx"),
                    )?,
                    xy: i64_value(
                        matrix
                            .get("xy")
                            .ok_or_else(|| format!("transforms[{index}].matrix.xy is missing"))?,
                        &format!("transforms[{index}].matrix.xy"),
                    )?,
                    yx: i64_value(
                        matrix
                            .get("yx")
                            .ok_or_else(|| format!("transforms[{index}].matrix.yx is missing"))?,
                        &format!("transforms[{index}].matrix.yx"),
                    )?,
                    yy: i64_value(
                        matrix
                            .get("yy")
                            .ok_or_else(|| format!("transforms[{index}].matrix.yy is missing"))?,
                        &format!("transforms[{index}].matrix.yy"),
                    )?,
                }),
            };
            let delta = match value.get("delta") {
                Some(Value::Null) | None => None,
                Some(delta) => Some(FT_Vector {
                    x: i64_value(
                        delta
                            .get("x")
                            .ok_or_else(|| format!("transforms[{index}].delta.x is missing"))?,
                        &format!("transforms[{index}].delta.x"),
                    )?,
                    y: i64_value(
                        delta
                            .get("y")
                            .ok_or_else(|| format!("transforms[{index}].delta.y is missing"))?,
                        &format!("transforms[{index}].delta.y"),
                    )?,
                }),
            };
            Ok(GlyphTransformSpec { matrix, delta })
        })
        .collect()
}

fn glyph_transform_specs_arg(params: &Value) -> Result<String, String> {
    Ok(glyph_transform_specs(params)?
        .into_iter()
        .map(|spec| {
            let matrix = spec.matrix.map_or_else(
                || "null".to_string(),
                |matrix| format!("{},{},{},{}", matrix.xx, matrix.xy, matrix.yx, matrix.yy),
            );
            let delta = spec.delta.map_or_else(
                || "null".to_string(),
                |delta| format!("{},{}", delta.x, delta.y),
            );
            format!("{matrix}/{delta}")
        })
        .collect::<Vec<_>>()
        .join(";"))
}

fn glyph_transform_load_flags(params: &Value) -> Result<FT_Int32, String> {
    load_flags_param(glyph_transform_setup_params(params))
}

fn outline_runtime_supported(case: &InputCase) -> bool {
    if case.expect_error
        || !has_runtime_font_source(case)
        || !assets_are_runtime_resolved(case)
        || has_probe_params(case)
        || first_glyph_index_arg(&case.inputs.params).is_err()
        || load_flags_param(&case.inputs.params).is_err()
    {
        return false;
    }
    if case.operation == "ftglyph.glyph_get_cbox" {
        return bbox_modes_param(&case.inputs.params).is_ok_and(|modes| !modes.is_empty());
    }
    true
}

