fn rust_palette_case(case: &InputCase) -> Result<RunOutput, String> {
    match case.case_id.as_str() {
        "ftcolor.FT_Palette_Data_Get.success_sfnt_without_cpal"
        | "ftcolor.FT_Palette_Data_Get.success_non_sfnt_null_palette_data"
        | "ftcolor.FT_Palette_Data_Get.success_sfnt_cpal_palette_data" => {
            let face = open_face(case)?;
            let mut data = FT_Palette_Data {
                num_palettes: 999,
                palette_name_ids: ptr::dangling::<FT_UShort>(),
                palette_flags: ptr::dangling::<FT_UShort>(),
                num_palette_entries: 999,
                palette_entry_name_ids: ptr::dangling::<FT_UShort>(),
            };
            let err = FT_Palette_Data_Get(Some(&face), Some(&mut data));
            Ok(ok(palette_data_json(
                err,
                data.num_palettes,
                data.num_palette_entries,
                data.palette_name_ids,
                data.palette_flags,
                data.palette_entry_name_ids,
            )))
        }
        "ftcolor.FT_Palette_Data_Get.error_null_face_or_output" => {
            let face = open_face(case)?;
            Ok(error_with_output(
                FT_Err_Invalid_Face_Handle as FT_Error,
                rust_palette_data_null_inputs(&face),
            ))
        }
        "ftcolor.FT_Palette_Data.palette_data_get_values"
        | "ftcolor.FT_PALETTE_FOR_DARK_BACKGROUND.palette_flags_runtime"
        | "ftcolor.FT_PALETTE_FOR_LIGHT_BACKGROUND.palette_flags_runtime" => {
            let face = open_face(case)?;
            Ok(ok(rust_palette_data_values_json(FT_Palette_Data_Copy(
                Some(&face),
            ))))
        }
        "ftcolor.FT_Palette_Select.success_non_sfnt_returns_null_palette" => {
            let face = open_face(case)?;
            let mut palette = ptr::dangling::<FT_Color>();
            let err = FT_Palette_Select(Some(&face), 0, Some(&mut palette));
            Ok(ok(json!({
                "error": err,
                "apalette_nullness": if palette.is_null() { "null" } else { "non_null" }
            })))
        }
        "ftcolor.FT_Palette_Select.error_null_face_or_invalid_palette_index" => {
            let face = open_face(case)?;
            Ok(error_with_output(
                FT_Err_Invalid_Face_Handle as FT_Error,
                rust_palette_select_error_json(&face),
            ))
        }
        "ftcolor.FT_Palette_Select.success_selects_palette_and_returns_entries"
        | "ftcolor.FT_Color.palette_entries_preserve_bgra_order" => {
            let face = open_face(case)?;
            Ok(ok(rust_palette_select_runs_json(&face)))
        }
        "ftcolor.FT_Palette_Select.success_null_output_selects_without_return" => {
            let face = open_face(case)?;
            Ok(ok(rust_palette_select_null_output_json(&face)))
        }
        "ftcolor.FT_Palette_Select.success_reselect_resets_user_modifications" => {
            let face = open_face(case)?;
            Ok(ok(rust_palette_reselect_json(&face)))
        }
        "ftcolor.FT_Palette_Set_Foreground_Color.success_non_sfnt_noop" => {
            let face = open_face(case)?;
            let err = FT_Palette_Set_Foreground_Color(
                Some(&face),
                FT_Color {
                    blue: 1,
                    green: 2,
                    red: 3,
                    alpha: 4,
                },
            );
            Ok(ok(
                json!({"error": err, "followup_palette_or_render_state": "unchanged"}),
            ))
        }
        "ftcolor.FT_Palette_Set_Foreground_Color.error_null_face" => {
            Ok(error(FT_Err_Invalid_Face_Handle as FT_Error))
        }
        other => Err(format!("unsupported color palette case {other}")),
    }
}

