fn rust_malformed_maxp_row(variant: &str, bytes: &[u8], face_index: i64) -> Value {
    let library = FT_Init_FreeType();
    match FT_New_Memory_Face(&library, bytes, face_index, 20.0) {
        Ok(face) => {
            let ptr = FT_Get_Sfnt_Table(&face, FT_SFNT_MAXP as FT_Sfnt_Tag);
            let record = FT_Get_Sfnt_MaxProfile_Copy(&face);
            json!({
                "variant": variant,
                "error": FT_Err_Ok,
                "face_load_error": FT_Err_Ok,
                "pointer_null": ptr.is_null(),
                "fields_if_loaded": tt_maxprofile_record_json(record),
            })
        }
        Err(err) => json!({
            "variant": variant,
            "error": err,
            "face_load_error": err,
            "pointer_null": true,
            "fields_if_loaded": Value::Null,
        }),
    }
}

fn rust_malformed_maxp_route(case: &InputCase) -> Result<RunOutput, String> {
    let face_index = face_index_param(&case.inputs.params)?;
    let truncated = required_asset_bytes(case, "truncated_maxp")?;
    let invalid = required_asset_bytes(case, "invalid_maxp")?;
    Ok(ok(json!({
        "rows": [
            rust_malformed_maxp_row("truncated_maxp", truncated.as_ref(), face_index),
            rust_malformed_maxp_row("invalid_maxp", invalid.as_ref(), face_index),
        ]
    })))
}

fn c_malformed_maxp_row(variant: &str, bytes: &[u8], face_index: i64) -> Result<Value, String> {
    let mut library = ptr::null_mut();
    let init_error = c_abi::FT_Init_FreeType(&mut library);
    let mut face = ptr::null_mut();
    let mut face_error = init_error;
    if face_error == FT_Err_Ok {
        let file_size = i64::try_from(bytes.len()).map_err(|err| err.to_string())?;
        face_error =
            c_abi::FT_New_Memory_Face(library, bytes.as_ptr(), file_size, face_index, &mut face);
    }
    let record = if face_error == FT_Err_Ok {
        c_abi::abi_sfnt_maxp(face)
    } else {
        None
    };
    if !face.is_null() {
        c_done_face(face);
    }
    if !library.is_null() {
        c_done_library(library);
    }
    Ok(json!({
        "variant": variant,
        "error": face_error,
        "face_load_error": face_error,
        "pointer_null": record.is_none(),
        "fields_if_loaded": c_tt_maxprofile_record_json(record),
    }))
}

fn c_malformed_maxp_route(case: &InputCase) -> Result<RunOutput, String> {
    let face_index = face_index_param(&case.inputs.params)?;
    let truncated = required_asset_bytes(case, "truncated_maxp")?;
    let invalid = required_asset_bytes(case, "invalid_maxp")?;
    Ok(ok(json!({
        "rows": [
            c_malformed_maxp_row("truncated_maxp", truncated.as_ref(), face_index)?,
            c_malformed_maxp_row("invalid_maxp", invalid.as_ref(), face_index)?,
        ]
    })))
}

fn wasm_malformed_maxp_row(variant: &str, bytes: &[u8], face_index: i64) -> Value {
    let status = wasm_abi::fontdone_wasm_open_face(bytes.as_ptr(), bytes.len(), face_index, 20.0);
    if status.error != FT_Err_Ok {
        return json!({
            "variant": variant,
            "error": status.error,
            "face_load_error": status.error,
            "pointer_null": true,
            "fields_if_loaded": Value::Null,
        });
    }
    let mut record = wasm_abi::FontdoneWasmMaxProfile::default();
    let table_status = wasm_abi::fontdone_wasm_get_sfnt_maxp(
        status.handle,
        FT_SFNT_MAXP as wasm_abi::FT_Sfnt_Tag,
        &mut record,
    );
    wasm_done_face(status.handle);
    json!({
        "variant": variant,
        "error": FT_Err_Ok,
        "face_load_error": FT_Err_Ok,
        "pointer_null": table_status != FT_Err_Ok,
        "fields_if_loaded": if table_status == FT_Err_Ok {
            wasm_tt_maxprofile_record_json(record)
        } else {
            Value::Null
        },
    })
}

fn wasm_malformed_maxp_route(case: &InputCase) -> Result<RunOutput, String> {
    let face_index = face_index_param(&case.inputs.params)?;
    let truncated = required_asset_bytes(case, "truncated_maxp")?;
    let invalid = required_asset_bytes(case, "invalid_maxp")?;
    Ok(ok(json!({
        "rows": [
            wasm_malformed_maxp_row("truncated_maxp", truncated.as_ref(), face_index),
            wasm_malformed_maxp_row("invalid_maxp", invalid.as_ref(), face_index),
        ]
    })))
}

fn rust_sfnt_table_info_output(face: &FT_Face, params: &Value) -> Result<RunOutput, String> {
    let tag_ptr_state = sfnt_table_info_tag_ptr_arg(params)?;
    let length_ptr_state = sfnt_table_info_length_ptr_arg(params)?;
    let index = sfnt_table_info_index_arg(params)?
        .parse::<u32>()
        .map_err(|e| e.to_string())?;
    let mut tag_after: FT_ULong = 0;
    let mut length_after: FT_ULong = 0;
    let tag_ptr = if tag_ptr_state == "non_null" {
        Some(&mut tag_after)
    } else {
        None
    };
    let length_ptr = if length_ptr_state == "non_null" {
        Some(&mut length_after)
    } else {
        None
    };
    let err = FT_Sfnt_Table_Info(face, index as FT_UInt, tag_ptr, length_ptr);
    sfnt_table_info_result(err, tag_after, length_after)
}

fn c_sfnt_table_info_output(face: c_abi::FT_Face, params: &Value) -> Result<RunOutput, String> {
    let tag_ptr_state = sfnt_table_info_tag_ptr_arg(params)?;
    let length_ptr_state = sfnt_table_info_length_ptr_arg(params)?;
    let index = sfnt_table_info_index_arg(params)?
        .parse::<u32>()
        .map_err(|e| e.to_string())?;
    let mut tag_after: c_abi::FT_ULong = 0;
    let mut length_after: c_abi::FT_ULong = 0;
    let tag_ptr = if tag_ptr_state == "non_null" {
        (&mut tag_after) as *mut c_abi::FT_ULong
    } else {
        ptr::null_mut()
    };
    let length_ptr = if length_ptr_state == "non_null" {
        (&mut length_after) as *mut c_abi::FT_ULong
    } else {
        ptr::null_mut()
    };
    let err = c_abi::FT_Sfnt_Table_Info(face, index as c_abi::FT_UInt, tag_ptr, length_ptr);
    sfnt_table_info_result(err, tag_after, length_after)
}

fn wasm_sfnt_table_info_output(handle: usize, params: &Value) -> Result<RunOutput, String> {
    let tag_ptr_state = sfnt_table_info_tag_ptr_arg(params)?;
    let length_ptr_state = sfnt_table_info_length_ptr_arg(params)?;
    let index = sfnt_table_info_index_arg(params)?
        .parse::<u32>()
        .map_err(|e| e.to_string())?;
    let mut tag_after: wasm_abi::FT_ULong = 0;
    let mut length_after: wasm_abi::FT_ULong = 0;
    let tag_ptr = if tag_ptr_state == "non_null" {
        (&mut tag_after) as *mut wasm_abi::FT_ULong
    } else {
        ptr::null_mut()
    };
    let length_ptr = if length_ptr_state == "non_null" {
        (&mut length_after) as *mut wasm_abi::FT_ULong
    } else {
        ptr::null_mut()
    };
    let err = wasm_abi::fontdone_wasm_sfnt_table_info(
        handle,
        index as wasm_abi::FT_UInt,
        tag_ptr,
        length_ptr,
    );
    sfnt_table_info_result(err, tag_after, length_after)
}

fn sfnt_table_info_result(
    err: FT_Error,
    tag_after: FT_ULong,
    length_after: FT_ULong,
) -> Result<RunOutput, String> {
    let output = json!({
        "tag_after": tag_after,
        "length_after": length_after
    });
    if err == FT_Err_Ok {
        Ok(ok(output))
    } else {
        Ok(error_with_output(err, output))
    }
}

fn rust_sfnt_os2_unicode_ranges_output(face: &FT_Face, params: &Value) -> Result<Value, String> {
    let glyph_indices = representative_codepoints(params)?
        .into_iter()
        .map(|codepoint| FT_Get_Char_Index(face, codepoint))
        .collect();
    match rust_os2_unicode_ranges(face) {
        Some((range1, range2, range3, range4)) => Ok(os2_unicode_ranges_json(
            true,
            range1,
            range2,
            range3,
            range4,
            glyph_indices,
        )),
        None => Ok(os2_unicode_ranges_json(false, 0, 0, 0, 0, glyph_indices)),
    }
}

fn rust_os2_unicode_ranges(face: &FT_Face) -> Option<(u64, u64, u64, u64)> {
    let mut length = 16;
    let bytes = FT_Load_Sfnt_Table(face, 0x4F53_2F32, 42, Some(&mut length))
        .ok()
        .flatten()?;
    if bytes.len() < 16 {
        return None;
    }
    Some((
        u64::from(u32::from_be_bytes(bytes[0..4].try_into().ok()?)),
        u64::from(u32::from_be_bytes(bytes[4..8].try_into().ok()?)),
        u64::from(u32::from_be_bytes(bytes[8..12].try_into().ok()?)),
        u64::from(u32::from_be_bytes(bytes[12..16].try_into().ok()?)),
    ))
}

fn c_sfnt_os2_unicode_ranges_output(face: c_abi::FT_Face, params: &Value) -> Result<Value, String> {
    let glyph_indices = representative_codepoints(params)?
        .into_iter()
        .map(|codepoint| c_abi::FT_Get_Char_Index(face, codepoint))
        .collect();
    match c_abi::abi_sfnt_os2(face) {
        Some(os2) => Ok(os2_unicode_ranges_json(
            true,
            os2.ulUnicodeRange1 as u64,
            os2.ulUnicodeRange2 as u64,
            os2.ulUnicodeRange3 as u64,
            os2.ulUnicodeRange4 as u64,
            glyph_indices,
        )),
        None => Ok(os2_unicode_ranges_json(false, 0, 0, 0, 0, glyph_indices)),
    }
}

fn wasm_sfnt_os2_unicode_ranges_output(handle: usize, params: &Value) -> Result<Value, String> {
    let glyph_indices = representative_codepoints(params)?
        .into_iter()
        .map(|codepoint| wasm_abi::fontdone_wasm_get_char_index(handle, codepoint))
        .collect();
    let mut os2 = wasm_abi::FontdoneWasmOs2::default();
    let error = wasm_abi::fontdone_wasm_get_sfnt_os2(
        handle,
        FT_SFNT_OS2 as wasm_abi::FT_Sfnt_Tag,
        &mut os2,
    );
    if error != FT_Err_Ok {
        return Ok(os2_unicode_ranges_json(false, 0, 0, 0, 0, glyph_indices));
    }
    Ok(os2_unicode_ranges_json(
        true,
        os2.ulUnicodeRange1,
        os2.ulUnicodeRange2,
        os2.ulUnicodeRange3,
        os2.ulUnicodeRange4,
        glyph_indices,
    ))
}

