fn ftmm_apply_rust_blend_prior(face: &mut FT_Face, prior: &FtmmPriorCall) -> FT_Error {
    match prior.kind.as_str() {
        "set_var_blend" => {
            FT_Set_Var_Blend_Coordinates(Some(face), prior.count, Some(&prior.coords))
        }
        "set_mm_blend" => FT_Set_MM_Blend_Coordinates(Some(face), prior.count, Some(&prior.coords)),
        _ => FT_Err_Ok,
    }
}

fn rust_ftmm_blend_coordinates(case: &InputCase, mode: &str) -> Result<RunOutput, String> {
    let bytes = ftmm_blend_font_bytes(case)?;
    let mut face =
        rust_new_face_from_bytes(bytes.as_ref(), face_index_param(&case.inputs.params)?)?;
    let params = &case.inputs.params;
    let prior = ftmm_prior_call(params)?;
    let set_coords = ftmm_optional_coords_from_params(params)?;
    let output_count = ftmm_axis_count_hint(case, params, &prior, &set_coords)?;
    let mut status = ftmm_apply_rust_blend_prior(&mut face, &prior);
    if status == FT_Err_Ok {
        let set_count = ftmm_num_coords(params).unwrap_or(0);
        status = match mode {
            "set-var" => FT_Set_Var_Blend_Coordinates(
                Some(&mut face),
                set_count,
                if ftmm_coords_pointer_is_null(params) {
                    None
                } else {
                    Some(&set_coords)
                },
            ),
            "set-mm" => FT_Set_MM_Blend_Coordinates(
                Some(&mut face),
                set_count,
                if ftmm_coords_pointer_is_null(params) {
                    None
                } else {
                    Some(&set_coords)
                },
            ),
            _ => FT_Err_Ok,
        };
    }
    let mut coords = vec![0; usize::try_from(output_count).unwrap_or(0)];
    if status == FT_Err_Ok {
        status = match mode {
            "get-mm" => FT_Get_MM_Blend_Coordinates(
                Some(&face),
                output_count,
                if ftmm_coords_pointer_is_null(params) {
                    None
                } else {
                    Some(&mut coords)
                },
            ),
            _ => FT_Get_Var_Blend_Coordinates(
                Some(&face),
                output_count,
                if ftmm_coords_pointer_is_null(params) {
                    None
                } else {
                    Some(&mut coords)
                },
            ),
        };
    }
    Ok(ftmm_blend_output(status, &coords, face.face_flags))
}

fn rust_ftmm_set_var_blend_glyph_output(case: &InputCase) -> Result<RunOutput, String> {
    let mut face = open_face_with_size(case, pixel_size_param(&case.inputs.params)?)?;
    let params = &case.inputs.params;
    let set_coords = ftmm_optional_coords_from_params(params)?;
    let set_err = FT_Set_Var_Blend_Coordinates(
        Some(&mut face),
        ftmm_num_coords(params)?,
        if ftmm_coords_pointer_is_null(params) {
            None
        } else {
            Some(&set_coords)
        },
    );
    if set_err != FT_Err_Ok {
        return Ok(error(set_err));
    }
    let slot = match FT_Load_Glyph(&face, glyph_index_param(params)?, load_flags_param(params)?) {
        Ok(slot) => slot,
        Err(err) => return Ok(error(err)),
    };
    match FT_Render_Glyph(slot, render_mode_param(params)?) {
        Ok(slot) => Ok(ok(slot_json(&slot))),
        Err(err) => Ok(error(err)),
    }
}

fn ftmm_apply_c_blend_prior(face: c_abi::FT_Face, prior: &FtmmPriorCall) -> FT_Error {
    match prior.kind.as_str() {
        "set_var_blend" => {
            c_abi::FT_Set_Var_Blend_Coordinates(face, prior.count, prior.coords.as_ptr())
        }
        "set_mm_blend" => {
            c_abi::FT_Set_MM_Blend_Coordinates(face, prior.count, prior.coords.as_ptr())
        }
        _ => FT_Err_Ok,
    }
}

fn c_ftmm_blend_coordinates(case: &InputCase, mode: &str) -> Result<RunOutput, String> {
    let bytes = ftmm_blend_font_bytes(case)?;
    let (library, face) =
        c_new_face_from_bytes(bytes.as_ref(), face_index_param(&case.inputs.params)?)?;
    let params = &case.inputs.params;
    let prior = ftmm_prior_call(params)?;
    let set_coords = ftmm_optional_coords_from_params(params)?;
    let output_count = ftmm_axis_count_hint(case, params, &prior, &set_coords)?;
    let mut status = ftmm_apply_c_blend_prior(face, &prior);
    if status == FT_Err_Ok {
        let set_count = ftmm_num_coords(params).unwrap_or(0);
        let coords_ptr = if ftmm_coords_pointer_is_null(params) {
            std::ptr::null()
        } else {
            set_coords.as_ptr()
        };
        status = match mode {
            "set-var" => c_abi::FT_Set_Var_Blend_Coordinates(face, set_count, coords_ptr),
            "set-mm" => c_abi::FT_Set_MM_Blend_Coordinates(face, set_count, coords_ptr),
            _ => FT_Err_Ok,
        };
    }
    let mut coords = vec![0; usize::try_from(output_count).unwrap_or(0)];
    if status == FT_Err_Ok {
        status = match mode {
            "get-mm" => c_abi::FT_Get_MM_Blend_Coordinates(
                face,
                output_count,
                if ftmm_coords_pointer_is_null(params) {
                    std::ptr::null_mut()
                } else {
                    coords.as_mut_ptr()
                },
            ),
            _ => c_abi::FT_Get_Var_Blend_Coordinates(
                face,
                output_count,
                if ftmm_coords_pointer_is_null(params) {
                    std::ptr::null_mut()
                } else {
                    coords.as_mut_ptr()
                },
            ),
        };
    }
    let face_flags = c_abi::abi_face_info(face)
        .ok_or_else(|| "missing C ABI face info".to_string())?
        .face_flags;
    c_done_face(face);
    c_done_library(library);
    Ok(ftmm_blend_output(status, &coords, face_flags))
}

fn c_ftmm_set_var_blend_glyph_output(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_open_face_with_size(case, pixel_size_param(&case.inputs.params)?)?;
    let params = &case.inputs.params;
    let set_coords = ftmm_optional_coords_from_params(params)?;
    let coords_ptr = if ftmm_coords_pointer_is_null(params) {
        std::ptr::null()
    } else {
        set_coords.as_ptr()
    };
    let set_err = c_abi::FT_Set_Var_Blend_Coordinates(face, ftmm_num_coords(params)?, coords_ptr);
    let output = if set_err != FT_Err_Ok {
        Ok(error(set_err))
    } else {
        let load_err =
            c_abi::FT_Load_Glyph(face, glyph_index_param(params)?, load_flags_param(params)?);
        if load_err != FT_Err_Ok {
            Ok(error(load_err))
        } else {
            let render_err = c_abi::abi_render_glyph_from_face(face, render_mode_param(params)?);
            if render_err != FT_Err_Ok {
                Ok(error(render_err))
            } else {
                c_slot_json(face).map(ok)
            }
        }
    };
    c_done_face(face);
    c_done_library(library);
    output
}

