fn sfnt_lang_tag_output_kind(params: &Value) -> &'static str {
    if lifecycle_handle_param(params, "output") == Some("null") {
        "null"
    } else {
        "valid"
    }
}

fn sfnt_lang_tag_token_arg(params: &Value) -> Result<String, String> {
    let value = params
        .get("langID")
        .ok_or_else(|| "missing langID".to_string())?;
    sfnt_lang_tag_token(value)
}

fn sfnt_lang_tag_token(value: &Value) -> Result<String, String> {
    if let Some(number) = value.as_u64() {
        return Ok(number.to_string());
    }
    let text = value
        .as_str()
        .ok_or_else(|| "langID must be integer or string".to_string())?;
    Ok(text.to_string())
}

fn sfnt_lang_tag_variants_arg(params: &Value) -> Result<String, String> {
    let variants = params
        .get("variants")
        .and_then(Value::as_array)
        .ok_or_else(|| "missing variants".to_string())?;
    variants
        .iter()
        .map(|variant| {
            let face = variant
                .get("face")
                .and_then(Value::as_str)
                .unwrap_or("valid");
            let output = variant
                .get("output")
                .and_then(Value::as_str)
                .unwrap_or("valid_pointer");
            let output = if output == "null" { "null" } else { "valid" };
            let lang = sfnt_lang_tag_token(
                variant
                    .get("langID")
                    .ok_or_else(|| "variant missing langID".to_string())?,
            )?;
            Ok(format!("{face}:{lang}:{output}"))
        })
        .collect::<Result<Vec<_>, String>>()
        .map(|rows| rows.join(";"))
}

fn parse_sfnt_lang_tag_numeric(text: &str) -> Result<u32, String> {
    if let Some(hex) = text.strip_prefix("0x") {
        u32::from_str_radix(hex, 16).map_err(|err| err.to_string())
    } else {
        text.parse::<u32>().map_err(|err| err.to_string())
    }
}

fn sfnt_lang_tag_json(tag: &FT_SfntLangTag) -> Value {
    let bytes = c_abi::abi_byte_slice(tag.string.cast_const(), tag.string_len);
    let nullness = if tag.string.is_null() {
        "null"
    } else {
        "non_null"
    };
    json!({
        "return": FT_Err_Ok,
        "string_nullness": nullness,
        "string_len": tag.string_len,
        "string_bytes": hex_bytes(&bytes),
        "record": {
            "string_nullness": nullness,
            "string_len": tag.string_len,
            "string_bytes": hex_bytes(&bytes)
        }
    })
}

fn rust_sfnt_lang_tag_single(
    face: Option<&FT_Face>,
    token: &str,
    output_kind: &str,
) -> Result<(FT_Error, Option<Value>), String> {
    let lang_id = parse_sfnt_lang_tag_numeric(token)?;
    let output_is_null = output_kind == "null";
    let mut tag = FT_SfntLangTag::default();
    let err = if output_is_null {
        FT_Get_Sfnt_LangTag(face, lang_id, None)
    } else {
        FT_Get_Sfnt_LangTag(face, lang_id, Some(&mut tag))
    };
    let output = (err == FT_Err_Ok).then(|| sfnt_lang_tag_json(&tag));
    Ok((err, output))
}

fn rust_sfnt_lang_tag_variants(face: &FT_Face, params: &Value) -> Result<RunOutput, String> {
    let variants = params
        .get("variants")
        .and_then(Value::as_array)
        .ok_or_else(|| "missing variants".to_string())?;
    let mut status_sequence = Vec::with_capacity(variants.len());
    let mut error_sequence = Vec::with_capacity(variants.len());
    let mut first_error = FT_Err_Ok;
    for variant in variants {
        let face_kind = variant
            .get("face")
            .and_then(Value::as_str)
            .unwrap_or("valid");
        let face_arg = if face_kind == "null" {
            None
        } else {
            Some(face)
        };
        let output = variant
            .get("output")
            .and_then(Value::as_str)
            .unwrap_or("valid_pointer");
        let output_kind = if output == "null" { "null" } else { "valid" };
        let token = sfnt_lang_tag_token(
            variant
                .get("langID")
                .ok_or_else(|| "variant missing langID".to_string())?,
        )?;
        let (err, _) = rust_sfnt_lang_tag_single(face_arg, &token, output_kind)?;
        status_sequence.push(if err == FT_Err_Ok { "ok" } else { "error" });
        error_sequence.push(err);
        if first_error == FT_Err_Ok && err != FT_Err_Ok {
            first_error = err;
        }
    }
    let output = json!({
        "status_sequence": status_sequence,
        "error_sequence": error_sequence
    });
    if first_error == FT_Err_Ok {
        Ok(ok(output))
    } else {
        Ok(error_with_output(first_error, output))
    }
}

fn rust_sfnt_lang_tag(case: &InputCase) -> Result<RunOutput, String> {
    let face = open_face(case)?;
    if case.inputs.params.get("variants").is_some() {
        return rust_sfnt_lang_tag_variants(&face, &case.inputs.params);
    }
    let token = sfnt_lang_tag_token_arg(&case.inputs.params)?;
    let (err, output) = rust_sfnt_lang_tag_single(
        Some(&face),
        &token,
        sfnt_lang_tag_output_kind(&case.inputs.params),
    )?;
    if err == FT_Err_Ok {
        Ok(ok(output.unwrap_or_else(|| json!({"return": FT_Err_Ok}))))
    } else {
        Ok(error(err))
    }
}

fn rust_sfnt_name_match_output(face: &FT_Face, params: &Value) -> Result<Value, String> {
    let fields = sfnt_name_match_fields(params)?;
    let count = FT_Get_Sfnt_Name_Count(Some(face));
    let mut matches = Vec::new();
    for index in 0..count {
        let mut name = FT_SfntName::default();
        let error = FT_Get_Sfnt_Name(Some(face), index, Some(&mut name));
        if error == FT_Err_Ok
            && sfnt_name_matches(
                fields,
                name.platform_id,
                name.encoding_id,
                name.language_id,
                name.name_id,
            )
        {
            matches.push(rust_sfnt_name_record_json(index, &name));
        }
    }
    Ok(sfnt_name_match_json(count, matches))
}

fn c_sfnt_name_match_output(face: c_abi::FT_Face, params: &Value) -> Result<Value, String> {
    let fields = sfnt_name_match_fields(params)?;
    let count = c_abi::FT_Get_Sfnt_Name_Count(face);
    let mut matches = Vec::new();
    for index in 0..count {
        let mut name = c_abi::FT_SfntName::default();
        let error = c_abi::FT_Get_Sfnt_Name(face, index, &mut name);
        if error == FT_Err_Ok
            && sfnt_name_matches(
                fields,
                name.platform_id,
                name.encoding_id,
                name.language_id,
                name.name_id,
            )
        {
            matches.push(c_sfnt_name_record_json(index, &name));
        }
    }
    Ok(sfnt_name_match_json(count, matches))
}

fn wasm_sfnt_name_match_output(handle: usize, params: &Value) -> Result<Value, String> {
    let fields = sfnt_name_match_fields(params)?;
    let count = wasm_abi::fontdone_wasm_get_sfnt_name_count(handle);
    let mut matches = Vec::new();
    for index in 0..count {
        let mut name = wasm_abi::FontdoneWasmSfntName::default();
        let error = wasm_abi::fontdone_wasm_get_sfnt_name(handle, index, &mut name);
        if error == FT_Err_Ok
            && sfnt_name_matches(
                fields,
                name.platform_id,
                name.encoding_id,
                name.language_id,
                name.name_id,
            )
        {
            matches.push(wasm_sfnt_name_record_json(index, &name));
        }
    }
    Ok(sfnt_name_match_json(count, matches))
}

fn sfnt_name_match_json(count: u32, matches: Vec<Value>) -> Value {
    let status = if matches.is_empty() {
        FT_Err_Invalid_Argument
    } else {
        FT_Err_Ok
    };
    let matched_name = matches.first().cloned().unwrap_or(Value::Null);
    json!({
        "name_count": count,
        "matches": matches,
        "status": status,
        "matched_name": matched_name
    })
}

fn sfnt_mac_encoding_record_json(
    status: i32,
    matched_charmap: Value,
    glyph_indices: Vec<u32>,
    matched_name: Value,
) -> Value {
    json!({
        "status": status,
        "matched_charmap": matched_charmap,
        "glyph_indices": glyph_indices,
        "matched_name": matched_name,
    })
}

fn rust_sfnt_mac_encoding_record_output(
    face: &mut FT_Face,
    params: &Value,
) -> Result<Value, String> {
    let fields = required_sfnt_mac_fields(params)?;
    let charmap_index = rust_find_charmap_index(face, fields.platform_id, fields.encoding_id);
    let (status, matched_charmap) = if let Some(index) = charmap_index {
        let charmap = rust_face_charmap(face, index);
        let status = FT_Set_Charmap(Some(face), charmap);
        let info = rust_face_charmap_info(face, index)
            .ok_or_else(|| format!("missing rust charmap info at index {index}"))?;
        (status, rust_charmap_json(index, info))
    } else {
        (FT_Err_Invalid_Argument, Value::Null)
    };
    let glyph_indices = representative_codepoints(params)?
        .into_iter()
        .map(|codepoint| {
            if status == FT_Err_Ok {
                FT_Get_Char_Index(face, codepoint)
            } else {
                0
            }
        })
        .collect();
    let matched_name = rust_sfnt_name_match_output(face, params)?
        .get("matched_name")
        .cloned()
        .unwrap_or(Value::Null);
    Ok(sfnt_mac_encoding_record_json(
        status,
        matched_charmap,
        glyph_indices,
        matched_name,
    ))
}

fn c_sfnt_mac_encoding_record_output(
    face: c_abi::FT_Face,
    params: &Value,
) -> Result<Value, String> {
    let fields = required_sfnt_mac_fields(params)?;
    let charmap_index = c_find_charmap_index(face, fields.platform_id, fields.encoding_id);
    let (status, matched_charmap) = if let Some(index) = charmap_index {
        let charmap = c_abi::abi_charmap_by_index(face, index)
            .ok_or_else(|| format!("missing c charmap pointer at index {index}"))?;
        let status = c_abi::FT_Set_Charmap(face, charmap);
        let info = c_abi::abi_charmap_info_by_index(face, index)
            .ok_or_else(|| format!("missing c charmap info at index {index}"))?;
        (status, c_charmap_json(index, info))
    } else {
        (FT_Err_Invalid_Argument, Value::Null)
    };
    let glyph_indices = representative_codepoints(params)?
        .into_iter()
        .map(|codepoint| {
            if status == FT_Err_Ok {
                c_abi::FT_Get_Char_Index(face, codepoint)
            } else {
                0
            }
        })
        .collect();
    let matched_name = c_sfnt_name_match_output(face, params)?
        .get("matched_name")
        .cloned()
        .unwrap_or(Value::Null);
    Ok(sfnt_mac_encoding_record_json(
        status,
        matched_charmap,
        glyph_indices,
        matched_name,
    ))
}

fn wasm_sfnt_mac_encoding_record_output(handle: usize, params: &Value) -> Result<Value, String> {
    let fields = required_sfnt_mac_fields(params)?;
    let charmap_index = wasm_find_charmap_index(handle, fields.platform_id, fields.encoding_id);
    let (status, matched_charmap) = if let Some(index) = charmap_index {
        let status = wasm_abi::fontdone_wasm_set_charmap(handle, index);
        let mut info = wasm_abi::FontdoneWasmCharmap::default();
        let info_error = wasm_abi::fontdone_wasm_get_charmap(handle, index, &mut info);
        if info_error != FT_Err_Ok {
            return Ok(sfnt_mac_encoding_record_json(
                info_error,
                Value::Null,
                Vec::new(),
                Value::Null,
            ));
        }
        (status, wasm_charmap_json(&info))
    } else {
        (FT_Err_Invalid_Argument, Value::Null)
    };
    let glyph_indices = representative_codepoints(params)?
        .into_iter()
        .map(|codepoint| {
            if status == FT_Err_Ok {
                wasm_abi::fontdone_wasm_get_char_index(handle, codepoint)
            } else {
                0
            }
        })
        .collect();
    let matched_name = wasm_sfnt_name_match_output(handle, params)?
        .get("matched_name")
        .cloned()
        .unwrap_or(Value::Null);
    Ok(sfnt_mac_encoding_record_json(
        status,
        matched_charmap,
        glyph_indices,
        matched_name,
    ))
}

