fn rust_library_version_output(params: &Value) -> Result<Value, String> {
    let library = if library_present_arg(params)? != 0 {
        Some(FT_Init_FreeType())
    } else {
        None
    };
    library_version_output(params, |mask, major, minor, patch| {
        FT_Library_Version(
            library.as_ref(),
            if mask & LIBRARY_VERSION_MAJOR != 0 {
                Some(major)
            } else {
                None
            },
            if mask & LIBRARY_VERSION_MINOR != 0 {
                Some(minor)
            } else {
                None
            },
            if mask & LIBRARY_VERSION_PATCH != 0 {
                Some(patch)
            } else {
                None
            },
        );
    })
}

fn c_library_version_output(params: &Value) -> Result<Value, String> {
    let mut library = std::ptr::null_mut();
    let live = library_present_arg(params)? != 0;
    if live {
        let err = c_abi::FT_Init_FreeType(&mut library);
        if err != FT_Err_Ok {
            return Err(format!("FT_Init_FreeType returned {err}"));
        }
    }
    let output = library_version_output(params, |mask, major, minor, patch| {
        c_abi::FT_Library_Version(
            library,
            if mask & LIBRARY_VERSION_MAJOR != 0 {
                major
            } else {
                std::ptr::null_mut()
            },
            if mask & LIBRARY_VERSION_MINOR != 0 {
                minor
            } else {
                std::ptr::null_mut()
            },
            if mask & LIBRARY_VERSION_PATCH != 0 {
                patch
            } else {
                std::ptr::null_mut()
            },
        );
    });
    if live {
        c_done_library(library);
    }
    output
}

fn wasm_library_version_output(params: &Value) -> Result<Value, String> {
    let live = library_present_arg(params)?;
    library_version_output(params, |mask, major, minor, patch| {
        wasm_abi::fontdone_wasm_library_version(
            live,
            if mask & LIBRARY_VERSION_MAJOR != 0 {
                major
            } else {
                std::ptr::null_mut()
            },
            if mask & LIBRARY_VERSION_MINOR != 0 {
                minor
            } else {
                std::ptr::null_mut()
            },
            if mask & LIBRARY_VERSION_PATCH != 0 {
                patch
            } else {
                std::ptr::null_mut()
            },
        );
    })
}

fn rust_init_free_type(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "alibrary") == Some("null") {
        return Ok(error(FT_Err_Invalid_Face_Handle as FT_Error));
    }
    let _library = FT_Init_FreeType();
    Ok(ok(init_free_type_output(
        case,
        || Some(1),
        || rust_init_free_type_version_and_load(case),
    )?))
}

fn c_init_free_type(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "alibrary") == Some("null") {
        return Ok(error(c_abi::FT_Init_FreeType(std::ptr::null_mut())));
    }
    let mut library = std::ptr::null_mut();
    let err = c_abi::FT_Init_FreeType(&mut library);
    if err != FT_Err_Ok {
        return Ok(error(err));
    }
    let output = init_free_type_output(
        case,
        || Some(library.addr() as u64),
        || c_init_free_type_version_and_load(case),
    )?;
    c_done_library(library);
    Ok(ok(output))
}

fn wasm_init_free_type(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "alibrary") == Some("null") {
        return Ok(error(FT_Err_Invalid_Face_Handle as FT_Error));
    }
    let output = init_free_type_output(
        case,
        || {
            #[cfg(feature = "abi-test-support")]
            {
                return Some(u64::from(
                    wasm_abi::abi_support_init_free_type_created_library(),
                ));
            }
            #[allow(unreachable_code)]
            None
        },
        || wasm_init_free_type_version_and_load(case),
    )?;
    Ok(ok(output))
}

fn init_free_type_output<F, G>(
    case: &InputCase,
    library_identity: F,
    version_and_load: G,
) -> Result<Value, String>
where
    F: FnOnce() -> Option<u64>,
    G: FnOnce() -> Result<Value, String>,
{
    match case.case.as_str() {
        "creates_library_handle" => {
            let identity = library_identity();
            Ok(json!({
                "library": {
                    "nullness": if identity.unwrap_or(0) != 0 { "non_null" } else { "null" },
                    "identity_class": "fresh"
                }
            }))
        }
        "created_library_reports_version_and_modules" => version_and_load(),
        other => Err(format!("unsupported init_free_type case {other}")),
    }
}

fn rust_init_free_type_version_and_load(case: &InputCase) -> Result<Value, String> {
    Ok(json!({
        "version": init_free_type_version_from_rows(rust_library_version_output(&json!({
            "library": "new_from_FT_Init_FreeType",
            "outputs": ["amajor", "aminor", "apatch"]
        }))?)?,
        "face_load_probe": rust_init_free_type_face_load_probe(case)?
    }))
}

fn c_init_free_type_version_and_load(case: &InputCase) -> Result<Value, String> {
    Ok(json!({
        "version": init_free_type_version_from_rows(c_library_version_output(&json!({
            "library": "new_from_FT_Init_FreeType",
            "outputs": ["amajor", "aminor", "apatch"]
        }))?)?,
        "face_load_probe": c_init_free_type_face_load_probe(case)?
    }))
}

fn wasm_init_free_type_version_and_load(case: &InputCase) -> Result<Value, String> {
    Ok(json!({
        "version": init_free_type_version_from_rows(wasm_library_version_output(&json!({
            "library": "new_from_FT_Init_FreeType",
            "outputs": ["amajor", "aminor", "apatch"]
        }))?)?,
        "face_load_probe": wasm_init_free_type_face_load_probe(case)?
    }))
}

fn init_free_type_version_from_rows(version: Value) -> Result<Value, String> {
    version
        .get("rows")
        .and_then(Value::as_array)
        .and_then(|rows| rows.first())
        .and_then(|row| row.get("writes"))
        .cloned()
        .ok_or_else(|| "library version output missing writes".to_string())
}

fn rust_init_free_type_face_load_probe(case: &InputCase) -> Result<Value, String> {
    let data = font_bytes(case)?;
    let library = FT_Init_FreeType();
    match FT_New_Memory_Face(
        &library,
        data.as_ref(),
        face_index_param(&case.inputs.params)?,
        20.0,
    ) {
        Ok(face) => {
            let load_glyph_error = match FT_Load_Glyph(&face, 0, FT_LOAD_DEFAULT) {
                Ok(_) => FT_Err_Ok,
                Err(err) => err,
            };
            Ok(json!({
                "new_face_error": FT_Err_Ok,
                "load_glyph_error": load_glyph_error
            }))
        }
        Err(err) => Ok(json!({
            "new_face_error": err,
            "load_glyph_error": FT_Err_Invalid_Face_Handle as FT_Error
        })),
    }
}

fn c_init_free_type_face_load_probe(case: &InputCase) -> Result<Value, String> {
    let bytes = font_bytes(case)?;
    let mut library = std::ptr::null_mut();
    let init_err = c_abi::FT_Init_FreeType(&mut library);
    if init_err != FT_Err_Ok {
        return Ok(json!({
            "new_face_error": init_err,
            "load_glyph_error": FT_Err_Invalid_Face_Handle as FT_Error
        }));
    }
    let mut face = std::ptr::null_mut();
    let file_size = i64::try_from(bytes.len()).map_err(|err| err.to_string())?;
    let new_face_error = c_abi::FT_New_Memory_Face(
        library,
        bytes.as_ptr(),
        file_size,
        face_index_param(&case.inputs.params)?,
        &mut face,
    );
    let load_glyph_error = if new_face_error == FT_Err_Ok {
        c_abi::FT_Load_Glyph(face, 0, FT_LOAD_DEFAULT)
    } else {
        FT_Err_Invalid_Face_Handle as FT_Error
    };
    if !face.is_null() {
        c_done_face(face);
    }
    c_done_library(library);
    Ok(json!({
        "new_face_error": new_face_error,
        "load_glyph_error": load_glyph_error
    }))
}

fn wasm_init_free_type_face_load_probe(case: &InputCase) -> Result<Value, String> {
    let bytes = font_bytes(case)?;
    let status = wasm_abi::fontdone_wasm_open_face(
        bytes.as_ptr(),
        bytes.len(),
        face_index_param(&case.inputs.params)?,
        20.0,
    );
    let load_glyph_error = if status.error == FT_Err_Ok {
        wasm_abi::fontdone_wasm_load_glyph(status.handle, 0, FT_LOAD_DEFAULT)
    } else {
        FT_Err_Invalid_Face_Handle as FT_Error
    };
    if status.handle != 0 {
        wasm_done_face(status.handle);
    }
    Ok(json!({
        "new_face_error": status.error,
        "load_glyph_error": load_glyph_error
    }))
}

fn rust_truetype_engine_output(params: &Value) -> Result<Value, String> {
    let library = match truetype_engine_library_present_arg(params)? {
        0 => None,
        2 => Some(FT_New_Library_Without_Default_Modules()),
        _ => Some(FT_Init_FreeType()),
    };
    Ok(json!({
        "engine_type": FT_Get_TrueType_Engine_Type(library.as_ref()),
        "module_present": FT_Library_Has_TrueType_Module(library.as_ref()),
        "service_present": FT_Library_Has_TrueType_Engine_Service(library.as_ref())
    }))
}

fn c_truetype_engine_output(params: &Value) -> Result<Value, String> {
    let library_kind = truetype_engine_library_present_arg(params)?;
    let mut library = std::ptr::null_mut();
    if library_kind == 1 {
        let err = c_abi::FT_Init_FreeType(&mut library);
        if err != FT_Err_Ok {
            return Err(format!("FT_Init_FreeType returned {err}"));
        }
    } else if library_kind == 2 {
        library = c_abi::abi_support_new_library_without_default_modules();
    }
    let engine_type = c_abi::FT_Get_TrueType_Engine_Type(library);
    let module_present = c_abi::abi_support_library_has_truetype_module(library);
    let service_present = c_abi::abi_support_library_has_truetype_engine_service(library);
    if library_kind != 0 {
        c_done_library(library);
    }
    Ok(json!({
        "engine_type": engine_type,
        "module_present": module_present,
        "service_present": service_present
    }))
}

fn wasm_truetype_engine_output(params: &Value) -> Result<Value, String> {
    let (engine_type, module_present, service_present) =
        wasm_abi::abi_support_truetype_engine_observation(truetype_engine_library_present_arg(
            params,
        )?);
    Ok(json!({
        "engine_type": engine_type,
        "module_present": module_present,
        "service_present": service_present
    }))
}

const PROPERTY_SENTINEL: FT_UInt = 0xDEAD_BEEF;
const BDF_PROPERTY_TYPE_SENTINEL: i32 = 0x7777_7777;

#[derive(Clone, Copy)]
enum PropertyBackend {
    Rust,
    CAbi,
    Wasm,
}

fn property_get_case_output(
    case: &InputCase,
    backend: PropertyBackend,
) -> Result<RunOutput, String> {
    match case.case_id.as_str() {
        "ftmodapi.FT_Property_Get.gets_supported_property"
        | "ftdriver.TT_INTERPRETER_VERSION_40.default_interpreter_version" => {
            let mut value = PROPERTY_SENTINEL;
            let error = property_get_call(backend, 1, 1, 1, Some(&mut value));
            Ok(ok(json!({
                "status": error,
                "value": value,
                "module_service": error == FT_Err_Ok
            })))
        }
        "fterrdef.FT_Err_Missing_Property.known_property_success" => {
            let mut value = PROPERTY_SENTINEL;
            let error = property_get_call(backend, 1, 4, 4, Some(&mut value));
            Ok(ok(json!({
                "status": error,
                "value": value,
                "module_service": error == FT_Err_Ok
            })))
        }
        "ftmodapi.FT_Property_Get.rejects_null_arguments" => {
            let mut library_value = PROPERTY_SENTINEL;
            let mut module_value = PROPERTY_SENTINEL;
            let mut property_value = PROPERTY_SENTINEL;
            let rows = [
                (
                    "library",
                    property_get_call(backend, 0, 1, 1, Some(&mut library_value)),
                    Some(library_value),
                ),
                (
                    "module_name",
                    property_get_call(backend, 1, 0, 1, Some(&mut module_value)),
                    Some(module_value),
                ),
                (
                    "property_name",
                    property_get_call(backend, 1, 1, 0, Some(&mut property_value)),
                    Some(property_value),
                ),
                ("value", property_get_call(backend, 1, 1, 1, None), None),
            ];
            Ok(ok(json!({
                "error": rows[0].1,
                "rows": rows.into_iter().map(|(field, error, value_after)| json!({
                    "field": field,
                    "error": error,
                    "value_after": value_after
                })).collect::<Vec<_>>()
            })))
        }
        "ftmodapi.FT_Property_Get.missing_or_unsupported_property_service" => {
            let mut missing_value = PROPERTY_SENTINEL;
            let missing = property_get_call(backend, 1, 3, 1, Some(&mut missing_value));
            let mut unsupported_value = PROPERTY_SENTINEL;
            let unsupported = property_get_call(backend, 1, 2, 1, Some(&mut unsupported_value));
            Ok(ok(json!({
                "error": missing,
                "rows": [
                    {"module": "fixture_missing", "error": missing, "value_after": missing_value},
                    {"module": "sfnt", "error": unsupported, "value_after": unsupported_value}
                ]
            })))
        }
        "ftmodapi.FT_Property_Get.invalid_property_name"
        | "fterrdef.FT_Err_Missing_Property.driver_property_unknown_name" => {
            let mut value = PROPERTY_SENTINEL;
            let error = property_get_call(backend, 1, 1, 2, Some(&mut value));
            Ok(ok(json!({
                "error": error,
                "rows": [{"property": "fixture-missing-property", "error": error, "value_after": value}]
            })))
        }
        "ftdriver.FT_Prop_GlyphToScriptMap.invalid_face_error_matches_c" => {
            property_glyph_to_script_map_invalid_face_output(backend)
        }
        "ftdriver.FT_Prop_GlyphToScriptMap.property_get_returns_face_map" => {
            property_glyph_to_script_map_success_output(case, backend)
        }
        other => Err(format!("unsupported property get case {other}")),
    }
}

fn bdf_property_error_case_supported(case: &InputCase) -> bool {
    matches!(
        case.case_id.as_str(),
        "ftbdf.FT_Get_BDF_Property.success_bdf_string_integer_cardinal_properties"
            | "ftbdf.FT_Get_BDF_Property.error_missing_property_sets_none"
            | "ftbdf.FT_Get_BDF_Property.error_null_face_or_output"
            | "ftbdf.FT_Get_BDF_Property.error_unsupported_face_or_unselected_strike"
    )
}

fn bdf_property_success_row_case(case: &InputCase) -> bool {
    matches!(
        case.case_id.as_str(),
        "ftbdf.FT_Get_BDF_Property.success_bdf_string_integer_cardinal_properties"
    )
}

fn bdf_property_names_for_case(case: &InputCase) -> Result<Vec<String>, String> {
    case.inputs
        .params
        .get("properties")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .map(|item| {
                    item.as_str()
                        .map(str::to_string)
                        .ok_or_else(|| format!("invalid BDF property name {item}"))
                })
                .collect()
        })
        .unwrap_or_else(|| {
            bdf_property_name_for_case(case).map(|property_name| vec![property_name.to_string()])
        })
}

fn bdf_charset_case_supported(case: &InputCase) -> bool {
    matches!(
        case.case_id.as_str(),
        "ftbdf.FT_Get_BDF_Charset_ID.error_non_bdf_face"
            | "ftbdf.FT_Get_BDF_Charset_ID.success_bdf_face_charset"
            | "ftbdf.FT_Get_BDF_Charset_ID.error_null_face_or_outputs"
    )
}

fn bdf_charset_pointer_json<T>(pointer: *const T) -> Value {
    if pointer.addr() == 1 {
        return json!({
            "null": false,
            "bytes": "",
            "length": PROPERTY_SENTINEL,
            "sentinel": true
        });
    }
    ffi_nullable_c_string_json(pointer.cast())
}

fn bdf_charset_run_output(
    error: FT_Error,
    charset_encoding: Value,
    charset_registry: Value,
) -> RunOutput {
    let output = json!({
        "error": error,
        "charset_encoding": charset_encoding,
        "charset_registry": charset_registry
    });
    if error == FT_Err_Ok {
        ok(output)
    } else {
        error_with_output(error, output)
    }
}

fn bdf_charset_null_matrix_output(
    null_face_error: FT_Error,
    null_face_encoding: Value,
    null_face_registry: Value,
    null_encoding_error: FT_Error,
    registry_only: Value,
    null_registry_error: FT_Error,
    encoding_only: Value,
    both_outputs_null_error: FT_Error,
) -> RunOutput {
    let output = json!({
        "error": null_face_error,
        "rows": [
            {
                "variant": "face",
                "error": null_face_error,
                "charset_encoding": null_face_encoding,
                "charset_registry": null_face_registry
            },
            {
                "variant": "charset_encoding",
                "error": null_encoding_error,
                "charset_encoding": null,
                "charset_registry": registry_only
            },
            {
                "variant": "charset_registry",
                "error": null_registry_error,
                "charset_encoding": encoding_only,
                "charset_registry": null
            },
            {
                "variant": "both_outputs",
                "error": both_outputs_null_error,
                "charset_encoding": null,
                "charset_registry": null
            }
        ]
    });
    if null_face_error == FT_Err_Ok {
        ok(output)
    } else {
        error_with_output(null_face_error, output)
    }
}

fn rust_bdf_charset_output(case: &InputCase) -> Result<RunOutput, String> {
    let data = font_bytes(case)?;
    let face = rust_new_face_from_bytes(data.as_ref(), face_index_param(&case.inputs.params)?)?;
    if case.case_id == "ftbdf.FT_Get_BDF_Charset_ID.error_null_face_or_outputs" {
        let mut null_face_encoding = std::ptr::without_provenance::<FT_String>(1);
        let mut null_face_registry = std::ptr::without_provenance::<FT_String>(1);
        let null_face_error = FT_Get_BDF_Charset_ID(
            None,
            Some(&mut null_face_encoding),
            Some(&mut null_face_registry),
        );
        let mut registry_only = std::ptr::without_provenance::<FT_String>(1);
        let null_encoding_error =
            FT_Get_BDF_Charset_ID(Some(&face), None, Some(&mut registry_only));
        let mut encoding_only = std::ptr::without_provenance::<FT_String>(1);
        let null_registry_error =
            FT_Get_BDF_Charset_ID(Some(&face), Some(&mut encoding_only), None);
        let both_outputs_null_error = FT_Get_BDF_Charset_ID(Some(&face), None, None);
        return Ok(bdf_charset_null_matrix_output(
            null_face_error,
            bdf_charset_pointer_json(null_face_encoding),
            bdf_charset_pointer_json(null_face_registry),
            null_encoding_error,
            bdf_charset_pointer_json(registry_only),
            null_registry_error,
            bdf_charset_pointer_json(encoding_only),
            both_outputs_null_error,
        ));
    }
    let mut encoding = std::ptr::without_provenance::<FT_String>(1);
    let mut registry = std::ptr::without_provenance::<FT_String>(1);
    let error = FT_Get_BDF_Charset_ID(Some(&face), Some(&mut encoding), Some(&mut registry));
    Ok(bdf_charset_run_output(
        error,
        bdf_charset_pointer_json(encoding),
        bdf_charset_pointer_json(registry),
    ))
}

fn c_bdf_charset_output(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_new_face_without_size(case)?;
    if case.case_id == "ftbdf.FT_Get_BDF_Charset_ID.error_null_face_or_outputs" {
        let mut null_face_encoding = std::ptr::without_provenance::<c_abi::FT_String>(1);
        let mut null_face_registry = std::ptr::without_provenance::<c_abi::FT_String>(1);
        let null_face_error = c_abi::FT_Get_BDF_Charset_ID(
            std::ptr::null_mut(),
            &mut null_face_encoding,
            &mut null_face_registry,
        );
        let mut registry_only = std::ptr::without_provenance::<c_abi::FT_String>(1);
        let null_encoding_error =
            c_abi::FT_Get_BDF_Charset_ID(face, std::ptr::null_mut(), &mut registry_only);
        let mut encoding_only = std::ptr::without_provenance::<c_abi::FT_String>(1);
        let null_registry_error =
            c_abi::FT_Get_BDF_Charset_ID(face, &mut encoding_only, std::ptr::null_mut());
        let both_outputs_null_error =
            c_abi::FT_Get_BDF_Charset_ID(face, std::ptr::null_mut(), std::ptr::null_mut());
        let output = bdf_charset_null_matrix_output(
            null_face_error,
            bdf_charset_pointer_json(null_face_encoding),
            bdf_charset_pointer_json(null_face_registry),
            null_encoding_error,
            bdf_charset_pointer_json(registry_only),
            null_registry_error,
            bdf_charset_pointer_json(encoding_only),
            both_outputs_null_error,
        );
        c_done_face(face);
        c_done_library(library);
        return Ok(output);
    }
    let mut encoding = std::ptr::without_provenance::<c_abi::FT_String>(1);
    let mut registry = std::ptr::without_provenance::<c_abi::FT_String>(1);
    let error = c_abi::FT_Get_BDF_Charset_ID(face, &mut encoding, &mut registry);
    let output = bdf_charset_run_output(
        error,
        bdf_charset_pointer_json(encoding),
        bdf_charset_pointer_json(registry),
    );
    c_done_face(face);
    c_done_library(library);
    Ok(output)
}

fn wasm_bdf_charset_output(case: &InputCase) -> Result<RunOutput, String> {
    let data = font_bytes(case)?;
    let handle = wasm_new_face_from_bytes(data.as_ref(), face_index_param(&case.inputs.params)?)?;
    if case.case_id == "ftbdf.FT_Get_BDF_Charset_ID.error_null_face_or_outputs" {
        let mut null_face_output = wasm_abi::FontdoneWasmBdfCharset {
            charset_encoding: std::ptr::without_provenance::<FT_Byte>(1),
            charset_encoding_len: PROPERTY_SENTINEL,
            charset_registry: std::ptr::without_provenance::<FT_Byte>(1),
            charset_registry_len: PROPERTY_SENTINEL,
        };
        let null_face_error = wasm_abi::fontdone_wasm_get_bdf_charset_id(0, &mut null_face_output);
        let mut registry_only = wasm_abi::FontdoneWasmBdfCharset {
            charset_encoding: std::ptr::without_provenance::<FT_Byte>(1),
            charset_encoding_len: PROPERTY_SENTINEL,
            charset_registry: std::ptr::without_provenance::<FT_Byte>(1),
            charset_registry_len: PROPERTY_SENTINEL,
        };
        let null_encoding_error =
            wasm_abi::fontdone_wasm_get_bdf_charset_id(handle, &mut registry_only);
        let mut encoding_only = wasm_abi::FontdoneWasmBdfCharset {
            charset_encoding: std::ptr::without_provenance::<FT_Byte>(1),
            charset_encoding_len: PROPERTY_SENTINEL,
            charset_registry: std::ptr::without_provenance::<FT_Byte>(1),
            charset_registry_len: PROPERTY_SENTINEL,
        };
        let null_registry_error =
            wasm_abi::fontdone_wasm_get_bdf_charset_id(handle, &mut encoding_only);
        let both_outputs_null_error =
            wasm_abi::fontdone_wasm_get_bdf_charset_id(handle, std::ptr::null_mut());
        let output = bdf_charset_null_matrix_output(
            null_face_error,
            bdf_charset_pointer_json(null_face_output.charset_encoding),
            bdf_charset_pointer_json(null_face_output.charset_registry),
            null_encoding_error,
            bdf_charset_pointer_json(registry_only.charset_registry),
            null_registry_error,
            bdf_charset_pointer_json(encoding_only.charset_encoding),
            both_outputs_null_error,
        );
        wasm_done_face(handle);
        return Ok(output);
    }
    let mut output = wasm_abi::FontdoneWasmBdfCharset {
        charset_encoding: std::ptr::without_provenance::<FT_Byte>(1),
        charset_encoding_len: PROPERTY_SENTINEL,
        charset_registry: std::ptr::without_provenance::<FT_Byte>(1),
        charset_registry_len: PROPERTY_SENTINEL,
    };
    let error = wasm_abi::fontdone_wasm_get_bdf_charset_id(handle, &mut output);
    let output = bdf_charset_run_output(
        error,
        bdf_charset_pointer_json(output.charset_encoding),
        bdf_charset_pointer_json(output.charset_registry),
    );
    wasm_done_face(handle);
    Ok(output)
}

fn bdf_property_sentinel() -> BDF_PropertyRec {
    BDF_PropertyRec {
        type_: BDF_PROPERTY_TYPE_SENTINEL,
        u: BDF_PropertyValue {
            cardinal: PROPERTY_SENTINEL,
        },
    }
}

fn bdf_property_after_json(property: &BDF_PropertyRec) -> Value {
    let snapshot = c_abi::abi_bdf_property_snapshot(property);
    bdf_property_snapshot_json(
        snapshot.type_,
        snapshot.atom.cast(),
        snapshot.integer,
        snapshot.cardinal,
    )
}

fn bdf_property_snapshot_json(
    type_: BDF_PropertyType,
    atom: *const FT_String,
    integer: FT_Int32,
    cardinal: FT_UInt32,
) -> Value {
    match type_ {
        BDF_PROPERTY_TYPE_ATOM => {
            json!({
                "type": type_,
                "atom_string": ffi_nullable_c_string_json(atom),
                "integer": null,
                "cardinal": null
            })
        }
        BDF_PROPERTY_TYPE_INTEGER => {
            json!({
                "type": type_,
                "atom_string": null,
                "integer": integer,
                "cardinal": null
            })
        }
        BDF_PROPERTY_TYPE_CARDINAL => {
            json!({
                "type": type_,
                "atom_string": null,
                "integer": null,
                "cardinal": cardinal
            })
        }
        _ => json!({
            "type": type_,
            "atom_string": null,
            "integer": integer,
            "cardinal": cardinal
        }),
    }
}

fn bdf_property_run_output(error_code: FT_Error, output: Value) -> RunOutput {
    if error_code == FT_Err_Ok {
        ok(output)
    } else {
        error_with_output(error_code, output)
    }
}

fn bdf_property_name_for_case(case: &InputCase) -> Result<&str, String> {
    match case.case_id.as_str() {
        "ftbdf.FT_Get_BDF_Property.error_missing_property_sets_none" => Ok("NO_SUCH_PROPERTY"),
        "ftbdf.FT_Get_BDF_Property.error_unsupported_face_or_unselected_strike" => {
            Ok("FAMILY_NAME")
        }
        other => Err(format!("unsupported BDF property scalar case {other}")),
    }
}

fn rust_bdf_property_output(case: &InputCase) -> Result<RunOutput, String> {
    if case.case_id == "ftbdf.FT_Get_BDF_Property.error_null_face_or_output" {
        let mut null_face_property = bdf_property_sentinel();
        let null_face_error =
            FT_Get_BDF_Property(None, Some("FAMILY_NAME"), Some(&mut null_face_property));
        let data = font_bytes(case)?;
        let face = rust_new_face_from_bytes(data.as_ref(), face_index_param(&case.inputs.params)?)?;
        let null_output_error = FT_Get_BDF_Property(Some(&face), Some("FAMILY_NAME"), None);
        return Ok(bdf_property_run_output(
            null_face_error,
            json!({
                "error": null_face_error,
                "rows": [
                    {
                        "variant": "face",
                        "error": null_face_error,
                        "property_after": bdf_property_after_json(&null_face_property)
                    },
                    {
                        "variant": "aproperty",
                        "error": null_output_error,
                        "property_after": null
                    }
                ]
            }),
        ));
    }

    if bdf_property_success_row_case(case) {
        let data = font_bytes(case)?;
        let face = rust_new_face_from_bytes(data.as_ref(), face_index_param(&case.inputs.params)?)?;
        let rows = bdf_property_names_for_case(case)?
            .into_iter()
            .map(|property_name| {
                let mut property = bdf_property_sentinel();
                let error =
                    FT_Get_BDF_Property(Some(&face), Some(&property_name), Some(&mut property));
                json!({
                    "property_name": property_name,
                    "error": error,
                    "property_after": bdf_property_after_json(&property)
                })
            })
            .collect::<Vec<_>>();
        return Ok(ok(json!({"rows": rows})));
    }

    let property_name = bdf_property_name_for_case(case)?;
    let data = font_bytes(case)?;
    let face = rust_new_face_from_bytes(data.as_ref(), face_index_param(&case.inputs.params)?)?;
    let mut property = bdf_property_sentinel();
    let error = FT_Get_BDF_Property(Some(&face), Some(property_name), Some(&mut property));
    Ok(bdf_property_run_output(
        error,
        json!({
            "error": error,
            "property_name": property_name,
            "property_after": bdf_property_after_json(&property)
        }),
    ))
}

fn c_bdf_property_output(case: &InputCase) -> Result<RunOutput, String> {
    if case.case_id == "ftbdf.FT_Get_BDF_Property.error_null_face_or_output" {
        let mut null_face_property = bdf_property_sentinel();
        let prop_name = CString::new("FAMILY_NAME").map_err(|err| err.to_string())?;
        let null_face_error = c_abi::FT_Get_BDF_Property(
            std::ptr::null_mut(),
            prop_name.as_ptr(),
            &mut null_face_property,
        );
        let (library, face) = c_new_face_without_size(case)?;
        let null_output_error =
            c_abi::FT_Get_BDF_Property(face, prop_name.as_ptr(), std::ptr::null_mut());
        c_done_face(face);
        c_done_library(library);
        return Ok(bdf_property_run_output(
            null_face_error,
            json!({
                "error": null_face_error,
                "rows": [
                    {
                        "variant": "face",
                        "error": null_face_error,
                        "property_after": bdf_property_after_json(&null_face_property)
                    },
                    {
                        "variant": "aproperty",
                        "error": null_output_error,
                        "property_after": null
                    }
                ]
            }),
        ));
    }

    if bdf_property_success_row_case(case) {
        let (library, face) = c_new_face_without_size(case)?;
        let rows = bdf_property_names_for_case(case)?
            .into_iter()
            .map(|property_name| {
                let prop_name =
                    CString::new(property_name.as_str()).map_err(|err| err.to_string())?;
                let mut property = bdf_property_sentinel();
                let error = c_abi::FT_Get_BDF_Property(face, prop_name.as_ptr(), &mut property);
                Ok(json!({
                    "property_name": property_name,
                    "error": error,
                    "property_after": bdf_property_after_json(&property)
                }))
            })
            .collect::<Result<Vec<_>, String>>()?;
        c_done_face(face);
        c_done_library(library);
        return Ok(ok(json!({"rows": rows})));
    }

    let property_name = bdf_property_name_for_case(case)?;
    let prop_name = CString::new(property_name).map_err(|err| err.to_string())?;
    let (library, face) = c_new_face_without_size(case)?;
    let mut property = bdf_property_sentinel();
    let error = c_abi::FT_Get_BDF_Property(face, prop_name.as_ptr(), &mut property);
    c_done_face(face);
    c_done_library(library);
    Ok(bdf_property_run_output(
        error,
        json!({
            "error": error,
            "property_name": property_name,
            "property_after": bdf_property_after_json(&property)
        }),
    ))
}

fn wasm_bdf_property_after_json(property: &wasm_abi::FontdoneWasmBdfProperty) -> Value {
    match property.type_ {
        BDF_PROPERTY_TYPE_ATOM => json!({
            "type": property.type_,
            "atom_string": wasm_raw_string_json(property.atom, property.atom_len),
            "integer": null,
            "cardinal": null
        }),
        _ => bdf_property_snapshot_json(
            property.type_,
            std::ptr::null(),
            property.integer,
            property.cardinal,
        ),
    }
}

fn wasm_bdf_property_sentinel() -> wasm_abi::FontdoneWasmBdfProperty {
    wasm_abi::FontdoneWasmBdfProperty {
        type_: BDF_PROPERTY_TYPE_SENTINEL,
        atom: std::ptr::null(),
        atom_len: 0,
        integer: PROPERTY_SENTINEL as FT_Int32,
        cardinal: PROPERTY_SENTINEL,
    }
}

fn wasm_raw_string_json(ptr: *const FT_Byte, len: FT_UInt) -> Value {
    if ptr.is_null() {
        return nullable_c_string_json(None);
    }
    let bytes = c_abi::abi_byte_slice(ptr, len);
    json!({
        "null": false,
        "bytes": hex_bytes(&bytes),
        "length": bytes.len()
    })
}

fn wasm_bdf_property_output(case: &InputCase) -> Result<RunOutput, String> {
    if case.case_id == "ftbdf.FT_Get_BDF_Property.error_null_face_or_output" {
        let mut null_face_property = wasm_bdf_property_sentinel();
        let prop_name = b"FAMILY_NAME";
        let null_face_error = wasm_abi::fontdone_wasm_get_bdf_property(
            0,
            prop_name.as_ptr(),
            prop_name.len() as FT_UInt,
            &mut null_face_property,
        );
        let data = font_bytes(case)?;
        let handle =
            wasm_new_face_from_bytes(data.as_ref(), face_index_param(&case.inputs.params)?)?;
        let null_output_error = wasm_abi::fontdone_wasm_get_bdf_property(
            handle,
            prop_name.as_ptr(),
            prop_name.len() as FT_UInt,
            std::ptr::null_mut(),
        );
        wasm_done_face(handle);
        return Ok(bdf_property_run_output(
            null_face_error,
            json!({
                "error": null_face_error,
                "rows": [
                    {
                        "variant": "face",
                        "error": null_face_error,
                        "property_after": wasm_bdf_property_after_json(&null_face_property)
                    },
                    {
                        "variant": "aproperty",
                        "error": null_output_error,
                        "property_after": null
                    }
                ]
            }),
        ));
    }

    if bdf_property_success_row_case(case) {
        let data = font_bytes(case)?;
        let handle =
            wasm_new_face_from_bytes(data.as_ref(), face_index_param(&case.inputs.params)?)?;
        let rows = bdf_property_names_for_case(case)?
            .into_iter()
            .map(|property_name| {
                let mut property = wasm_bdf_property_sentinel();
                let error = wasm_abi::fontdone_wasm_get_bdf_property(
                    handle,
                    property_name.as_ptr(),
                    property_name.len() as FT_UInt,
                    &mut property,
                );
                json!({
                    "property_name": property_name,
                    "error": error,
                    "property_after": wasm_bdf_property_after_json(&property)
                })
            })
            .collect::<Vec<_>>();
        wasm_done_face(handle);
        return Ok(ok(json!({"rows": rows})));
    }

    let property_name = bdf_property_name_for_case(case)?;
    let data = font_bytes(case)?;
    let handle = wasm_new_face_from_bytes(data.as_ref(), face_index_param(&case.inputs.params)?)?;
    let mut property = wasm_bdf_property_sentinel();
    let error = wasm_abi::fontdone_wasm_get_bdf_property(
        handle,
        property_name.as_ptr(),
        property_name.len() as FT_UInt,
        &mut property,
    );
    wasm_done_face(handle);
    Ok(bdf_property_run_output(
        error,
        json!({
            "error": error,
            "property_name": property_name,
            "property_after": wasm_bdf_property_after_json(&property)
        }),
    ))
}

fn property_set_case_output(
    case: &InputCase,
    backend: PropertyBackend,
) -> Result<RunOutput, String> {
    match case.case_id.as_str() {
        "ftmodapi.FT_Property_Set.sets_supported_property" => {
            let rows = [
                TT_INTERPRETER_VERSION_35,
                TT_INTERPRETER_VERSION_38,
                TT_INTERPRETER_VERSION_40,
            ]
            .into_iter()
            .map(|value| {
                let (set_status, get_status, value_after_get) =
                    property_set_then_get_call(backend, 1, 1, Some(value as FT_UInt));
                json!({
                    "input": value,
                    "set_status": set_status,
                    "get_status": get_status,
                    "value_after_get": value_after_get
                })
            })
            .collect::<Vec<_>>();
            Ok(ok(json!({ "rows": rows })))
        }
        "ftdriver.TT_INTERPRETER_VERSION_35.interpreter_version_property_roundtrip"
        | "ftdriver.TT_INTERPRETER_VERSION_38.interpreter_version_property_normalizes_to_40"
        | "ftdriver.TT_INTERPRETER_VERSION_40.interpreter_version_property_roundtrip" => {
            let value = u32_param(&case.inputs.params, "value")? as FT_UInt;
            let (set_status, get_status, value_after_get) =
                property_set_then_get_call(backend, 1, 1, Some(value));
            Ok(ok(json!({
                "input": value,
                "set_status": set_status,
                "get_status": get_status,
                "value_after_get": value_after_get
            })))
        }
        "ftmodapi.FT_Property_Set.rejects_null_arguments" => {
            let rows = [
                (
                    "library",
                    property_set_call(backend, 0, 1, Some(TT_INTERPRETER_VERSION_40 as FT_UInt)),
                ),
                (
                    "module_name",
                    property_set_call(backend, 1, 0, Some(TT_INTERPRETER_VERSION_40 as FT_UInt)),
                ),
                ("property_name", property_set_call(backend, 1, 1, None)),
                ("value", property_set_call(backend, 1, 1, None)),
            ];
            Ok(ok(json!({
                "error": rows[0].1,
                "rows": rows.into_iter().map(|(field, error)| json!({
                    "field": field,
                    "error": error
                })).collect::<Vec<_>>()
            })))
        }
        "ftmodapi.FT_Property_Set.missing_or_unsupported_property_service" => {
            let missing =
                property_set_call(backend, 1, 3, Some(TT_INTERPRETER_VERSION_40 as FT_UInt));
            let unsupported =
                property_set_call(backend, 1, 2, Some(TT_INTERPRETER_VERSION_40 as FT_UInt));
            Ok(ok(json!({
                "error": missing,
                "rows": [
                    {"module": "fixture_missing", "error": missing, "property_after": PROPERTY_SENTINEL},
                    {"module": "sfnt", "error": unsupported, "property_after": PROPERTY_SENTINEL}
                ]
            })))
        }
        "ftmodapi.FT_Property_Set.invalid_property_or_value" => {
            let (missing_error, missing_after) = property_rejected_set_preservation(
                backend,
                1,
                2,
                TT_INTERPRETER_VERSION_40 as FT_UInt,
            );
            let (value_error, value_after) =
                property_rejected_set_preservation(backend, 1, 1, 9999);
            Ok(ok(json!({
                "error": missing_error,
                "rows": [
                    {
                        "scenario": "invalid_property",
                        "error": missing_error,
                        "previous_property_value": TT_INTERPRETER_VERSION_40,
                        "property_after": missing_after
                    },
                    {
                        "scenario": "invalid_value",
                        "error": value_error,
                        "previous_property_value": TT_INTERPRETER_VERSION_40,
                        "property_after": value_after
                    }
                ]
            })))
        }
        other => Err(format!("unsupported property set case {other}")),
    }
}

fn increase_x_height_limits(case: &InputCase) -> Result<Vec<FT_UInt>, String> {
    array_param(&case.inputs.params, "limits")?
        .iter()
        .map(|value| u32_value(value, "limits[]").map(|value| value as FT_UInt))
        .collect()
}

fn property_face_identity_json<T>(face: *const T, prop_face: FT_Pointer) -> Value {
    json!({
        "identity_class": if !face.is_null() && prop_face == face.cast_mut().cast() {
            "same-live-face"
        } else if prop_face.is_null() {
            "null"
        } else {
            "other"
        }
    })
}

fn property_map_identity_json(map: *mut FT_UShort) -> Value {
    json!({
        "identity_class": if map.is_null() {
            "null"
        } else if map.addr() == 1 {
            "sentinel"
        } else {
            "other"
        },
        "nullness": map.is_null()
    })
}

fn glyph_to_script_target_char_code(case: &InputCase) -> Result<FT_ULong, String> {
    if case.case_id == "ftdriver.FT_AUTOHINTER_SCRIPT_NONE.default_and_fallback_property_roundtrip"
    {
        return Ok(0x41);
    }
    match string_param(&case.inputs.params, "target_glyph")? {
        "latin_A_greek_alpha_cyrillic_be" | "latin_A_manual_none" => Ok(0x41),
        "cjk_u4e00" => Ok(0x4E00),
        "indic_devanagari_ka" => Ok(0x0915),
        target => Err(format!("unsupported glyph-to-script target {target}")),
    }
}

fn glyph_to_script_map_sample_from_face(face: &FT_Face, map: *mut FT_UShort) -> Vec<Value> {
    let mut glyph_indices = vec![0];
    for cp in [0x41, 0x4E2D, 0x0905] {
        let glyph_index = FT_Get_Char_Index(face, cp);
        if glyph_index != 0 {
            glyph_indices.push(glyph_index);
        }
    }
    if map.is_null() {
        return Vec::new();
    }
    FT_Glyph_To_Script_Map_Sample_For_Test(face, &glyph_indices)
        .into_iter()
        .map(|(glyph_index, script)| {
            json!({
                "glyph_index": glyph_index,
                "script": script
            })
        })
        .collect()
}

fn property_glyph_to_script_runtime_output(
    error: FT_Error,
    face_identity: Value,
    map: *mut FT_UShort,
    num_glyphs: FT_Long,
    target_glyph_index: FT_UInt,
    target_script: FT_UShort,
    load_error: FT_Error,
    glyph_slot: Value,
) -> RunOutput {
    ok(json!({
        "error": error,
        "prop_after": {
            "face": face_identity,
            "map": property_map_identity_json(map)
        },
        "num_glyphs": num_glyphs,
        "target": {
            "glyph_index": target_glyph_index,
            "script": target_script
        },
        "load_error": load_error,
        "glyph_slot": glyph_slot
    }))
}

fn rust_property_glyph_to_script_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    let library = FT_Init_FreeType();
    let face = open_face(case)?;
    let face_ptr = (&face as *const FT_Face).cast_mut().cast();
    let mut prop = FT_Prop_GlyphToScriptMap {
        face: face_ptr,
        map: std::ptr::without_provenance_mut(1),
    };
    let error = FT_Property_Get_GlyphToScriptMap(
        Some(&library),
        Some("autofitter"),
        Some("glyph-to-script-map"),
        Some(&face),
        Some(&mut prop),
    );
    let target_glyph_index = FT_Get_Char_Index(&face, glyph_to_script_target_char_code(case)?);
    let target_script = FT_Glyph_To_Script_Map_Sample_For_Test(&face, &[target_glyph_index])
        .into_iter()
        .next()
        .map(|(_, script)| script)
        .unwrap_or(0);
    let load_result = FT_Load_Glyph(&face, target_glyph_index, FT_LOAD_FORCE_AUTOHINT);
    let (load_error, glyph_slot) = match load_result {
        Ok(slot) => (FT_Err_Ok as FT_Error, slot_json(&slot)),
        Err(err) => (err, Value::Null),
    };
    Ok(property_glyph_to_script_runtime_output(
        error,
        property_face_identity_json(&face, prop.face),
        prop.map,
        face.num_glyphs,
        target_glyph_index,
        target_script,
        load_error,
        glyph_slot,
    ))
}

fn c_property_glyph_to_script_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_open_face(case)?;
    let mut prop = FT_Prop_GlyphToScriptMap {
        face: face.cast(),
        map: std::ptr::without_provenance_mut(1),
    };
    let error = c_abi::FT_Property_Get(
        library,
        c"autofitter".as_ptr(),
        c"glyph-to-script-map".as_ptr(),
        (&mut prop as *mut FT_Prop_GlyphToScriptMap).cast(),
    );
    let target_glyph_index =
        c_abi::FT_Get_Char_Index(face, glyph_to_script_target_char_code(case)?);
    let target_script = c_abi::abi_glyph_to_script_map_sample(face, &[target_glyph_index])
        .into_iter()
        .next()
        .map(|(_, script)| script)
        .unwrap_or(0);
    let load_error = c_abi::FT_Load_Glyph(face, target_glyph_index, FT_LOAD_FORCE_AUTOHINT);
    let glyph_slot = if load_error == FT_Err_Ok {
        c_slot_json(face)?
    } else {
        Value::Null
    };
    let num_glyphs = c_abi::abi_face_info(face)
        .map(|info| info.num_glyphs)
        .unwrap_or(0);
    let output = property_glyph_to_script_runtime_output(
        error,
        property_face_identity_json(face, prop.face),
        prop.map,
        num_glyphs,
        target_glyph_index,
        target_script,
        load_error,
        glyph_slot,
    );
    c_done_face(face);
    c_done_library(library);
    Ok(output)
}

fn wasm_property_glyph_to_script_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    let handle = wasm_open_face(case)?;
    let target_glyph_index =
        wasm_abi::fontdone_wasm_get_char_index(handle, glyph_to_script_target_char_code(case)?);
    let snapshot =
        wasm_abi::abi_property_glyph_to_script_map_snapshot(handle, &[target_glyph_index]);
    let target_script = snapshot
        .sample
        .iter()
        .find_map(|(glyph_index, script)| (*glyph_index == target_glyph_index).then_some(*script))
        .unwrap_or(0);
    let load_error =
        wasm_abi::fontdone_wasm_load_glyph(handle, target_glyph_index, FT_LOAD_FORCE_AUTOHINT);
    let glyph_slot = if load_error == FT_Err_Ok {
        wasm_slot_json(handle)?
    } else {
        Value::Null
    };
    let output = property_glyph_to_script_runtime_output(
        snapshot.error,
        json!({"identity_class": snapshot.face_identity}),
        if snapshot.map_is_null {
            std::ptr::null_mut()
        } else {
            std::ptr::without_provenance_mut(2)
        },
        snapshot.num_glyphs,
        target_glyph_index,
        target_script,
        load_error,
        glyph_slot,
    );
    wasm_done_face(handle);
    Ok(output)
}

fn property_glyph_to_script_map_output(
    error: FT_Error,
    face_identity: Value,
    map: *mut FT_UShort,
    num_glyphs: FT_Long,
    map_sample: Vec<Value>,
) -> RunOutput {
    ok(json!({
        "error": error,
        "prop_after": {
            "face": face_identity,
            "map": property_map_identity_json(map)
        },
        "num_glyphs": num_glyphs,
        "map_sample": map_sample
    }))
}

fn property_glyph_to_script_map_success_output(
    case: &InputCase,
    backend: PropertyBackend,
) -> Result<RunOutput, String> {
    match backend {
        PropertyBackend::Rust => {
            let library = FT_Init_FreeType();
            let face = open_face(case)?;
            let face_ptr = (&face as *const FT_Face).cast_mut().cast();
            let mut prop = FT_Prop_GlyphToScriptMap {
                face: face_ptr,
                map: std::ptr::without_provenance_mut(1),
            };
            let error = FT_Property_Get_GlyphToScriptMap(
                Some(&library),
                Some("autofitter"),
                Some("glyph-to-script-map"),
                Some(&face),
                Some(&mut prop),
            );
            let sample = glyph_to_script_map_sample_from_face(&face, prop.map);
            Ok(property_glyph_to_script_map_output(
                error,
                property_face_identity_json(&face, prop.face),
                prop.map,
                face.num_glyphs,
                sample,
            ))
        }
        PropertyBackend::CAbi => {
            let (library, face) = c_open_face(case)?;
            let mut prop = FT_Prop_GlyphToScriptMap {
                face: face.cast(),
                map: std::ptr::without_provenance_mut(1),
            };
            let error = c_abi::FT_Property_Get(
                library,
                c"autofitter".as_ptr(),
                c"glyph-to-script-map".as_ptr(),
                (&mut prop as *mut FT_Prop_GlyphToScriptMap).cast(),
            );
            let mut glyph_indices = vec![0];
            for cp in [0x41, 0x4E2D, 0x0905] {
                let glyph_index = c_abi::FT_Get_Char_Index(face, cp);
                if glyph_index != 0 {
                    glyph_indices.push(glyph_index);
                }
            }
            let num_glyphs = c_abi::abi_face_info(face)
                .map(|info| info.num_glyphs)
                .unwrap_or(0);
            let sample = c_abi::abi_glyph_to_script_map_sample(face, &glyph_indices)
                .into_iter()
                .map(|(glyph_index, script)| json!({"glyph_index": glyph_index, "script": script}))
                .collect();
            let output = property_glyph_to_script_map_output(
                error,
                property_face_identity_json(face, prop.face),
                prop.map,
                num_glyphs,
                sample,
            );
            c_done_face(face);
            c_done_library(library);
            Ok(output)
        }
        PropertyBackend::Wasm => {
            let handle = wasm_open_face(case)?;
            let glyph_indices = [0, 0x41, 0x4E2D, 0x0905]
                .into_iter()
                .filter_map(|cp| {
                    if cp == 0 {
                        Some(0)
                    } else {
                        let glyph = wasm_abi::fontdone_wasm_get_char_index(handle, cp);
                        (glyph != 0).then_some(glyph)
                    }
                })
                .collect::<Vec<_>>();
            let snapshot =
                wasm_abi::abi_property_glyph_to_script_map_snapshot(handle, &glyph_indices);
            wasm_done_face(handle);
            Ok(property_glyph_to_script_map_output(
                snapshot.error,
                json!({"identity_class": snapshot.face_identity}),
                if snapshot.map_is_null {
                    std::ptr::null_mut()
                } else {
                    std::ptr::without_provenance_mut(2)
                },
                snapshot.num_glyphs,
                snapshot
                    .sample
                    .into_iter()
                    .map(|(glyph_index, script)| {
                        json!({"glyph_index": glyph_index, "script": script})
                    })
                    .collect(),
            ))
        }
    }
}

fn property_glyph_to_script_map_invalid_face_output(
    backend: PropertyBackend,
) -> Result<RunOutput, String> {
    let (error, map) = match backend {
        PropertyBackend::Rust => {
            let library = FT_Init_FreeType();
            let mut prop = FT_Prop_GlyphToScriptMap {
                face: std::ptr::null_mut(),
                map: std::ptr::without_provenance_mut(1),
            };
            let error = FT_Property_Get_GlyphToScriptMap(
                Some(&library),
                Some("autofitter"),
                Some("glyph-to-script-map"),
                None,
                Some(&mut prop),
            );
            (error, prop.map)
        }
        PropertyBackend::CAbi => {
            let mut library = std::ptr::null_mut();
            let init_error = c_abi::FT_Init_FreeType(&mut library);
            if init_error != FT_Err_Ok {
                return Ok(error_with_output(init_error, json!({"error": init_error})));
            }
            let mut prop = FT_Prop_GlyphToScriptMap {
                face: std::ptr::null_mut(),
                map: std::ptr::without_provenance_mut(1),
            };
            let error = c_abi::FT_Property_Get(
                library,
                c"autofitter".as_ptr(),
                c"glyph-to-script-map".as_ptr(),
                (&mut prop as *mut FT_Prop_GlyphToScriptMap).cast(),
            );
            c_done_library(library);
            (error, prop.map)
        }
        PropertyBackend::Wasm => {
            let mut map_is_null = -1;
            let error =
                wasm_abi::fontdone_wasm_property_glyph_to_script_map_invalid_face(&mut map_is_null);
            let map = if map_is_null == 1 {
                std::ptr::null_mut()
            } else {
                std::ptr::without_provenance_mut(1)
            };
            (error, map)
        }
    };
    Ok(error_with_output(
        error,
        json!({
            "error": error,
            "prop_after": {
                "face": property_face_identity_json::<c_void>(std::ptr::null(), std::ptr::null_mut()),
                "map": property_map_identity_json(map)
            }
        }),
    ))
}

