fn property_increase_x_height_roundtrip_output(
    case: &InputCase,
    backend: PropertyBackend,
) -> Result<RunOutput, String> {
    let limits = increase_x_height_limits(case)?;
    let rows = match backend {
        PropertyBackend::Rust => {
            let library = FT_Init_FreeType();
            let mut face = open_face(case)?;
            let face_ptr = (&mut face as *mut FT_Face).cast::<c_void>();
            limits
                .into_iter()
                .map(|limit| {
                    let set_prop = FT_Prop_IncreaseXHeight {
                        face: face_ptr,
                        limit,
                    };
                    let set_error = FT_Property_Set_IncreaseXHeight(
                        Some(&library),
                        Some("autofitter"),
                        Some("increase-x-height"),
                        Some(&mut face),
                        Some(&set_prop),
                    );
                    let mut get_prop = FT_Prop_IncreaseXHeight {
                        face: face_ptr,
                        limit: PROPERTY_SENTINEL,
                    };
                    let get_error = FT_Property_Get_IncreaseXHeight(
                        Some(&library),
                        Some("autofitter"),
                        Some("increase-x-height"),
                        Some(&face),
                        Some(&mut get_prop),
                    );
                    json!({
                        "input": limit,
                        "set_error": set_error,
                        "get_error": get_error,
                        "set_prop": {
                            "face": property_face_identity_json(&face, set_prop.face),
                            "limit": set_prop.limit
                        },
                        "get_prop": {
                            "face": property_face_identity_json(&face, get_prop.face),
                            "limit": get_prop.limit
                        }
                    })
                })
                .collect::<Vec<_>>()
        }
        PropertyBackend::CAbi => {
            let (library, face) = c_open_face(case)?;
            let rows = limits
                .into_iter()
                .map(|limit| {
                    let set_prop = FT_Prop_IncreaseXHeight {
                        face: face.cast(),
                        limit,
                    };
                    let set_error = c_abi::FT_Property_Set(
                        library,
                        c"autofitter".as_ptr(),
                        c"increase-x-height".as_ptr(),
                        (&set_prop as *const FT_Prop_IncreaseXHeight).cast(),
                    );
                    let mut get_prop = FT_Prop_IncreaseXHeight {
                        face: face.cast(),
                        limit: PROPERTY_SENTINEL,
                    };
                    let get_error = c_abi::FT_Property_Get(
                        library,
                        c"autofitter".as_ptr(),
                        c"increase-x-height".as_ptr(),
                        (&mut get_prop as *mut FT_Prop_IncreaseXHeight).cast(),
                    );
                    json!({
                        "input": limit,
                        "set_error": set_error,
                        "get_error": get_error,
                        "set_prop": {
                            "face": property_face_identity_json(face, set_prop.face),
                            "limit": set_prop.limit
                        },
                        "get_prop": {
                            "face": property_face_identity_json(face, get_prop.face),
                            "limit": get_prop.limit
                        }
                    })
                })
                .collect::<Vec<_>>();
            c_done_face(face);
            c_done_library(library);
            rows
        }
        PropertyBackend::Wasm => {
            let handle = wasm_open_face(case)?;
            let rows = limits
                .into_iter()
                .map(|limit| {
                    let mut out = PROPERTY_SENTINEL;
                    let get_error = wasm_abi::fontdone_wasm_property_increase_x_height_set_then_get(
                        handle, limit, &mut out,
                    );
                    json!({
                        "input": limit,
                        "set_error": if get_error == FT_Err_Ok { FT_Err_Ok } else { get_error },
                        "get_error": get_error,
                        "set_prop": {
                            "face": {"identity_class": "same-live-face"},
                            "limit": limit
                        },
                        "get_prop": {
                            "face": {"identity_class": "same-live-face"},
                            "limit": out
                        }
                    })
                })
                .collect::<Vec<_>>();
            wasm_done_face(handle);
            rows
        }
    };
    Ok(ok(json!({ "rows": rows })))
}

fn autofitter_script_property_case(case: &InputCase) -> bool {
    matches!(
        case.case_id.as_str(),
        "ftdriver.FT_AUTOHINTER_SCRIPT_LATIN.default_script_property_roundtrip"
            | "ftdriver.FT_AUTOHINTER_SCRIPT_CJK.fallback_script_property_roundtrip"
            | "ftdriver.FT_AUTOHINTER_SCRIPT_INDIC.fallback_script_property_validation"
            | "ftdriver.FT_AUTOHINTER_SCRIPT_NONE.default_and_fallback_property_roundtrip"
    )
}

fn autofitter_property_selector(property_name: &str) -> Result<i32, String> {
    match property_name {
        "default-script" => Ok(3),
        "fallback-script" => Ok(4),
        other => Err(format!("unsupported autofitter property {other}")),
    }
}

fn property_autofitter_script_roundtrip_output(
    case: &InputCase,
    backend: PropertyBackend,
) -> Result<RunOutput, String> {
    let value = u32_param(&case.inputs.params, "value")? as FT_UInt;
    let property_names = string_array_param(&case.inputs.params, "property_names")?;
    let rows = property_names
        .iter()
        .filter(|property_name| property_name.as_str() != "glyph-to-script-map")
        .map(|property_name| {
            let property_selector = autofitter_property_selector(property_name)?;
            let mut initial = PROPERTY_SENTINEL;
            let initial_get =
                property_get_call(backend, 1, 4, property_selector, Some(&mut initial));
            let (set_error, get_error, readback) =
                property_set_then_get_call(backend, 4, property_selector, Some(value));
            let mut bad_module_value = PROPERTY_SENTINEL;
            let bad_module_error = property_get_call(
                backend,
                1,
                3,
                property_selector,
                Some(&mut bad_module_value),
            );
            let mut bad_property_value = PROPERTY_SENTINEL;
            let bad_property_error =
                property_get_call(backend, 1, 4, 2, Some(&mut bad_property_value));
            let invalid_set_error =
                property_set_call_with_property(backend, 1, 4, property_selector, Some(9999));
            let mut post_invalid = PROPERTY_SENTINEL;
            let post_invalid_get =
                property_get_call(backend, 1, 4, property_selector, Some(&mut post_invalid));
            Ok(json!({
                "property": property_name,
                "initial_get_error": initial_get,
                "initial_readback": initial,
                "set_error": set_error,
                "get_error": get_error,
                "readback_value": readback,
                "bad_module_error": bad_module_error,
                "bad_module_value_after": bad_module_value,
                "bad_property_error": bad_property_error,
                "bad_property_value_after": bad_property_value,
                "invalid_set_error": invalid_set_error,
                "post_invalid_get_error": post_invalid_get,
                "post_invalid_readback": post_invalid
            }))
        })
        .collect::<Result<Vec<_>, String>>()?;
    let glyph_to_script_map = if case.case_id.as_str()
        == "ftdriver.FT_AUTOHINTER_SCRIPT_NONE.default_and_fallback_property_roundtrip"
    {
        Some(match backend {
            PropertyBackend::Rust => rust_property_glyph_to_script_runtime_output(case)?.output,
            PropertyBackend::CAbi => c_property_glyph_to_script_runtime_output(case)?.output,
            PropertyBackend::Wasm => wasm_property_glyph_to_script_runtime_output(case)?.output,
        })
    } else {
        None
    };
    Ok(ok(json!({
        "rows": rows,
        "glyph_to_script_map": glyph_to_script_map
    })))
}

fn property_get_call(
    backend: PropertyBackend,
    library_present: i32,
    module_selector: i32,
    property_selector: i32,
    value: Option<&mut FT_UInt>,
) -> FT_Error {
    match backend {
        PropertyBackend::Rust => {
            let library = if library_present == 0 {
                None
            } else {
                Some(FT_Init_FreeType())
            };
            FT_Property_Get(
                library.as_ref(),
                property_module_selector(module_selector),
                property_name_selector(property_selector),
                value,
            )
        }
        PropertyBackend::CAbi => {
            c_property_get_call(library_present, module_selector, property_selector, value)
        }
        PropertyBackend::Wasm => wasm_abi::fontdone_wasm_property_get(
            library_present,
            module_selector,
            property_selector,
            value.map_or(std::ptr::null_mut(), |value| value as *mut FT_UInt),
        ),
    }
}

fn property_set_call(
    backend: PropertyBackend,
    library_present: i32,
    module_selector: i32,
    value: Option<FT_UInt>,
) -> FT_Error {
    property_set_call_with_property(backend, library_present, module_selector, 1, value)
}

fn property_set_call_with_property(
    backend: PropertyBackend,
    library_present: i32,
    module_selector: i32,
    property_selector: i32,
    value: Option<FT_UInt>,
) -> FT_Error {
    match backend {
        PropertyBackend::Rust => {
            let mut library = if library_present == 0 {
                None
            } else {
                Some(FT_Init_FreeType())
            };
            FT_Property_Set(
                library.as_mut(),
                property_module_selector(module_selector),
                property_name_selector(property_selector),
                value,
            )
        }
        PropertyBackend::CAbi => {
            let value_storage = value.unwrap_or_default();
            c_property_set_call(
                library_present,
                module_selector,
                property_selector,
                value.map_or(std::ptr::null(), |_| &value_storage as *const FT_UInt),
            )
        }
        PropertyBackend::Wasm => {
            let value_storage = value.unwrap_or_default();
            let mut out = PROPERTY_SENTINEL;
            wasm_abi::fontdone_wasm_property_set_then_get(
                library_present,
                module_selector,
                property_selector,
                value.map_or(std::ptr::null(), |_| &value_storage as *const FT_UInt),
                &mut out,
            )
        }
    }
}

fn property_set_then_get_call(
    backend: PropertyBackend,
    module_selector: i32,
    property_selector: i32,
    value: Option<FT_UInt>,
) -> (FT_Error, FT_Error, FT_UInt) {
    match backend {
        PropertyBackend::Rust => {
            let mut library = FT_Init_FreeType();
            let set_status = FT_Property_Set(
                Some(&mut library),
                property_module_selector(module_selector),
                property_name_selector(property_selector),
                value,
            );
            let mut out = PROPERTY_SENTINEL;
            let get_status = FT_Property_Get(
                Some(&library),
                property_module_selector(module_selector),
                property_name_selector(property_selector),
                Some(&mut out),
            );
            (set_status, get_status, out)
        }
        PropertyBackend::CAbi => {
            c_property_set_then_get_call(module_selector, property_selector, value)
        }
        PropertyBackend::Wasm => {
            let value_storage = value.unwrap_or_default();
            let mut out = PROPERTY_SENTINEL;
            let set_status = wasm_abi::fontdone_wasm_property_set_then_get(
                1,
                module_selector,
                property_selector,
                value.map_or(std::ptr::null(), |_| &value_storage as *const FT_UInt),
                &mut out,
            );
            let get_status = if set_status == FT_Err_Ok {
                FT_Err_Ok
            } else {
                set_status
            };
            (set_status, get_status, out)
        }
    }
}

fn property_rejected_set_preservation(
    backend: PropertyBackend,
    module_selector: i32,
    property_selector: i32,
    rejected_value: FT_UInt,
) -> (FT_Error, FT_UInt) {
    if let PropertyBackend::Wasm = backend {
        let value_storage = rejected_value;
        let mut ignored = PROPERTY_SENTINEL;
        let set_status = wasm_abi::fontdone_wasm_property_set_then_get(
            1,
            module_selector,
            property_selector,
            &value_storage,
            &mut ignored,
        );
        let mut value_after = PROPERTY_SENTINEL;
        let _ = wasm_abi::fontdone_wasm_property_get(
            1,
            module_selector,
            property_selector,
            &mut value_after,
        );
        return (set_status, value_after);
    }
    let (set_status, get_status, value_after) = property_set_then_get_call(
        backend,
        module_selector,
        property_selector,
        Some(rejected_value),
    );
    let _ = get_status;
    (set_status, value_after)
}

fn rust_default_properties_value(library_present: i32, env: Option<&str>) -> Option<FT_UInt> {
    let mut library = if library_present == 0 {
        None
    } else {
        Some(FT_Init_FreeType())
    };
    FT_Set_Default_Properties_From_Env(library.as_mut(), env);
    let library = library.as_ref()?;
    let mut value = PROPERTY_SENTINEL;
    let error = FT_Property_Get(
        Some(library),
        Some("truetype"),
        Some("interpreter-version"),
        Some(&mut value),
    );
    (error == FT_Err_Ok).then_some(value)
}

fn c_default_properties_value(library_present: i32, env: Option<&str>) -> Option<FT_UInt> {
    c_abi::abi_support_set_default_properties(library_present, env)
}

fn wasm_default_properties_value(library_present: i32, env: Option<&str>) -> Option<FT_UInt> {
    wasm_abi::abi_support_set_default_properties(library_present, env)
}

fn default_properties_value(
    backend: PropertyBackend,
    library_present: i32,
    env: Option<&str>,
) -> Option<FT_UInt> {
    match backend {
        PropertyBackend::Rust => rust_default_properties_value(library_present, env),
        PropertyBackend::CAbi => c_default_properties_value(library_present, env),
        PropertyBackend::Wasm => wasm_default_properties_value(library_present, env),
    }
}

fn set_default_properties_case_output(
    case: &InputCase,
    backend: PropertyBackend,
) -> Result<RunOutput, String> {
    match case.case_id.as_str() {
        "ftmodapi.FT_Set_Default_Properties.no_environment_noop" => {
            let before = default_properties_value(backend, 1, None);
            let after = default_properties_value(backend, 1, None);
            Ok(ok(json!({
                "property_before": before,
                "property_after": after
            })))
        }
        "ftmodapi.FT_Set_Default_Properties.parses_supported_environment_property" => {
            let after =
                default_properties_value(backend, 1, Some("truetype:interpreter-version=35"));
            Ok(ok(json!({
                "environment_properties_enabled": after == Some(TT_INTERPRETER_VERSION_35 as FT_UInt),
                "property_after": after
            })))
        }
        "ftmodapi.FT_Set_Default_Properties.ignores_malformed_or_failed_properties" => {
            let malformed = default_properties_value(backend, 1, Some("malformed"));
            let missing = default_properties_value(backend, 1, Some("missing:property=1"));
            let null_library =
                default_properties_value(backend, 0, Some("truetype:interpreter-version=35"));
            Ok(ok(json!({
                "return": "void",
                "crashed": false,
                "rows": [
                    {"scenario": "malformed", "property_after": malformed},
                    {"scenario": "missing_property", "property_after": missing},
                    {"scenario": "null_library", "property_after": null_library}
                ]
            })))
        }
        other => Err(format!("unsupported set default properties case {other}")),
    }
}

fn property_module_selector(selector: i32) -> Option<&'static str> {
    match selector {
        0 => None,
        1 => Some("truetype"),
        2 => Some("sfnt"),
        3 => Some("fixture_missing"),
        4 => Some("autofitter"),
        _ => Some("fixture_missing"),
    }
}

fn property_name_selector(selector: i32) -> Option<&'static str> {
    match selector {
        0 => None,
        1 => Some("interpreter-version"),
        2 => Some("fixture-missing-property"),
        3 => Some("default-script"),
        4 => Some("fallback-script"),
        _ => Some("fixture-missing-property"),
    }
}

fn c_property_get_call(
    library_present: i32,
    module_selector: i32,
    property_selector: i32,
    value: Option<&mut FT_UInt>,
) -> FT_Error {
    let mut library = std::ptr::null_mut();
    if library_present != 0 && c_abi::FT_Init_FreeType(&mut library) != FT_Err_Ok {
        return FT_Err_Invalid_Library_Handle as FT_Error;
    }
    let error = c_abi::FT_Property_Get(
        library,
        property_module_cstr(module_selector),
        property_name_cstr(property_selector),
        value.map_or(std::ptr::null_mut(), |value| (value as *mut FT_UInt).cast()),
    );
    if !library.is_null() {
        c_done_library(library);
    }
    error
}

fn c_property_set_call(
    library_present: i32,
    module_selector: i32,
    property_selector: i32,
    value: *const FT_UInt,
) -> FT_Error {
    let mut library = std::ptr::null_mut();
    if library_present != 0 && c_abi::FT_Init_FreeType(&mut library) != FT_Err_Ok {
        return FT_Err_Invalid_Library_Handle as FT_Error;
    }
    let error = c_abi::FT_Property_Set(
        library,
        property_module_cstr(module_selector),
        property_name_cstr(property_selector),
        value.cast(),
    );
    if !library.is_null() {
        c_done_library(library);
    }
    error
}

fn c_property_set_then_get_call(
    module_selector: i32,
    property_selector: i32,
    value: Option<FT_UInt>,
) -> (FT_Error, FT_Error, FT_UInt) {
    let mut library = std::ptr::null_mut();
    if c_abi::FT_Init_FreeType(&mut library) != FT_Err_Ok {
        return (
            FT_Err_Invalid_Library_Handle as FT_Error,
            FT_Err_Invalid_Library_Handle as FT_Error,
            PROPERTY_SENTINEL,
        );
    }
    let value_storage = value.unwrap_or_default();
    let set_status = c_abi::FT_Property_Set(
        library,
        property_module_cstr(module_selector),
        property_name_cstr(property_selector),
        value
            .map_or(std::ptr::null(), |_| &value_storage as *const FT_UInt)
            .cast(),
    );
    let mut out = PROPERTY_SENTINEL;
    let get_status = c_abi::FT_Property_Get(
        library,
        property_module_cstr(module_selector),
        property_name_cstr(property_selector),
        (&mut out as *mut FT_UInt).cast(),
    );
    c_done_library(library);
    (set_status, get_status, out)
}

fn property_module_cstr(selector: i32) -> *const std::ffi::c_char {
    match selector {
        0 => std::ptr::null(),
        1 => c"truetype".as_ptr(),
        2 => c"sfnt".as_ptr(),
        3 => c"fixture_missing".as_ptr(),
        4 => c"autofitter".as_ptr(),
        _ => c"fixture_missing".as_ptr(),
    }
}

fn property_name_cstr(selector: i32) -> *const std::ffi::c_char {
    match selector {
        0 => std::ptr::null(),
        1 => c"interpreter-version".as_ptr(),
        2 => c"fixture-missing-property".as_ptr(),
        3 => c"default-script".as_ptr(),
        4 => c"fallback-script".as_ptr(),
        _ => c"fixture-missing-property".as_ptr(),
    }
}

fn debug_hook_action(case: &InputCase) -> Result<i32, String> {
    if case.case_id.contains(".stores_valid_hook")
        || case.case_id.contains(".debug_hook_index_import_contract")
    {
        Ok(1)
    } else if case.case_id.contains(".null_library_noop") {
        Ok(2)
    } else if case.case_id.contains(".invalid_index_or_null_hook_noop") {
        Ok(3)
    } else {
        Err(format!("unsupported debug hook case {}", case.case_id))
    }
}

fn debug_hook_library_present(params: &Value) -> i32 {
    if params
        .get("library")
        .and_then(Value::as_str)
        .is_some_and(|library| library == "null")
    {
        0
    } else {
        1
    }
}

fn debug_hook_class_name(class: FT_Int) -> &'static str {
    match class {
        1 => "hook_a",
        2 => "hook_b",
        3 => "other",
        _ => "null",
    }
}

fn debug_hook_snapshot_json(classes: [FT_Int; 4]) -> Value {
    json!(classes.map(debug_hook_class_name))
}

fn debug_hook_output(action: i32, before: [FT_Int; 4], after: [FT_Int; 4]) -> Value {
    match action {
        1 => json!({
            "return": "void",
            "debug_hooks_snapshot": debug_hook_snapshot_json(after),
            "stored_slot_identity": debug_hook_class_name(after[0])
        }),
        2 => json!({
            "return": "void",
            "crashed": false,
            "observable_writes": "none"
        }),
        3 => json!({
            "return": "void",
            "debug_hooks_before": debug_hook_snapshot_json(before),
            "debug_hooks_after": debug_hook_snapshot_json(after)
        }),
        _ => json!({ "return": "void" }),
    }
}

fn rust_set_debug_hook(case: &InputCase) -> Result<RunOutput, String> {
    let Ok(action) = debug_hook_action(case) else {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    };
    let mut library = if debug_hook_library_present(&case.inputs.params) != 0 {
        Some(FT_Init_FreeType())
    } else {
        None
    };
    if action == 3 {
        FT_Set_Debug_Hook(
            library.as_mut(),
            FT_DEBUG_HOOK_TRUETYPE as FT_UInt,
            Some(debug_hook_a),
        );
    }
    let before =
        FT_Library_Debug_Hook_Classes(library.as_ref(), Some(debug_hook_a), Some(debug_hook_b));
    match action {
        1 => FT_Set_Debug_Hook(
            library.as_mut(),
            FT_DEBUG_HOOK_TRUETYPE as FT_UInt,
            Some(debug_hook_a),
        ),
        3 => {
            FT_Set_Debug_Hook(library.as_mut(), 4, Some(debug_hook_b));
            FT_Set_Debug_Hook(library.as_mut(), FT_DEBUG_HOOK_TRUETYPE as FT_UInt, None);
        }
        _ => FT_Set_Debug_Hook(
            library.as_mut(),
            FT_DEBUG_HOOK_TRUETYPE as FT_UInt,
            Some(debug_hook_a),
        ),
    }
    let after =
        FT_Library_Debug_Hook_Classes(library.as_ref(), Some(debug_hook_a), Some(debug_hook_b));
    Ok(ok(debug_hook_output(action, before, after)))
}

fn c_set_debug_hook(case: &InputCase) -> Result<RunOutput, String> {
    let Ok(action) = debug_hook_action(case) else {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    };
    let mut library = std::ptr::null_mut();
    if debug_hook_library_present(&case.inputs.params) != 0 {
        let err = c_abi::FT_Init_FreeType(&mut library);
        if err != FT_Err_Ok {
            return Err(format!("FT_Init_FreeType returned {err}"));
        }
    }
    if action == 3 {
        c_abi::FT_Set_Debug_Hook(
            library,
            FT_DEBUG_HOOK_TRUETYPE as FT_UInt,
            Some(debug_hook_a),
        );
    }
    let before =
        c_abi::abi_support_debug_hook_classes(library, Some(debug_hook_a), Some(debug_hook_b));
    match action {
        1 => c_abi::FT_Set_Debug_Hook(
            library,
            FT_DEBUG_HOOK_TRUETYPE as FT_UInt,
            Some(debug_hook_a),
        ),
        3 => {
            c_abi::FT_Set_Debug_Hook(library, 4, Some(debug_hook_b));
            c_abi::FT_Set_Debug_Hook(library, FT_DEBUG_HOOK_TRUETYPE as FT_UInt, None);
        }
        _ => c_abi::FT_Set_Debug_Hook(
            library,
            FT_DEBUG_HOOK_TRUETYPE as FT_UInt,
            Some(debug_hook_a),
        ),
    }
    let after =
        c_abi::abi_support_debug_hook_classes(library, Some(debug_hook_a), Some(debug_hook_b));
    c_done_library(library);
    Ok(ok(debug_hook_output(action, before, after)))
}

fn wasm_set_debug_hook(case: &InputCase) -> Result<RunOutput, String> {
    let Ok(action) = debug_hook_action(case) else {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    };
    let (_library_present, before, after) = wasm_abi::abi_support_debug_hook_classes(
        debug_hook_library_present(&case.inputs.params),
        action,
    );
    Ok(ok(debug_hook_output(action, before, after)))
}

fn add_default_modules_action(case: &InputCase) -> Result<i32, String> {
    if case
        .case_id
        .contains("ftmodapi.FT_Add_Default_Modules.null_library_no_return_error")
    {
        Ok(1)
    } else if case
        .case_id
        .contains("ftmodapi.FT_Add_Default_Modules.installs_default_module_table")
    {
        Ok(2)
    } else {
        Err(format!(
            "unsupported FT_Add_Default_Modules case {}",
            case.case_id
        ))
    }
}

fn add_default_modules_output() -> Value {
    json!({
        "return": "void",
        "crashed": false,
        "observable_writes": "none"
    })
}

fn rust_add_default_modules(case: &InputCase) -> Result<RunOutput, String> {
    let Ok(action) = add_default_modules_action(case) else {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    };
    if action == 1 {
        FT_Add_Default_Modules(None);
        return Ok(ok(add_default_modules_output()));
    }
    let mut library = FT_New_Library_Without_Default_Modules();
    FT_Add_Default_Modules(Some(&mut library));
    Ok(ok(add_default_modules_observation(
        &case.inputs.params,
        FT_Library_Default_Module_Names(Some(&library)),
    )?))
}

fn c_add_default_modules(case: &InputCase) -> Result<RunOutput, String> {
    let Ok(action) = add_default_modules_action(case) else {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    };
    if action == 1 {
        c_abi::FT_Add_Default_Modules(std::ptr::null_mut());
        return Ok(ok(add_default_modules_output()));
    }
    let library = c_abi::abi_support_new_library_without_default_modules();
    c_abi::FT_Add_Default_Modules(library);
    let output = add_default_modules_observation(
        &case.inputs.params,
        c_abi::abi_support_library_default_module_names(library),
    )?;
    c_done_library(library);
    Ok(ok(output))
}

fn wasm_add_default_modules(case: &InputCase) -> Result<RunOutput, String> {
    let Ok(action) = add_default_modules_action(case) else {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    };
    if action == 1 {
        let crashed = wasm_abi::abi_support_add_default_modules(0);
        return Ok(ok(json!({
            "return": "void",
            "crashed": crashed,
            "observable_writes": "none"
        })));
    }
    let (_crashed, module_names) = wasm_abi::abi_support_add_default_modules_observation(1);
    Ok(ok(add_default_modules_observation(
        &case.inputs.params,
        module_names,
    )?))
}

fn add_default_modules_observation(params: &Value, module_names: &[&str]) -> Result<Value, String> {
    let probes = add_default_module_probe_names(params)?;
    let module_names_in_order = module_names
        .iter()
        .copied()
        .filter(|name| probes.iter().any(|probe| probe == name))
        .collect::<Vec<_>>();
    let mut lookup_results = serde_json::Map::new();
    for probe in probes {
        lookup_results.insert(probe.clone(), json!(module_names.contains(&probe.as_str())));
    }
    Ok(json!({
        "return": "void",
        "module_names_in_order": module_names_in_order,
        "lookup_results": lookup_results
    }))
}

fn add_default_module_probe_names(params: &Value) -> Result<Vec<String>, String> {
    array_param(params, "probe_names")?
        .iter()
        .map(|value| {
            value
                .as_str()
                .map(ToOwned::to_owned)
                .ok_or_else(|| format!("probe name must be a string, got {value}"))
        })
        .collect()
}

fn add_default_module_probe_names_arg(params: &Value) -> Result<String, String> {
    Ok(add_default_module_probe_names(params)?.join(","))
}

fn module_flag_value(symbol: &str) -> Result<FT_ULong, String> {
    let value = match symbol {
        "FT_MODULE_FONT_DRIVER" => FT_MODULE_FONT_DRIVER,
        "FT_MODULE_RENDERER" => FT_MODULE_RENDERER,
        "FT_MODULE_HINTER" => FT_MODULE_HINTER,
        "FT_MODULE_STYLER" => FT_MODULE_STYLER,
        "FT_MODULE_DRIVER_SCALABLE" => FT_MODULE_DRIVER_SCALABLE,
        "FT_MODULE_DRIVER_NO_OUTLINES" => FT_MODULE_DRIVER_NO_OUTLINES,
        "FT_MODULE_DRIVER_HAS_HINTER" => FT_MODULE_DRIVER_HAS_HINTER,
        "FT_MODULE_DRIVER_HINTS_LIGHTLY" => FT_MODULE_DRIVER_HINTS_LIGHTLY,
        other => return Err(format!("unsupported module flag {other}")),
    };
    Ok(value as FT_ULong)
}

fn module_flag_names(params: &Value) -> Result<Vec<String>, String> {
    if let Some(value) = params.get("module_names") {
        return value
            .as_array()
            .ok_or_else(|| "module_names must be an array".to_string())?
            .iter()
            .map(|value| {
                value
                    .as_str()
                    .map(ToOwned::to_owned)
                    .ok_or_else(|| format!("module name must be a string, got {value}"))
            })
            .collect();
    }
    Ok(vec![string_param(params, "module_name")?.to_string()])
}

fn module_flag_output<F>(params: &Value, mut flags_for: F) -> Result<Value, String>
where
    F: FnMut(&str) -> Option<FT_ULong>,
{
    let flag_symbol = string_param(params, "flag")?;
    let flag = module_flag_value(flag_symbol)?;
    let rows = module_flag_names(params)?
        .into_iter()
        .map(|module| {
            let flags = flags_for(&module);
            let flags_value = flags.unwrap_or(0);
            json!({
                "module": module,
                "present": flags.is_some(),
                "flags": flags_value,
                "has_flag": flags.is_some_and(|flags| flags & flag != 0),
            })
        })
        .collect::<Vec<_>>();
    Ok(json!({
        "flag": flag_symbol,
        "flag_value": flag,
        "modules": rows,
    }))
}

fn module_flag_names_arg(params: &Value) -> Result<String, String> {
    Ok(module_flag_names(params)?.join(","))
}

fn module_lookup_names(params: &Value) -> Result<Vec<String>, String> {
    if let Some(scenarios) = params.get("scenarios").and_then(Value::as_array) {
        return scenarios
            .iter()
            .map(|scenario| {
                let object = scenario
                    .as_object()
                    .ok_or_else(|| format!("module scenario must be an object, got {scenario}"))?;
                object
                    .get("module_name")
                    .and_then(Value::as_str)
                    .map(ToOwned::to_owned)
                    .ok_or_else(|| {
                        format!("module scenario missing string module_name: {scenario}")
                    })
            })
            .collect();
    }
    module_flag_names(params)
}

fn module_lookup_library_present(params: &Value) -> i32 {
    let library = lifecycle_handle_param(params, "library");
    if library == Some("null") {
        return 0;
    }
    if let Some(scenarios) = params.get("scenarios").and_then(Value::as_array) {
        if scenarios.iter().all(|scenario| {
            scenario
                .get("library")
                .and_then(Value::as_str)
                .is_some_and(|library| library == "null")
        }) {
            return 0;
        }
    }
    1
}

fn module_lookup_names_arg(params: &Value) -> Result<String, String> {
    Ok(module_lookup_names(params)?.join(","))
}

fn module_lookup_output<F>(params: &Value, mut present_for: F) -> Result<Value, String>
where
    F: FnMut(Option<&str>) -> bool,
{
    let rows = module_lookup_names(params)?
        .into_iter()
        .map(|module| {
            let module_name = if module == "null" {
                None
            } else {
                Some(module.as_str())
            };
            let present = present_for(module_name);
            json!({
                "module": module,
                "nullness": !present,
                "class_name": if present { module_name } else { None },
            })
        })
        .collect::<Vec<_>>();
    Ok(json!({ "lookups": rows }))
}

fn module_interface_service_names(params: &Value) -> Result<Vec<String>, String> {
    array_param(params, "service_names")?
        .iter()
        .map(|value| {
            value
                .as_str()
                .map(ToOwned::to_owned)
                .ok_or_else(|| format!("service name must be a string, got {value}"))
        })
        .collect()
}

fn module_interface_service_names_arg(params: &Value) -> Result<String, String> {
    Ok(module_interface_service_names(params)?.join(","))
}

fn module_interface_output<P, I, R>(
    params: &Value,
    mut present_for: P,
    mut interface_for: I,
    mut requester_for: R,
) -> Result<Value, String>
where
    P: FnMut(Option<&str>) -> bool,
    I: FnMut(Option<&str>) -> bool,
    R: FnMut(Option<&str>, &str) -> bool,
{
    let service_names = module_interface_service_names(params)?;
    let modules = module_lookup_names(params)?
        .into_iter()
        .map(|module| {
            let module_name = if module == "null" {
                None
            } else {
                Some(module.as_str())
            };
            let requester_result_class = service_names
                .iter()
                .map(|service| {
                    (
                        service.clone(),
                        if requester_for(module_name, service) {
                            json!("service_pointer")
                        } else {
                            json!("null")
                        },
                    )
                })
                .collect::<serde_json::Map<_, _>>();
            let callback_invocations = service_names
                .iter()
                .map(|service| {
                    json!({
                        "typedef": "FT_Module_Requester",
                        "name": service,
                        "status_or_nullness": requester_result_class
                            .get(service)
                            .cloned()
                            .unwrap_or_else(|| json!("null")),
                    })
                })
                .collect::<Vec<_>>();
            json!({
                "module": module,
                "module_found": present_for(module_name),
                "module_interface_nullness": !interface_for(module_name),
                "requester_result_class": requester_result_class,
                "callback_invocations": callback_invocations,
            })
        })
        .collect::<Vec<_>>();
    Ok(json!({ "modules": modules }))
}

fn rust_get_module(case: &InputCase) -> Result<RunOutput, String> {
    let library = if module_lookup_library_present(&case.inputs.params) != 0 {
        Some(FT_Init_FreeType())
    } else {
        None
    };
    Ok(ok(module_lookup_output(&case.inputs.params, |name| {
        name.is_some_and(|name| FT_Library_Has_Module(library.as_ref(), name))
    })?))
}

fn c_get_module(case: &InputCase) -> Result<RunOutput, String> {
    let mut library = std::ptr::null_mut();
    if module_lookup_library_present(&case.inputs.params) != 0 {
        let err = c_abi::FT_Init_FreeType(&mut library);
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
    }
    let output = module_lookup_output(&case.inputs.params, |name| {
        name.is_some_and(|name| c_abi::abi_support_library_has_module(library, name))
    })?;
    if !library.is_null() {
        c_done_library(library);
    }
    Ok(ok(output))
}

fn wasm_get_module(case: &InputCase) -> Result<RunOutput, String> {
    let library_present = module_lookup_library_present(&case.inputs.params);
    Ok(ok(module_lookup_output(&case.inputs.params, |name| {
        name.is_some_and(|name| wasm_abi::abi_support_default_module_present(library_present, name))
    })?))
}

fn rust_module_interface_probe(case: &InputCase) -> Result<RunOutput, String> {
    let library = if module_lookup_library_present(&case.inputs.params) != 0 {
        Some(FT_Init_FreeType())
    } else {
        None
    };
    Ok(ok(module_interface_output(
        &case.inputs.params,
        |name| name.is_some_and(|name| FT_Library_Has_Module(library.as_ref(), name)),
        |name| !FT_Get_Module_Interface(library.as_ref(), name).is_null(),
        |name, service| FT_Module_Requester_Service_Available(library.as_ref(), name, service),
    )?))
}

fn c_module_interface_probe(case: &InputCase) -> Result<RunOutput, String> {
    let mut library = std::ptr::null_mut();
    if module_lookup_library_present(&case.inputs.params) != 0 {
        let err = c_abi::FT_Init_FreeType(&mut library);
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
    }
    let output = module_interface_output(
        &case.inputs.params,
        |name| name.is_some_and(|name| c_abi::abi_support_library_has_module(library, name)),
        |name| c_abi::abi_support_module_interface_present(library, name),
        |name, service| {
            c_abi::abi_support_module_requester_service_available(library, name, service)
        },
    )?;
    if !library.is_null() {
        c_done_library(library);
    }
    Ok(ok(output))
}

fn wasm_module_interface_probe(case: &InputCase) -> Result<RunOutput, String> {
    let library_present = module_lookup_library_present(&case.inputs.params);
    Ok(ok(module_interface_output(
        &case.inputs.params,
        |name| {
            name.is_some_and(|name| {
                wasm_abi::abi_support_default_module_present(library_present, name)
            })
        },
        |name| wasm_abi::abi_support_module_interface_present(library_present, name),
        |name, service| {
            wasm_abi::abi_support_module_requester_service_available(library_present, name, service)
        },
    )?))
}

fn library_lifecycle_action(case: &InputCase) -> Result<i32, String> {
    match case.case_id.as_str() {
        "ftmodapi.FT_New_Library.creates_library_with_version_and_refcount" => Ok(1),
        "ftmodapi.FT_Reference_Library.increments_refcount" => Ok(2),
        "ftmodapi.FT_Done_Library.decrements_reference_without_destroying" => Ok(3),
        other => Err(format!("unsupported library lifecycle case {other}")),
    }
}

fn new_library_output(
    major: FT_Int,
    minor: FT_Int,
    patch: FT_Int,
    refcount_initial: usize,
    memory_pointer_identity: bool,
    default_modules_installed: bool,
) -> Value {
    json!({
        "status": FT_Err_Ok,
        "library_handle": {"nullness": false},
        "version_fields": {"major": major, "minor": minor, "patch": patch},
        "refcount_initial": refcount_initial,
        "memory_pointer_identity": memory_pointer_identity,
        "default_modules_installed": default_modules_installed,
    })
}

fn reference_library_output(
    reference_status: FT_Error,
    first_done_status: FT_Error,
    library_still_usable_after_first_done: bool,
    final_done_status: FT_Error,
) -> Value {
    json!({
        "reference_status": reference_status,
        "first_done_status": first_done_status,
        "library_still_usable_after_first_done": library_still_usable_after_first_done,
        "final_done_status": final_done_status,
    })
}

fn reference_then_done_library_output(
    reference_status: FT_Error,
    done_status: FT_Error,
    library_still_usable: bool,
    module_nullness: bool,
) -> Value {
    json!({
        "status_sequence": [reference_status, done_status],
        "library_still_usable": library_still_usable,
        "module_lookup_after_done": {"nullness": module_nullness},
    })
}

fn rust_library_lifecycle(case: &InputCase) -> Result<RunOutput, String> {
    match library_lifecycle_action(case)? {
        1 => {
            let mut memory = FT_MemoryRec::default();
            let mut library = FT_New_Library(Some(&mut memory))
                .map_err(|err| format!("FT_New_Library failed with {err}"))?;
            let mut major = -1;
            let mut minor = -1;
            let mut patch = -1;
            FT_Library_Version(
                Some(&library),
                Some(&mut major),
                Some(&mut minor),
                Some(&mut patch),
            );
            let refcount_initial = FT_Library_Refcount(Some(&library));
            let memory_pointer_identity = FT_Library_Memory(Some(&library)) == &mut memory;
            let default_modules_installed = FT_Library_Has_Module(Some(&library), "truetype");
            FT_Reference_Library(Some(&mut library));
            FT_Done_Library(Some(&mut library));
            FT_Done_Library(Some(&mut library));
            Ok(ok(new_library_output(
                major,
                minor,
                patch,
                refcount_initial,
                memory_pointer_identity,
                default_modules_installed,
            )))
        }
        2 => {
            let mut library = FT_New_Library_Without_Default_Modules();
            FT_Add_Default_Modules(Some(&mut library));
            let reference_status = FT_Reference_Library(Some(&mut library));
            let first_done_status = FT_Done_Library(Some(&mut library));
            let usable = FT_Library_Has_Module(Some(&library), "truetype");
            let final_done_status = FT_Done_Library(Some(&mut library));
            Ok(ok(reference_library_output(
                reference_status,
                first_done_status,
                usable,
                final_done_status,
            )))
        }
        3 => {
            let mut library = FT_New_Library_Without_Default_Modules();
            FT_Add_Default_Modules(Some(&mut library));
            let reference_status = FT_Reference_Library(Some(&mut library));
            let done_status = FT_Done_Library(Some(&mut library));
            let usable = FT_Library_Has_Module(Some(&library), "truetype");
            FT_Done_Library(Some(&mut library));
            Ok(ok(reference_then_done_library_output(
                reference_status,
                done_status,
                usable,
                !usable,
            )))
        }
        action => Err(format!("unsupported library lifecycle action {action}")),
    }
}

extern "C" fn c_library_alloc(_memory: c_abi::FT_Memory, size: c_long) -> FT_Pointer {
    let size = usize::try_from(size).unwrap_or(0);
    Box::into_raw(Box::new(vec![0_u8; size])).cast()
}

extern "C" fn c_library_free(_memory: c_abi::FT_Memory, block: FT_Pointer) {
    let _ = block;
}

fn c_library_lifecycle(case: &InputCase) -> Result<RunOutput, String> {
    let action = library_lifecycle_action(case)?;
    let mut memory = c_abi::FT_MemoryRec {
        user: ptr::null_mut(),
        alloc: Some(c_library_alloc),
        free: Some(c_library_free),
        realloc: None,
    };
    let mut library = ptr::null_mut();
    let err = c_abi::FT_New_Library(&mut memory, &mut library);
    if err != FT_Err_Ok {
        return Ok(error(err));
    }
    match action {
        1 => {
            let mut major = -1;
            let mut minor = -1;
            let mut patch = -1;
            c_abi::FT_Library_Version(library, &mut major, &mut minor, &mut patch);
            let refcount_initial = c_abi::abi_support_library_refcount(library);
            let memory_pointer_identity =
                c_abi::abi_support_library_memory_is(library, &mut memory);
            let default_modules_installed =
                c_abi::abi_support_library_has_module(library, "truetype");
            c_abi::FT_Reference_Library(library);
            c_abi::FT_Done_Library(library);
            let output = new_library_output(
                major,
                minor,
                patch,
                refcount_initial,
                memory_pointer_identity,
                default_modules_installed,
            );
            c_abi::FT_Done_Library(library);
            Ok(ok(output))
        }
        2 => {
            c_abi::FT_Add_Default_Modules(library);
            let reference_status = c_abi::FT_Reference_Library(library);
            let first_done_status = c_abi::FT_Done_Library(library);
            let usable = c_abi::abi_support_library_has_module(library, "truetype");
            let final_done_status = c_abi::FT_Done_Library(library);
            Ok(ok(reference_library_output(
                reference_status,
                first_done_status,
                usable,
                final_done_status,
            )))
        }
        3 => {
            c_abi::FT_Add_Default_Modules(library);
            let reference_status = c_abi::FT_Reference_Library(library);
            let done_status = c_abi::FT_Done_Library(library);
            let usable = c_abi::abi_support_library_has_module(library, "truetype");
            let output =
                reference_then_done_library_output(reference_status, done_status, usable, !usable);
            c_abi::FT_Done_Library(library);
            Ok(ok(output))
        }
        other => Err(format!("unsupported C library lifecycle action {other}")),
    }
}

fn wasm_library_lifecycle(case: &InputCase) -> Result<RunOutput, String> {
    match library_lifecycle_action(case)? {
        1 => {
            let (major, minor, patch, refcount, memory_identity, default_modules) =
                wasm_abi::abi_support_new_library_observation();
            Ok(ok(new_library_output(
                major,
                minor,
                patch,
                refcount,
                memory_identity,
                default_modules,
            )))
        }
        2 => {
            let (reference_status, first_done_status, usable, final_done_status) =
                wasm_abi::abi_support_reference_library_observation();
            Ok(ok(reference_library_output(
                reference_status,
                first_done_status,
                usable,
                final_done_status,
            )))
        }
        3 => {
            let (reference_status, done_status, usable, module_nullness) =
                wasm_abi::abi_support_reference_then_done_library_observation();
            Ok(ok(reference_then_done_library_output(
                reference_status,
                done_status,
                usable,
                module_nullness,
            )))
        }
        action => Err(format!(
            "unsupported WASM library lifecycle action {action}"
        )),
    }
}

fn rust_inspect_module_flags(case: &InputCase) -> Result<RunOutput, String> {
    let library = FT_Init_FreeType();
    Ok(ok(module_flag_output(&case.inputs.params, |name| {
        FT_Library_Module_Flags(Some(&library), name)
    })?))
}

fn c_inspect_module_flags(case: &InputCase) -> Result<RunOutput, String> {
    let mut library = std::ptr::null_mut();
    let err = c_abi::FT_Init_FreeType(&mut library);
    if err != FT_Err_Ok {
        return Ok(error(err));
    }
    let output = module_flag_output(&case.inputs.params, |name| {
        c_abi::abi_support_library_module_flags(library, name)
    })?;
    c_done_library(library);
    Ok(ok(output))
}

fn wasm_inspect_module_flags(case: &InputCase) -> Result<RunOutput, String> {
    Ok(ok(module_flag_output(&case.inputs.params, |name| {
        wasm_abi::abi_support_default_module_flags(name)
    })?))
}

fn renderer_format_value(value: &Value) -> Result<FT_Glyph_Format, String> {
    if let Some(text) = value.as_str() {
        return match text {
            "FT_GLYPH_FORMAT_OUTLINE" => Ok(FT_GLYPH_FORMAT_OUTLINE),
            "FT_GLYPH_FORMAT_BITMAP" => Ok(FT_GLYPH_FORMAT_BITMAP),
            "FT_GLYPH_FORMAT_SVG" => Ok(FT_GLYPH_FORMAT_SVG),
            "FT_GLYPH_FORMAT_NONE" => Ok(FT_GLYPH_FORMAT_NONE),
            "FT_MAKE_TAG('?', '?', '?', '?')" => Ok(0x3f3f_3f3f),
            other => {
                i64_value(&Value::String(other.to_string()), "renderer format").and_then(|format| {
                    FT_Glyph_Format::try_from(format).map_err(|err| {
                        format!("renderer format does not fit FT_Glyph_Format: {err}")
                    })
                })
            }
        };
    }
    let format = i64_value(value, "renderer format")?;
    FT_Glyph_Format::try_from(format)
        .map_err(|err| format!("renderer format does not fit FT_Glyph_Format: {err}"))
}

fn renderer_formats_param(params: &Value) -> Result<Vec<FT_Glyph_Format>, String> {
    if let Some(values) = params.get("formats").and_then(Value::as_array) {
        return values.iter().map(renderer_format_value).collect();
    }
    let value = params
        .get("format")
        .ok_or_else(|| "FT_Get_Renderer requires format or formats".to_string())?;
    Ok(vec![renderer_format_value(value)?])
}

fn renderer_formats_arg(params: &Value) -> Result<String, String> {
    Ok(renderer_formats_param(params)?
        .into_iter()
        .map(|format| format.to_string())
        .collect::<Vec<_>>()
        .join(","))
}

fn renderer_class_rows<F>(params: &Value, mut lookup: F) -> Result<Value, String>
where
    F: FnMut(FT_Glyph_Format) -> Option<(&'static str, FT_Glyph_Format, bool, bool)>,
{
    let rows = renderer_formats_param(params)?
        .into_iter()
        .map(|format| {
            if let Some((module_name, glyph_format, has_render_glyph, has_raster_class)) =
                lookup(format)
            {
                json!({
                    "format": format,
                    "renderer_present": true,
                    "renderer_class": {
                        "module_name": module_name,
                        "glyph_format": glyph_format,
                        "has_render_glyph": has_render_glyph,
                        "has_raster_class": has_raster_class,
                    },
                })
            } else {
                json!({
                    "format": format,
                    "renderer_present": false,
                    "renderer_class": null,
                })
            }
        })
        .collect::<Vec<_>>();
    Ok(json!({ "format_results": rows }))
}

fn rust_get_renderer(case: &InputCase) -> Result<RunOutput, String> {
    let library = if lifecycle_handle_param_is_null(&case.inputs.params, "library") {
        None
    } else {
        Some(FT_Init_FreeType())
    };
    Ok(ok(renderer_class_rows(&case.inputs.params, |format| {
        FT_Library_Renderer_Class(library.as_ref(), format)
    })?))
}

fn c_get_renderer(case: &InputCase) -> Result<RunOutput, String> {
    let mut library = std::ptr::null_mut();
    let use_null = lifecycle_handle_param_is_null(&case.inputs.params, "library");
    if !use_null {
        let err = c_abi::FT_Init_FreeType(&mut library);
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
    }
    let output = renderer_class_rows(&case.inputs.params, |format| {
        c_abi::abi_support_library_renderer_class(library, format)
    })?;
    c_done_library(library);
    Ok(ok(output))
}

fn wasm_get_renderer(case: &InputCase) -> Result<RunOutput, String> {
    let use_null = lifecycle_handle_param_is_null(&case.inputs.params, "library");
    Ok(ok(renderer_class_rows(&case.inputs.params, |format| {
        if use_null {
            wasm_abi::abi_support_null_renderer_class(format)
        } else {
            wasm_abi::abi_support_default_renderer_class(format)
        }
    })?))
}

fn done_mm_var_library_present(params: &Value) -> i32 {
    i32::from(!param_is_null(params, "library"))
}

fn done_mm_var_descriptor_present(params: &Value) -> i32 {
    i32::from(!param_is_null(params, "descriptor"))
}

fn done_mm_var_output(err: FT_Error, descriptor_present: i32) -> RunOutput {
    if err == FT_Err_Ok {
        ok(json!({
            "free_events": if descriptor_present != 0 { "descriptor" } else { "none" }
        }))
    } else {
        error(err)
    }
}

fn ftmm_get_and_done_mm_var_output(
    get_return: FT_Error,
    done_return: FT_Error,
    pointer_non_null: bool,
    before_count: usize,
    after_get_count: usize,
    after_done_count: usize,
) -> RunOutput {
    let output = json!({
        "get_return": get_return,
        "amaster_pointer": if pointer_non_null { "non_null" } else { "null" },
        "descriptor_pointer_identity": if pointer_non_null { "same_pointer" } else { "null" },
        "done_return": done_return,
        "allocation_events": if pointer_non_null && after_get_count > before_count {
            "descriptor_allocated"
        } else if pointer_non_null {
            "descriptor_available"
        } else {
            "none"
        },
        "free_event": if pointer_non_null && done_return == FT_Err_Ok && after_done_count <= before_count {
            "allocation_released"
        } else {
            "none"
        },
        "free_events": if pointer_non_null && done_return == FT_Err_Ok && after_done_count <= before_count {
            "allocation_released"
        } else {
            "none"
        },
    });
    if get_return == FT_Err_Ok && done_return == FT_Err_Ok {
        ok(output)
    } else {
        error_with_output(
            if get_return != FT_Err_Ok {
                get_return
            } else {
                done_return
            },
            output,
        )
    }
}

fn rust_ftmm_get_and_done_mm_var(case: &InputCase) -> Result<RunOutput, String> {
    let face = rust_new_face_without_size(case)?;
    let mut master = FT_MM_Var::default();
    let mut axes = vec![FT_Var_Axis::default(); 64];
    let mut namedstyles = vec![FT_Var_Named_Style::default(); 256];
    let mut namedstyle_coords = vec![FT_Fixed::default(); 64 * 256];
    let get_return = FT_Get_MM_Var(
        Some(&face),
        Some(&mut master),
        Some(&mut axes),
        Some(&mut namedstyles),
        Some(&mut namedstyle_coords),
    );
    let pointer_non_null = get_return == FT_Err_Ok;
    let done_return = if pointer_non_null {
        let library = FT_Init_FreeType();
        FT_Done_MM_Var(Some(&library), Some(&mut master))
    } else {
        FT_Err_Ok
    };
    Ok(ftmm_get_and_done_mm_var_output(
        get_return,
        done_return,
        pointer_non_null,
        0,
        usize::from(pointer_non_null),
        0,
    ))
}

fn c_ftmm_get_and_done_mm_var(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_new_face_without_size(case)?;
    let before_count = c_abi::abi_support_owned_mm_var_count();
    let mut master_ptr: *mut FT_MM_Var = std::ptr::null_mut();
    let get_return = c_abi::FT_Get_MM_Var(face, &mut master_ptr);
    let after_get_count = c_abi::abi_support_owned_mm_var_count();
    let pointer_non_null = !master_ptr.is_null();
    let done_return = if get_return == FT_Err_Ok {
        c_abi::FT_Done_MM_Var(library, master_ptr)
    } else {
        FT_Err_Ok
    };
    let after_done_count = c_abi::abi_support_owned_mm_var_count();
    c_done_face(face);
    c_done_library(library);
    Ok(ftmm_get_and_done_mm_var_output(
        get_return,
        done_return,
        pointer_non_null,
        before_count,
        after_get_count,
        after_done_count,
    ))
}

fn wasm_ftmm_get_and_done_mm_var(case: &InputCase) -> Result<RunOutput, String> {
    let handle = wasm_new_face_without_size(case)?;
    let mut master = FT_MM_Var::default();
    let mut axes = vec![FT_Var_Axis::default(); 64];
    let (get_return, done_return, before_count, after_get_count, after_done_count) =
        wasm_abi::abi_support_get_and_done_mm_var(
            handle,
            &mut master,
            axes.as_mut_ptr(),
            FT_UInt::try_from(axes.len()).unwrap_or(0),
        );
    let pointer_non_null = get_return == FT_Err_Ok;
    wasm_done_face(handle);
    Ok(ftmm_get_and_done_mm_var_output(
        get_return,
        done_return,
        pointer_non_null,
        before_count,
        after_get_count,
        after_done_count,
    ))
}

fn rust_done_mm_var(case: &InputCase) -> Result<RunOutput, String> {
    let library = (done_mm_var_library_present(&case.inputs.params) != 0).then(FT_Init_FreeType);
    let mut descriptor =
        (done_mm_var_descriptor_present(&case.inputs.params) != 0).then(FT_MM_Var::default);
    let err = FT_Done_MM_Var(library.as_ref(), descriptor.as_mut());
    Ok(done_mm_var_output(
        err,
        done_mm_var_descriptor_present(&case.inputs.params),
    ))
}

fn c_done_mm_var(case: &InputCase) -> Result<RunOutput, String> {
    let mut library = std::ptr::null_mut();
    if done_mm_var_library_present(&case.inputs.params) != 0 {
        let err = c_abi::FT_Init_FreeType(&mut library);
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
    }
    let mut descriptor = FT_MM_Var::default();
    let descriptor_ptr = if done_mm_var_descriptor_present(&case.inputs.params) != 0 {
        &mut descriptor
    } else {
        std::ptr::null_mut()
    };
    let err = c_abi::FT_Done_MM_Var(library, descriptor_ptr);
    if !library.is_null() {
        c_done_library(library);
    }
    Ok(done_mm_var_output(
        err,
        done_mm_var_descriptor_present(&case.inputs.params),
    ))
}

fn wasm_done_mm_var(case: &InputCase) -> Result<RunOutput, String> {
    let err = wasm_abi::abi_support_done_mm_var(
        done_mm_var_library_present(&case.inputs.params),
        done_mm_var_descriptor_present(&case.inputs.params),
    );
    Ok(done_mm_var_output(
        err,
        done_mm_var_descriptor_present(&case.inputs.params),
    ))
}

fn rust_done_freetype(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "library") == Some("null") {
        return Ok(lifecycle_result(FT_Done_FreeType(None)));
    }
    let data = font_bytes(case)?;
    let library = FT_Init_FreeType();
    let _face = FT_New_Memory_Face(
        &library,
        data.as_ref(),
        face_index_param(&case.inputs.params)?,
        20.0,
    )
    .map_err(|err| format!("FT_New_Memory_Face returned {err}"))?;
    Ok(lifecycle_result(FT_Done_FreeType(Some(library))))
}

fn c_done_freetype_output(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "library") == Some("null") {
        return Ok(lifecycle_result(c_abi::FT_Done_FreeType(
            std::ptr::null_mut(),
        )));
    }
    let bytes = font_bytes(case)?;
    let mut library = std::ptr::null_mut();
    let err = c_abi::FT_Init_FreeType(&mut library);
    if err != FT_Err_Ok {
        return Ok(error(err));
    }
    let mut face = std::ptr::null_mut();
    let file_size = i64::try_from(bytes.len()).map_err(|err| err.to_string())?;
    let err = c_abi::FT_New_Memory_Face(
        library,
        bytes.as_ptr(),
        file_size,
        face_index_param(&case.inputs.params)?,
        &mut face,
    );
    if err != FT_Err_Ok {
        c_done_library(library);
        return Ok(error(err));
    }
    Ok(lifecycle_result(c_abi::FT_Done_FreeType(library)))
}

fn wasm_done_freetype_output(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "library") == Some("null") {
        return Ok(lifecycle_result(wasm_abi::fontdone_wasm_done_freetype(0)));
    }
    let handle = wasm_new_face_without_size(case)?;
    wasm_done_face(handle);
    Ok(lifecycle_result(wasm_abi::fontdone_wasm_done_freetype(1)))
}

