fn rust_outline_operation(face: &FT_Face, case: &InputCase) -> Result<RunOutput, String> {
    match FT_Load_Glyph(
        face,
        glyph_index_param(&case.inputs.params)?,
        load_flags_param(&case.inputs.params)?,
    ) {
        Ok(slot) => {
            let outline_cbox = rust_outline_operation_cbox(&slot, case)?;
            let outline_bbox = rust_outline_operation_bbox(&slot, case)?;
            Ok(ok(outline_operation_output(
                case,
                slot.format,
                slot.outline.as_ref().map(outline_snapshot_json),
                bbox_from_rust_bbox(outline_bbox),
                bbox_from_rust_bbox(outline_cbox),
            )?))
        }
        Err(err) => Ok(error(err)),
    }
}

fn rust_outline_operation_cbox(slot: &FT_GlyphSlot, case: &InputCase) -> Result<FT_BBox, String> {
    if case.operation != "ftoutln.outline_get_cbox" {
        return Ok(slot.outline_cbox);
    }
    let Some(outline) = slot.outline.as_ref() else {
        return Err("outline_get_cbox missing outline snapshot".to_string());
    };
    let mut cbox = FT_BBox::default();
    FT_Outline_Get_CBox(Some(outline), Some(&mut cbox));
    if cbox != slot.outline_cbox {
        return Err(format!(
            "outline_get_cbox helper mismatch: helper={cbox:?} slot={:?}",
            slot.outline_cbox
        ));
    }
    Ok(cbox)
}

fn rust_outline_operation_bbox(slot: &FT_GlyphSlot, case: &InputCase) -> Result<FT_BBox, String> {
    if case.operation != "ftbbox.outline_get_bbox" {
        return Ok(slot.outline_bbox);
    }
    let Some(outline) = slot.outline.as_ref() else {
        return Err("outline_get_bbox missing outline snapshot".to_string());
    };
    let mut bbox = FT_BBox::default();
    let err = FT_Outline_Get_BBox(Some(outline), Some(&mut bbox));
    if err != FT_Err_Ok {
        return Err(format!("outline_get_bbox helper returned {err}"));
    }
    if bbox != slot.outline_bbox {
        return Err(format!(
            "outline_get_bbox helper mismatch: helper={bbox:?} slot={:?}",
            slot.outline_bbox
        ));
    }
    Ok(bbox)
}

fn c_outline_operation(face: c_abi::FT_Face, case: &InputCase) -> Result<RunOutput, String> {
    let err = c_abi::FT_Load_Glyph(
        face,
        glyph_index_param(&case.inputs.params)?,
        load_flags_param(&case.inputs.params)?,
    );
    if err != FT_Err_Ok {
        return Ok(error(err));
    }
    let slot = c_abi::abi_slot_snapshot(face)
        .ok_or_else(|| "missing c glyph slot snapshot".to_string())?;
    let outline_bbox = c_outline_operation_bbox(&slot, case)?;
    Ok(ok(outline_operation_output(
        case,
        slot.format,
        slot.outline.as_ref().map(outline_snapshot_json),
        bbox_from_c_bbox(outline_bbox),
        bbox_from_c_bbox(slot.outline_cbox),
    )?))
}

fn c_outline_operation_bbox(
    slot: &c_abi::AbiSlotSnapshot,
    case: &InputCase,
) -> Result<c_abi::FT_BBox, String> {
    if case.operation != "ftbbox.outline_get_bbox" {
        return Ok(slot.outline_bbox);
    }
    let Some(outline) = slot.outline.as_ref() else {
        return Err("c outline_get_bbox missing outline snapshot".to_string());
    };
    let mut points = outline
        .points
        .iter()
        .map(|point| c_abi::FT_Vector {
            x: point.x,
            y: point.y,
        })
        .collect::<Vec<_>>();
    let mut tags = outline.tags.clone();
    let mut contours = outline.contours.clone();
    let c_outline = c_abi::FT_Outline {
        n_contours: u16::try_from(contours.len()).unwrap_or(u16::MAX),
        n_points: u16::try_from(points.len()).unwrap_or(u16::MAX),
        points: points.as_mut_ptr(),
        tags: tags.as_mut_ptr(),
        contours: contours.as_mut_ptr(),
        flags: outline.flags,
    };
    let mut bbox = c_abi::FT_BBox::default();
    let err = c_abi::FT_Outline_Get_BBox(&c_outline, &mut bbox);
    if err != FT_Err_Ok {
        return Err(format!("c outline_get_bbox returned {err}"));
    }
    if bbox.xMin != slot.outline_bbox.xMin
        || bbox.yMin != slot.outline_bbox.yMin
        || bbox.xMax != slot.outline_bbox.xMax
        || bbox.yMax != slot.outline_bbox.yMax
    {
        return Err(format!(
            "c outline_get_bbox mismatch: helper={} slot={}",
            bbox_json(bbox_from_c_bbox(bbox)),
            bbox_json(bbox_from_c_bbox(slot.outline_bbox))
        ));
    }
    Ok(bbox)
}

fn wasm_outline_operation(handle: usize, case: &InputCase) -> Result<RunOutput, String> {
    let err = wasm_abi::fontdone_wasm_load_glyph(
        handle,
        glyph_index_param(&case.inputs.params)?,
        load_flags_param(&case.inputs.params)?,
    );
    if err != FT_Err_Ok {
        return Ok(error(err));
    }
    let slot = wasm_abi::abi_slot_snapshot(handle)
        .ok_or_else(|| "missing wasm glyph slot snapshot".to_string())?;
    let outline_bbox = wasm_outline_operation_bbox(&slot, case)?;
    Ok(ok(outline_operation_output(
        case,
        slot.format,
        slot.outline.as_ref().map(outline_snapshot_json),
        bbox_from_wasm_public_bbox(outline_bbox),
        bbox_from_wasm_bbox(slot.outline_cbox),
    )?))
}

fn wasm_outline_operation_bbox(
    slot: &wasm_abi::AbiSlotSnapshot,
    case: &InputCase,
) -> Result<wasm_abi::FontdoneWasmBBox, String> {
    if case.operation != "ftbbox.outline_get_bbox" {
        return Ok(wasm_abi::FontdoneWasmBBox {
            xMin: slot.outline_bbox.xMin,
            yMin: slot.outline_bbox.yMin,
            xMax: slot.outline_bbox.xMax,
            yMax: slot.outline_bbox.yMax,
        });
    }
    let Some(outline) = slot.outline.as_ref() else {
        return Err("wasm outline_get_bbox missing outline snapshot".to_string());
    };
    let mut points = outline
        .points
        .iter()
        .map(|point| wasm_abi::FontdoneWasmVector {
            x: point.x,
            y: point.y,
        })
        .collect::<Vec<_>>();
    let mut tags = outline.tags.clone();
    let mut contours = outline.contours.clone();
    let wasm_outline = wasm_abi::FontdoneWasmOutline {
        n_contours: u16::try_from(contours.len()).unwrap_or(u16::MAX),
        n_points: u16::try_from(points.len()).unwrap_or(u16::MAX),
        points: points.as_mut_ptr(),
        tags: tags.as_mut_ptr(),
        contours: contours.as_mut_ptr(),
        flags: outline.flags,
    };
    let mut bbox = wasm_abi::FontdoneWasmBBox::default();
    let err = wasm_abi::fontdone_wasm_outline_get_bbox(&wasm_outline, &mut bbox);
    if err != FT_Err_Ok {
        return Err(format!("wasm outline_get_bbox returned {err}"));
    }
    if bbox.xMin != slot.outline_bbox.xMin
        || bbox.yMin != slot.outline_bbox.yMin
        || bbox.xMax != slot.outline_bbox.xMax
        || bbox.yMax != slot.outline_bbox.yMax
    {
        return Err(format!(
            "wasm outline_get_bbox mismatch: helper={} slot={}",
            bbox_json(bbox_from_wasm_public_bbox(bbox)),
            bbox_json(JsonBBox {
                x_min: slot.outline_bbox.xMin,
                y_min: slot.outline_bbox.yMin,
                x_max: slot.outline_bbox.xMax,
                y_max: slot.outline_bbox.yMax,
            })
        ));
    }
    Ok(bbox)
}

fn glyph_transform_mutation_class(spec: GlyphTransformSpec) -> &'static str {
    match (spec.matrix.is_some(), spec.delta.is_some()) {
        (false, false) => "none",
        (false, true) => "delta_only",
        (true, false) => "matrix_only",
        (true, true) => "matrix_delta",
    }
}

fn glyph_transform_row_json(
    glyph_index: u32,
    transform_index: usize,
    status: FT_Error,
    outline: Option<Value>,
    advance: Option<Value>,
    cbox: Option<Value>,
    mutation_class: &str,
) -> Value {
    json!({
        "glyph_index": glyph_index,
        "transform_index": transform_index,
        "status": status,
        "outline": outline,
        "root": advance.map(|advance| json!({"advance": advance})),
        "cbox": cbox,
        "mutation_class": mutation_class
    })
}

fn glyph_transform_output(rows: Vec<Value>) -> RunOutput {
    ok(json!({ "rows": rows }))
}

fn rust_glyph_transform(case: &InputCase) -> Result<RunOutput, String> {
    let face = open_face(case)?;
    let params = &case.inputs.params;
    let load_flags = glyph_transform_load_flags(params)?;
    let transforms = glyph_transform_specs(params)?;
    let mut rows = Vec::new();
    for glyph_index in glyph_transform_indices(params)? {
        for (transform_index, spec) in transforms.iter().copied().enumerate() {
            let row = match FT_Load_Glyph(&face, glyph_index, load_flags) {
                Ok(slot) => match FT_Get_Outline_Glyph(Some(&slot)) {
                    Ok(mut glyph) => {
                        let status = FT_Glyph_Transform_Outline(
                            Some(&mut glyph),
                            spec.matrix.as_ref(),
                            spec.delta.as_ref(),
                        );
                        let mut cbox = FT_BBox::default();
                        FT_Outline_Glyph_CBox(Some(&glyph), 0, Some(&mut cbox));
                        glyph_transform_row_json(
                            glyph_index,
                            transform_index,
                            status,
                            Some(outline_snapshot_json(&glyph.outline)),
                            Some(json!({"x": glyph.root.advance.x, "y": glyph.root.advance.y})),
                            Some(bbox_json(bbox_from_rust_bbox(cbox))),
                            glyph_transform_mutation_class(spec),
                        )
                    }
                    Err(status) => glyph_transform_row_json(
                        glyph_index,
                        transform_index,
                        status,
                        None,
                        None,
                        None,
                        "error",
                    ),
                },
                Err(status) => glyph_transform_row_json(
                    glyph_index,
                    transform_index,
                    status,
                    None,
                    None,
                    None,
                    "error",
                ),
            };
            rows.push(row);
        }
    }
    Ok(glyph_transform_output(rows))
}

fn c_outline_record_json(outline: &c_abi::FT_Outline) -> Value {
    json!({
        "n_points": outline.n_points,
        "n_contours": outline.n_contours,
        "points": [],
        "tags": [],
        "contours": [],
        "flags": outline.flags
    })
}

fn c_glyph_transform(case: &InputCase) -> Result<RunOutput, String> {
    let (_library, face) = c_open_face(case)?;
    let params = &case.inputs.params;
    let load_flags = glyph_transform_load_flags(params)?;
    let transforms = glyph_transform_specs(params)?;
    let mut rows = Vec::new();
    for glyph_index in glyph_transform_indices(params)? {
        for (transform_index, spec) in transforms.iter().copied().enumerate() {
            let mut glyph: c_abi::FT_Glyph = ptr::null_mut();
            let mut status = c_abi::FT_Load_Glyph(face, glyph_index, load_flags);
            if status == FT_Err_Ok {
                match c_abi::abi_get_outline_glyph_from_face(face) {
                    Ok(created) => glyph = created,
                    Err(err) => status = err,
                }
            }
            let matrix = spec.matrix.map(|matrix| c_abi::FT_Matrix {
                xx: matrix.xx,
                xy: matrix.xy,
                yx: matrix.yx,
                yy: matrix.yy,
            });
            let delta = spec.delta.map(|delta| c_abi::FT_Vector {
                x: delta.x,
                y: delta.y,
            });
            if status == FT_Err_Ok {
                status = c_abi::FT_Glyph_Transform(
                    glyph,
                    matrix.as_ref().map_or(ptr::null(), ptr::from_ref),
                    delta.as_ref().map_or(ptr::null(), ptr::from_ref),
                );
            }
            let row = if status == FT_Err_Ok {
                let snapshot = c_abi::abi_outline_glyph_snapshot(glyph)
                    .ok_or_else(|| "missing c outline glyph snapshot".to_string())?;
                glyph_transform_row_json(
                    glyph_index,
                    transform_index,
                    status,
                    Some(outline_snapshot_json(&snapshot.outline)),
                    Some(json!({"x": snapshot.advance.x, "y": snapshot.advance.y})),
                    Some(bbox_json(bbox_from_c_bbox(snapshot.cbox))),
                    glyph_transform_mutation_class(spec),
                )
            } else {
                glyph_transform_row_json(
                    glyph_index,
                    transform_index,
                    status,
                    None,
                    None,
                    None,
                    "error",
                )
            };
            rows.push(row);
            if !glyph.is_null() {
                c_abi::FT_Done_Glyph(glyph);
            }
        }
    }
    c_done_face(face);
    Ok(glyph_transform_output(rows))
}

fn wasm_outline_record_json(outline: &wasm_abi::FontdoneWasmOutline) -> Value {
    json!({
        "n_points": outline.n_points,
        "n_contours": outline.n_contours,
        "points": [],
        "tags": [],
        "contours": [],
        "flags": outline.flags
    })
}

fn wasm_glyph_transform(case: &InputCase) -> Result<RunOutput, String> {
    let handle = wasm_open_face(case)?;
    let params = &case.inputs.params;
    let load_flags = glyph_transform_load_flags(params)?;
    let transforms = glyph_transform_specs(params)?;
    let mut rows = Vec::new();
    for glyph_index in glyph_transform_indices(params)? {
        for (transform_index, spec) in transforms.iter().copied().enumerate() {
            let mut glyph_handle = 0usize;
            let mut status = wasm_abi::fontdone_wasm_load_glyph(handle, glyph_index, load_flags);
            if status == FT_Err_Ok {
                status = wasm_abi::fontdone_wasm_get_glyph_from_face(handle, &mut glyph_handle);
            }
            let matrix = spec.matrix.map(|matrix| wasm_abi::FontdoneWasmMatrix {
                xx: matrix.xx,
                xy: matrix.xy,
                yx: matrix.yx,
                yy: matrix.yy,
            });
            let delta = spec.delta.map(|delta| wasm_abi::FontdoneWasmVector {
                x: delta.x,
                y: delta.y,
            });
            let glyph =
                ptr::with_exposed_provenance_mut::<wasm_abi::FontdoneWasmGlyph>(glyph_handle);
            if status == FT_Err_Ok {
                status = wasm_abi::fontdone_wasm_glyph_transform(
                    glyph,
                    matrix.as_ref().map_or(ptr::null(), ptr::from_ref),
                    delta.as_ref().map_or(ptr::null(), ptr::from_ref),
                );
            }
            let row = if status == FT_Err_Ok {
                let snapshot = wasm_abi::abi_outline_glyph_snapshot(glyph_handle)
                    .ok_or_else(|| "missing wasm outline glyph snapshot".to_string())?;
                glyph_transform_row_json(
                    glyph_index,
                    transform_index,
                    status,
                    Some(outline_snapshot_json(&snapshot.outline)),
                    Some(json!({"x": snapshot.advance.x, "y": snapshot.advance.y})),
                    Some(bbox_json(bbox_from_wasm_public_bbox(snapshot.cbox))),
                    glyph_transform_mutation_class(spec),
                )
            } else {
                glyph_transform_row_json(
                    glyph_index,
                    transform_index,
                    status,
                    None,
                    None,
                    None,
                    "error",
                )
            };
            rows.push(row);
            if glyph_handle != 0 {
                wasm_abi::fontdone_wasm_done_glyph_handle(glyph);
            }
        }
    }
    wasm_done_face(handle);
    Ok(glyph_transform_output(rows))
}

fn rust_glyph_to_bitmap(face: &FT_Face, case: &InputCase) -> Result<RunOutput, String> {
    let render_mode = render_mode_param(&case.inputs.params)?;
    let loaded = FT_Load_Glyph(
        face,
        glyph_index_param(&case.inputs.params)?,
        load_flags_param(&case.inputs.params)?,
    );
    match loaded.and_then(|slot| FT_Render_Glyph(slot, render_mode)) {
        Ok(slot) => Ok(ok(rust_bitmap_glyph_json(
            &slot,
            bool_param(&case.inputs.params, "destroy", false)?,
        ))),
        Err(err) => Ok(error(err)),
    }
}

fn c_glyph_to_bitmap(face: c_abi::FT_Face, case: &InputCase) -> Result<RunOutput, String> {
    let load_err = c_abi::FT_Load_Glyph(
        face,
        glyph_index_param(&case.inputs.params)?,
        load_flags_param(&case.inputs.params)?,
    );
    let err = if load_err == FT_Err_Ok {
        c_abi::abi_render_glyph_from_face(face, render_mode_param(&case.inputs.params)?)
    } else {
        load_err
    };
    if err != FT_Err_Ok {
        return Ok(error(err));
    }
    let slot = c_abi::abi_slot_snapshot(face)
        .ok_or_else(|| "missing c glyph slot snapshot".to_string())?;
    Ok(ok(c_bitmap_glyph_json(
        &slot,
        bool_param(&case.inputs.params, "destroy", false)?,
    )))
}

fn wasm_glyph_to_bitmap(handle: usize, case: &InputCase) -> Result<RunOutput, String> {
    let load_err = wasm_abi::fontdone_wasm_load_glyph(
        handle,
        glyph_index_param(&case.inputs.params)?,
        load_flags_param(&case.inputs.params)?,
    );
    let err = if load_err == FT_Err_Ok {
        wasm_abi::fontdone_wasm_render_glyph(handle, render_mode_param(&case.inputs.params)?)
    } else {
        load_err
    };
    if err != FT_Err_Ok {
        return Ok(error(err));
    }
    let slot = wasm_abi::abi_slot_snapshot(handle)
        .ok_or_else(|| "missing wasm glyph slot snapshot".to_string())?;
    Ok(ok(wasm_bitmap_glyph_json(
        &slot,
        bool_param(&case.inputs.params, "destroy", false)?,
    )))
}

