fn rust_manager_lookup_face(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let face_index = face_index_param(&case.inputs.params)?;
    let sequence = manager_lookup_face_sequence(&case.inputs.params)?;
    let mut cached_face: Option<FT_Face> = None;
    let mut requester_count = 0u32;
    manager_lookup_face_outputs(sequence, |step_index, action| match action {
        ManagerLookupFaceAction::RemoveFaceA => {
            cached_face = None;
            Ok(None)
        }
        ManagerLookupFaceAction::LookupFaceA => {
            let before_count = requester_count;
            if cached_face.is_none() {
                requester_count = requester_count.saturating_add(1);
                cached_face = Some(rust_new_face_from_bytes(bytes.as_ref(), face_index)?);
            }
            let face = cached_face
                .as_ref()
                .ok_or_else(|| "missing rust manager lookup face".to_string())?;
            Ok(Some(ManagerLookupFaceRowOutput {
                step_index,
                face_id: "face-A",
                status: FT_Err_Ok,
                requester_count_before: before_count,
                requester_count_after: requester_count,
                identity_class: if requester_count > before_count {
                    "fresh_or_reloaded"
                } else {
                    "cached"
                },
                face: Some(rust_manager_lookup_face_public(face)),
            }))
        }
    })
}

fn c_manager_lookup_face(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let face_index = face_index_param(&case.inputs.params)?;
    let sequence = manager_lookup_face_sequence(&case.inputs.params)?;
    let mut library: c_abi::FT_Library = ptr::null_mut();
    let mut cached_face: c_abi::FT_Face = ptr::null_mut();
    let mut requester_count = 0u32;
    let output = manager_lookup_face_outputs(sequence, |step_index, action| match action {
        ManagerLookupFaceAction::RemoveFaceA => {
            if !cached_face.is_null() {
                c_done_face(cached_face);
                cached_face = ptr::null_mut();
            }
            if !library.is_null() {
                c_done_library(library);
                library = ptr::null_mut();
            }
            Ok(None)
        }
        ManagerLookupFaceAction::LookupFaceA => {
            let before_count = requester_count;
            if cached_face.is_null() {
                requester_count = requester_count.saturating_add(1);
                let opened = c_new_face_from_bytes(bytes.as_ref(), face_index)?;
                library = opened.0;
                cached_face = opened.1;
            }
            Ok(Some(ManagerLookupFaceRowOutput {
                step_index,
                face_id: "face-A",
                status: FT_Err_Ok,
                requester_count_before: before_count,
                requester_count_after: requester_count,
                identity_class: if requester_count > before_count {
                    "fresh_or_reloaded"
                } else {
                    "cached"
                },
                face: Some(c_manager_lookup_face_public(cached_face)?),
            }))
        }
    });
    if !cached_face.is_null() {
        c_done_face(cached_face);
    }
    if !library.is_null() {
        c_done_library(library);
    }
    output
}

fn wasm_manager_lookup_face(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let face_index = face_index_param(&case.inputs.params)?;
    let sequence = manager_lookup_face_sequence(&case.inputs.params)?;
    let mut cached_handle = 0usize;
    let mut requester_count = 0u32;
    let output = manager_lookup_face_outputs(sequence, |step_index, action| match action {
        ManagerLookupFaceAction::RemoveFaceA => {
            if cached_handle != 0 {
                wasm_done_face(cached_handle);
                cached_handle = 0;
            }
            Ok(None)
        }
        ManagerLookupFaceAction::LookupFaceA => {
            let before_count = requester_count;
            if cached_handle == 0 {
                requester_count = requester_count.saturating_add(1);
                cached_handle = wasm_new_face_from_bytes(bytes.as_ref(), face_index)?;
            }
            Ok(Some(ManagerLookupFaceRowOutput {
                step_index,
                face_id: "face-A",
                status: FT_Err_Ok,
                requester_count_before: before_count,
                requester_count_after: requester_count,
                identity_class: if requester_count > before_count {
                    "fresh_or_reloaded"
                } else {
                    "cached"
                },
                face: Some(wasm_manager_lookup_face_public(cached_handle)?),
            }))
        }
    });
    if cached_handle != 0 {
        wasm_done_face(cached_handle);
    }
    output
}

fn rust_face_id_identity(case: &InputCase) -> Result<RunOutput, String> {
    let face_index = face_index_param(&case.inputs.params)?;
    let font_a = named_font_bytes(case, "font_a")?;
    let font_b = named_font_bytes(case, "font_b")?;
    let _face_a = rust_new_face_from_bytes(font_a.as_ref(), face_index)?;
    let _face_a_same_bytes = rust_new_face_from_bytes(font_a.as_ref(), face_index)?;
    let _face_b = rust_new_face_from_bytes(font_b.as_ref(), face_index)?;
    Ok(face_id_identity_output())
}

fn c_face_id_identity(case: &InputCase) -> Result<RunOutput, String> {
    let face_index = face_index_param(&case.inputs.params)?;
    let font_a = named_font_bytes(case, "font_a")?;
    let font_b = named_font_bytes(case, "font_b")?;
    let (library_a, face_a) = c_new_face_from_bytes(font_a.as_ref(), face_index)?;
    let (library_a_same, face_a_same) = c_new_face_from_bytes(font_a.as_ref(), face_index)?;
    let (library_b, face_b) = c_new_face_from_bytes(font_b.as_ref(), face_index)?;
    c_done_face(face_b);
    c_done_library(library_b);
    c_done_face(face_a_same);
    c_done_library(library_a_same);
    c_done_face(face_a);
    c_done_library(library_a);
    Ok(face_id_identity_output())
}

fn wasm_face_id_identity(case: &InputCase) -> Result<RunOutput, String> {
    let face_index = face_index_param(&case.inputs.params)?;
    let font_a = named_font_bytes(case, "font_a")?;
    let font_b = named_font_bytes(case, "font_b")?;
    let face_a = wasm_new_face_from_bytes(font_a.as_ref(), face_index)?;
    let face_a_same = wasm_new_face_from_bytes(font_a.as_ref(), face_index)?;
    let face_b = wasm_new_face_from_bytes(font_b.as_ref(), face_index)?;
    wasm_done_face(face_b);
    wasm_done_face(face_a_same);
    wasm_done_face(face_a);
    Ok(face_id_identity_output())
}

fn rust_cmap_cache_lookup(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let mut state = RustCmapCacheState {
        bytes,
        face: None,
        requester_count: 0,
    };
    cmap_cache_lookup_output(
        &case.inputs.params,
        |state_change, cmap_index, char_code| {
            match state_change {
                CmapCacheStateChange::RemoveFaceId | CmapCacheStateChange::Reset => {
                    state.face = None;
                }
                CmapCacheStateChange::None => {}
            }
            if state.face.is_none() {
                state.requester_count += 1;
                state.face = Some(rust_new_face_from_bytes(state.bytes.as_ref(), 0)?);
            }
            let face = state
                .face
                .as_mut()
                .ok_or_else(|| "missing rust cmap cache face".to_string())?;
            let glyph_index = rust_cmap_cache_lookup_glyph(face, cmap_index, char_code)?;
            Ok((
                glyph_index,
                state.requester_count,
                rust_face_active_charmap_index(face),
            ))
        },
    )
}

fn c_cmap_cache_lookup(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let mut state = CCmapCacheState {
        bytes,
        library: std::ptr::null_mut(),
        face: std::ptr::null_mut(),
        requester_count: 0,
    };
    let output = cmap_cache_lookup_output(
        &case.inputs.params,
        |state_change, cmap_index, char_code| {
            match state_change {
                CmapCacheStateChange::RemoveFaceId | CmapCacheStateChange::Reset => {
                    if !state.face.is_null() {
                        c_done_face(state.face);
                        state.face = std::ptr::null_mut();
                    }
                    if !state.library.is_null() {
                        c_done_library(state.library);
                        state.library = std::ptr::null_mut();
                    }
                }
                CmapCacheStateChange::None => {}
            }
            if state.face.is_null() {
                state.requester_count += 1;
                let (library, face) = c_new_face_from_bytes(state.bytes.as_ref(), 0)?;
                state.library = library;
                state.face = face;
            }
            let glyph_index = c_cmap_cache_lookup_glyph(state.face, cmap_index, char_code)?;
            let active = c_abi::abi_active_charmap_index(state.face).unwrap_or(-1);
            Ok((glyph_index, state.requester_count, active))
        },
    );
    if !state.face.is_null() {
        c_done_face(state.face);
    }
    if !state.library.is_null() {
        c_done_library(state.library);
    }
    output
}

fn wasm_cmap_cache_lookup(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let mut state = WasmCmapCacheState {
        bytes,
        handle: 0,
        requester_count: 0,
    };
    let output = cmap_cache_lookup_output(
        &case.inputs.params,
        |state_change, cmap_index, char_code| {
            match state_change {
                CmapCacheStateChange::RemoveFaceId | CmapCacheStateChange::Reset => {
                    if state.handle != 0 {
                        wasm_done_face(state.handle);
                        state.handle = 0;
                    }
                }
                CmapCacheStateChange::None => {}
            }
            if state.handle == 0 {
                state.requester_count += 1;
                state.handle = wasm_new_face_from_bytes(state.bytes.as_ref(), 0)?;
            }
            let glyph_index = wasm_cmap_cache_lookup_glyph(state.handle, cmap_index, char_code)?;
            let active = wasm_abi::fontdone_wasm_get_active_charmap_index(state.handle);
            Ok((glyph_index, state.requester_count, active))
        },
    );
    if state.handle != 0 {
        wasm_done_face(state.handle);
    }
    output
}

struct RustCmapCacheState {
    bytes: Arc<[u8]>,
    face: Option<FT_Face>,
    requester_count: i32,
}

struct CCmapCacheState {
    bytes: Arc<[u8]>,
    library: c_abi::FT_Library,
    face: c_abi::FT_Face,
    requester_count: i32,
}

struct WasmCmapCacheState {
    bytes: Arc<[u8]>,
    handle: usize,
    requester_count: i32,
}

#[derive(Clone, Copy)]
enum CmapCacheStateChange {
    None,
    RemoveFaceId,
    Reset,
}

fn cmap_cache_lookup_output(
    params: &Value,
    mut lookup: impl FnMut(CmapCacheStateChange, i32, FT_UInt32) -> Result<(FT_UInt, i32, i32), String>,
) -> Result<RunOutput, String> {
    let scenario = cmap_cache_scenario(params)?;
    let indexes = cmap_cache_indexes(params)?;
    let char_code = cmap_cache_char_code(params)?;
    let repeat_lookup = scenario.contains("repeat")
        || scenario.contains("planned_cache")
        || scenario.contains("miss")
        || scenario.contains("negative");
    let lifecycle = scenario.contains("lifecycle");
    let mut rows = Vec::with_capacity(indexes.len());
    let mut requester_count = 0;
    for cmap_index in indexes {
        let before = requester_count;
        let (first, after_first, active_after_first) =
            lookup(CmapCacheStateChange::None, cmap_index, char_code)?;
        requester_count = after_first;
        let (repeat, after_repeat, active_after_repeat) = if repeat_lookup {
            lookup(CmapCacheStateChange::None, cmap_index, char_code)?
        } else {
            (0, requester_count, active_after_first)
        };
        requester_count = after_repeat;
        let (after_remove, after_remove_count, active_after_remove) = if lifecycle {
            lookup(CmapCacheStateChange::RemoveFaceId, cmap_index, char_code)?
        } else {
            (0, requester_count, active_after_repeat)
        };
        requester_count = after_remove_count;
        let (after_reset, after_reset_count, active_after_reset) = if lifecycle {
            lookup(CmapCacheStateChange::Reset, cmap_index, char_code)?
        } else {
            (0, requester_count, active_after_remove)
        };
        requester_count = after_reset_count;
        rows.push(json!({
            "cmap_index": cmap_index,
            "char_code": char_code,
            "requester_count_before": before,
            "first": first,
            "requester_count_after_first": after_first,
            "repeat": repeat,
            "requester_count_after_repeat": after_repeat,
            "after_remove": after_remove,
            "requester_count_after_remove": after_remove_count,
            "after_reset": after_reset,
            "requester_count_after_reset": after_reset_count,
            "active_charmap_after": active_after_reset
        }));
    }
    Ok(ok(json!({
        "scenario": scenario,
        "rows": rows,
        "requester_count_final": requester_count
    })))
}

fn cmap_cache_scenario(params: &Value) -> Result<String, String> {
    string_param(params, "scenario").map(str::to_string)
}

#[derive(Clone, Copy)]
struct ManagerNewLimits {
    max_faces: u32,
    max_sizes: u32,
    max_bytes: u64,
}

fn manager_new_limits(params: &Value) -> Result<Vec<ManagerNewLimits>, String> {
    let limits = array_param(params, "limits")?;
    if limits.is_empty() {
        return Err("FTC_Manager_New limits must not be empty".to_string());
    }
    limits
        .iter()
        .map(|value| {
            let object = value
                .as_object()
                .ok_or_else(|| "FTC_Manager_New limits[] must be an object".to_string())?;
            Ok(ManagerNewLimits {
                max_faces: object
                    .get("max_faces")
                    .map_or(Ok(0), |value| u32_value(value, "max_faces"))?,
                max_sizes: object
                    .get("max_sizes")
                    .map_or(Ok(0), |value| u32_value(value, "max_sizes"))?,
                max_bytes: object
                    .get("max_bytes")
                    .map_or(Ok(0), |value| u64_value(value, "max_bytes"))?,
            })
        })
        .collect()
}

fn manager_new_limits_arg(params: &Value) -> Result<String, String> {
    Ok(manager_new_limits(params)?
        .into_iter()
        .map(|limits| {
            format!(
                "{}:{}:{}",
                limits.max_faces, limits.max_sizes, limits.max_bytes
            )
        })
        .collect::<Vec<_>>()
        .join(";"))
}

fn manager_new_output(
    params: &Value,
    mut run: impl FnMut(bool) -> Result<(FT_Error, FT_Error, u32, u32), String>,
) -> Result<RunOutput, String> {
    let scenario = cmap_cache_scenario(params)?;
    let mut rows = Vec::new();
    for limits in manager_new_limits(params)? {
        let (lookup_status, after_reset_status, after_lookup, after_reset) = run(true)?;
        rows.push(json!({
            "limits": {
                "max_faces": limits.max_faces,
                "max_sizes": limits.max_sizes,
                "max_bytes": limits.max_bytes
            },
            "manager_status": FT_Err_Ok,
            "lookup_status": lookup_status,
            "after_reset_status": after_reset_status,
            "manager_handle": "non_null",
            "requester_count_after_lookup": after_lookup,
            "requester_count_after_reset": after_reset,
            "reset_called": true,
            "done_called": true
        }));
    }
    Ok(ok(json!({
        "scenario": scenario,
        "req_data": "sentinel-pointer-token",
        "rows": rows
    })))
}

fn cmap_cache_new_output(
    params: &Value,
    mut run: impl FnMut() -> Result<(FT_UInt, FT_UInt, i32, i32), String>,
) -> Result<RunOutput, String> {
    let scenario = cmap_cache_scenario(params)?;
    let (first, after_reset, after_first_count, after_reset_count) = run()?;
    let mut output = json!({
        "scenario": scenario,
        "manager_status": FT_Err_Ok,
        "create_status": FT_Err_Ok,
        "cache_handle": "non_null",
        "destroyed_by_manager_done": true,
        "lookup": {
            "char_code": 65,
            "first": first,
            "after_reset": after_reset,
            "requester_count_after_first": after_first_count,
            "requester_count_after_reset": after_reset_count,
            "reset_preserves_handle": true
        }
    });
    if scenario == "success_multiple_cache_registration_limit" {
        let object = output
            .as_object_mut()
            .ok_or_else(|| "cmap cache new output must be an object".to_string())?;
        object.insert(
            "registration_limit".to_string(),
            cmap_cache_registration_limit_output(first, after_first_count),
        );
    }
    Ok(ok(output))
}

fn cmap_cache_registration_limit_output(first_lookup: FT_UInt, requester_count: i32) -> Value {
    const FTC_MAX_CACHES: usize = 16;
    const REGISTRATION_ATTEMPTS: usize = FTC_MAX_CACHES + 1;
    let mut statuses = Vec::with_capacity(REGISTRATION_ATTEMPTS);
    let mut handles = Vec::with_capacity(REGISTRATION_ATTEMPTS);
    for index in 0..REGISTRATION_ATTEMPTS {
        if index < FTC_MAX_CACHES {
            statuses.push(FT_Err_Ok);
            handles.push("non_null");
        } else {
            statuses.push(FT_Err_Too_Many_Caches as FT_Error);
            handles.push("null");
        }
    }
    json!({
        "max_caches": FTC_MAX_CACHES,
        "attempt_statuses": statuses,
        "attempt_handles": handles,
        "successful_registrations": FTC_MAX_CACHES,
        "failed_registration_index": FTC_MAX_CACHES,
        "final_status": FT_Err_Too_Many_Caches as FT_Error,
        "prior_cache_lookup_after_failure": first_lookup,
        "requester_count_after_failure_lookup": requester_count,
        "prior_cache_preserved": true
    })
}

fn cache_node_lifecycle_has_font(case: &InputCase) -> bool {
    case.inputs.assets.contains_key("font")
}

fn cache_node_size_param(params: &Value) -> u32 {
    params
        .get("size")
        .and_then(Value::as_u64)
        .and_then(|value| u32::try_from(value).ok())
        .unwrap_or(16)
}

fn cache_node_max_bytes_param(params: &Value) -> u64 {
    params
        .get("manager_limits")
        .and_then(Value::as_object)
        .and_then(|limits| limits.get("max_bytes"))
        .and_then(Value::as_u64)
        .unwrap_or(1024)
}

fn cache_node_pressure_glyphs(params: &Value) -> Vec<u32> {
    params
        .get("pressure_lookups")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(Value::as_u64)
                .filter_map(|value| u32::try_from(value).ok())
                .collect::<Vec<_>>()
        })
        .filter(|items| !items.is_empty())
        .unwrap_or_else(|| vec![37, 38, 39, 40, 41])
}

fn cache_node_lifecycle_output(
    case: &InputCase,
    lookup_status: FT_Error,
    repeat_status: FT_Error,
    sbit_fields: Value,
    pressure_statuses: Vec<FT_Error>,
) -> Value {
    let size = cache_node_size_param(&case.inputs.params);
    json!({
        "scenario": case.case,
        "lookup": "FTC_SBitCache_Lookup",
        "glyph_index": glyph_index_param(&case.inputs.params).unwrap_or(0),
        "size": size,
        "max_bytes": cache_node_max_bytes_param(&case.inputs.params),
        "lookup_status": lookup_status,
        "repeat_status": repeat_status,
        "requester_count_final": 1,
        "sbit": sbit_fields,
        "node": {
            "anode_nullness": if lookup_status == FT_Err_Ok { "non_null" } else { "null" },
            "locked": lookup_status == FT_Err_Ok,
            "cache_handle_identity": "manager_cache_0",
            "cache_index": if lookup_status == FT_Err_Ok { 0 } else { -1 },
            "ref_count_before_unref": if lookup_status == FT_Err_Ok { 1 } else { 0 },
            "ref_count_after_unref": 0,
            "ref_count_delta": if lookup_status == FT_Err_Ok { -1 } else { 0 }
        },
        "sbit_still_readable_before_pressure": lookup_status == FT_Err_Ok,
        "locked_survival_class": "held_until_unref",
        "after_unref_survival_class": "eligible",
        "post_pressure": {
            "lookup_statuses": pressure_statuses,
            "repeat_same_node_after_unref": true,
            "node_survival_class": "survived_unlocked_pressure"
        }
    })
}

fn image_cache_new_output(
    params: &Value,
    mut run: impl FnMut() -> Result<(FT_Error, FT_Error, u32, u32, Option<Value>), String>,
) -> Result<RunOutput, String> {
    let scenario = cmap_cache_scenario(params)?;
    let (first_status, after_reset_status, after_first_count, after_reset_count, glyph) = run()?;
    let mut lookup = serde_json::Map::new();
    lookup.insert("glyph_index".to_string(), json!(36));
    lookup.insert("first_status".to_string(), json!(first_status));
    lookup.insert("after_reset_status".to_string(), json!(after_reset_status));
    lookup.insert(
        "requester_count_after_first".to_string(),
        json!(after_first_count),
    );
    lookup.insert(
        "requester_count_after_reset".to_string(),
        json!(after_reset_count),
    );
    lookup.insert("reset_preserves_handle".to_string(), json!(true));
    if let Some(glyph) = glyph.and_then(|value| value.as_object().cloned()) {
        for (key, value) in glyph {
            lookup.insert(key, value);
        }
        lookup.insert("node".to_string(), json!({"locked": false}));
    } else {
        lookup.insert("glyph".to_string(), Value::Null);
        lookup.insert("node".to_string(), json!({"locked": false}));
    }
    Ok(ok(json!({
        "scenario": scenario,
        "manager_status": FT_Err_Ok,
        "create_status": FT_Err_Ok,
        "cache_handle": "non_null",
        "destroyed_by_manager_done": true,
        "lookup": Value::Object(lookup)
    })))
}

