fn ftc_sbit_fields_from_rendered_bitmap(mut fields: Value) -> Value {
    if let Some(object) = fields.as_object_mut() {
        // FTC_SBitCache_LookupScaler returns FTC_SBitRec, not FT_GlyphSlot.
        // C FreeType 2.14.3 ftcsbits.c stores grayscale `max_grays` as the
        // maximum sample value; the FT_Bitmap slot records `num_grays` as the
        // count of gray levels.  A normal 8-bit gray bitmap is therefore
        // FTC_SBit.max_grays=255 and FT_Bitmap.num_grays=256.
        if object
            .get("max_grays")
            .and_then(Value::as_u64)
            .is_some_and(|value| value == 256)
        {
            object.insert("max_grays".to_string(), json!(255));
        }
    }
    fields
}

fn sbit_json(
    width: u32,
    height: u32,
    left: i32,
    top: i32,
    mut format: i32,
    mut max_grays: u16,
    pitch: i32,
    xadvance: i64,
    yadvance: i64,
    buffer: Option<&[u8]>,
) -> Value {
    let buffer = buffer.filter(|buffer| !buffer.is_empty());
    if buffer.is_none() && format == FT_PIXEL_MODE_NONE && max_grays == 0 {
        format = FT_PIXEL_MODE_GRAY;
        max_grays = 256;
    }
    json!({
        "sbit": {
            "width": width,
            "height": height,
            "left": left,
            "top": top,
            "format": format,
            "max_grays": max_grays,
            "pitch": pitch,
            "xadvance": xadvance,
            "yadvance": yadvance,
            "buffer_null": buffer.is_none(),
            "buffer_hex": buffer.map_or_else(String::new, hex_bytes)
        },
        "node": {
            "locked": false
        }
    })
}

fn glyph_record_json(format: i32, advance_x: i64, advance_y: i64) -> Value {
    json!({
        "glyph": {
            "format": format,
            "advance": {
                "x": glyph_advance_16dot16(advance_x),
                "y": glyph_advance_16dot16(advance_y)
            },
            "library_present": true,
            "clazz_present": true
        }
    })
}

fn glyph_record_action(operation: &str) -> &'static str {
    match operation {
        "ftglyph.glyph_copy" => "copy",
        "ftglyph.get_glyph" => "get",
        _ => "record",
    }
}

fn rust_bitmap_glyph_json(slot: &FT_GlyphSlot, destroy: bool) -> Value {
    let bitmap = slot.bitmap.as_ref().map_or(Value::Null, |bitmap| {
        json!({
            "width": bitmap.width,
            "rows": bitmap.rows,
            "pitch": bitmap.pitch,
            "pixel_mode": bitmap.pixel_mode,
            "num_grays": bitmap.num_grays,
            "left": slot.bitmap_left,
            "top": slot.bitmap_top,
            "buffer_hex": hex_bytes(&bitmap.buffer)
        })
    });
    bitmap_glyph_json(
        slot.format,
        i64::from(slot.advance.x),
        i64::from(slot.advance.y),
        destroy,
        bitmap,
    )
}

