fn bitmap_glyph_json(
    format: i32,
    advance_x: i64,
    advance_y: i64,
    destroy: bool,
    bitmap: Value,
) -> Value {
    json!({
        "format": format,
        "advance": {
            "x": glyph_advance_16dot16(advance_x),
            "y": glyph_advance_16dot16(advance_y)
        },
        "destroy": destroy,
        "bitmap": bitmap
    })
}

fn glyph_advance_16dot16(value: i64) -> i64 {
    value.saturating_mul(1024)
}

