fn outline_operation_output(
    case: &InputCase,
    slot_format: i32,
    outline: Option<Value>,
    bbox: JsonBBox,
    cbox: JsonBBox,
) -> Result<Value, String> {
    match case.operation.as_str() {
        "freetype.load_glyph_outline" => Ok(json!({
            "slot_format": slot_format,
            "outline": outline.unwrap_or_else(empty_outline_json),
            "cbox": bbox_json(cbox)
        })),
        "ftbbox.outline_get_bbox" => Ok(json!({
            "bbox_error": FT_Err_Ok,
            "bbox": bbox_json(bbox),
            "cbox": bbox_json(cbox)
        })),
        "ftoutln.outline_get_cbox" => Ok(json!({
            "cbox": bbox_json(cbox)
        })),
        "ftglyph.glyph_get_cbox" => Ok(json!({
            "boxes": bbox_modes_param(&case.inputs.params)?
                .into_iter()
                .map(|mode| json!({"mode": mode as u32, "bbox": bbox_json(apply_bbox_mode(cbox, mode))}))
                .collect::<Vec<_>>()
        })),
        other => Err(format!("unsupported outline operation {other}")),
    }
}

fn outline_snapshot_json(outline: &FT_OutlineSnapshot) -> Value {
    json!({
        "n_points": outline.points.len(),
        "n_contours": outline.contours.len(),
        "points": outline.points
            .iter()
            .map(|point| json!({"x": point.x, "y": point.y}))
            .collect::<Vec<_>>(),
        "tags": outline.tags,
        "contours": outline.contours,
        "flags": outline.flags
    })
}

fn empty_outline_json() -> Value {
    json!({
        "n_points": 0,
        "n_contours": 0,
        "points": [],
        "tags": [],
        "contours": [],
        "flags": 0
    })
}

fn bbox_json(bbox: JsonBBox) -> Value {
    json!({
        "xMin": bbox.x_min,
        "yMin": bbox.y_min,
        "xMax": bbox.x_max,
        "yMax": bbox.y_max
    })
}

fn apply_bbox_mode(bbox: JsonBBox, mode: i32) -> JsonBBox {
    match mode {
        1 => JsonBBox {
            x_min: pix_floor(bbox.x_min),
            y_min: pix_floor(bbox.y_min),
            x_max: pix_ceil(bbox.x_max),
            y_max: pix_ceil(bbox.y_max),
        },
        2 => JsonBBox {
            x_min: bbox.x_min >> 6,
            y_min: bbox.y_min >> 6,
            x_max: bbox.x_max >> 6,
            y_max: bbox.y_max >> 6,
        },
        3 => {
            let gridfit = apply_bbox_mode(bbox, 1);
            JsonBBox {
                x_min: gridfit.x_min >> 6,
                y_min: gridfit.y_min >> 6,
                x_max: gridfit.x_max >> 6,
                y_max: gridfit.y_max >> 6,
            }
        }
        _ => bbox,
    }
}

fn pix_floor(value: i64) -> i64 {
    value & !63
}

fn pix_ceil(value: i64) -> i64 {
    (value + 63) & !63
}

#[derive(Debug, Clone, Copy)]
struct FtsynthSlantRow {
    glyph_index: u32,
    load_flags: i32,
    xslant: i64,
    yslant: i64,
}

fn ftsynth_slant_rows_arg(params: &Value, oblique: bool) -> Result<String, String> {
    Ok(ftsynth_slant_rows(params, oblique)?
        .into_iter()
        .map(|row| {
            format!(
                "{}:{}:{}:{}",
                row.glyph_index, row.load_flags, row.xslant, row.yslant
            )
        })
        .collect::<Vec<_>>()
        .join(","))
}

fn ftsynth_slant_rows(params: &Value, oblique: bool) -> Result<Vec<FtsynthSlantRow>, String> {
    let load = params.get("load").unwrap_or(params);
    let load_flags = load_flags_param(load)?;
    let glyph_indices = if let Some(values) = load.get("glyph_indices").and_then(Value::as_array) {
        values
            .iter()
            .enumerate()
            .map(|(index, value)| u32_value(value, &format!("glyph_indices[{index}]")))
            .collect::<Result<Vec<_>, _>>()?
    } else if let Some(value) = load.get("glyph_index") {
        vec![u32_value(value, "glyph_index")?]
    } else {
        vec![glyph_index_param(load)?]
    };
    if glyph_indices.is_empty() {
        return Err("ftsynth slant rows require at least one glyph index".to_string());
    }

    let slants = if oblique {
        vec![(0x0366A, 0)]
    } else if let Some(values) = params.get("slants").and_then(Value::as_array) {
        values
            .iter()
            .enumerate()
            .map(|(index, value)| ftsynth_slant_value(value, &format!("slants[{index}]")))
            .collect::<Result<Vec<_>, _>>()?
    } else {
        vec![ftsynth_slant_value(params, "slant")?]
    };
    if slants.is_empty() {
        return Err("ftsynth slant rows require at least one slant".to_string());
    }

    let mut rows = Vec::new();
    for glyph_index in glyph_indices {
        for (xslant, yslant) in &slants {
            rows.push(FtsynthSlantRow {
                glyph_index,
                load_flags,
                xslant: *xslant,
                yslant: *yslant,
            });
        }
    }
    Ok(rows)
}

fn ftsynth_slant_value(value: &Value, label: &str) -> Result<(i64, i64), String> {
    let xslant = value
        .get("xslant_16_16")
        .map(|value| i64_value(value, &format!("{label}.xslant_16_16")))
        .transpose()?
        .unwrap_or(0);
    let yslant = value
        .get("yslant_16_16")
        .map(|value| i64_value(value, &format!("{label}.yslant_16_16")))
        .transpose()?
        .unwrap_or(0);
    Ok((xslant, yslant))
}

#[derive(Debug, Clone, Copy)]
struct FtsynthWeightRow {
    glyph_index: u32,
    load_flags: i32,
    xdelta: i64,
    ydelta: i64,
}

fn ftsynth_weight_rows_arg(params: &Value, embolden: bool) -> Result<String, String> {
    Ok(ftsynth_weight_rows(params, embolden)?
        .into_iter()
        .map(|row| {
            format!(
                "{}:{}:{}:{}",
                row.glyph_index, row.load_flags, row.xdelta, row.ydelta
            )
        })
        .collect::<Vec<_>>()
        .join(","))
}

fn ftsynth_weight_rows(params: &Value, embolden: bool) -> Result<Vec<FtsynthWeightRow>, String> {
    let load = params.get("load").unwrap_or(params);
    let load_flags = load_flags_param(load)?;
    let glyph_indices = if let Some(values) = load.get("glyph_indices").and_then(Value::as_array) {
        values
            .iter()
            .enumerate()
            .map(|(index, value)| u32_value(value, &format!("glyph_indices[{index}]")))
            .collect::<Result<Vec<_>, _>>()?
    } else if let Some(value) = load.get("glyph_index") {
        vec![u32_value(value, "glyph_index")?]
    } else {
        vec![glyph_index_param(load)?]
    };
    if glyph_indices.is_empty() {
        return Err("ftsynth weight rows require at least one glyph index".to_string());
    }

    let adjustments = if embolden {
        let strength = params
            .get("compare_with_adjust_weight_strength")
            .map(|value| i64_value(value, "compare_with_adjust_weight_strength"))
            .transpose()?
            .unwrap_or(0x0AAA);
        vec![(strength, strength)]
    } else if let Some(values) = params.get("adjustments").and_then(Value::as_array) {
        values
            .iter()
            .enumerate()
            .map(|(index, value)| ftsynth_weight_value(value, &format!("adjustments[{index}]")))
            .collect::<Result<Vec<_>, _>>()?
    } else {
        vec![ftsynth_weight_value(params, "adjustment")?]
    };
    if adjustments.is_empty() {
        return Err("ftsynth weight rows require at least one adjustment".to_string());
    }

    let mut rows = Vec::new();
    for glyph_index in glyph_indices {
        for (xdelta, ydelta) in &adjustments {
            rows.push(FtsynthWeightRow {
                glyph_index,
                load_flags,
                xdelta: *xdelta,
                ydelta: *ydelta,
            });
        }
    }
    Ok(rows)
}

fn ftsynth_weight_value(value: &Value, label: &str) -> Result<(i64, i64), String> {
    let xdelta = value
        .get("xdelta_16_16")
        .map(|value| i64_value(value, &format!("{label}.xdelta_16_16")))
        .transpose()?
        .unwrap_or(0);
    let ydelta = value
        .get("ydelta_16_16")
        .map(|value| i64_value(value, &format!("{label}.ydelta_16_16")))
        .transpose()?
        .unwrap_or(0);
    Ok((xdelta, ydelta))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum FtsynthNullNoopFunction {
    AdjustWeight,
    Embolden,
    Oblique,
    Slant,
}

impl FtsynthNullNoopFunction {
    fn as_str(self) -> &'static str {
        match self {
            Self::AdjustWeight => "FT_GlyphSlot_AdjustWeight",
            Self::Embolden => "FT_GlyphSlot_Embolden",
            Self::Oblique => "FT_GlyphSlot_Oblique",
            Self::Slant => "FT_GlyphSlot_Slant",
        }
    }
}

#[derive(Debug, Clone, Copy)]
struct FtsynthNullNoop {
    function: FtsynthNullNoopFunction,
    first: i64,
    second: i64,
}

fn ftsynth_null_noop_param(params: &Value) -> Result<FtsynthNullNoop, String> {
    let function = match string_param(params, "function")? {
        "FT_GlyphSlot_AdjustWeight" => FtsynthNullNoopFunction::AdjustWeight,
        "FT_GlyphSlot_Embolden" => FtsynthNullNoopFunction::Embolden,
        "FT_GlyphSlot_Oblique" => FtsynthNullNoopFunction::Oblique,
        "FT_GlyphSlot_Slant" => FtsynthNullNoopFunction::Slant,
        other => return Err(format!("unsupported ftsynth null no-op function {other}")),
    };
    let (first, second) = match function {
        FtsynthNullNoopFunction::AdjustWeight => ftsynth_weight_value(params, "adjustment")?,
        FtsynthNullNoopFunction::Slant => ftsynth_slant_value(params, "slant")?,
        FtsynthNullNoopFunction::Embolden | FtsynthNullNoopFunction::Oblique => (0, 0),
    };
    Ok(FtsynthNullNoop {
        function,
        first,
        second,
    })
}

fn ftsynth_null_noop_oracle_args(params: &Value) -> Result<Vec<String>, String> {
    let row = ftsynth_null_noop_param(params)?;
    Ok(vec![
        "--glyphslot-null-noop".to_string(),
        row.function.as_str().to_string(),
        row.first.to_string(),
        row.second.to_string(),
    ])
}

fn ftsynth_null_noop_output(row: FtsynthNullNoop) -> RunOutput {
    ok(json!({
        "function": row.function.as_str(),
        "slot": "null",
        "first": row.first,
        "second": row.second,
        "completed": true
    }))
}

fn rust_ftsynth_null_noop(case: &InputCase) -> Result<RunOutput, String> {
    let row = ftsynth_null_noop_param(&case.inputs.params)?;
    match row.function {
        FtsynthNullNoopFunction::AdjustWeight => {
            FT_GlyphSlot_AdjustWeight(None, row.first, row.second);
        }
        FtsynthNullNoopFunction::Embolden => FT_GlyphSlot_Embolden(None),
        FtsynthNullNoopFunction::Oblique => FT_GlyphSlot_Oblique(None),
        FtsynthNullNoopFunction::Slant => FT_GlyphSlot_Slant(None, row.first, row.second),
    }
    Ok(ftsynth_null_noop_output(row))
}

fn c_ftsynth_null_noop(case: &InputCase) -> Result<RunOutput, String> {
    let row = ftsynth_null_noop_param(&case.inputs.params)?;
    match row.function {
        FtsynthNullNoopFunction::AdjustWeight => {
            c_abi::FT_GlyphSlot_AdjustWeight(ptr::null_mut(), row.first, row.second);
        }
        FtsynthNullNoopFunction::Embolden => c_abi::FT_GlyphSlot_Embolden(ptr::null_mut()),
        FtsynthNullNoopFunction::Oblique => c_abi::FT_GlyphSlot_Oblique(ptr::null_mut()),
        FtsynthNullNoopFunction::Slant => {
            c_abi::FT_GlyphSlot_Slant(ptr::null_mut(), row.first, row.second);
        }
    }
    Ok(ftsynth_null_noop_output(row))
}

fn wasm_ftsynth_null_noop(case: &InputCase) -> Result<RunOutput, String> {
    let row = ftsynth_null_noop_param(&case.inputs.params)?;
    let err = match row.function {
        FtsynthNullNoopFunction::AdjustWeight => {
            wasm_abi::fontdone_wasm_glyphslot_adjust_weight(0, row.first, row.second)
        }
        FtsynthNullNoopFunction::Embolden => wasm_abi::fontdone_wasm_glyphslot_embolden(0),
        FtsynthNullNoopFunction::Oblique => wasm_abi::fontdone_wasm_glyphslot_oblique(0),
        FtsynthNullNoopFunction::Slant => {
            wasm_abi::fontdone_wasm_glyphslot_slant(0, row.first, row.second)
        }
    };
    if err != FT_Err_Ok {
        return Ok(error(err));
    }
    Ok(ftsynth_null_noop_output(row))
}

fn ftsynth_output(rows: Vec<Value>) -> RunOutput {
    ok(json!({ "rows": rows }))
}

fn ftsynth_row_json(row: FtsynthSlantRow, before: Value, after: Value) -> Value {
    json!({
        "glyph_index": row.glyph_index,
        "load_flags": row.load_flags,
        "xslant": row.xslant,
        "yslant": row.yslant,
        "slot_format": after["slot_format"].clone(),
        "outline_points_before": before["outline_points"].clone(),
        "outline_points_after": after["outline_points"].clone(),
        "outline_cbox_after": after["outline_cbox"].clone(),
        "metrics_before": before["metrics"].clone(),
        "metrics_after": after["metrics"].clone(),
        "advance_before": before["advance"].clone(),
        "advance_after": after["advance"].clone()
    })
}

fn ftsynth_weight_row_json(row: FtsynthWeightRow, before: Value, after: Value) -> Value {
    json!({
        "glyph_index": row.glyph_index,
        "load_flags": row.load_flags,
        "xdelta": row.xdelta,
        "ydelta": row.ydelta,
        "slot_format": after["slot_format"].clone(),
        "outline_points_before": before["outline_points"].clone(),
        "outline_points_after": after["outline_points"].clone(),
        "outline_cbox_after": after["outline_cbox"].clone(),
        "bitmap_before": before["bitmap"].clone(),
        "bitmap_after": after["bitmap"].clone(),
        "bitmap_top_before": before["bitmap_top"].clone(),
        "bitmap_top_after": after["bitmap_top"].clone(),
        "metrics_before": before["metrics"].clone(),
        "metrics_after": after["metrics"].clone(),
        "advance_before": before["advance"].clone(),
        "advance_after": after["advance"].clone()
    })
}

fn ftsynth_rust_slot_state(slot: &FT_GlyphSlot) -> Value {
    json!({
        "slot_format": slot.format,
        "outline_points": ftsynth_outline_points_json(slot.outline.as_ref()),
        "outline_cbox": json!({
            "xMin": slot.outline_cbox.xMin,
            "yMin": slot.outline_cbox.yMin,
            "xMax": slot.outline_cbox.xMax,
            "yMax": slot.outline_cbox.yMax
        }),
        "bitmap": ftsynth_rust_bitmap_json(slot),
        "bitmap_top": slot.bitmap.as_ref().map_or(Value::Null, |_| json!(slot.bitmap_top)),
        "metrics": glyph_metrics_fields_json(rust_metrics_fields(&slot.metrics)),
        "advance": {
            "x": slot.advance.x,
            "y": slot.advance.y
        }
    })
}

fn ftsynth_rust_bitmap_json(slot: &FT_GlyphSlot) -> Value {
    slot.bitmap.as_ref().map_or(Value::Null, |bitmap| {
        json!({
            "width": bitmap.width,
            "rows": bitmap.rows,
            "pitch": bitmap.pitch,
            "pixel_mode": bitmap.pixel_mode,
            "num_grays": bitmap.num_grays,
            "left": slot.bitmap_left,
            "top": slot.bitmap_top,
            "buffer_hex": hex_bytes(&bitmap.buffer)
        })
    })
}

fn ftsynth_outline_points_json(outline: Option<&FT_OutlineSnapshot>) -> Value {
    outline.map_or_else(
        || json!([]),
        |outline| {
            json!(
                outline
                    .points
                    .iter()
                    .map(|point| json!({"x": point.x, "y": point.y}))
                    .collect::<Vec<_>>()
            )
        },
    )
}

fn rust_ftsynth_slant(case: &InputCase, oblique: bool) -> Result<RunOutput, String> {
    let face = open_face(case)?;
    let mut rows = Vec::new();
    for row in ftsynth_slant_rows(&case.inputs.params, oblique)? {
        let mut slot = match FT_Load_Glyph(&face, row.glyph_index, row.load_flags) {
            Ok(slot) => slot,
            Err(err) => return Ok(error(err)),
        };
        let before = ftsynth_rust_slot_state(&slot);
        if oblique {
            FT_GlyphSlot_Oblique(Some(&mut slot));
        } else {
            FT_GlyphSlot_Slant(Some(&mut slot), row.xslant, row.yslant);
        }
        rows.push(ftsynth_row_json(
            row,
            before,
            ftsynth_rust_slot_state(&slot),
        ));
    }
    Ok(ftsynth_output(rows))
}

fn rust_ftsynth_weight(case: &InputCase, embolden: bool) -> Result<RunOutput, String> {
    if !has_runtime_font_source(case) {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    }
    let face = open_face(case)?;
    let mut rows = Vec::new();
    for row in ftsynth_weight_rows(&case.inputs.params, embolden)? {
        let mut slot = match FT_Load_Glyph(&face, row.glyph_index, row.load_flags) {
            Ok(slot) => slot,
            Err(err) => return Ok(error(err)),
        };
        let before = ftsynth_rust_slot_state(&slot);
        if embolden {
            FT_GlyphSlot_Embolden(Some(&mut slot));
        } else {
            FT_GlyphSlot_AdjustWeight(Some(&mut slot), row.xdelta, row.ydelta);
        }
        rows.push(ftsynth_weight_row_json(
            row,
            before,
            ftsynth_rust_slot_state(&slot),
        ));
    }
    Ok(ftsynth_output(rows))
}

fn rust_render_glyph(
    face: &FT_Face,
    glyph_input: GlyphLoadInput,
    load_flags: i32,
    render_mode: i32,
    repeat_count: u32,
) -> Result<RunOutput, String> {
    if repeat_count > 1 {
        let mut rows = Vec::new();
        for iteration in 0..repeat_count {
            let loaded = match glyph_input {
                GlyphLoadInput::CharCode(char_code) => FT_Load_Char(face, char_code, load_flags),
                GlyphLoadInput::GlyphIndex(glyph_index) => {
                    FT_Load_Glyph(face, glyph_index, load_flags)
                }
            };
            match loaded.and_then(|slot| FT_Render_Glyph(slot, render_mode)) {
                Ok(slot) => rows.push(render_glyph_sequence_row(iteration, slot_json(&slot))),
                Err(err) => return Ok(error(err)),
            }
        }
        return Ok(ok(render_glyph_sequence_json(rows)));
    }

    let loaded = match glyph_input {
        GlyphLoadInput::CharCode(char_code) => FT_Load_Char(face, char_code, load_flags),
        GlyphLoadInput::GlyphIndex(glyph_index) => FT_Load_Glyph(face, glyph_index, load_flags),
    };
    match loaded.and_then(|slot| FT_Render_Glyph(slot, render_mode)) {
        Ok(slot) => Ok(ok(slot_json(&slot))),
        Err(err) => Ok(error(err)),
    }
}

fn rust_load_char_public_api(case: &InputCase) -> Result<RunOutput, String> {
    let raw_load_flags = load_flags_param(&case.inputs.params)?;
    let char_code = u64_param(&case.inputs.params, "char_code")?;
    if lifecycle_handle_param(&case.inputs.params, "face") == Some("null") {
        return Ok(error(FT_Err_Invalid_Face_Handle as FT_Error));
    }
    let Ok(char_code) = u32::try_from(char_code) else {
        let face = open_face(case)?;
        return match FT_Load_Char(&face, char_code.into(), raw_load_flags) {
            Ok(slot) => Ok(ok(slot_json(&slot))),
            Err(err) => Ok(error(err)),
        };
    };
    let load_flags = match load_flags_to_core(raw_load_flags) {
        Ok(flags) => flags,
        Err(err) => return Ok(error(err)),
    };
    let face = open_api_face(case)?;
    let expected_autohint_bits = reset_autohint_coverage_if_requested(case)?;
    let output = match face.load_char(char_code, load_flags) {
        Ok(slot) => ok(api_slot_json(&slot)),
        Err(err) => error(font_error_to_ft(err)),
    };
    assert_autohint_coverage_bits(case, expected_autohint_bits.as_deref())?;
    Ok(output)
}

fn assert_api_load_glyph_agrees(
    case: &InputCase,
    ffi_result: Result<&FT_GlyphSlot, FT_Error>,
) -> Result<(), String> {
    if !checks_api_load_glyph_agreement(case)? {
        return Ok(());
    }
    let load_flags = match load_flags_to_core(load_flags_param(&case.inputs.params)?) {
        Ok(flags) => flags,
        Err(err) => {
            return Err(format!(
                "{} load flag conversion failed: {err}",
                case.case_id
            ));
        }
    };
    let ffi_face = open_face(case)?;
    let glyph_index = u16::try_from(rust_resolved_glyph_index(&ffi_face, &case.inputs.params)?)
        .map_err(|err| format!("{} glyph_index does not fit u16: {err}", case.case_id))?;
    let face = open_api_face(case)?;
    let expected_autohint_bits = reset_autohint_coverage_if_requested(case)?;
    let api_result = face
        .load_glyph(glyph_index, load_flags)
        .map_err(font_error_to_ft);
    assert_autohint_coverage_bits(case, expected_autohint_bits.as_deref())?;
    match (api_result, ffi_result) {
        (Ok(api_slot), Ok(ffi_slot)) => {
            let ffi_json = slot_json(ffi_slot);
            let api_json = api_slot_json(&api_slot);
            if api_json != ffi_json {
                return Err(format!(
                    "{} Face::load_glyph disagrees with FT_Load_Glyph: api={api_json} ffi={ffi_json}",
                    case.case_id
                ));
            }
        }
        (Err(api_err), Err(ffi_err)) if api_err == ffi_err => {}
        (Err(api_err), Err(ffi_err)) => {
            return Err(format!(
                "{} Face::load_glyph error disagrees with FT_Load_Glyph: api={api_err} ffi={ffi_err}",
                case.case_id
            ));
        }
        (Ok(api_slot), Err(ffi_err)) => {
            let api_json = api_slot_json(&api_slot);
            return Err(format!(
                "{} Face::load_glyph succeeded while FT_Load_Glyph returned {ffi_err}: api={api_json}",
                case.case_id
            ));
        }
        (Err(api_err), Ok(ffi_slot)) => {
            let ffi_json = slot_json(ffi_slot);
            return Err(format!(
                "{} Face::load_glyph returned {api_err} while FT_Load_Glyph succeeded: ffi={ffi_json}",
                case.case_id
            ));
        }
    }
    Ok(())
}

fn checks_api_load_glyph_agreement(case: &InputCase) -> Result<bool, String> {
    bool_param(&case.inputs.params, "assert_api_load_glyph_agrees", false)
}

fn reset_autohint_coverage_if_requested(case: &InputCase) -> Result<Option<Vec<u32>>, String> {
    let expected = autohint_coverage_bits_param(case)?;
    if expected.is_some() {
        autohint_coverage::reset();
        let mask = autohint_coverage::current_mask();
        if mask != 0 {
            return Err(format!(
                "{} autohint coverage reset left mask=0x{mask:x}",
                case.case_id
            ));
        }
    }
    Ok(expected)
}

fn assert_autohint_coverage_bits(case: &InputCase, expected: Option<&[u32]>) -> Result<(), String> {
    let Some(expected) = expected else {
        return Ok(());
    };
    let mask = autohint_coverage::current_mask();
    let actual = autohint_coverage::collect_hit_bits(mask);
    let missing = expected
        .iter()
        .copied()
        .filter(|bit| !actual.contains(bit))
        .collect::<Vec<_>>();
    autohint_coverage::reset();
    if !missing.is_empty() {
        return Err(format!(
            "{} autohint coverage bits missing: expected_include={expected:?} actual={actual:?} missing={missing:?}",
            case.case_id
        ));
    }
    Ok(())
}

fn autohint_coverage_bits_param(case: &InputCase) -> Result<Option<Vec<u32>>, String> {
    let Some(raw) = case
        .inputs
        .params
        .get("assert_autohint_coverage_bits_include")
    else {
        return Ok(None);
    };
    let values = raw.as_array().ok_or_else(|| {
        format!(
            "{} assert_autohint_coverage_bits_include must be an array",
            case.case_id
        )
    })?;
    let mut bits = Vec::with_capacity(values.len());
    for value in values {
        let bit = value.as_u64().ok_or_else(|| {
            format!(
                "{} assert_autohint_coverage_bits_include entries must be integers",
                case.case_id
            )
        })?;
        if bit >= u64::BITS.into() {
            return Err(format!(
                "{} autohint coverage bit {bit} is outside the u64 mask",
                case.case_id
            ));
        }
        bits.push(u32::try_from(bit).map_err(|err| {
            format!(
                "{} autohint coverage bit {bit} does not fit u32: {err}",
                case.case_id
            )
        })?);
    }
    Ok(Some(bits))
}

fn rust_render_glyph_public_api(case: &InputCase) -> Result<RunOutput, String> {
    if case.case_id
        == "freetype.FT_Render_Glyph.error_unloaded_or_unsupported_slot_format.unrouted_slot_states"
    {
        let face = open_face(case)?;
        return rust_render_glyph_slot_states(&face, &case.inputs.params);
    }
    let raw_load_flags = load_flags_param(&case.inputs.params)?;
    let repeat_count = render_repeat_count_param(&case.inputs.params)?;
    let capture_error_slot = bool_param(&case.inputs.params, "capture_render_error_slot", false)?;
    if capture_error_slot {
        if repeat_count != 1 || !case.expect_error {
            return Err(format!(
                "{} capture_render_error_slot requires one expected-error render",
                case.case_id
            ));
        }
        let face = open_face(case)?;
        let loaded = match glyph_load_input_param(&case.inputs.params)? {
            GlyphLoadInput::CharCode(char_code) => FT_Load_Char(&face, char_code, raw_load_flags),
            GlyphLoadInput::GlyphIndex(glyph_index) => {
                FT_Load_Glyph(&face, glyph_index, raw_load_flags)
            }
        };
        let loaded = match loaded {
            Ok(slot) => slot,
            Err(err) => return Ok(error(err)),
        };
        return match FT_Render_Glyph(loaded.clone(), render_mode_param(&case.inputs.params)?) {
            Ok(slot) => Ok(ok(slot_json(&slot))),
            Err(err) => Ok(error_with_output(err, slot_json(&loaded))),
        };
    }
    if raw_load_flags & FT_LOAD_RENDER != 0 {
        let face = open_face(case)?;
        return rust_render_glyph(
            &face,
            glyph_load_input_param(&case.inputs.params)?,
            raw_load_flags,
            render_mode_param(&case.inputs.params)?,
            repeat_count,
        );
    }
    let face = open_api_face(case)?;
    let glyph_index = match glyph_load_input_param(&case.inputs.params)? {
        GlyphLoadInput::CharCode(char_code) => {
            face.get_char_index(u32::try_from(char_code).map_err(|err| err.to_string())?)
        }
        GlyphLoadInput::GlyphIndex(glyph_index) => {
            u16::try_from(glyph_index).map_err(|err| err.to_string())?
        }
    };
    let load_flags = match load_flags_to_core(raw_load_flags) {
        Ok(flags) => flags,
        Err(err) => return Ok(error(err)),
    };
    let Some(render_mode) = render_mode_to_core(render_mode_param(&case.inputs.params)?) else {
        return Ok(error(FT_Err_Cannot_Render_Glyph));
    };
    if repeat_count > 1 {
        let mut rows = Vec::new();
        for iteration in 0..repeat_count {
            match face.render_loaded_glyph(glyph_index, load_flags, render_mode) {
                Ok(slot) => {
                    let slot_json = api_slot_json(&slot);
                    assert_font_render_mode_agrees(case, &slot_json)?;
                    rows.push(render_glyph_sequence_row(iteration, slot_json));
                }
                Err(err) => return Ok(error(font_error_to_ft(err))),
            }
        }
        return Ok(ok(render_glyph_sequence_json(rows)));
    }
    match face.render_loaded_glyph(glyph_index, load_flags, render_mode) {
        Ok(slot) => {
            let slot_json = api_slot_json(&slot);
            assert_font_render_mode_agrees(case, &slot_json)?;
            Ok(ok(slot_json))
        }
        Err(err) => Ok(error(font_error_to_ft(err))),
    }
}

fn assert_font_render_mode_agrees(case: &InputCase, slot_json: &Value) -> Result<(), String> {
    if !bool_param(&case.inputs.params, "assert_font_render_mode_agrees", false)? {
        return Ok(());
    }
    let Some(render_mode) = render_mode_to_core(render_mode_param(&case.inputs.params)?) else {
        return Ok(());
    };
    if let Some(expected) = case
        .inputs
        .params
        .get("assert_render_mode_fixture_name")
        .and_then(Value::as_str)
    {
        let actual = render_mode_fixture_name(render_mode);
        if actual != expected {
            return Err(format!(
                "{} render mode fixture name disagrees: mode={actual} expected={expected}",
                case.case_id
            ));
        }
    }
    let text = case
        .inputs
        .params
        .get("font_render_text")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            format!(
                "{} assert_font_render_mode_agrees requires font_render_text",
                case.case_id
            )
        })?;
    let data = font_bytes(case)?;
    let (_, pixel_height) = pixel_size_param(&case.inputs.params)?;
    let load_mode = font_load_mode_from_params(&case.inputs.params)?;
    let font = if bool_param(
        &case.inputs.params,
        "assert_font_truetype_constructor_agrees",
        false,
    )? {
        if load_mode != LoadMode::Default {
            return Err(format!(
                "{} assert_font_truetype_constructor_agrees requires default load mode",
                case.case_id
            ));
        }
        Font::truetype(data.as_ref(), pixel_height as f32)
    } else {
        Font::truetype_with_load_mode(data.as_ref(), pixel_height as f32, load_mode)
    }
    .map_err(|err| format!("{} Font constructor returned {err}", case.case_id))?;
    if bool_param(&case.inputs.params, "assert_font_face_count_agrees", false)? {
        let face = open_face(case)?;
        let expected = usize::try_from(face.num_faces)
            .map_err(|err| format!("{} FT_FaceRec.num_faces invalid: {err}", case.case_id))?;
        let actual = Font::face_count(data.as_ref()).map_err(|err| {
            format!(
                "{} Font::face_count returned {}",
                case.case_id,
                font_error_to_ft(err)
            )
        })?;
        if actual != expected {
            return Err(format!(
                "{} Font::face_count disagrees with FT_FaceRec.num_faces: font={actual} face={expected}",
                case.case_id
            ));
        }
    }
    if bool_param(&case.inputs.params, "assert_font_empty_text_render", false)? {
        let empty_bitmap = font.render_mode("", render_mode).map_err(|err| {
            format!(
                "{} Font::render_mode(\"\") returned {}",
                case.case_id,
                font_error_to_ft(err)
            )
        })?;
        let empty_json = rendered_bitmap_json(&empty_bitmap);
        if !is_empty_rendered_bitmap_json(&empty_json) {
            return Err(format!(
                "{} Font::render_mode(\"\") returned non-empty bitmap: {empty_json}",
                case.case_id
            ));
        }
    }
    let ch = text
        .chars()
        .next()
        .ok_or_else(|| "font_render_text must not be empty".to_string())?;
    let char_bitmap = font.render_char_mode(ch, render_mode).map_err(|err| {
        format!(
            "{} Font::render_char_mode returned {}",
            case.case_id,
            font_error_to_ft(err)
        )
    })?;
    let text_bitmap = font.render_mode(text, render_mode).map_err(|err| {
        format!(
            "{} Font::render_mode returned {}",
            case.case_id,
            font_error_to_ft(err)
        )
    })?;
    let char_json = rendered_bitmap_json(&char_bitmap);
    let text_json = rendered_bitmap_json(&text_bitmap);
    if let Some(expected) = case
        .inputs
        .params
        .get("assert_pixel_mode_fixture_name")
        .and_then(Value::as_str)
    {
        let actual = pixel_mode_fixture_name(char_bitmap.pixel_mode);
        if actual != expected {
            return Err(format!(
                "{} pixel mode fixture name disagrees: pixel={actual} expected={expected}",
                case.case_id
            ));
        }
    }
    assert_font_convenience_helpers_agree(case, &font, text, render_mode, &char_bitmap, slot_json)?;
    let Some(slot_bitmap) = slot_json.get("bitmap") else {
        return Err(format!(
            "{} slot output missing bitmap for Font render comparison",
            case.case_id
        ));
    };
    if slot_bitmap.is_null() {
        if !is_empty_rendered_bitmap_json(&char_json) {
            return Err(format!(
                "{} Font::render_char_mode returned non-empty bitmap while FT_Render_Glyph exposed no bitmap: font={char_json}",
                case.case_id
            ));
        }
        if text_json != char_json {
            return Err(format!(
                "{} Font::render_mode disagrees with Font::render_char_mode: text={text_json} char={char_json}",
                case.case_id
            ));
        }
        return Ok(());
    }
    if &char_json != slot_bitmap {
        return Err(format!(
            "{} Font::render_char_mode disagrees with FT_Render_Glyph: font={char_json} slot={slot_bitmap}",
            case.case_id
        ));
    }
    if text_json != char_json {
        return Err(format!(
            "{} Font::render_mode disagrees with Font::render_char_mode: text={text_json} char={char_json}",
            case.case_id
        ));
    }
    Ok(())
}

fn render_mode_fixture_name(mode: RenderMode) -> &'static str {
    match mode {
        RenderMode::Normal => "normal",
        RenderMode::Mono => "mono",
        RenderMode::Lcd => "lcd",
        RenderMode::LcdV => "lcd_v",
        RenderMode::Sdf => "sdf",
    }
}

fn pixel_mode_fixture_name(mode: PixelMode) -> &'static str {
    match mode {
        PixelMode::Gray => "gray",
        PixelMode::Mono => "mono",
        PixelMode::Gray2 => "gray2",
        PixelMode::Gray4 => "gray4",
        PixelMode::Lcd => "lcd",
        PixelMode::LcdV => "lcd_v",
        PixelMode::Bgra => "bgra",
    }
}

fn font_load_mode_from_params(params: &Value) -> Result<LoadMode, String> {
    let load_flags = load_flags_param(params)?;
    let no_autohint = load_flags & FT_LOAD_NO_AUTOHINT != 0;
    if load_flags & FT_LOAD_NO_HINTING != 0
        || load_flags & (FT_LOAD_NO_SCALE | FT_LOAD_NO_RECURSE) != 0
    {
        Ok(LoadMode::NoHinting)
    } else if FT_LOAD_TARGET_MODE(load_flags) == FT_RENDER_MODE_LIGHT && !no_autohint {
        Ok(LoadMode::TargetLight)
    } else if load_flags & FT_LOAD_FORCE_AUTOHINT != 0 {
        if no_autohint {
            Ok(LoadMode::NoAutoHint)
        } else {
            Ok(LoadMode::ForceAutoHint)
        }
    } else if no_autohint {
        Ok(LoadMode::NoAutoHint)
    } else {
        Ok(LoadMode::Default)
    }
}

fn assert_font_convenience_helpers_agree(
    case: &InputCase,
    font: &Font,
    text: &str,
    render_mode: RenderMode,
    rendered: &RenderedBitmap,
    slot_json: &Value,
) -> Result<(), String> {
    if bool_param(&case.inputs.params, "assert_font_getmetrics_agrees", false)? {
        let face = open_face(case)?;
        let metrics = face.size_metrics;
        let expected = (
            u32_from_positive_26dot6(metrics.ascender, "ascender")?,
            u32_from_positive_26dot6(-metrics.descender, "descender")?,
        );
        let actual = font.getmetrics();
        if actual != expected {
            return Err(format!(
                "{} Font::getmetrics disagrees with FT_Size_Metrics: font={actual:?} size_metrics={expected:?}",
                case.case_id
            ));
        }
    }

    if bool_param(&case.inputs.params, "assert_font_getlength_agrees", false)? {
        let expected_advance = slot_json
            .pointer("/metrics/horiAdvance")
            .and_then(Value::as_i64)
            .ok_or_else(|| {
                format!(
                    "{} assert_font_getlength_agrees requires slot metrics.horiAdvance",
                    case.case_id
                )
            })?;
        let actual = font.getlength(text);
        let expected = expected_advance as f32 / 64.0;
        if (actual - expected).abs() > 0.001 {
            return Err(format!(
                "{} Font::getlength disagrees with glyph-slot advance: font={actual} slot={expected}",
                case.case_id
            ));
        }
    }

    if bool_param(
        &case.inputs.params,
        "assert_font_glyph_metrics_agrees",
        false,
    )? {
        let ch = text
            .chars()
            .next()
            .ok_or_else(|| "font_render_text must not be empty".to_string())?;
        let metrics = font.glyph_metrics(ch as u32).map_err(|err| {
            format!(
                "{} Font::glyph_metrics returned {}",
                case.case_id,
                font_error_to_ft(err)
            )
        })?;
        let actual = json!({
            "width": metrics.width,
            "height": metrics.height,
            "horiBearingX": metrics.hori_bearing_x,
            "horiBearingY": metrics.hori_bearing_y,
            "horiAdvance": metrics.hori_advance,
            "vertBearingX": metrics.vert_bearing_x,
            "vertBearingY": metrics.vert_bearing_y,
            "vertAdvance": metrics.vert_advance
        });
        let expected = slot_json
            .get("metrics")
            .ok_or_else(|| format!("{} slot output missing metrics", case.case_id))?;
        if &actual != expected {
            return Err(format!(
                "{} Font::glyph_metrics disagrees with glyph-slot metrics: font={actual} slot={expected}",
                case.case_id
            ));
        }
    }

    if bool_param(&case.inputs.params, "assert_font_getmask_agrees", false)? {
        if render_mode != RenderMode::Normal {
            return Err(format!(
                "{} assert_font_getmask_agrees requires FT_RENDER_MODE_NORMAL",
                case.case_id
            ));
        }
        let bbox = font.getbbox(text);
        let mask = font.getmask(text).map_err(|err| {
            format!(
                "{} Font::getmask returned {}",
                case.case_id,
                font_error_to_ft(err)
            )
        })?;
        let expected_len = usize::try_from(mask.width)
            .ok()
            .and_then(|width| {
                usize::try_from(mask.height)
                    .ok()
                    .and_then(|height| width.checked_mul(height))
            })
            .ok_or_else(|| format!("{} Font::getmask dimensions overflow", case.case_id))?;
        if mask.pixels.len() != expected_len {
            return Err(format!(
                "{} Font::getmask pixel length disagrees with dimensions: len={} width={} height={}",
                case.case_id,
                mask.pixels.len(),
                mask.width,
                mask.height
            ));
        }
        if (mask.xmin, mask.ymin) != (bbox.0, bbox.1) {
            return Err(format!(
                "{} Font::getbbox offset disagrees with Font::getmask: bbox={bbox:?} mask=({}, {})",
                case.case_id, mask.xmin, mask.ymin
            ));
        }
        if mask.width != rendered.width
            || mask.height != rendered.rows
            || mask.pixels != rendered.buffer
        {
            return Err(format!(
                "{} Font::getmask disagrees with Font::render_mode(Normal): mask={}x{} rendered={}x{}",
                case.case_id, mask.width, mask.height, rendered.width, rendered.rows
            ));
        }
    }

    if bool_param(&case.inputs.params, "assert_font_empty_text_mask", false)? {
        let bbox = font.getbbox("");
        let mask = font.getmask("").map_err(|err| {
            format!(
                "{} Font::getmask(\"\") returned {}",
                case.case_id,
                font_error_to_ft(err)
            )
        })?;
        if bbox != (0, 0, 0, 0)
            || mask.width != 0
            || mask.height != 0
            || !mask.pixels.is_empty()
            || mask.xmin != 0
            || mask.ymin != 0
            || mask.advance_width != 0
        {
            return Err(format!(
                "{} empty Font bbox/mask was not empty: bbox={bbox:?} mask={}x{} len={}",
                case.case_id,
                mask.width,
                mask.height,
                mask.pixels.len()
            ));
        }
    }

    Ok(())
}

fn u32_from_positive_26dot6(value: i64, label: &str) -> Result<u32, String> {
    u32::try_from(value >> 6).map_err(|err| format!("{label} does not fit u32 pixels: {err}"))
}

fn is_empty_rendered_bitmap_json(value: &Value) -> bool {
    value.get("width").and_then(Value::as_u64) == Some(0)
        && value.get("rows").and_then(Value::as_u64) == Some(0)
        && value.get("pitch").and_then(Value::as_i64) == Some(0)
        && value.get("left").and_then(Value::as_i64) == Some(0)
        && value.get("top").and_then(Value::as_i64) == Some(0)
        && value.get("buffer_hex").and_then(Value::as_str) == Some("")
}

fn c_render_glyph(
    face: c_abi::FT_Face,
    glyph_input: GlyphLoadInput,
    load_flags: i32,
    render_mode: i32,
    repeat_count: u32,
    capture_error_slot: bool,
) -> Result<RunOutput, String> {
    if repeat_count > 1 {
        let mut rows = Vec::new();
        for iteration in 0..repeat_count {
            let load_err = match glyph_input {
                GlyphLoadInput::CharCode(char_code) => {
                    c_abi::FT_Load_Char(face, char_code, load_flags)
                }
                GlyphLoadInput::GlyphIndex(glyph_index) => {
                    c_abi::FT_Load_Glyph(face, glyph_index, load_flags)
                }
            };
            let err = if load_err == FT_Err_Ok {
                c_abi::abi_render_glyph_from_face(face, render_mode)
            } else {
                load_err
            };
            if err != FT_Err_Ok {
                return Ok(error(err));
            }
            rows.push(render_glyph_sequence_row(iteration, c_slot_json(face)?));
        }
        return Ok(ok(render_glyph_sequence_json(rows)));
    }

    let load_err = match glyph_input {
        GlyphLoadInput::CharCode(char_code) => c_abi::FT_Load_Char(face, char_code, load_flags),
        GlyphLoadInput::GlyphIndex(glyph_index) => {
            c_abi::FT_Load_Glyph(face, glyph_index, load_flags)
        }
    };
    let err = if load_err == FT_Err_Ok {
        c_abi::abi_render_glyph_from_face(face, render_mode)
    } else {
        load_err
    };
    if err == FT_Err_Ok {
        c_slot_json(face).map(ok)
    } else if capture_error_slot && load_err == FT_Err_Ok {
        Ok(error_with_output(err, c_slot_json(face)?))
    } else {
        Ok(error(err))
    }
}

fn wasm_render_glyph(
    handle: usize,
    glyph_input: GlyphLoadInput,
    load_flags: i32,
    render_mode: i32,
    repeat_count: u32,
    capture_error_slot: bool,
) -> Result<RunOutput, String> {
    if repeat_count > 1 {
        let mut rows = Vec::new();
        for iteration in 0..repeat_count {
            let load_err = match glyph_input {
                GlyphLoadInput::CharCode(char_code) => {
                    wasm_abi::fontdone_wasm_load_char(handle, char_code, load_flags)
                }
                GlyphLoadInput::GlyphIndex(glyph_index) => {
                    wasm_abi::fontdone_wasm_load_glyph(handle, glyph_index, load_flags)
                }
            };
            let err = if load_err == FT_Err_Ok {
                wasm_abi::fontdone_wasm_render_glyph(handle, render_mode)
            } else {
                load_err
            };
            if err != FT_Err_Ok {
                return Ok(error(err));
            }
            rows.push(render_glyph_sequence_row(
                iteration,
                wasm_slot_json(handle)?,
            ));
        }
        return Ok(ok(render_glyph_sequence_json(rows)));
    }

    let load_err = match glyph_input {
        GlyphLoadInput::CharCode(char_code) => {
            wasm_abi::fontdone_wasm_load_char(handle, char_code, load_flags)
        }
        GlyphLoadInput::GlyphIndex(glyph_index) => {
            wasm_abi::fontdone_wasm_load_glyph(handle, glyph_index, load_flags)
        }
    };
    let err = if load_err == FT_Err_Ok {
        wasm_abi::fontdone_wasm_render_glyph(handle, render_mode)
    } else {
        load_err
    };
    if err != FT_Err_Ok && capture_error_slot && load_err == FT_Err_Ok {
        Ok(error_with_output(err, wasm_slot_json(handle)?))
    } else {
        wasm_slot_output(handle, err)
    }
}

fn face_macro_flags_values(params: &Value) -> Result<Vec<i64>, String> {
    let values = params
        .get("flags")
        .or_else(|| params.get("face_flags_values"))
        .and_then(Value::as_array)
        .ok_or_else(|| "missing flags/face_flags_values array".to_string())?
        .iter()
        .map(|value| i64_value(value, "face_flags"))
        .collect::<Result<Vec<_>, String>>()?;
    if values.is_empty() {
        return Err("face_macro_flags requires at least one flag value".to_string());
    }
    let mut seen = BTreeSet::new();
    for value in &values {
        if !seen.insert(*value) {
            return Err(format!("duplicate face_flags value {value}"));
        }
    }
    Ok(values)
}

fn face_macro_flags_json(case: &InputCase) -> Result<Value, String> {
    let macro_name = face_macro_param(case)?;
    let face_index = face_index_param(&case.inputs.params)?;
    let rows = face_macro_flags_values(&case.inputs.params)?
        .into_iter()
        .map(|face_flags| {
            let info = FT_FaceRecPublic {
                face_index,
                face_flags,
                ..FT_FaceRecPublic::default()
            };
            Ok(json!({
                "face_flags": face_flags,
                "macro_result": face_macro_result(&info, macro_name)?
            }))
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok(json!({
        "macro": macro_name,
        "import_compiles": true,
        "rows": rows
    }))
}

fn rust_face_macro(face: &FT_Face, case: &InputCase) -> Result<RunOutput, String> {
    Ok(ok(face_macro_json(
        &rust_face_info(face),
        face_macro_param(case)?,
    )?))
}

