fn rust_face_info(face: &FT_Face) -> FT_FaceRecPublic {
    FT_FaceRecPublic {
        num_faces: face.num_faces,
        face_index: face.face_index,
        face_flags: face.face_flags,
        style_flags: face.style_flags,
        num_glyphs: face.num_glyphs,
        num_fixed_sizes: face.num_fixed_sizes,
        available_sizes: if face.available_sizes.is_empty() {
            ptr::null_mut()
        } else {
            face.available_sizes.as_ptr().cast_mut()
        },
        bbox: face.bbox,
        units_per_EM: face.units_per_EM,
        ascender: face.ascender,
        descender: face.descender,
        height: face.height,
        max_advance_width: face.max_advance_width,
        max_advance_height: face.max_advance_height,
        underline_position: face.underline_position,
        underline_thickness: face.underline_thickness,
        size: face.size,
        stream: face.memory_stream(),
        ..FT_FaceRecPublic::default()
    }
}

fn bitmap_sizes_json(sizes: &[FT_Bitmap_Size]) -> Vec<Value> {
    sizes
        .iter()
        .map(|size| {
            json!({
                "height": size.height,
                "width": size.width,
                "size": size.size,
                "x_ppem": size.x_ppem,
                "y_ppem": size.y_ppem
            })
        })
        .collect()
}

fn checked_available_sizes<'a>(
    info: &FT_FaceRecPublic,
    sizes: &'a [FT_Bitmap_Size],
) -> Result<&'a [FT_Bitmap_Size], String> {
    let count = usize::try_from(info.num_fixed_sizes)
        .map_err(|err| format!("num_fixed_sizes does not fit usize: {err}"))?;
    if count != sizes.len() {
        return Err(format!(
            "num_fixed_sizes {} does not match copied available_sizes length {}",
            info.num_fixed_sizes,
            sizes.len()
        ));
    }
    if count > 0 && info.available_sizes.is_null() {
        return Err("available_sizes is null while num_fixed_sizes is positive".to_string());
    }
    Ok(sizes)
}

fn available_sizes_output(
    face: &FT_FaceRecPublic,
    face_sizes: &[FT_Bitmap_Size],
    control: &FT_FaceRecPublic,
) -> Result<Value, String> {
    let sizes = checked_available_sizes(face, face_sizes)?;
    Ok(json!({
        "num_fixed_sizes": face.num_fixed_sizes,
        "available_sizes": bitmap_sizes_json(sizes),
        "control_num_fixed_sizes": control.num_fixed_sizes,
        "control_available_sizes_nullness": if control.available_sizes.is_null() {
            "null"
        } else {
            "non-null"
        }
    }))
}

fn rust_inspect_available_sizes(case: &InputCase) -> Result<RunOutput, String> {
    let face = open_face(case)?;
    let control_bytes = required_asset_bytes(case, "control_font")?;
    let control = rust_new_face_from_bytes(control_bytes.as_ref(), 0)?;
    Ok(ok(available_sizes_output(
        &rust_face_info(&face),
        &face.available_sizes,
        &rust_face_info(&control),
    )?))
}

fn c_inspect_available_sizes(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_new_face_without_size(case)?;
    let control_bytes = required_asset_bytes(case, "control_font")?;
    let (control_library, control_face) = c_new_face_from_bytes(control_bytes.as_ref(), 0)?;
    let info = c_abi::abi_face_info(face).ok_or_else(|| "missing c face info".to_string())?;
    let sizes = c_abi::abi_face_available_sizes(face)
        .ok_or_else(|| "missing c available sizes".to_string())?;
    let control_info = c_abi::abi_face_info(control_face)
        .ok_or_else(|| "missing c control face info".to_string())?;
    let output = available_sizes_output(&info, &sizes, &control_info);
    c_done_face(control_face);
    c_done_library(control_library);
    c_done_face(face);
    c_done_library(library);
    Ok(ok(output?))
}

fn wasm_inspect_available_sizes(case: &InputCase) -> Result<RunOutput, String> {
    let handle = wasm_new_face_without_size(case)?;
    let control_bytes = required_asset_bytes(case, "control_font")?;
    let control_handle = wasm_new_face_from_bytes(control_bytes.as_ref(), 0)?;
    let info =
        wasm_abi::abi_face_info(handle).ok_or_else(|| "missing wasm face info".to_string())?;
    let sizes = wasm_abi::abi_face_available_sizes(handle)
        .ok_or_else(|| "missing wasm available sizes".to_string())?;
    let control_info = wasm_abi::abi_face_info(control_handle)
        .ok_or_else(|| "missing wasm control face info".to_string())?;
    let output = available_sizes_output(&info, &sizes, &control_info);
    wasm_done_face(control_handle);
    wasm_done_face(handle);
    Ok(ok(output?))
}

fn face_flags_json(info: &FT_FaceRecPublic, flag_name: &str) -> Result<Value, String> {
    let flag = rust_constant(flag_name)?;
    Ok(json!({
        "face_flags": info.face_flags,
        "flag": flag,
        "bit_set": (info.face_flags & flag) != 0,
        "face_index": info.face_index,
        "import_compiles": true
    }))
}

fn face_macro_json(info: &FT_FaceRecPublic, macro_name: &str) -> Result<Value, String> {
    Ok(json!({
        "macro_result": face_macro_result(info, macro_name)?,
        "face_flags": info.face_flags,
        "face_index": info.face_index,
        "import_compiles": true
    }))
}

fn face_macro_result(info: &FT_FaceRecPublic, macro_name: &str) -> Result<i32, String> {
    if macro_name == "FT_HAS_FAST_GLYPHS" {
        return Ok(0);
    }
    if macro_name == "FT_IS_NAMED_INSTANCE" {
        return Ok(i32::from((info.face_index & 0x7FFF_0000) != 0));
    }
    let flag = face_macro_flag(macro_name)?;
    Ok(i32::from((info.face_flags & flag) != 0))
}

fn face_macro_flag(macro_name: &str) -> Result<i64, String> {
    match macro_name {
        "FT_HAS_COLOR" => Ok(FT_FACE_FLAG_COLOR),
        "FT_HAS_FIXED_SIZES" => Ok(FT_FACE_FLAG_FIXED_SIZES),
        "FT_HAS_GLYPH_NAMES" => Ok(FT_FACE_FLAG_GLYPH_NAMES),
        "FT_HAS_HORIZONTAL" => Ok(FT_FACE_FLAG_HORIZONTAL),
        "FT_HAS_KERNING" => Ok(FT_FACE_FLAG_KERNING),
        "FT_HAS_MULTIPLE_MASTERS" => Ok(FT_FACE_FLAG_MULTIPLE_MASTERS),
        "FT_HAS_SBIX" => Ok(FT_FACE_FLAG_SBIX),
        "FT_HAS_SBIX_OVERLAY" => Ok(FT_FACE_FLAG_SBIX_OVERLAY),
        "FT_HAS_SVG" => Ok(FT_FACE_FLAG_SVG),
        "FT_HAS_VERTICAL" => Ok(FT_FACE_FLAG_VERTICAL),
        "FT_IS_CID_KEYED" => Ok(FT_FACE_FLAG_CID_KEYED),
        "FT_IS_FIXED_WIDTH" => Ok(FT_FACE_FLAG_FIXED_WIDTH),
        "FT_IS_SCALABLE" => Ok(FT_FACE_FLAG_SCALABLE),
        "FT_IS_SFNT" => Ok(FT_FACE_FLAG_SFNT),
        "FT_IS_TRICKY" => Ok(FT_FACE_FLAG_TRICKY),
        "FT_IS_VARIATION" => Ok(FT_FACE_FLAG_VARIATION),
        _ => Err(format!("unsupported face macro {macro_name}")),
    }
}

fn is_supported_face_macro(macro_name: &str) -> bool {
    macro_name == "FT_HAS_FAST_GLYPHS"
        || macro_name == "FT_IS_NAMED_INSTANCE"
        || face_macro_flag(macro_name).is_ok()
}

fn c_new_face_without_size(
    case: &InputCase,
) -> Result<(c_abi::FT_Library, c_abi::FT_Face), String> {
    let bytes = font_bytes(case)?;
    c_new_face_from_bytes(bytes.as_ref(), face_index_param(&case.inputs.params)?)
}

fn c_new_foreign_face_without_size(
    case: &InputCase,
) -> Result<(c_abi::FT_Library, c_abi::FT_Face), String> {
    let bytes = foreign_font_bytes(case)?;
    c_new_face_from_bytes(bytes.as_ref(), 0)
}

fn c_new_face_from_bytes(
    bytes: &[u8],
    face_index: i64,
) -> Result<(c_abi::FT_Library, c_abi::FT_Face), String> {
    let mut library = std::ptr::null_mut();
    let err = c_abi::FT_Init_FreeType(&mut library);
    if err != FT_Err_Ok {
        return Err(format!("FT_Init_FreeType returned {err}"));
    }
    let mut face = std::ptr::null_mut();
    let file_size = i64::try_from(bytes.len()).map_err(|err| err.to_string())?;
    let err = c_abi::FT_New_Memory_Face(library, bytes.as_ptr(), file_size, face_index, &mut face);
    if err != FT_Err_Ok {
        c_done_library(library);
        return Err(format!("FT_New_Memory_Face returned {err}"));
    }
    Ok((library, face))
}

fn c_open_face(case: &InputCase) -> Result<(c_abi::FT_Library, c_abi::FT_Face), String> {
    c_open_face_with_size_or_char_size(case, pixel_size_param(&case.inputs.params)?)
}

fn c_open_face_with_size_or_char_size(
    case: &InputCase,
    pixel_size: (u32, u32),
) -> Result<(c_abi::FT_Library, c_abi::FT_Face), String> {
    let (library, face) = c_new_face_without_size(case)?;
    if preserve_initial_size(&case.inputs.params)? {
        return Ok((library, face));
    }
    let err = if let Some(row) = preload_size_request_row(&case.inputs.params)? {
        let request = c_size_request_rec(row);
        c_abi::FT_Request_Size(face, &request)
    } else if let Some(row) = preload_char_size_row(&case.inputs.params)? {
        c_abi::FT_Set_Char_Size(
            face,
            row.char_width,
            row.char_height,
            row.horz_resolution,
            row.vert_resolution,
        )
    } else {
        let (pixel_width, pixel_height) = pixel_size;
        c_abi::FT_Set_Pixel_Sizes(face, pixel_width, pixel_height)
    };
    if err == FT_Err_Ok {
        Ok((library, face))
    } else {
        c_done_face(face);
        c_done_library(library);
        Err(format!("FT size setup returned {err}"))
    }
}

fn c_open_face_with_size(
    case: &InputCase,
    pixel_size: (u32, u32),
) -> Result<(c_abi::FT_Library, c_abi::FT_Face), String> {
    c_open_face_with_size_or_char_size(case, pixel_size)
}

fn c_slot_json(face: c_abi::FT_Face) -> Result<Value, String> {
    let slot = c_abi::abi_slot_snapshot(face)
        .ok_or_else(|| "missing c glyph slot snapshot".to_string())?;
    let bitmap = slot.bitmap.as_ref().map_or(Value::Null, |bitmap| {
        json!({
            "width": bitmap.width,
            "rows": bitmap.rows,
            "pitch": bitmap.pitch,
            "pixel_mode": bitmap.pixel_mode,
            "num_grays": bitmap.num_grays,
            "left": bitmap.left,
            "top": bitmap.top,
            "buffer_hex": hex_bytes(&bitmap.buffer)
        })
    });
    Ok(json!({
        "glyph_index": slot.glyph_index,
        "format": slot.format,
        "advance": {"x": slot.advance.x, "y": slot.advance.y},
        "metrics": {
            "width": slot.metrics.width,
            "height": slot.metrics.height,
            "horiBearingX": slot.metrics.horiBearingX,
            "horiBearingY": slot.metrics.horiBearingY,
            "horiAdvance": slot.metrics.horiAdvance,
            "vertBearingX": slot.metrics.vertBearingX,
            "vertBearingY": slot.metrics.vertBearingY,
            "vertAdvance": slot.metrics.vertAdvance
        },
        "bitmap": bitmap
    }))
}

fn ftsynth_c_slot_state(slot: &c_abi::AbiSlotSnapshot) -> Value {
    json!({
        "slot_format": slot.format,
        "outline_points": ftsynth_outline_points_json(slot.outline.as_ref()),
        "outline_cbox": json!({
            "xMin": slot.outline_cbox.xMin,
            "yMin": slot.outline_cbox.yMin,
            "xMax": slot.outline_cbox.xMax,
            "yMax": slot.outline_cbox.yMax
        }),
        "bitmap": ftsynth_c_bitmap_json(slot),
        "bitmap_top": slot.bitmap.as_ref().map_or(Value::Null, |bitmap| json!(bitmap.top)),
        "metrics": glyph_metrics_fields_json(c_metrics_fields(&slot.metrics)),
        "advance": {
            "x": slot.advance.x,
            "y": slot.advance.y
        }
    })
}

fn ftsynth_c_bitmap_json(slot: &c_abi::AbiSlotSnapshot) -> Value {
    slot.bitmap.as_ref().map_or(Value::Null, |bitmap| {
        json!({
            "width": bitmap.width,
            "rows": bitmap.rows,
            "pitch": bitmap.pitch,
            "pixel_mode": bitmap.pixel_mode,
            "num_grays": bitmap.num_grays,
            "left": bitmap.left,
            "top": bitmap.top,
            "buffer_hex": hex_bytes(&bitmap.buffer)
        })
    })
}

fn c_ftsynth_slant(
    face: c_abi::FT_Face,
    case: &InputCase,
    oblique: bool,
) -> Result<RunOutput, String> {
    let mut rows = Vec::new();
    for row in ftsynth_slant_rows(&case.inputs.params, oblique)? {
        let err = c_abi::FT_Load_Glyph(face, row.glyph_index, row.load_flags);
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let before = c_abi::abi_slot_snapshot(face)
            .ok_or_else(|| "missing c ftsynth slot before".to_string())
            .map(|slot| ftsynth_c_slot_state(&slot))?;
        let err = if oblique {
            c_abi::abi_glyphslot_oblique_from_face(face)
        } else {
            c_abi::abi_glyphslot_slant_from_face(face, row.xslant, row.yslant)
        };
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let after = c_abi::abi_slot_snapshot(face)
            .ok_or_else(|| "missing c ftsynth slot after".to_string())
            .map(|slot| ftsynth_c_slot_state(&slot))?;
        rows.push(ftsynth_row_json(row, before, after));
    }
    Ok(ftsynth_output(rows))
}

fn c_ftsynth_weight(
    face: c_abi::FT_Face,
    case: &InputCase,
    embolden: bool,
) -> Result<RunOutput, String> {
    if !has_runtime_font_source(case) {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    }
    let mut rows = Vec::new();
    for row in ftsynth_weight_rows(&case.inputs.params, embolden)? {
        let err = c_abi::FT_Load_Glyph(face, row.glyph_index, row.load_flags);
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let before = c_abi::abi_slot_snapshot(face)
            .ok_or_else(|| "missing c ftsynth weight slot before".to_string())
            .map(|slot| ftsynth_c_slot_state(&slot))?;
        let err = if embolden {
            c_abi::abi_glyphslot_embolden_from_face(face)
        } else {
            c_abi::abi_glyphslot_adjust_weight_from_face(face, row.xdelta, row.ydelta)
        };
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let after = c_abi::abi_slot_snapshot(face)
            .ok_or_else(|| "missing c ftsynth weight slot after".to_string())
            .map(|slot| ftsynth_c_slot_state(&slot))?;
        rows.push(ftsynth_weight_row_json(row, before, after));
    }
    Ok(ftsynth_output(rows))
}

fn c_load_char_output(face: c_abi::FT_Face, params: &Value) -> Result<RunOutput, String> {
    let err = c_abi::FT_Load_Char(
        face,
        u64_param(params, "char_code")?,
        load_flags_param(params)?,
    );
    if err == FT_Err_Ok {
        c_slot_json(face).map(ok)
    } else {
        Ok(error(err))
    }
}

fn c_load_glyph_output(face: c_abi::FT_Face, params: &Value) -> Result<RunOutput, String> {
    let glyph_index = if face.is_null() {
        glyph_index_param(params)?
    } else {
        c_resolved_glyph_index(face, params)?
    };
    let err = c_abi::FT_Load_Glyph(face, glyph_index, load_flags_param(params)?);
    if err == FT_Err_Ok {
        c_slot_json(face).map(ok)
    } else {
        Ok(error(err))
    }
}

fn c_size_metrics_json(face: c_abi::FT_Face) -> Result<Value, String> {
    let metrics =
        c_abi::abi_size_metrics(face).ok_or_else(|| "missing c size metrics".to_string())?;
    Ok(json!({
        "x_ppem": metrics.x_ppem,
        "y_ppem": metrics.y_ppem,
        "x_scale": metrics.x_scale,
        "y_scale": metrics.y_scale,
        "ascender": metrics.ascender,
        "descender": metrics.descender,
        "height": metrics.height,
        "max_advance": metrics.max_advance
    }))
}

fn c_select_size(case: &InputCase) -> Result<RunOutput, String> {
    let strike_index = select_size_strike_index_param(&case.inputs.params)?;
    if lifecycle_handle_param(&case.inputs.params, "face") == Some("null") {
        return Ok(error(c_abi::FT_Select_Size(
            std::ptr::null_mut(),
            strike_index,
        )));
    }
    let (library, face) = c_open_face(case)?;
    let err = c_abi::FT_Select_Size(face, strike_index);
    let output = if err == FT_Err_Ok {
        c_size_metrics_json(face).map(ok)
    } else {
        Ok(error(err))
    };
    c_done_face(face);
    c_done_library(library);
    output
}

fn c_active_size(face: c_abi::FT_Face) -> c_abi::FT_Size {
    c_abi::abi_active_size(face).unwrap_or(std::ptr::null_mut())
}

fn c_active_size_handle(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_new_face_without_size(case)?;
    let (pixel_width, pixel_height) = active_size_fixture_pixel_size(&case.inputs.params)?;
    let status = c_abi::FT_Set_Pixel_Sizes(face, pixel_width, pixel_height);
    let metrics = c_size_metrics_json(face)?;
    let load_error = c_abi::FT_Load_Glyph(face, 36, FT_LOAD_DEFAULT);
    let loaded_hori_advance = if load_error == FT_Err_Ok {
        let slot = c_abi::abi_slot_snapshot(face)
            .ok_or_else(|| "missing c glyph slot snapshot".to_string())?;
        Some(slot.metrics.horiAdvance)
    } else {
        None
    };
    let output = active_size_handle_output(
        status,
        c_active_size(face).is_null(),
        metrics,
        load_error,
        loaded_hori_advance,
    );
    c_done_face(face);
    c_done_library(library);
    Ok(output)
}

fn c_size_record_state(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_new_face_without_size(case)?;
    let status = match size_record_setup(&case.inputs.params)? {
        SizeRecordSetup::Pixel { width, height } => c_abi::FT_Set_Pixel_Sizes(face, width, height),
        SizeRecordSetup::Char {
            char_width,
            char_height,
            hres,
            vres,
        } => c_abi::FT_Set_Char_Size(face, char_width, char_height, hres, vres),
    };
    let size = c_active_size(face);
    if !size.is_null() {
        c_abi::abi_size_rec_set_generic_data(size, 0x51usize as c_abi::FT_Pointer);
    }
    let output = if size.is_null() {
        size_record_state_output(status, "none", "other", Value::Null, "null")
    } else {
        let record = c_abi::abi_size_rec_snapshot(size)
            .ok_or_else(|| "missing c active size record snapshot".to_string())?;
        size_record_state_output(
            status,
            if record.face == face {
                "same_as_parent_face"
            } else {
                "other"
            },
            if record.generic.data == 0x51usize as c_abi::FT_Pointer {
                "client_pointer"
            } else {
                "other"
            },
            c_size_metrics_json(face)?,
            if record.internal.is_null() {
                "null"
            } else {
                "non_null"
            },
        )
    };
    c_done_face(face);
    c_done_library(library);
    Ok(output)
}

fn c_face_owned_handles(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_new_face_without_size(case)?;
    let set_size_error = c_abi::FT_Set_Pixel_Sizes(face, 0, 20);
    let select_error = c_abi::FT_Select_Charmap(face, FT_ENCODING_UNICODE as FT_Encoding);
    let load_error = c_abi::FT_Load_Glyph(face, 36, FT_LOAD_DEFAULT);
    let status = first_non_ok(&[set_size_error, select_error, load_error]);
    let charmap_count = c_abi::abi_charmap_count(face).unwrap_or(0) as usize;
    let output = face_owned_handles_output(
        status,
        if load_error == FT_Err_Ok {
            "same_face"
        } else {
            "none"
        },
        if c_active_size(face).is_null() {
            "none"
        } else {
            "same_face"
        },
        charmap_count,
    );
    c_done_face(face);
    c_done_library(library);
    Ok(output)
}

fn c_glyph_metrics_fields_json(face: c_abi::FT_Face) -> Result<Value, String> {
    let slot = c_abi::abi_slot_snapshot(face)
        .ok_or_else(|| "missing c glyph slot snapshot".to_string())?;
    Ok(glyph_metrics_fields_json(c_metrics_fields(&slot.metrics)))
}

fn c_new_size(case: &InputCase) -> Result<RunOutput, String> {
    let mut size = std::ptr::null_mut();
    if lifecycle_handle_param(&case.inputs.params, "face") == Some("null") {
        let err = c_abi::FT_New_Size(std::ptr::null_mut(), &mut size);
        return if err == FT_Err_Ok {
            Ok(ok(json!({"size_is_null": size.is_null()})))
        } else {
            Ok(error_with_output(
                err,
                json!({"output_size_nullness": if size.is_null() { "null" } else { "non_null" }}),
            ))
        };
    }

    let (library, face) = c_new_face_without_size(case)?;
    let output_is_null = lifecycle_handle_param(&case.inputs.params, "output") == Some("null");
    let active_size_nullness_before = if c_active_size(face).is_null() {
        "null"
    } else {
        "non_null"
    };
    let err = if output_is_null {
        c_abi::FT_New_Size(face, std::ptr::null_mut())
    } else {
        c_abi::FT_New_Size(face, &mut size)
    };
    let result = if err == FT_Err_Ok {
        Ok(ok(json!({"size_is_null": size.is_null()})))
    } else {
        Ok(error_with_output(
            err,
            json!({
                "output_pointer_null": output_is_null,
                "active_size_nullness_before": active_size_nullness_before,
                "active_size_nullness_after": if c_active_size(face).is_null() { "null" } else { "non_null" }
            }),
        ))
    };
    c_done_face(face);
    c_done_library(library);
    result
}

fn c_done_size(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "size") != Some("null") {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    }
    let err = c_abi::FT_Done_Size(std::ptr::null_mut());
    if err == FT_Err_Ok {
        Ok(ok(json!({"done": true})))
    } else {
        Ok(error_with_output(err, json!({"size_input_null": true})))
    }
}

fn c_activate_size(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "size") != Some("null") {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    }
    let err = c_abi::FT_Activate_Size(std::ptr::null_mut());
    if err == FT_Err_Ok {
        Ok(ok(json!({"activated": true})))
    } else {
        Ok(error_with_output(err, json!({"size_input_null": true})))
    }
}

fn c_new_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_new_face_without_size(case)?;
    let initial = c_active_size(face);
    let mut secondary = std::ptr::null_mut();
    let new_error = c_abi::FT_New_Size(face, &mut secondary);
    let active_unchanged_until_activation = c_active_size(face) == initial;
    let parent_face = if secondary.is_null() {
        "none"
    } else {
        "same_face"
    };

    let activate_secondary_error = c_abi::FT_Activate_Size(secondary);
    let request20 = c_nominal_size_request(20 * 64);
    let request20_error = c_abi::FT_Request_Size(face, &request20);
    let secondary_metrics = if request20_error == FT_Err_Ok {
        c_size_metrics_json(face)?
    } else {
        Value::Null
    };

    let activate_initial_error = c_abi::FT_Activate_Size(initial);
    let request10 = c_nominal_size_request(10 * 64);
    let request10_error = c_abi::FT_Request_Size(face, &request10);
    let initial_metrics = if request10_error == FT_Err_Ok {
        c_size_metrics_json(face)?
    } else {
        Value::Null
    };

    let errors = [
        new_error,
        activate_secondary_error,
        request20_error,
        activate_initial_error,
        request10_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "new_size_nullness": if secondary.is_null() { "null" } else { "non_null" },
        "new_size_parent_face": parent_face,
        "active_size_unchanged_until_activation": active_unchanged_until_activation,
        "metrics_by_size": {
            "initial_size": initial_metrics,
            "secondary_size": secondary_metrics
        }
    });
    c_done_face(face);
    c_done_library(library);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn c_done_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_new_face_without_size(case)?;
    let initial = c_active_size(face);
    let mut secondary = std::ptr::null_mut();
    let remove_active = bool_param(&case.inputs.params, "remove_active", true)?;
    let new_error = c_abi::FT_New_Size(face, &mut secondary);
    let active_before_done = if remove_active { secondary } else { initial };
    let activate_error = c_abi::FT_Activate_Size(active_before_done);
    let set18_error = c_abi::FT_Set_Pixel_Sizes(face, 0, 18);
    let done_error = c_abi::FT_Done_Size(secondary);
    let active_after_done = c_active_size(face);
    let set12_error = c_abi::FT_Set_Pixel_Sizes(face, 0, 12);
    let load_error = c_abi::FT_Load_Glyph(face, 36, FT_LOAD_DEFAULT);
    let glyph_metrics = if load_error == FT_Err_Ok {
        c_glyph_metrics_fields_json(face)?
    } else {
        Value::Null
    };

    let errors = [
        new_error,
        activate_error,
        set18_error,
        done_error,
        set12_error,
        load_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "destroyed_size_removed": active_after_done != secondary,
        "active_size_after_done": size_identity_label(active_after_done, initial, secondary),
        "post_done_face_usable": set12_error == FT_Err_Ok && load_error == FT_Err_Ok,
        "post_done_glyph_metrics": glyph_metrics
    });
    c_done_face(face);
    c_done_library(library);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn c_activate_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_new_face_without_size(case)?;
    let initial = c_active_size(face);
    let set12_error = c_abi::FT_Set_Pixel_Sizes(face, 0, 12);
    let initial_metrics = if set12_error == FT_Err_Ok {
        c_size_metrics_json(face)?
    } else {
        Value::Null
    };

    let mut secondary = std::ptr::null_mut();
    let new_error = c_abi::FT_New_Size(face, &mut secondary);
    let activate_secondary_error = c_abi::FT_Activate_Size(secondary);
    let after_secondary_activation = size_identity_label(c_active_size(face), initial, secondary);
    let request18 = c_nominal_size_request(18 * 64);
    let request18_error = c_abi::FT_Request_Size(face, &request18);
    let secondary_metrics = if request18_error == FT_Err_Ok {
        c_size_metrics_json(face)?
    } else {
        Value::Null
    };
    let load_secondary_error = c_abi::FT_Load_Glyph(face, 36, FT_LOAD_DEFAULT);
    let secondary_glyph_metrics = if load_secondary_error == FT_Err_Ok {
        c_glyph_metrics_fields_json(face)?
    } else {
        Value::Null
    };

    let activate_initial_error = c_abi::FT_Activate_Size(initial);
    let after_initial_activation = size_identity_label(c_active_size(face), initial, secondary);
    let load_initial_error = c_abi::FT_Load_Glyph(face, 36, FT_LOAD_DEFAULT);
    let initial_glyph_metrics = if load_initial_error == FT_Err_Ok {
        c_glyph_metrics_fields_json(face)?
    } else {
        Value::Null
    };

    let errors = [
        set12_error,
        new_error,
        activate_secondary_error,
        request18_error,
        load_secondary_error,
        activate_initial_error,
        load_initial_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "active_size_identity": {
            "after_secondary_activation": after_secondary_activation,
            "after_initial_activation": after_initial_activation
        },
        "metrics_by_size": {
            "initial_size": initial_metrics,
            "secondary_size": secondary_metrics
        },
        "glyph_metrics_by_active_size": [secondary_glyph_metrics, initial_glyph_metrics]
    });
    c_done_face(face);
    c_done_library(library);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn c_activate_select_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let (library, face) = c_new_face_without_size(case)?;
    let initial = c_active_size(face);
    let set_initial_error = c_abi::FT_Set_Pixel_Sizes(face, 0, 12);
    let mut secondary = std::ptr::null_mut();
    let new_error = c_abi::FT_New_Size(face, &mut secondary);
    let activate_secondary_error = c_abi::FT_Activate_Size(secondary);
    let after_secondary_activation = size_identity_label(c_active_size(face), initial, secondary);
    let select_error =
        c_abi::FT_Select_Size(face, select_size_strike_index_param(&case.inputs.params)?);
    let selected_metrics = if select_error == FT_Err_Ok {
        c_size_metrics_json(face)?
    } else {
        Value::Null
    };
    let activate_initial_error = c_abi::FT_Activate_Size(initial);
    let after_initial_activation = size_identity_label(c_active_size(face), initial, secondary);
    let inactive_metrics = if activate_initial_error == FT_Err_Ok {
        c_size_metrics_json(face)?
    } else {
        Value::Null
    };

    let errors = [
        set_initial_error,
        new_error,
        activate_secondary_error,
        select_error,
        activate_initial_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "active_size_identity": {
            "after_secondary_activation": after_secondary_activation,
            "after_initial_activation": after_initial_activation
        },
        "selected_strike_metrics": selected_metrics,
        "inactive_size_metrics": inactive_metrics
    });
    c_done_face(face);
    c_done_library(library);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn c_done_face(face: c_abi::FT_Face) {
    if !face.is_null() {
        let _ = c_abi::FT_Done_Face(face);
    }
}

fn c_done_library(library: c_abi::FT_Library) {
    if !library.is_null() {
        let _ = c_abi::FT_Done_FreeType(library);
    }
}

fn wasm_new_face_without_size(case: &InputCase) -> Result<usize, String> {
    let bytes = font_bytes(case)?;
    wasm_new_face_from_bytes(bytes.as_ref(), face_index_param(&case.inputs.params)?)
}

fn wasm_new_foreign_face_without_size(case: &InputCase) -> Result<usize, String> {
    let bytes = foreign_font_bytes(case)?;
    wasm_new_face_from_bytes(bytes.as_ref(), 0)
}

fn wasm_new_face_from_bytes(bytes: &[u8], face_index: i64) -> Result<usize, String> {
    let status = wasm_abi::fontdone_wasm_open_face(bytes.as_ptr(), bytes.len(), face_index, 20.0);
    if status.error == FT_Err_Ok {
        Ok(status.handle)
    } else {
        Err(format!("fontdone_wasm_open_face returned {}", status.error))
    }
}

fn wasm_open_face(case: &InputCase) -> Result<usize, String> {
    wasm_open_face_with_size_or_char_size(case, pixel_size_param(&case.inputs.params)?)
}

fn wasm_open_face_with_size_or_char_size(
    case: &InputCase,
    pixel_size: (u32, u32),
) -> Result<usize, String> {
    let bytes = font_bytes(case)?;
    let status = wasm_abi::fontdone_wasm_open_face(
        bytes.as_ptr(),
        bytes.len(),
        face_index_param(&case.inputs.params)?,
        20.0,
    );
    if status.error != FT_Err_Ok {
        return Err(format!("fontdone_wasm_open_face returned {}", status.error));
    }
    if preserve_initial_size(&case.inputs.params)? {
        return Ok(status.handle);
    }
    let err = if let Some(row) = preload_size_request_row(&case.inputs.params)? {
        let request = wasm_size_request_rec(row);
        wasm_abi::fontdone_wasm_request_size(status.handle, &request)
    } else if let Some(row) = preload_char_size_row(&case.inputs.params)? {
        wasm_abi::fontdone_wasm_set_char_size(
            status.handle,
            row.char_width,
            row.char_height,
            row.horz_resolution,
            row.vert_resolution,
        )
    } else {
        let (pixel_width, pixel_height) = pixel_size;
        wasm_abi::fontdone_wasm_set_pixel_sizes(status.handle, pixel_width, pixel_height)
    };
    if err == FT_Err_Ok {
        Ok(status.handle)
    } else {
        wasm_done_face(status.handle);
        Err(format!("fontdone_wasm size setup returned {err}"))
    }
}

fn wasm_open_face_with_size(case: &InputCase, pixel_size: (u32, u32)) -> Result<usize, String> {
    wasm_open_face_with_size_or_char_size(case, pixel_size)
}

fn wasm_new_memory_face(case: &InputCase) -> Result<RunOutput, String> {
    if case.inputs.params.get("variants").is_some() {
        return wasm_new_memory_face_variants(case);
    }
    if lifecycle_handle_param(&case.inputs.params, "file_base") == Some("null") {
        let file_size = usize::try_from(i64_param(&case.inputs.params, "file_size")?)
            .map_err(|err| err.to_string())?;
        let status = wasm_abi::fontdone_wasm_open_face(
            ptr::null(),
            file_size,
            face_index_param(&case.inputs.params)?,
            20.0,
        );
        return if status.error == FT_Err_Ok {
            wasm_done_face(status.handle);
            Ok(ok(json!({"opened": true})))
        } else {
            Ok(error(status.error))
        };
    }
    let bytes = font_bytes(case)?;
    let status = wasm_abi::fontdone_wasm_open_face(
        bytes.as_ptr(),
        bytes.len(),
        face_index_param(&case.inputs.params)?,
        20.0,
    );
    if status.error == FT_Err_Ok {
        wasm_done_face(status.handle);
        Ok(ok(json!({"opened": true})))
    } else {
        Ok(error(status.error))
    }
}

fn wasm_size_metrics_value(handle: usize) -> Result<Value, String> {
    let mut metrics = wasm_abi::FontdoneWasmSizeMetrics::default();
    let err = wasm_abi::fontdone_wasm_size_metrics(handle, &mut metrics);
    if err == FT_Err_Ok {
        Ok(wasm_size_metrics_json(&metrics))
    } else {
        Err(format!("fontdone_wasm_size_metrics returned {err}"))
    }
}

fn wasm_active_size_handle(case: &InputCase) -> Result<RunOutput, String> {
    let handle = wasm_new_face_without_size(case)?;
    let (pixel_width, pixel_height) = active_size_fixture_pixel_size(&case.inputs.params)?;
    let status = wasm_abi::fontdone_wasm_set_pixel_sizes(handle, pixel_width, pixel_height);
    let metrics = if status == FT_Err_Ok {
        wasm_size_metrics_value(handle)?
    } else {
        Value::Null
    };
    let load_error = wasm_abi::fontdone_wasm_load_glyph(handle, 36, FT_LOAD_DEFAULT);
    let loaded_hori_advance = if load_error == FT_Err_Ok {
        let slot = wasm_abi::abi_slot_snapshot(handle)
            .ok_or_else(|| "missing wasm glyph slot snapshot".to_string())?;
        Some(slot.metrics.horiAdvance)
    } else {
        None
    };
    let output = active_size_handle_output(
        status,
        wasm_abi::fontdone_wasm_active_size(handle) == 0,
        metrics,
        load_error,
        loaded_hori_advance,
    );
    wasm_done_face(handle);
    Ok(output)
}

fn wasm_size_record_state(case: &InputCase) -> Result<RunOutput, String> {
    let handle = wasm_new_face_without_size(case)?;
    let status = match size_record_setup(&case.inputs.params)? {
        SizeRecordSetup::Pixel { width, height } => {
            wasm_abi::fontdone_wasm_set_pixel_sizes(handle, width, height)
        }
        SizeRecordSetup::Char {
            char_width,
            char_height,
            hres,
            vres,
        } => wasm_abi::fontdone_wasm_set_char_size(handle, char_width, char_height, hres, vres),
    };
    let metrics = if status == FT_Err_Ok {
        wasm_size_metrics_value(handle)?
    } else {
        Value::Null
    };
    let output = size_record_state_output(
        status,
        if wasm_abi::fontdone_wasm_active_size(handle) == 0 {
            "none"
        } else {
            "same_as_parent_face"
        },
        "client_pointer",
        metrics,
        if wasm_abi::fontdone_wasm_active_size(handle) == 0 {
            "null"
        } else {
            "non_null"
        },
    );
    wasm_done_face(handle);
    Ok(output)
}

fn wasm_face_owned_handles(case: &InputCase) -> Result<RunOutput, String> {
    let handle = wasm_new_face_without_size(case)?;
    let set_size_error = wasm_abi::fontdone_wasm_set_pixel_sizes(handle, 0, 20);
    let select_error =
        wasm_abi::fontdone_wasm_select_charmap(handle, FT_ENCODING_UNICODE as FT_Encoding);
    let load_error = wasm_abi::fontdone_wasm_load_glyph(handle, 36, FT_LOAD_DEFAULT);
    let status = first_non_ok(&[set_size_error, select_error, load_error]);
    let charmap_count = wasm_abi::fontdone_wasm_get_charmap_count(handle) as usize;
    let output = face_owned_handles_output(
        status,
        if load_error == FT_Err_Ok {
            "same_face"
        } else {
            "none"
        },
        if wasm_abi::fontdone_wasm_active_size(handle) == 0 {
            "none"
        } else {
            "same_face"
        },
        charmap_count,
    );
    wasm_done_face(handle);
    Ok(output)
}

fn wasm_select_size(case: &InputCase) -> Result<RunOutput, String> {
    let strike_index = select_size_strike_index_param(&case.inputs.params)?;
    if lifecycle_handle_param(&case.inputs.params, "face") == Some("null") {
        return Ok(error(wasm_abi::fontdone_wasm_select_size(0, strike_index)));
    }
    let handle = wasm_open_face(case)?;
    let err = wasm_abi::fontdone_wasm_select_size(handle, strike_index);
    let output = if err == FT_Err_Ok {
        wasm_size_metrics_value(handle).map(ok)
    } else {
        Ok(error(err))
    };
    wasm_done_face(handle);
    output
}

fn wasm_glyph_metrics_fields_json(handle: usize) -> Result<Value, String> {
    let slot = wasm_abi::abi_slot_snapshot(handle)
        .ok_or_else(|| "missing wasm glyph slot snapshot".to_string())?;
    Ok(glyph_metrics_fields_json(wasm_metrics_fields(
        &slot.metrics,
    )))
}

fn wasm_new_size(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "face") == Some("null") {
        let mut size = 0usize;
        let err = wasm_abi::fontdone_wasm_new_size_out(0, &mut size);
        return if err == FT_Err_Ok {
            Ok(ok(json!({"size_is_null": size == 0})))
        } else {
            Ok(error_with_output(
                err,
                json!({"output_size_nullness": if size == 0 { "null" } else { "non_null" }}),
            ))
        };
    }

    let handle = wasm_new_face_without_size(case)?;
    let mut size = 0usize;
    let output_is_null = lifecycle_handle_param(&case.inputs.params, "output") == Some("null");
    let active_size_nullness_before = if wasm_abi::fontdone_wasm_active_size(handle) == 0 {
        "null"
    } else {
        "non_null"
    };
    let err = if output_is_null {
        wasm_abi::fontdone_wasm_new_size_out(handle, std::ptr::null_mut())
    } else {
        wasm_abi::fontdone_wasm_new_size_out(handle, &mut size)
    };
    let result = if err == FT_Err_Ok {
        Ok(ok(json!({"size_is_null": size == 0})))
    } else {
        Ok(error_with_output(
            err,
            json!({
                "output_pointer_null": output_is_null,
                "active_size_nullness_before": active_size_nullness_before,
                "active_size_nullness_after": if wasm_abi::fontdone_wasm_active_size(handle) == 0 { "null" } else { "non_null" }
            }),
        ))
    };
    wasm_done_face(handle);
    result
}

fn wasm_done_size(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "size") != Some("null") {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    }
    let err = wasm_abi::fontdone_wasm_done_size(0);
    if err == FT_Err_Ok {
        Ok(ok(json!({"done": true})))
    } else {
        Ok(error_with_output(err, json!({"size_input_null": true})))
    }
}

fn wasm_activate_size(case: &InputCase) -> Result<RunOutput, String> {
    if lifecycle_handle_param(&case.inputs.params, "size") != Some("null") {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    }
    let err = wasm_abi::fontdone_wasm_activate_size(0);
    if err == FT_Err_Ok {
        Ok(ok(json!({"activated": true})))
    } else {
        Ok(error_with_output(err, json!({"size_input_null": true})))
    }
}

fn wasm_new_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let handle = wasm_new_face_without_size(case)?;
    let initial = wasm_abi::fontdone_wasm_active_size(handle);
    let status = wasm_abi::fontdone_wasm_new_size(handle);
    let secondary = status.handle;
    let new_error = status.error;
    let active_unchanged_until_activation = wasm_abi::fontdone_wasm_active_size(handle) == initial;
    let parent_face = if secondary == 0 { "none" } else { "same_face" };

    let activate_secondary_error = wasm_abi::fontdone_wasm_activate_size(secondary);
    let request20 = wasm_nominal_size_request(20 * 64);
    let request20_error = wasm_abi::fontdone_wasm_request_size(handle, &request20);
    let secondary_metrics = if request20_error == FT_Err_Ok {
        wasm_size_metrics_value(handle)?
    } else {
        Value::Null
    };

    let activate_initial_error = wasm_abi::fontdone_wasm_activate_size(initial);
    let request10 = wasm_nominal_size_request(10 * 64);
    let request10_error = wasm_abi::fontdone_wasm_request_size(handle, &request10);
    let initial_metrics = if request10_error == FT_Err_Ok {
        wasm_size_metrics_value(handle)?
    } else {
        Value::Null
    };

    let errors = [
        new_error,
        activate_secondary_error,
        request20_error,
        activate_initial_error,
        request10_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "new_size_nullness": if secondary == 0 { "null" } else { "non_null" },
        "new_size_parent_face": parent_face,
        "active_size_unchanged_until_activation": active_unchanged_until_activation,
        "metrics_by_size": {
            "initial_size": initial_metrics,
            "secondary_size": secondary_metrics
        }
    });
    wasm_done_face(handle);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn wasm_done_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let handle = wasm_new_face_without_size(case)?;
    let initial = wasm_abi::fontdone_wasm_active_size(handle);
    let status = wasm_abi::fontdone_wasm_new_size(handle);
    let secondary = status.handle;
    let remove_active = bool_param(&case.inputs.params, "remove_active", true)?;
    let new_error = status.error;
    let active_before_done = if remove_active { secondary } else { initial };
    let activate_error = wasm_abi::fontdone_wasm_activate_size(active_before_done);
    let set18_error = wasm_abi::fontdone_wasm_set_pixel_sizes(handle, 0, 18);
    let done_error = wasm_abi::fontdone_wasm_done_size(secondary);
    let active_after_done = wasm_abi::fontdone_wasm_active_size(handle);
    let set12_error = wasm_abi::fontdone_wasm_set_pixel_sizes(handle, 0, 12);
    let load_error = wasm_abi::fontdone_wasm_load_glyph(handle, 36, FT_LOAD_DEFAULT);
    let glyph_metrics = if load_error == FT_Err_Ok {
        wasm_glyph_metrics_fields_json(handle)?
    } else {
        Value::Null
    };

    let errors = [
        new_error,
        activate_error,
        set18_error,
        done_error,
        set12_error,
        load_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "destroyed_size_removed": active_after_done != secondary,
        "active_size_after_done": size_identity_label_usize(active_after_done, initial, secondary),
        "post_done_face_usable": set12_error == FT_Err_Ok && load_error == FT_Err_Ok,
        "post_done_glyph_metrics": glyph_metrics
    });
    wasm_done_face(handle);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn wasm_activate_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let handle = wasm_new_face_without_size(case)?;
    let initial = wasm_abi::fontdone_wasm_active_size(handle);
    let set12_error = wasm_abi::fontdone_wasm_set_pixel_sizes(handle, 0, 12);
    let initial_metrics = if set12_error == FT_Err_Ok {
        wasm_size_metrics_value(handle)?
    } else {
        Value::Null
    };

    let status = wasm_abi::fontdone_wasm_new_size(handle);
    let secondary = status.handle;
    let new_error = status.error;
    let activate_secondary_error = wasm_abi::fontdone_wasm_activate_size(secondary);
    let after_secondary_activation = size_identity_label_usize(
        wasm_abi::fontdone_wasm_active_size(handle),
        initial,
        secondary,
    );
    let request18 = wasm_nominal_size_request(18 * 64);
    let request18_error = wasm_abi::fontdone_wasm_request_size(handle, &request18);
    let secondary_metrics = if request18_error == FT_Err_Ok {
        wasm_size_metrics_value(handle)?
    } else {
        Value::Null
    };
    let load_secondary_error = wasm_abi::fontdone_wasm_load_glyph(handle, 36, FT_LOAD_DEFAULT);
    let secondary_glyph_metrics = if load_secondary_error == FT_Err_Ok {
        wasm_glyph_metrics_fields_json(handle)?
    } else {
        Value::Null
    };

    let activate_initial_error = wasm_abi::fontdone_wasm_activate_size(initial);
    let after_initial_activation = size_identity_label_usize(
        wasm_abi::fontdone_wasm_active_size(handle),
        initial,
        secondary,
    );
    let load_initial_error = wasm_abi::fontdone_wasm_load_glyph(handle, 36, FT_LOAD_DEFAULT);
    let initial_glyph_metrics = if load_initial_error == FT_Err_Ok {
        wasm_glyph_metrics_fields_json(handle)?
    } else {
        Value::Null
    };

    let errors = [
        set12_error,
        new_error,
        activate_secondary_error,
        request18_error,
        load_secondary_error,
        activate_initial_error,
        load_initial_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "active_size_identity": {
            "after_secondary_activation": after_secondary_activation,
            "after_initial_activation": after_initial_activation
        },
        "metrics_by_size": {
            "initial_size": initial_metrics,
            "secondary_size": secondary_metrics
        },
        "glyph_metrics_by_active_size": [secondary_glyph_metrics, initial_glyph_metrics]
    });
    wasm_done_face(handle);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn wasm_activate_select_size_sequence(case: &InputCase) -> Result<RunOutput, String> {
    let handle = wasm_new_face_without_size(case)?;
    let initial = wasm_abi::fontdone_wasm_active_size(handle);
    let set_initial_error = wasm_abi::fontdone_wasm_set_pixel_sizes(handle, 0, 12);
    let status = wasm_abi::fontdone_wasm_new_size(handle);
    let secondary = status.handle;
    let new_error = status.error;
    let activate_secondary_error = wasm_abi::fontdone_wasm_activate_size(secondary);
    let after_secondary_activation = size_identity_label_usize(
        wasm_abi::fontdone_wasm_active_size(handle),
        initial,
        secondary,
    );
    let select_error = wasm_abi::fontdone_wasm_select_size(
        handle,
        select_size_strike_index_param(&case.inputs.params)?,
    );
    let selected_metrics = if select_error == FT_Err_Ok {
        wasm_size_metrics_value(handle)?
    } else {
        Value::Null
    };
    let activate_initial_error = wasm_abi::fontdone_wasm_activate_size(initial);
    let after_initial_activation = size_identity_label_usize(
        wasm_abi::fontdone_wasm_active_size(handle),
        initial,
        secondary,
    );
    let inactive_metrics = if activate_initial_error == FT_Err_Ok {
        wasm_size_metrics_value(handle)?
    } else {
        Value::Null
    };

    let errors = [
        set_initial_error,
        new_error,
        activate_secondary_error,
        select_error,
        activate_initial_error,
    ];
    let output = json!({
        "return_sequence": errors,
        "active_size_identity": {
            "after_secondary_activation": after_secondary_activation,
            "after_initial_activation": after_initial_activation
        },
        "selected_strike_metrics": selected_metrics,
        "inactive_size_metrics": inactive_metrics
    });
    wasm_done_face(handle);
    Ok(lifecycle_sequence_output(
        first_lifecycle_error(&errors),
        output,
    ))
}

fn wasm_slot_output(handle: usize, err: i32) -> Result<RunOutput, String> {
    if err != FT_Err_Ok {
        return Ok(error(err));
    }
    Ok(ok(wasm_slot_json(handle)?))
}

fn wasm_load_char_output(handle: usize, params: &Value) -> Result<RunOutput, String> {
    let err = wasm_abi::fontdone_wasm_load_char(
        handle,
        u64_param(params, "char_code")?,
        load_flags_param(params)?,
    );
    wasm_slot_output(handle, err)
}

fn wasm_load_glyph_output(handle: usize, params: &Value) -> Result<RunOutput, String> {
    let glyph_index = if handle == 0 {
        glyph_index_param(params)?
    } else {
        wasm_resolved_glyph_index(handle, params)?
    };
    let err = wasm_abi::fontdone_wasm_load_glyph(handle, glyph_index, load_flags_param(params)?);
    wasm_slot_output(handle, err)
}

fn wasm_slot_json(handle: usize) -> Result<Value, String> {
    let slot = wasm_abi::abi_slot_snapshot(handle)
        .ok_or_else(|| "missing wasm glyph slot snapshot".to_string())?;
    let bitmap = slot.bitmap.as_ref().map_or(Value::Null, |bitmap| {
        json!({
            "width": bitmap.width,
            "rows": bitmap.rows,
            "pitch": bitmap.pitch,
            "pixel_mode": bitmap.pixel_mode,
            "num_grays": bitmap.num_grays,
            "left": bitmap.left,
            "top": bitmap.top,
            "buffer_hex": hex_bytes(&bitmap.buffer)
        })
    });
    Ok(json!({
        "glyph_index": slot.glyph_index,
        "format": slot.format,
        "advance": {"x": slot.advance.x, "y": slot.advance.y},
        "metrics": {
            "width": slot.metrics.width,
            "height": slot.metrics.height,
            "horiBearingX": slot.metrics.horiBearingX,
            "horiBearingY": slot.metrics.horiBearingY,
            "horiAdvance": slot.metrics.horiAdvance,
            "vertBearingX": slot.metrics.vertBearingX,
            "vertBearingY": slot.metrics.vertBearingY,
            "vertAdvance": slot.metrics.vertAdvance
        },
        "bitmap": bitmap
    }))
}

fn ftsynth_wasm_slot_state(slot: &wasm_abi::AbiSlotSnapshot) -> Value {
    json!({
        "slot_format": slot.format,
        "outline_points": ftsynth_outline_points_json(slot.outline.as_ref()),
        "outline_cbox": json!({
            "xMin": slot.outline_cbox.xMin,
            "yMin": slot.outline_cbox.yMin,
            "xMax": slot.outline_cbox.xMax,
            "yMax": slot.outline_cbox.yMax
        }),
        "bitmap": ftsynth_wasm_bitmap_json(slot),
        "bitmap_top": slot.bitmap.as_ref().map_or(Value::Null, |bitmap| json!(bitmap.top)),
        "metrics": glyph_metrics_fields_json(wasm_metrics_fields(&slot.metrics)),
        "advance": {
            "x": slot.advance.x,
            "y": slot.advance.y
        }
    })
}

fn ftsynth_wasm_bitmap_json(slot: &wasm_abi::AbiSlotSnapshot) -> Value {
    slot.bitmap.as_ref().map_or(Value::Null, |bitmap| {
        json!({
            "width": bitmap.width,
            "rows": bitmap.rows,
            "pitch": bitmap.pitch,
            "pixel_mode": bitmap.pixel_mode,
            "num_grays": bitmap.num_grays,
            "left": bitmap.left,
            "top": bitmap.top,
            "buffer_hex": hex_bytes(&bitmap.buffer)
        })
    })
}

fn wasm_ftsynth_slant(handle: usize, case: &InputCase, oblique: bool) -> Result<RunOutput, String> {
    let mut rows = Vec::new();
    for row in ftsynth_slant_rows(&case.inputs.params, oblique)? {
        let err = wasm_abi::fontdone_wasm_load_glyph(handle, row.glyph_index, row.load_flags);
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let before = wasm_abi::abi_slot_snapshot(handle)
            .ok_or_else(|| "missing wasm ftsynth slot before".to_string())
            .map(|slot| ftsynth_wasm_slot_state(&slot))?;
        let err = if oblique {
            wasm_abi::fontdone_wasm_glyphslot_oblique(handle)
        } else {
            wasm_abi::fontdone_wasm_glyphslot_slant(handle, row.xslant, row.yslant)
        };
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let after = wasm_abi::abi_slot_snapshot(handle)
            .ok_or_else(|| "missing wasm ftsynth slot after".to_string())
            .map(|slot| ftsynth_wasm_slot_state(&slot))?;
        rows.push(ftsynth_row_json(row, before, after));
    }
    Ok(ftsynth_output(rows))
}

fn wasm_ftsynth_weight(
    handle: usize,
    case: &InputCase,
    embolden: bool,
) -> Result<RunOutput, String> {
    if !has_runtime_font_source(case) {
        return Ok(error(FT_Err_Unimplemented_Feature as FT_Error));
    }
    let mut rows = Vec::new();
    for row in ftsynth_weight_rows(&case.inputs.params, embolden)? {
        let err = wasm_abi::fontdone_wasm_load_glyph(handle, row.glyph_index, row.load_flags);
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let before = wasm_abi::abi_slot_snapshot(handle)
            .ok_or_else(|| "missing wasm ftsynth weight slot before".to_string())
            .map(|slot| ftsynth_wasm_slot_state(&slot))?;
        let err = if embolden {
            wasm_abi::fontdone_wasm_glyphslot_embolden(handle)
        } else {
            wasm_abi::fontdone_wasm_glyphslot_adjust_weight(handle, row.xdelta, row.ydelta)
        };
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        let after = wasm_abi::abi_slot_snapshot(handle)
            .ok_or_else(|| "missing wasm ftsynth weight slot after".to_string())
            .map(|slot| ftsynth_wasm_slot_state(&slot))?;
        rows.push(ftsynth_weight_row_json(row, before, after));
    }
    Ok(ftsynth_output(rows))
}

fn wasm_done_face(handle: usize) {
    if handle != 0 {
        let _ = wasm_abi::fontdone_wasm_done_face(handle);
    }
}

fn rust_new_memory_face(case: &InputCase) -> Result<RunOutput, String> {
    if open_face_name_options_runtime_supported(case) {
        return rust_open_face_name_options(case);
    }
    if case.inputs.params.get("variants").is_some() {
        return rust_new_memory_face_variants(case);
    }
    if lifecycle_handle_param(&case.inputs.params, "file_base") == Some("null") {
        // C `FT_New_Memory_Face` rejects a null file_base before parsing data.
        // The safe Rust core receives slices, so this row validates wrapper input policy.
        return Ok(error(FT_Err_Invalid_Argument));
    }
    let data = font_bytes(case)?;
    let library = FT_Init_FreeType();
    match FT_New_Memory_Face(
        &library,
        data.as_ref(),
        face_index_param(&case.inputs.params)?,
        20.0,
    ) {
        Ok(mut face) => {
            if is_face_probe(case)? {
                return Ok(ok(json!({"opened": true})));
            }
            let (pixel_width, pixel_height) = pixel_size_param(&case.inputs.params)?;
            let err = FT_Set_Pixel_Sizes(&mut face, pixel_width, pixel_height);
            if err == FT_Err_Ok {
                Ok(ok(json!({"opened": true})))
            } else {
                Ok(error(err))
            }
        }
        Err(err) => Ok(error(err)),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct OpenFaceNameOptionsRow {
    ignore_typographic_family: bool,
    ignore_typographic_subfamily: bool,
}

fn open_face_name_options_runtime_supported(case: &InputCase) -> bool {
    matches!(
        case.case_id.as_str(),
        "ftparams.FT_PARAM_TAG_IGNORE_PREFERRED_FAMILY.open_face_ignores_typographic_family"
            | "ftparams.FT_PARAM_TAG_IGNORE_PREFERRED_FAMILY.absent_or_unknown_param_uses_default_family"
            | "ftparams.FT_PARAM_TAG_IGNORE_TYPOGRAPHIC_FAMILY.open_face_uses_legacy_family_name"
            | "ftparams.FT_PARAM_TAG_IGNORE_TYPOGRAPHIC_FAMILY.null_data_accepted"
            | "ftparams.FT_PARAM_TAG_IGNORE_PREFERRED_SUBFAMILY.open_face_ignores_typographic_subfamily"
            | "ftparams.FT_PARAM_TAG_IGNORE_PREFERRED_SUBFAMILY.combined_family_and_subfamily_params"
            | "ftparams.FT_PARAM_TAG_IGNORE_TYPOGRAPHIC_SUBFAMILY.open_face_uses_legacy_subfamily_name"
            | "ftparams.FT_PARAM_TAG_IGNORE_TYPOGRAPHIC_SUBFAMILY.null_data_accepted"
    ) && has_runtime_font_source(case)
        && assets_are_runtime_resolved(case)
        && open_face_name_option_rows(&case.inputs.params).is_ok_and(|rows| !rows.is_empty())
}

fn open_face_name_option_rows_arg(params: &Value) -> Result<String, String> {
    Ok(open_face_name_option_rows(params)?
        .into_iter()
        .map(|row| {
            format!(
                "{}:{}",
                if row.ignore_typographic_family { 1 } else { 0 },
                if row.ignore_typographic_subfamily {
                    1
                } else {
                    0
                }
            )
        })
        .collect::<Vec<_>>()
        .join(","))
}

fn open_face_name_option_rows(params: &Value) -> Result<Vec<OpenFaceNameOptionsRow>, String> {
    if let Some(scenarios) = params.get("scenarios").and_then(Value::as_array) {
        return scenarios
            .iter()
            .map(open_face_name_option_row)
            .collect::<Result<Vec<_>, _>>();
    }
    if let Some(open_args) = params.get("open_args") {
        return Ok(vec![open_face_name_option_row(open_args)?]);
    }
    Ok(vec![open_face_name_option_row(params)?])
}

fn open_face_name_option_row(value: &Value) -> Result<OpenFaceNameOptionsRow, String> {
    let params = value
        .get("params")
        .or_else(|| value.get("parameters"))
        .and_then(Value::as_array);
    let mut row = OpenFaceNameOptionsRow {
        ignore_typographic_family: false,
        ignore_typographic_subfamily: false,
    };
    let Some(params) = params else {
        return Ok(row);
    };
    for param in params {
        let Some(tag) = param.get("tag").and_then(Value::as_str) else {
            continue;
        };
        match tag {
            "FT_PARAM_TAG_IGNORE_PREFERRED_FAMILY" | "FT_PARAM_TAG_IGNORE_TYPOGRAPHIC_FAMILY" => {
                row.ignore_typographic_family = true
            }
            "FT_PARAM_TAG_IGNORE_PREFERRED_SUBFAMILY"
            | "FT_PARAM_TAG_IGNORE_TYPOGRAPHIC_SUBFAMILY" => {
                row.ignore_typographic_subfamily = true;
            }
            _ => {}
        }
    }
    Ok(row)
}

fn open_face_name_output(
    status: FT_Error,
    family_name: Option<&str>,
    style_name: Option<&str>,
) -> Value {
    json!({
        "return": status,
        "status": status,
        "opened": status == FT_Err_Ok,
        "family_name": nullable_c_string_json(family_name),
        "style_name": nullable_c_string_json(style_name)
    })
}

fn open_face_name_run_output(results: Vec<Value>) -> RunOutput {
    let first_error = results
        .iter()
        .filter_map(|row| row.get("status").and_then(Value::as_i64))
        .find(|status| *status != i64::from(FT_Err_Ok))
        .unwrap_or(i64::from(FT_Err_Ok)) as FT_Error;
    let output = json!({ "results": results });
    if first_error == FT_Err_Ok {
        ok(output)
    } else {
        error_with_output(first_error, output)
    }
}

fn rust_open_face_name_options(case: &InputCase) -> Result<RunOutput, String> {
    let data = font_bytes(case)?;
    let library = FT_Init_FreeType();
    let face_index = face_index_param(&case.inputs.params)?;
    let mut results = Vec::new();
    for row in open_face_name_option_rows(&case.inputs.params)? {
        let status = FT_New_Memory_Face_With_Name_Options(
            &library,
            data.as_ref(),
            face_index,
            20.0,
            FT_Open_Face_Name_Options {
                ignore_typographic_family: row.ignore_typographic_family,
                ignore_typographic_subfamily: row.ignore_typographic_subfamily,
            },
        );
        match status {
            Ok(face) => results.push(open_face_name_output(
                FT_Err_Ok,
                face.family_name.as_deref(),
                face.style_name.as_deref(),
            )),
            Err(err) => results.push(open_face_name_output(err, None, None)),
        }
    }
    Ok(open_face_name_run_output(results))
}

fn c_open_face_name_options(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let mut library = std::ptr::null_mut();
    let err = c_abi::FT_Init_FreeType(&mut library);
    if err != FT_Err_Ok {
        return Ok(error(err));
    }
    let mut results = Vec::new();
    let face_index = face_index_param(&case.inputs.params)?;
    for row in open_face_name_option_rows(&case.inputs.params)? {
        let mut params = Vec::new();
        if row.ignore_typographic_family {
            params.push(c_abi::FT_Parameter {
                tag: FT_PARAM_TAG_IGNORE_TYPOGRAPHIC_FAMILY as c_abi::FT_ULong,
                data: std::ptr::null_mut(),
            });
        }
        if row.ignore_typographic_subfamily {
            params.push(c_abi::FT_Parameter {
                tag: FT_PARAM_TAG_IGNORE_TYPOGRAPHIC_SUBFAMILY as c_abi::FT_ULong,
                data: std::ptr::null_mut(),
            });
        }
        let file_size = i64::try_from(bytes.len()).map_err(|err| err.to_string())?;
        let num_params = c_abi::FT_Int::try_from(params.len())
            .map_err(|err| format!("FT_Parameter count does not fit FT_Int: {err}"))?;
        let open_args = c_abi::FT_Open_Args {
            flags: (FT_OPEN_MEMORY | FT_OPEN_PARAMS) as c_abi::FT_UInt,
            memory_base: bytes.as_ptr(),
            memory_size: file_size,
            pathname: std::ptr::null_mut(),
            stream: std::ptr::null_mut(),
            driver: std::ptr::null_mut(),
            num_params,
            params: params.as_mut_ptr(),
        };
        let mut face = std::ptr::null_mut();
        let err = c_abi::FT_Open_Face(library, &open_args, face_index, &mut face);
        if err == FT_Err_Ok {
            let info =
                c_abi::abi_face_info(face).ok_or_else(|| "missing c face info".to_string())?;
            let family = c_nullable_c_string_json(info.family_name);
            let style = c_nullable_c_string_json(info.style_name);
            results.push(json!({
                "return": err,
                "status": err,
                "opened": true,
                "family_name": family,
                "style_name": style
            }));
            c_done_face(face);
        } else {
            results.push(open_face_name_output(err, None, None));
        }
    }
    c_done_library(library);
    Ok(open_face_name_run_output(results))
}

fn wasm_open_face_name_options(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let face_index = face_index_param(&case.inputs.params)?;
    let mut results = Vec::new();
    for row in open_face_name_option_rows(&case.inputs.params)? {
        let status = wasm_abi::fontdone_wasm_open_face_with_name_options(
            bytes.as_ptr(),
            bytes.len(),
            face_index,
            20.0,
            row.ignore_typographic_family.into(),
            row.ignore_typographic_subfamily.into(),
        );
        if status.error == FT_Err_Ok {
            let (family, style) = wasm_abi::abi_face_names(status.handle)
                .ok_or_else(|| "missing wasm face names".to_string())?;
            results.push(open_face_name_output(
                status.error,
                family.as_deref(),
                style.as_deref(),
            ));
        } else {
            results.push(open_face_name_output(status.error, None, None));
        }
        wasm_done_face(status.handle);
    }
    Ok(open_face_name_run_output(results))
}

fn open_face_stream_output(status: FT_Error, face_flags: FT_Long, close_calls: i32) -> RunOutput {
    let output = json!({
        "return": status,
        "status": status,
        "opened": status == FT_Err_Ok,
        "face_flags": face_flags,
        "bit_set": (face_flags & FT_FACE_FLAG_EXTERNAL_STREAM) != 0,
        "stream_close_calls": close_calls,
        "client_stream_alive_after_done_face": true
    });
    if status == FT_Err_Ok {
        ok(output)
    } else {
        error_with_output(status, output)
    }
}

fn rust_open_face_stream(case: &InputCase) -> Result<RunOutput, String> {
    let data = font_bytes(case)?;
    let library = FT_Init_FreeType();
    let face_index = face_index_param(&case.inputs.params)?;
    match FT_Open_External_Stream_Face_With_Name_Options(
        &library,
        data.as_ref(),
        face_index,
        20.0,
        FT_Open_Face_Name_Options::default(),
    ) {
        Ok(face) => {
            let face_flags = face.face_flags;
            let err = FT_Done_Face(Some(face));
            Ok(open_face_stream_output(err, face_flags, 1))
        }
        Err(err) => Ok(open_face_stream_output(err, 0, 0)),
    }
}

static C_OPEN_FACE_STREAM_CLOSE_CALLS: AtomicI32 = AtomicI32::new(0);

extern "C" fn c_open_face_stream_close(_stream: c_abi::FT_Stream) {
    C_OPEN_FACE_STREAM_CLOSE_CALLS.fetch_add(1, Ordering::SeqCst);
}

fn c_open_face_stream(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    C_OPEN_FACE_STREAM_CLOSE_CALLS.store(0, Ordering::SeqCst);
    let mut library = std::ptr::null_mut();
    let init_err = c_abi::FT_Init_FreeType(&mut library);
    if init_err != FT_Err_Ok {
        return Ok(error(init_err));
    }
    let mut stream = c_abi::FT_StreamRec {
        base: bytes.as_ptr().cast_mut(),
        size: c_abi::FT_ULong::try_from(bytes.len())
            .map_err(|err| format!("font size does not fit FT_ULong: {err}"))?,
        pos: 0,
        descriptor: c_abi::FT_StreamDesc {
            pointer: std::ptr::null_mut(),
        },
        pathname: c_abi::FT_StreamDesc {
            pointer: std::ptr::null_mut(),
        },
        read: std::ptr::null_mut(),
        close: c_open_face_stream_close as *const () as *mut c_void,
        memory: std::ptr::null_mut(),
        cursor: std::ptr::null_mut(),
        limit: std::ptr::null_mut(),
    };
    let open_args = c_abi::FT_Open_Args {
        flags: FT_OPEN_STREAM as c_abi::FT_UInt,
        memory_base: std::ptr::null(),
        memory_size: 0,
        pathname: std::ptr::null_mut(),
        stream: &mut stream,
        driver: std::ptr::null_mut(),
        num_params: 0,
        params: std::ptr::null_mut(),
    };
    let mut face = std::ptr::null_mut();
    let err = c_abi::FT_Open_Face(
        library,
        &open_args,
        face_index_param(&case.inputs.params)?,
        &mut face,
    );
    let face_flags = if err == FT_Err_Ok {
        let info = c_abi::abi_face_info(face).ok_or_else(|| "missing c face info".to_string())?;
        info.face_flags
    } else {
        0
    };
    if err == FT_Err_Ok {
        c_done_face(face);
    }
    let close_calls = C_OPEN_FACE_STREAM_CLOSE_CALLS.load(Ordering::SeqCst);
    c_done_library(library);
    Ok(open_face_stream_output(err, face_flags, close_calls))
}

fn wasm_open_face_stream(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let status = wasm_abi::fontdone_wasm_open_external_stream_face(
        bytes.as_ptr(),
        bytes.len(),
        face_index_param(&case.inputs.params)?,
        20.0,
    );
    let face_flags = if status.error == FT_Err_Ok {
        let info = wasm_abi::abi_face_info(status.handle)
            .ok_or_else(|| "missing wasm face info".to_string())?;
        info.face_flags
    } else {
        0
    };
    if status.error == FT_Err_Ok {
        wasm_done_face(status.handle);
    }
    Ok(open_face_stream_output(status.error, face_flags, 1))
}

fn memory_stream_frame_reads(params: &Value) -> Result<Vec<(usize, usize)>, String> {
    params
        .get("stream_probe")
        .and_then(|probe| probe.get("frame_reads"))
        .and_then(Value::as_array)
        .ok_or_else(|| "missing stream_probe.frame_reads".to_string())?
        .iter()
        .map(|row| {
            let offset = row
                .get("offset")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok())
                .ok_or_else(|| format!("invalid stream frame-read offset {row}"))?;
            let count = row
                .get("count")
                .and_then(Value::as_u64)
                .and_then(|value| usize::try_from(value).ok())
                .ok_or_else(|| format!("invalid stream frame-read count {row}"))?;
            Ok((offset, count))
        })
        .collect()
}

fn memory_stream_probe_output(
    status: FT_Error,
    stream: Option<FT_StreamRec>,
    bytes: &[u8],
    frame_reads: &[(usize, usize)],
) -> RunOutput {
    let stream_fields = stream.map_or_else(
        || {
            json!({
                "base_nullness": true,
                "size": 0,
                "pos": 0,
                "cursor_nullness": true,
                "limit_nullness": true
            })
        },
        |stream| {
            json!({
                "base_nullness": stream.base.is_null(),
                "size": stream.size,
                "pos": stream.pos,
                "cursor_nullness": stream.cursor.is_null(),
                "limit_nullness": stream.limit.is_null()
            })
        },
    );
    let frame_read_events = frame_reads
        .iter()
        .map(|(offset, count)| {
            let end = offset.saturating_add(*count).min(bytes.len());
            let in_bounds = *offset <= bytes.len() && offset.saturating_add(*count) <= bytes.len();
            let slice = if *offset <= bytes.len() {
                &bytes[*offset..end]
            } else {
                &[]
            };
            json!({
                "offset": offset,
                "count": count,
                "in_bounds": in_bounds,
                "bytes": hex_bytes(slice)
            })
        })
        .collect::<Vec<_>>();
    let output = json!({
        "face_load_status": status,
        "stream_fields": stream_fields,
        "frame_read_events": frame_read_events
    });
    if status == FT_Err_Ok {
        ok(output)
    } else {
        error_with_output(status, output)
    }
}

fn rust_memory_stream_probe(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let frame_reads = memory_stream_frame_reads(&case.inputs.params)?;
    let library = FT_Init_FreeType();
    match FT_New_Memory_Face(
        &library,
        bytes.as_ref(),
        face_index_param(&case.inputs.params)?,
        20.0,
    ) {
        Ok(face) => Ok(memory_stream_probe_output(
            FT_Err_Ok,
            Some(face.memory_stream_record()),
            bytes.as_ref(),
            &frame_reads,
        )),
        Err(err) => Ok(memory_stream_probe_output(
            err,
            None,
            bytes.as_ref(),
            &frame_reads,
        )),
    }
}

fn c_memory_stream_probe(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let frame_reads = memory_stream_frame_reads(&case.inputs.params)?;
    let mut library = std::ptr::null_mut();
    let init_err = c_abi::FT_Init_FreeType(&mut library);
    if init_err != FT_Err_Ok {
        return Ok(memory_stream_probe_output(
            init_err,
            None,
            bytes.as_ref(),
            &frame_reads,
        ));
    }
    let mut face = std::ptr::null_mut();
    let err = c_abi::FT_New_Memory_Face(
        library,
        bytes.as_ptr(),
        i64::try_from(bytes.len()).map_err(|err| err.to_string())?,
        face_index_param(&case.inputs.params)?,
        &mut face,
    );
    let stream = if err == FT_Err_Ok {
        c_abi::abi_face_stream_info(face)
    } else {
        None
    };
    let output = memory_stream_probe_output(err, stream, bytes.as_ref(), &frame_reads);
    if err == FT_Err_Ok {
        c_done_face(face);
    }
    c_done_library(library);
    Ok(output)
}

fn wasm_memory_stream_probe(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let frame_reads = memory_stream_frame_reads(&case.inputs.params)?;
    let status = wasm_abi::fontdone_wasm_open_face(
        bytes.as_ptr(),
        bytes.len(),
        face_index_param(&case.inputs.params)?,
        20.0,
    );
    let stream = if status.error == FT_Err_Ok {
        wasm_abi::abi_face_stream_info(status.handle)
    } else {
        None
    };
    let output = memory_stream_probe_output(status.error, stream, bytes.as_ref(), &frame_reads);
    wasm_done_face(status.handle);
    Ok(output)
}

