fn open_face_ignored_params_runtime_supported(case: &InputCase) -> bool {
    matches!(
        case.case_id.as_str(),
        "ftparams.FT_PARAM_TAG_IGNORE_SBIX.unsupported_or_non_sbix_no_spurious_failure"
            | "ftparams.FT_PARAM_TAG_UNPATENTED_HINTING.open_face_no_effect"
            | "ftparams.FT_PARAM_TAG_UNPATENTED_HINTING.null_data_accepted_or_ignored"
    ) && has_runtime_font_source(case)
        && assets_are_runtime_resolved(case)
}

fn open_face_ignored_params_compare_control(case: &InputCase) -> bool {
    case.case_id == "ftparams.FT_PARAM_TAG_UNPATENTED_HINTING.open_face_no_effect"
}

fn open_face_ignored_params_probe(params: &Value) -> &Value {
    params.get("probe").unwrap_or(params)
}

fn open_face_ignored_params_glyph_index(params: &Value) -> u32 {
    let probe = open_face_ignored_params_probe(params);
    probe
        .get("glyph_index")
        .or_else(|| params.get("probe_glyph_index"))
        .and_then(|value| u32_value(value, "glyph_index").ok())
        .unwrap_or(0)
}

fn open_face_ignored_params_load_flags(params: &Value) -> Result<i32, String> {
    load_flags_param(open_face_ignored_params_probe(params))
}

fn open_face_ignored_params_size_ppem(params: &Value) -> Result<u32, String> {
    open_face_ignored_params_probe(params)
        .get("size_ppem")
        .map_or(Ok(0), |value| u32_value(value, "size_ppem"))
}

fn rust_open_face_ignored_observation(mut face: FT_Face, params: &Value) -> Result<Value, String> {
    let mut size_error = FT_Err_Ok;
    if let Some(size_ppem) = open_face_ignored_params_probe(params).get("size_ppem") {
        let size = u32_value(size_ppem, "size_ppem")?;
        size_error = FT_Set_Pixel_Sizes(&mut face, size, size);
        if size_error != FT_Err_Ok {
            return Ok(json!({
                "open_error": FT_Err_Ok,
                "face_flags": face.face_flags,
                "size_error": size_error,
                "load_error": size_error,
                "glyph_slot": Value::Null
            }));
        }
    }
    let glyph_index = open_face_ignored_params_glyph_index(params);
    let load_flags = open_face_ignored_params_load_flags(params)?;
    match FT_Load_Glyph(&face, glyph_index, load_flags) {
        Ok(slot) => Ok(json!({
            "open_error": FT_Err_Ok,
            "face_flags": face.face_flags,
            "size_error": size_error,
            "load_error": FT_Err_Ok,
            "glyph_slot": slot_json(&slot)
        })),
        Err(err) => Ok(json!({
            "open_error": FT_Err_Ok,
            "face_flags": face.face_flags,
            "size_error": size_error,
            "load_error": err,
            "glyph_slot": Value::Null
        })),
    }
}

fn rust_open_face_ignored_params(case: &InputCase) -> Result<RunOutput, String> {
    let data = font_bytes(case)?;
    let library = FT_Init_FreeType();
    let face_index = face_index_param(&case.inputs.params)?;
    let open = || FT_New_Memory_Face(&library, data.as_ref(), face_index, 20.0);
    if open_face_ignored_params_compare_control(case) {
        let control = match open() {
            Ok(face) => rust_open_face_ignored_observation(face, &case.inputs.params)?,
            Err(err) => {
                json!({"open_error": err, "face_flags": Value::Null, "glyph_slot": Value::Null})
            }
        };
        let test = match open() {
            Ok(face) => rust_open_face_ignored_observation(face, &case.inputs.params)?,
            Err(err) => {
                json!({"open_error": err, "face_flags": Value::Null, "glyph_slot": Value::Null})
            }
        };
        Ok(ok(json!({"control": control, "test": test})))
    } else {
        let output = match open() {
            Ok(face) => rust_open_face_ignored_observation(face, &case.inputs.params)?,
            Err(err) => {
                json!({"open_error": err, "face_flags": Value::Null, "glyph_slot": Value::Null})
            }
        };
        Ok(ok(output))
    }
}

fn ft_param_tag_value(tag: &str) -> Option<c_abi::FT_ULong> {
    match tag {
        "FT_PARAM_TAG_IGNORE_SBIX" => Some(FT_PARAM_TAG_IGNORE_SBIX as c_abi::FT_ULong),
        "FT_PARAM_TAG_UNPATENTED_HINTING" => {
            Some(FT_PARAM_TAG_UNPATENTED_HINTING as c_abi::FT_ULong)
        }
        _ => None,
    }
}

fn c_open_face_with_ignored_params(
    library: c_abi::FT_Library,
    bytes: &[u8],
    face_index: i64,
    fixture_params: &Value,
) -> Result<(FT_Error, c_abi::FT_Face), String> {
    let parameter_rows = fixture_params
        .get("parameters")
        .or_else(|| fixture_params.get("test_parameters"))
        .and_then(Value::as_array)
        .ok_or_else(|| "missing ignored FT_Open_Face parameter rows".to_string())?;
    let mut non_null_values = vec![1 as c_abi::FT_Bool; parameter_rows.len()];
    let mut params = Vec::with_capacity(parameter_rows.len());
    for (index, row) in parameter_rows.iter().enumerate() {
        let tag_name = row
            .get("tag")
            .and_then(Value::as_str)
            .ok_or_else(|| "missing ignored FT_Open_Face parameter tag".to_string())?;
        let tag = ft_param_tag_value(tag_name)
            .ok_or_else(|| format!("unsupported ignored FT_Open_Face parameter tag {tag_name}"))?;
        let data = if row
            .get("data_pointer_class")
            .and_then(Value::as_str)
            .is_some_and(|class| class == "non_null_ignored")
        {
            std::ptr::from_mut(&mut non_null_values[index]).cast::<c_void>()
        } else {
            std::ptr::null_mut()
        };
        params.push(c_abi::FT_Parameter { tag, data });
    }
    let file_size = i64::try_from(bytes.len()).map_err(|err| err.to_string())?;
    let open_args = c_abi::FT_Open_Args {
        flags: (FT_OPEN_MEMORY | FT_OPEN_PARAMS) as c_abi::FT_UInt,
        memory_base: bytes.as_ptr(),
        memory_size: file_size,
        pathname: std::ptr::null_mut(),
        stream: std::ptr::null_mut(),
        driver: std::ptr::null_mut(),
        num_params: params.len() as c_abi::FT_Int,
        params: params.as_mut_ptr(),
    };
    let mut face = std::ptr::null_mut();
    let err = c_abi::FT_Open_Face(library, &open_args, face_index, &mut face);
    Ok((err, face))
}

fn c_open_face_ignored_observation(face: c_abi::FT_Face, params: &Value) -> Result<Value, String> {
    let info = c_abi::abi_face_info(face).ok_or_else(|| "missing c face info".to_string())?;
    let mut size_error = FT_Err_Ok;
    if let Some(size_ppem) = open_face_ignored_params_probe(params).get("size_ppem") {
        let size = u32_value(size_ppem, "size_ppem")?;
        size_error = c_abi::FT_Set_Pixel_Sizes(face, size, size);
        if size_error != FT_Err_Ok {
            return Ok(json!({
                "open_error": FT_Err_Ok,
                "face_flags": info.face_flags,
                "size_error": size_error,
                "load_error": size_error,
                "glyph_slot": Value::Null
            }));
        }
    }
    let glyph_index = open_face_ignored_params_glyph_index(params);
    let load_flags = open_face_ignored_params_load_flags(params)?;
    let err = c_abi::FT_Load_Glyph(face, glyph_index, load_flags);
    Ok(json!({
        "open_error": FT_Err_Ok,
        "face_flags": info.face_flags,
        "size_error": size_error,
        "load_error": err,
        "glyph_slot": if err == FT_Err_Ok { c_slot_json(face)? } else { Value::Null }
    }))
}

fn c_open_face_ignored_params(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let mut library = std::ptr::null_mut();
    let init_err = c_abi::FT_Init_FreeType(&mut library);
    if init_err != FT_Err_Ok {
        return Ok(error(init_err));
    }
    let face_index = face_index_param(&case.inputs.params)?;
    if open_face_ignored_params_compare_control(case) {
        let mut control = std::ptr::null_mut();
        let file_size = i64::try_from(bytes.len()).map_err(|err| err.to_string())?;
        let control_err =
            c_abi::FT_New_Memory_Face(library, bytes.as_ptr(), file_size, face_index, &mut control);
        let control_output = if control_err == FT_Err_Ok {
            c_open_face_ignored_observation(control, &case.inputs.params)?
        } else {
            json!({"open_error": control_err, "face_flags": Value::Null, "glyph_slot": Value::Null})
        };
        let (test_err, test) = c_open_face_with_ignored_params(
            library,
            bytes.as_ref(),
            face_index,
            &case.inputs.params,
        )?;
        let test_output = if test_err == FT_Err_Ok {
            c_open_face_ignored_observation(test, &case.inputs.params)?
        } else {
            json!({"open_error": test_err, "face_flags": Value::Null, "glyph_slot": Value::Null})
        };
        c_done_face(control);
        c_done_face(test);
        c_done_library(library);
        Ok(ok(json!({"control": control_output, "test": test_output})))
    } else {
        let (err, face) = c_open_face_with_ignored_params(
            library,
            bytes.as_ref(),
            face_index,
            &case.inputs.params,
        )?;
        let output = if err == FT_Err_Ok {
            c_open_face_ignored_observation(face, &case.inputs.params)?
        } else {
            json!({"open_error": err, "face_flags": Value::Null, "glyph_slot": Value::Null})
        };
        c_done_face(face);
        c_done_library(library);
        Ok(ok(output))
    }
}

fn wasm_open_face_ignored_observation(handle: usize, params: &Value) -> Result<Value, String> {
    let info =
        wasm_abi::abi_face_info(handle).ok_or_else(|| "missing wasm face info".to_string())?;
    let mut size_error = FT_Err_Ok;
    if let Some(size_ppem) = open_face_ignored_params_probe(params).get("size_ppem") {
        let size = u32_value(size_ppem, "size_ppem")?;
        size_error = wasm_abi::fontdone_wasm_set_pixel_sizes(handle, size, size);
        if size_error != FT_Err_Ok {
            return Ok(json!({
                "open_error": FT_Err_Ok,
                "face_flags": info.face_flags,
                "size_error": size_error,
                "load_error": size_error,
                "glyph_slot": Value::Null
            }));
        }
    }
    let glyph_index = if handle == 0 {
        open_face_ignored_params_glyph_index(params)
    } else {
        wasm_resolved_glyph_index(handle, open_face_ignored_params_probe(params))
            .unwrap_or_else(|_| open_face_ignored_params_glyph_index(params))
    };
    let load_flags = open_face_ignored_params_load_flags(params)?;
    let err = wasm_abi::fontdone_wasm_load_glyph(handle, glyph_index, load_flags);
    Ok(json!({
        "open_error": FT_Err_Ok,
        "face_flags": info.face_flags,
        "size_error": size_error,
        "load_error": err,
        "glyph_slot": if err == FT_Err_Ok { wasm_slot_json(handle)? } else { Value::Null }
    }))
}

fn wasm_open_face_ignored_params(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let face_index = face_index_param(&case.inputs.params)?;
    let open = || wasm_abi::fontdone_wasm_open_face(bytes.as_ptr(), bytes.len(), face_index, 20.0);
    if open_face_ignored_params_compare_control(case) {
        let control_status = open();
        let control = if control_status.error == FT_Err_Ok {
            wasm_open_face_ignored_observation(control_status.handle, &case.inputs.params)?
        } else {
            json!({"open_error": control_status.error, "face_flags": Value::Null, "glyph_slot": Value::Null})
        };
        let test_status = open();
        let test = if test_status.error == FT_Err_Ok {
            wasm_open_face_ignored_observation(test_status.handle, &case.inputs.params)?
        } else {
            json!({"open_error": test_status.error, "face_flags": Value::Null, "glyph_slot": Value::Null})
        };
        wasm_done_face(control_status.handle);
        wasm_done_face(test_status.handle);
        Ok(ok(json!({"control": control, "test": test})))
    } else {
        let status = open();
        let output = if status.error == FT_Err_Ok {
            wasm_open_face_ignored_observation(status.handle, &case.inputs.params)?
        } else {
            json!({"open_error": status.error, "face_flags": Value::Null, "glyph_slot": Value::Null})
        };
        wasm_done_face(status.handle);
        Ok(ok(output))
    }
}

fn rust_new_memory_face_variants(case: &InputCase) -> Result<RunOutput, String> {
    let data = font_bytes(case)?;
    let library = FT_Init_FreeType();
    let rows = memory_face_rows(&case.inputs.params)?;
    memory_face_outputs(rows, |row| {
        if row.library_is_null {
            return Ok((FT_Err_Invalid_Library_Handle as FT_Error, true));
        }
        if row.open_args_is_null {
            return Ok((FT_Err_Invalid_Argument, true));
        }
        if row.aface_is_null {
            return Ok((FT_Err_Invalid_Argument, true));
        }
        if case.subject == "freetype.FT_Open_Face" {
            let source_flags =
                row.open_flags & (FT_OPEN_MEMORY | FT_OPEN_STREAM | FT_OPEN_PATHNAME);
            if source_flags != FT_OPEN_MEMORY {
                // C `FT_Open_Face` rejects calls unless exactly one source flag
                // is selected before any driver probing (ftobjs.c:2524-2547).
                return Ok((FT_Err_Invalid_Argument, true));
            }
        }
        let Some(bytes) = memory_face_row_bytes(data.as_ref(), row)? else {
            return Ok((FT_Err_Invalid_Argument, true));
        };
        match FT_New_Memory_Face(&library, bytes, row.face_index, 20.0) {
            Ok(_face) => Ok((FT_Err_Ok, false)),
            Err(err) => Ok((err, true)),
        }
    })
}

fn rust_new_face_variants(case: &InputCase) -> Result<RunOutput, String> {
    let pathname = font_pathname(case)?;
    let library = FT_Init_FreeType();
    let rows = memory_face_rows(&case.inputs.params)?;
    memory_face_outputs(rows, |row| {
        if row.library_is_null {
            return Ok((FT_Err_Invalid_Library_Handle as FT_Error, true));
        }
        if row.aface_is_null {
            return Ok((FT_Err_Invalid_Argument, true));
        }
        match FT_New_Face(&library, &pathname, row.face_index, 20.0) {
            Ok(_face) => Ok((FT_Err_Ok, false)),
            Err(err) => Ok((err, true)),
        }
    })
}

fn c_new_memory_face_variants(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let rows = memory_face_rows(&case.inputs.params)?;
    let mut library = std::ptr::null_mut();
    let err = c_abi::FT_Init_FreeType(&mut library);
    if err != FT_Err_Ok {
        return Ok(error(err));
    }
    let output = memory_face_outputs(rows, |row| {
        let file_size = memory_face_file_size(bytes.len(), row)?;
        let library_arg = if row.library_is_null {
            std::ptr::null_mut()
        } else {
            library
        };
        let mut face = std::ptr::null_mut();
        let face_ptr = if row.aface_is_null {
            std::ptr::null_mut()
        } else {
            &mut face
        };
        let open_args = c_abi::FT_Open_Args {
            flags: row.open_flags as c_abi::FT_UInt,
            memory_base: bytes.as_ptr(),
            memory_size: file_size,
            pathname: std::ptr::null_mut(),
            stream: std::ptr::null_mut(),
            driver: std::ptr::null_mut(),
            num_params: 0,
            params: std::ptr::null_mut(),
        };
        let err = if case.subject == "freetype.FT_Open_Face"
            || row.has_open_args
            || row.open_args_is_null
        {
            let args_ptr = if row.open_args_is_null {
                std::ptr::null()
            } else {
                &open_args
            };
            c_abi::FT_Open_Face(library_arg, args_ptr, row.face_index, face_ptr)
        } else {
            c_abi::FT_New_Memory_Face(
                library_arg,
                bytes.as_ptr(),
                file_size,
                row.face_index,
                face_ptr,
            )
        };
        let face_is_null = face.is_null();
        if err == FT_Err_Ok {
            c_done_face(face);
        }
        Ok((err, face_is_null))
    });
    c_done_library(library);
    output
}

fn c_new_memory_face_null_base(case: &InputCase) -> Result<RunOutput, String> {
    let mut library = std::ptr::null_mut();
    let init_err = c_abi::FT_Init_FreeType(&mut library);
    if init_err != FT_Err_Ok {
        return Ok(error(init_err));
    }
    let mut face = std::ptr::null_mut();
    let err = c_abi::FT_New_Memory_Face(
        library,
        ptr::null(),
        i64_param(&case.inputs.params, "file_size")?,
        face_index_param(&case.inputs.params)?,
        &mut face,
    );
    if err == FT_Err_Ok {
        c_done_face(face);
    }
    c_done_library(library);
    if err == FT_Err_Ok {
        Ok(ok(json!({"opened": true})))
    } else {
        Ok(error(err))
    }
}

fn wasm_new_memory_face_variants(case: &InputCase) -> Result<RunOutput, String> {
    let bytes = font_bytes(case)?;
    let rows = memory_face_rows(&case.inputs.params)?;
    memory_face_outputs(rows, |row| {
        if row.library_is_null {
            return Ok((FT_Err_Invalid_Library_Handle as FT_Error, true));
        }
        if row.open_args_is_null {
            return Ok((FT_Err_Invalid_Argument, true));
        }
        if row.aface_is_null {
            return Ok((FT_Err_Invalid_Argument, true));
        }
        if case.subject == "freetype.FT_Open_Face" {
            let source_flags =
                row.open_flags & (FT_OPEN_MEMORY | FT_OPEN_STREAM | FT_OPEN_PATHNAME);
            if source_flags != FT_OPEN_MEMORY {
                return Ok((FT_Err_Invalid_Argument, true));
            }
        }
        let file_size = memory_face_file_size(bytes.len(), row)?;
        let Ok(file_size) = usize::try_from(file_size) else {
            return Ok((FT_Err_Invalid_Argument, true));
        };
        let status =
            wasm_abi::fontdone_wasm_open_face(bytes.as_ptr(), file_size, row.face_index, 20.0);
        let face_is_null = status.handle == 0;
        wasm_done_face(status.handle);
        Ok((status.error, face_is_null))
    })
}

fn memory_face_outputs(
    rows: Vec<MemoryFaceRow>,
    mut call: impl FnMut(MemoryFaceRow) -> Result<(FT_Error, bool), String>,
) -> Result<RunOutput, String> {
    let mut first_error = FT_Err_Ok;
    let mut outputs = Vec::with_capacity(rows.len());
    for row in rows {
        let (status, face_is_null) = call(row)?;
        if first_error == FT_Err_Ok && status != FT_Err_Ok {
            first_error = status;
        }
        outputs.push(json!({
            "face_index": row.face_index,
            "file_size": row.file_size,
            "status": status,
            "error": status,
            "opened": !face_is_null,
            "face_nullness": if face_is_null { "null" } else { "non_null" }
        }));
    }
    let output = json!({ "outputs": outputs });
    if first_error == FT_Err_Ok {
        Ok(ok(output))
    } else {
        Ok(error_with_output(first_error, output))
    }
}

fn memory_face_file_size(data_len: usize, row: MemoryFaceRow) -> Result<i64, String> {
    Ok(row
        .file_size
        .unwrap_or_else(|| i64::try_from(data_len).unwrap_or(i64::MAX)))
}

fn memory_face_row_bytes(data: &[u8], row: MemoryFaceRow) -> Result<Option<&[u8]>, String> {
    let file_size = memory_face_file_size(data.len(), row)?;
    let Ok(file_size) = usize::try_from(file_size) else {
        return Ok(None);
    };
    data.get(..file_size).map(Some).ok_or_else(|| {
        format!(
            "file_size {file_size} exceeds fixture length {}",
            data.len()
        )
    })
}

fn rust_new_face_without_size(case: &InputCase) -> Result<FT_Face, String> {
    let data = font_bytes(case)?;
    rust_new_face_from_bytes(data.as_ref(), face_index_param(&case.inputs.params)?)
}

fn rust_new_foreign_face_without_size(case: &InputCase) -> Result<FT_Face, String> {
    let data = foreign_font_bytes(case)?;
    rust_new_face_from_bytes(data.as_ref(), 0)
}

fn rust_new_face_from_bytes(data: &[u8], face_index: i64) -> Result<FT_Face, String> {
    let library = FT_Init_FreeType();
    FT_New_Memory_Face(&library, data, face_index, 20.0)
        .map_err(|err| format!("FT_New_Memory_Face returned {err}"))
}

fn open_face(case: &InputCase) -> Result<FT_Face, String> {
    open_face_with_size_or_char_size(case, pixel_size_param(&case.inputs.params)?)
}

fn open_face_with_size_or_char_size(
    case: &InputCase,
    pixel_size: (u32, u32),
) -> Result<FT_Face, String> {
    let data = font_bytes(case)?;
    let library = FT_Init_FreeType();
    let mut face = FT_New_Memory_Face(
        &library,
        data.as_ref(),
        face_index_param(&case.inputs.params)?,
        20.0,
    )
    .map_err(|err| format!("FT_New_Memory_Face returned {err}"))?;
    if preserve_initial_size(&case.inputs.params)? {
        return Ok(face);
    }
    let err = if let Some(row) = preload_size_request_row(&case.inputs.params)? {
        let request = rust_size_request_rec(row);
        FT_Request_Size(Some(&mut face), Some(&request))
    } else if let Some(row) = preload_char_size_row(&case.inputs.params)? {
        FT_Set_Char_Size(
            &mut face,
            row.char_width,
            row.char_height,
            row.horz_resolution,
            row.vert_resolution,
        )
    } else {
        let (pixel_width, pixel_height) = pixel_size;
        FT_Set_Pixel_Sizes(&mut face, pixel_width, pixel_height)
    };
    if err == FT_Err_Ok {
        Ok(face)
    } else {
        Err(format!("FT size setup returned {err}"))
    }
}

fn open_face_with_size(case: &InputCase, pixel_size: (u32, u32)) -> Result<FT_Face, String> {
    open_face_with_size_or_char_size(case, pixel_size)
}

fn open_api_face(case: &InputCase) -> Result<ApiFace, String> {
    let data = font_bytes(case)?;
    let face_index =
        usize::try_from(face_index_param(&case.inputs.params)?).map_err(|err| err.to_string())?;
    let mut face = ApiFace::from_memory(data.as_ref(), face_index, 20.0)
        .map_err(|err| format!("Face::from_memory returned {err}"))?;
    if let Some(row) = preload_char_size_row(&case.inputs.params)? {
        let char_width = i32::try_from(row.char_width)
            .map_err(|err| format!("preload char_width does not fit i32: {err}"))?;
        let char_height = i32::try_from(row.char_height)
            .map_err(|err| format!("preload char_height does not fit i32: {err}"))?;
        face.set_char_size(
            char_width,
            char_height,
            row.horz_resolution,
            row.vert_resolution,
        );
    } else {
        let (pixel_width, pixel_height) = pixel_size_param(&case.inputs.params)?;
        face.set_pixel_sizes(pixel_width, pixel_height);
    }
    Ok(face)
}

fn rust_set_pixel_sizes(case: &InputCase) -> Result<RunOutput, String> {
    let data = font_bytes(case)?;
    let library = FT_Init_FreeType();
    match FT_New_Memory_Face(
        &library,
        data.as_ref(),
        face_index_param(&case.inputs.params)?,
        20.0,
    ) {
        Ok(mut face) => {
            let (pixel_width, pixel_height) = pixel_size_param(&case.inputs.params)?;
            let err = FT_Set_Pixel_Sizes(&mut face, pixel_width, pixel_height);
            if err == FT_Err_Ok {
                Ok(ok(size_metrics_json(&face.size_metrics)))
            } else {
                Ok(error(err))
            }
        }
        Err(err) => Ok(error(err)),
    }
}

fn rust_set_char_size(case: &InputCase) -> Result<RunOutput, String> {
    if !case.expect_error {
        return rust_set_char_size_public_api(case);
    }
    let mut face = rust_new_face_without_size(case)?;
    let rows = char_size_rows(&case.inputs.params)?;
    char_size_outputs(rows, |row| {
        let err = FT_Set_Char_Size(
            &mut face,
            row.char_width,
            row.char_height,
            row.horz_resolution,
            row.vert_resolution,
        );
        let output = if err == FT_Err_Ok {
            size_metrics_json(&face.size_metrics)
        } else {
            Value::Null
        };
        Ok((err, output))
    })
}

fn rust_set_char_size_public_api(case: &InputCase) -> Result<RunOutput, String> {
    let data = font_bytes(case)?;
    let face_index =
        usize::try_from(face_index_param(&case.inputs.params)?).map_err(|err| err.to_string())?;
    let mut face = ApiFace::from_memory(data.as_ref(), face_index, 20.0)
        .map_err(|err| format!("Face::from_memory returned {err}"))?;
    let rows = char_size_rows(&case.inputs.params)?;
    char_size_outputs(rows, |row| {
        let Ok(char_width) = i32::try_from(row.char_width) else {
            return Ok((FT_Err_Invalid_Argument, Value::Null));
        };
        let Ok(char_height) = i32::try_from(row.char_height) else {
            return Ok((FT_Err_Invalid_Argument, Value::Null));
        };
        face.set_char_size(
            char_width,
            char_height,
            row.horz_resolution,
            row.vert_resolution,
        );
        let metrics: FT_Size_Metrics = face.size_metrics().into();
        Ok((FT_Err_Ok, size_metrics_json(&metrics)))
    })
}

fn c_set_char_size(face: c_abi::FT_Face, case: &InputCase) -> Result<RunOutput, String> {
    let rows = char_size_rows(&case.inputs.params)?;
    char_size_outputs(rows, |row| {
        let err = c_abi::FT_Set_Char_Size(
            face,
            row.char_width,
            row.char_height,
            row.horz_resolution,
            row.vert_resolution,
        );
        let output = if err == FT_Err_Ok {
            c_size_metrics_json(face)?
        } else {
            Value::Null
        };
        Ok((err, output))
    })
}

fn wasm_set_char_size(handle: usize, case: &InputCase) -> Result<RunOutput, String> {
    let rows = char_size_rows(&case.inputs.params)?;
    char_size_outputs(rows, |row| {
        let err = wasm_abi::fontdone_wasm_set_char_size(
            handle,
            row.char_width,
            row.char_height,
            row.horz_resolution,
            row.vert_resolution,
        );
        let output = if err == FT_Err_Ok {
            let mut metrics = wasm_abi::FontdoneWasmSizeMetrics::default();
            let metrics_err = wasm_abi::fontdone_wasm_size_metrics(handle, &mut metrics);
            if metrics_err != FT_Err_Ok {
                return Ok((metrics_err, Value::Null));
            }
            wasm_size_metrics_json(&metrics)
        } else {
            Value::Null
        };
        Ok((err, output))
    })
}

fn char_size_outputs(
    rows: Vec<CharSizeRow>,
    mut call: impl FnMut(CharSizeRow) -> Result<(FT_Error, Value), String>,
) -> Result<RunOutput, String> {
    let mut first_error = FT_Err_Ok;
    let mut outputs = Vec::with_capacity(rows.len());
    for row in rows {
        let (status, output) = call(row)?;
        if first_error == FT_Err_Ok && status != FT_Err_Ok {
            first_error = status;
        }
        outputs.push(json!({
            "request": char_size_row_json(row),
            "status": status,
            "output": output
        }));
    }
    let output = json!({ "outputs": outputs });
    if first_error == FT_Err_Ok {
        Ok(ok(output))
    } else {
        Ok(error_with_output(first_error, output))
    }
}

fn rust_request_size(case: &InputCase) -> Result<RunOutput, String> {
    let mut face = rust_new_face_without_size(case)?;
    let rows = size_request_rows(&case.inputs.params)?;
    let mut outputs = Vec::with_capacity(rows.len());
    let mut first_error = FT_Err_Ok;
    for row in rows {
        let request = (!row.request_is_null).then(|| rust_size_request_rec(row));
        let err = if row.face_is_null {
            FT_Request_Size(None, request.as_ref())
        } else {
            FT_Request_Size(Some(&mut face), request.as_ref())
        };
        if first_error == FT_Err_Ok && err != FT_Err_Ok {
            first_error = err;
        }
        let metrics = if err == FT_Err_Ok && !row.face_is_null {
            size_metrics_json(&face.size_metrics)
        } else {
            Value::Null
        };
        outputs.push(size_request_row_output(row, err, metrics));
    }
    let output = json!({ "outputs": outputs });
    if first_error == FT_Err_Ok {
        Ok(ok(output))
    } else {
        Ok(error_with_output(first_error, output))
    }
}

fn c_request_size(face: c_abi::FT_Face, case: &InputCase) -> Result<RunOutput, String> {
    let rows = size_request_rows(&case.inputs.params)?;
    let mut outputs = Vec::with_capacity(rows.len());
    let mut first_error = FT_Err_Ok;
    for row in rows {
        let request = c_size_request_rec(row);
        let request_ptr = if row.request_is_null {
            std::ptr::null()
        } else {
            &request
        };
        let call_face = if row.face_is_null {
            std::ptr::null_mut()
        } else {
            face
        };
        let err = c_abi::FT_Request_Size(call_face, request_ptr);
        if first_error == FT_Err_Ok && err != FT_Err_Ok {
            first_error = err;
        }
        let metrics = if err == FT_Err_Ok && !row.face_is_null {
            c_size_metrics_json(face)?
        } else {
            Value::Null
        };
        outputs.push(size_request_row_output(row, err, metrics));
    }
    let output = json!({ "outputs": outputs });
    if first_error == FT_Err_Ok {
        Ok(ok(output))
    } else {
        Ok(error_with_output(first_error, output))
    }
}

fn wasm_request_size(handle: usize, case: &InputCase) -> Result<RunOutput, String> {
    let rows = size_request_rows(&case.inputs.params)?;
    let mut outputs = Vec::with_capacity(rows.len());
    let mut first_error = FT_Err_Ok;
    for row in rows {
        let request = wasm_size_request_rec(row);
        let request_ptr = if row.request_is_null {
            std::ptr::null()
        } else {
            &request
        };
        let call_handle = if row.face_is_null { 0 } else { handle };
        let err = wasm_abi::fontdone_wasm_request_size(call_handle, request_ptr);
        if first_error == FT_Err_Ok && err != FT_Err_Ok {
            first_error = err;
        }
        let metrics = if err == FT_Err_Ok && !row.face_is_null {
            let mut metrics = wasm_abi::FontdoneWasmSizeMetrics::default();
            let metrics_err = wasm_abi::fontdone_wasm_size_metrics(handle, &mut metrics);
            if metrics_err == FT_Err_Ok {
                wasm_size_metrics_json(&metrics)
            } else {
                Value::Null
            }
        } else {
            Value::Null
        };
        outputs.push(size_request_row_output(row, err, metrics));
    }
    let output = json!({ "outputs": outputs });
    if first_error == FT_Err_Ok {
        Ok(ok(output))
    } else {
        Ok(error_with_output(first_error, output))
    }
}

fn size_request_row_output(row: SizeRequestRow, err: i32, metrics: Value) -> Value {
    let request = if row.request_is_null {
        Value::Null
    } else {
        json!({
            "type": row.type_,
            "width": row.width,
            "height": row.height,
            "horiResolution": row.hori_resolution,
            "vertResolution": row.vert_resolution
        })
    };
    json!({
        "face": if row.face_is_null { "null" } else { "valid" },
        "request": request,
        "status": err,
        "metrics": metrics
    })
}

fn rust_size_request_rec(row: SizeRequestRow) -> FT_Size_RequestRec {
    FT_Size_RequestRec {
        type_: row.type_,
        width: row.width,
        height: row.height,
        horiResolution: row.hori_resolution,
        vertResolution: row.vert_resolution,
    }
}

fn c_size_request_rec(row: SizeRequestRow) -> c_abi::FT_Size_RequestRec {
    c_abi::FT_Size_RequestRec {
        type_: row.type_,
        width: row.width,
        height: row.height,
        horiResolution: row.hori_resolution,
        vertResolution: row.vert_resolution,
    }
}

fn wasm_size_request_rec(row: SizeRequestRow) -> wasm_abi::FontdoneWasmSizeRequest {
    wasm_abi::FontdoneWasmSizeRequest {
        type_: row.type_,
        width: row.width,
        height: row.height,
        horiResolution: row.hori_resolution,
        vertResolution: row.vert_resolution,
    }
}

