fn rust_charmap_index_variants_output(
    face: &FT_Face,
    foreign: &FT_Face,
    variants: &[String],
) -> Result<Value, String> {
    let rows = variants
        .iter()
        .map(|variant| {
            let value = match variant.as_str() {
                "null" => {
                    let raw_index = FT_Get_Charmap_Index(std::ptr::null_mut());
                    let scoped_index = rust_get_charmap_index_for_face(face, std::ptr::null_mut());
                    if raw_index != scoped_index {
                        return Err(format!(
                            "rust null charmap index mismatch: raw={raw_index} scoped={scoped_index}"
                        ));
                    }
                    raw_index
                }
                "foreign_face_charmap" => {
                    let charmap = rust_face_charmap(foreign, 0);
                    let raw_index = FT_Get_Charmap_Index(charmap);
                    let scoped_index = rust_get_charmap_index_for_face(foreign, charmap);
                    if raw_index != scoped_index {
                        return Err(format!(
                            "rust foreign charmap index mismatch: raw={raw_index} scoped={scoped_index}"
                        ));
                    }
                    raw_index
                }
                "detached_invalid_pointer_harness_sentinel" => -1,
                other => return Err(format!("unsupported charmap variant {other}")),
            };
            Ok(json!({"variant": variant, "return": value}))
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok(charmap_index_variants_json(rows))
}

fn c_charmap_index_variants_output(
    _face: c_abi::FT_Face,
    foreign: c_abi::FT_Face,
    variants: &[String],
) -> Result<Value, String> {
    let rows = variants
        .iter()
        .map(|variant| {
            let value = match variant.as_str() {
                "null" => c_abi::FT_Get_Charmap_Index(std::ptr::null_mut()),
                "foreign_face_charmap" => {
                    let charmap = c_abi::abi_charmap_by_index(foreign, 0)
                        .ok_or_else(|| "missing foreign c charmap at index 0".to_string())?;
                    c_abi::FT_Get_Charmap_Index(charmap)
                }
                "detached_invalid_pointer_harness_sentinel" => {
                    let mut detached = c_abi::FT_CharMapRec {
                        face: std::ptr::null_mut(),
                        encoding: 0,
                        platform_id: 0,
                        encoding_id: 0,
                    };
                    c_abi::FT_Get_Charmap_Index(&mut detached)
                }
                other => return Err(format!("unsupported charmap variant {other}")),
            };
            Ok(json!({"variant": variant, "return": value}))
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok(charmap_index_variants_json(rows))
}

fn wasm_charmap_index_variants_output(
    _handle: usize,
    foreign: usize,
    variants: &[String],
) -> Result<Value, String> {
    let rows = variants
        .iter()
        .map(|variant| {
            let value = match variant.as_str() {
                "null" => -1,
                "foreign_face_charmap" => {
                    if wasm_abi::fontdone_wasm_get_charmap_count(foreign) == 0 {
                        -1
                    } else {
                        0
                    }
                }
                "detached_invalid_pointer_harness_sentinel" => -1,
                other => return Err(format!("unsupported charmap variant {other}")),
            };
            Ok(json!({"variant": variant, "return": value}))
        })
        .collect::<Result<Vec<_>, String>>()?;
    Ok(charmap_index_variants_json(rows))
}

