fn font_bytes(case: &InputCase) -> Result<Arc<[u8]>, String> {
    match runtime_font_asset(case) {
        Some(font) => font_asset_bytes(font),
        None => {
            // Mirror push_font_source: when no font is specified and the case
            // does not expect an error, fall back to DejaVuSans.  Both the
            // C oracle (via push_font_source) and the Rust backend must agree
            // on which font data they use.
            if case.expect_error {
                return Err("missing font asset".to_string());
            }
            font_asset_bytes(&Asset::File {
                path: "input/fonts/DejaVuSans.ttf".to_string(),
                sha256: None,
                length: None,
            })
        }
    }
}

fn pfr_kerning_font_asset(case: &InputCase) -> Result<&Asset, String> {
    case.inputs
        .assets
        .get("kern_font")
        .or_else(|| runtime_font_asset(case))
        .ok_or_else(|| "missing PFR kerning fallback font asset".to_string())
}

fn pfr_kerning_font_bytes(case: &InputCase) -> Result<Arc<[u8]>, String> {
    font_asset_bytes(pfr_kerning_font_asset(case)?)
}

fn foreign_font_bytes(case: &InputCase) -> Result<Arc<[u8]>, String> {
    let font = case
        .inputs
        .assets
        .get("foreign_font")
        .ok_or_else(|| "missing foreign_font asset".to_string())?;
    font_asset_bytes(font)
}

fn named_font_bytes(case: &InputCase, name: &str) -> Result<Arc<[u8]>, String> {
    let font = case
        .inputs
        .assets
        .get(name)
        .ok_or_else(|| format!("missing {name} asset"))?;
    font_asset_bytes(font)
}

fn font_asset_bytes(font: &Asset) -> Result<Arc<[u8]>, String> {
    match font {
        Asset::List(items) => {
            let asset = items
                .iter()
                .find(|asset| asset_is_runtime_resolved(asset))
                .ok_or_else(|| format!("unresolved asset list {}", asset_label(font)))?;
            font_asset_bytes(asset)
        }
        Asset::File { .. } | Asset::Ref { .. } => {
            let path = asset_file_path(font)
                .ok_or_else(|| format!("unresolved shared asset ref {}", asset_label(font)))?;
            cached_file_bytes(path)
        }
        Asset::InlineBytes { encoding, .. } => {
            if encoding != "hex" {
                return Err(format!("unsupported inline byte encoding {encoding}"));
            }
            let value =
                inline_bytes_hex(font).ok_or_else(|| "missing inline hex bytes".to_string())?;
            cached_inline_bytes(value)
        }
        Asset::Other(_) => Err("unsupported font asset shape".to_string()),
    }
}

fn font_pathname(case: &InputCase) -> Result<String, String> {
    let font = runtime_font_asset(case).ok_or_else(|| "missing font asset".to_string())?;
    let path = asset_file_path(font)
        .ok_or_else(|| format!("FT_New_Face requires file asset, got {}", asset_label(font)))?;
    Ok(fixture_dir().join(path).display().to_string())
}

fn runtime_font_asset(case: &InputCase) -> Option<&Asset> {
    runtime_font_asset_entry(case).map(|(_, asset)| asset)
}

fn runtime_font_asset_entry(case: &InputCase) -> Option<(&str, &Asset)> {
    if case
        .inputs
        .params
        .get("charmap_selection")
        .and_then(Value::as_array)
        .is_some_and(|values| {
            values
                .iter()
                .any(|value| value.as_str() == Some("non_unicode_if_fixture_present"))
        })
    {
        if let Some(asset) = case.inputs.assets.get("non_unicode_charmap_font") {
            return Some(("non_unicode_charmap_font", asset));
        }
    }
    [
        "font",
        "hidden_axis_variable_font",
        "visible_axis_variable_font",
        "variable_font",
        "adobe_mm_font",
        "font_bytes",
        "fixture",
        "blob",
        "outline_font",
        "bitmap_strike_font",
        "svg_font",
        "composite_font",
    ]
    .into_iter()
    .find_map(|key| case.inputs.assets.get(key).map(|asset| (key, asset)))
    .or_else(|| {
        // Also check any key containing "font" (like "empty_charmap_font")
        case.inputs
            .assets
            .iter()
            .find(|(key, _)| key.contains("font"))
            .map(|(key, asset)| (key.as_str(), asset))
    })
    .or_else(|| {
        // Fallback: return the first resolved asset
        case.inputs.assets.iter().find_map(|(key, asset)| {
            if asset_is_runtime_resolved(asset) {
                Some((key.as_str(), asset))
            } else {
                None
            }
        })
    })
}

fn asset_is_runtime_resolved(asset: &Asset) -> bool {
    match asset {
        Asset::List(items) => items.iter().any(asset_is_runtime_resolved),
        Asset::File { .. } | Asset::Ref { .. } => asset_file_path(asset).is_some(),
        Asset::InlineBytes { encoding, .. } => {
            encoding == "hex" && inline_bytes_hex(asset).is_some()
        }
        Asset::Other(_) => false,
    }
}

fn asset_file_path(asset: &Asset) -> Option<&str> {
    match asset {
        Asset::List(items) => items.iter().find_map(asset_file_path),
        Asset::File { path, .. } => {
            if fixture_dir().join(path).is_file() {
                Some(path)
            } else {
                None
            }
        }
        Asset::Ref { id, path } => resolve_ref_file_path(id.as_deref(), path.as_deref()),
        Asset::InlineBytes { .. } | Asset::Other(_) => None,
    }
}

fn missing_pathname(case: &InputCase) -> Result<String, String> {
    let asset = case
        .inputs
        .assets
        .get("missing")
        .ok_or_else(|| "missing FT_New_Face missing-path asset".to_string())?;
    let path = match asset {
        Asset::File { path, .. } => path.as_str(),
        Asset::Ref {
            path: Some(path), ..
        } => path.as_str(),
        Asset::Ref { id: Some(id), .. } => id.as_str(),
        _ => {
            return Err(format!(
                "unsupported missing-path asset {}",
                asset_label(asset)
            ));
        }
    };
    let pathname = fixture_dir().join(path);
    if pathname.exists() {
        return Err(format!(
            "FT_New_Face missing-path fixture unexpectedly exists: {}",
            pathname.display()
        ));
    }
    Ok(pathname.to_string_lossy().into_owned())
}

fn resolve_ref_file_path<'a>(id: Option<&'a str>, path: Option<&'a str>) -> Option<&'a str> {
    [id, path].into_iter().flatten().find_map(|candidate| {
        if fixture_dir().join(candidate).is_file() {
            return Some(candidate);
        }
        match candidate {
            "fonts/basic/DejaVuSans.ttf"
            | "fonts/basic/dejavu-sans.ttf"
            | "fixtures/assets/fonts/DejaVuSans.ttf" => Some("input/fonts/DejaVuSans.ttf"),
            "fonts/bdf/properties-atoms-integers-cardinals.bdf" => {
                Some("input/fonts/bdf/properties-atoms-integers-cardinals.bdf")
            }
            _ => None,
        }
    })
}

fn asset_label(asset: &Asset) -> String {
    match asset {
        Asset::List(items) => items.iter().map(asset_label).collect::<Vec<_>>().join(","),
        Asset::Ref { id: Some(id), .. } => id.clone(),
        Asset::Ref {
            path: Some(path), ..
        } => path.clone(),
        Asset::Ref { .. } => "<anonymous>".to_string(),
        Asset::File { path, .. } => path.clone(),
        Asset::InlineBytes { .. } => "<inline-bytes>".to_string(),
        Asset::Other(_) => "<other-asset>".to_string(),
    }
}

fn inline_bytes_hex(asset: &Asset) -> Option<&str> {
    match asset {
        Asset::InlineBytes {
            value: Some(value), ..
        } => Some(value),
        Asset::InlineBytes {
            data: Some(data), ..
        } => Some(data),
        _ => None,
    }
}

fn cached_inline_bytes(value: &str) -> Result<Arc<[u8]>, String> {
    static CACHE: OnceLock<Mutex<BTreeMap<String, Arc<[u8]>>>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| Mutex::new(BTreeMap::new()));
    if let Some(bytes) = cache
        .lock()
        .map_err(|err| err.to_string())?
        .get(value)
        .map(Arc::clone)
    {
        return Ok(bytes);
    }
    let bytes = Arc::<[u8]>::from(decode_hex(value)?);
    let mut cache = cache.lock().map_err(|err| err.to_string())?;
    let bytes = cache
        .entry(value.to_string())
        .or_insert_with(|| Arc::clone(&bytes));
    Ok(Arc::clone(bytes))
}

fn cached_file_bytes(path: &str) -> Result<Arc<[u8]>, String> {
    static CACHE: OnceLock<Mutex<BTreeMap<String, Arc<[u8]>>>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| Mutex::new(BTreeMap::new()));
    if let Some(bytes) = cache
        .lock()
        .map_err(|err| err.to_string())?
        .get(path)
        .map(Arc::clone)
    {
        return Ok(bytes);
    }
    let bytes = Arc::<[u8]>::from(
        fs::read(fixture_dir().join(path)).map_err(|err| format!("read {path}: {err}"))?,
    );
    let mut cache = cache.lock().map_err(|err| err.to_string())?;
    let bytes = cache
        .entry(path.to_string())
        .or_insert_with(|| Arc::clone(&bytes));
    Ok(Arc::clone(bytes))
}

#[derive(Clone, Copy)]
enum GzipBackend {
    Rust,
    CAbi,
    Wasm,
}

fn gzip_payload_manifest(case: &InputCase) -> Result<GzipPayloadManifest, String> {
    let asset = case
        .inputs
        .assets
        .get("gzip_payloads")
        .ok_or_else(|| "missing gzip_payloads asset".to_string())?;
    let path =
        asset_file_path(asset).ok_or_else(|| format!("unresolved {}", asset_label(asset)))?;
    let text = fs::read_to_string(fixture_dir().join(path))
        .map_err(|err| format!("read gzip payload manifest {path}: {err}"))?;
    serde_json::from_str(&text).map_err(|err| format!("parse gzip payload manifest {path}: {err}"))
}

fn gzip_uncompress_output(case: &InputCase, backend: GzipBackend) -> Result<RunOutput, String> {
    let manifest = gzip_payload_manifest(case)?;
    let mut rows = Vec::new();
    for payload in manifest.payloads {
        let raw = cached_file_bytes(&payload.raw)?;
        let zlib_wrapped = payload.zlib_wrapped.as_deref().ok_or_else(|| {
            format!(
                "gzip uncompress payload {} missing zlib_wrapped",
                payload.id
            )
        })?;
        for (input_kind, input_path) in [
            ("gzip", payload.gzip.as_str()),
            ("zlib_wrapped", zlib_wrapped),
        ] {
            let input = cached_file_bytes(input_path)?;
            for (buffer_size, capacity) in [
                ("exact_uncompressed_size", raw.len()),
                (
                    "larger_than_uncompressed_size",
                    raw.len().checked_add(7).ok_or_else(|| {
                        format!("gzip payload {} output size overflow", payload.id)
                    })?,
                ),
            ] {
                let (status, output_len, output) =
                    gzip_uncompress_call(backend, input.as_ref(), capacity)?;
                rows.push(json!({
                    "payload": payload.id,
                    "input_kind": input_kind,
                    "buffer_size": buffer_size,
                    "status": status,
                    "output_len": output_len,
                    "output_bytes": hex_bytes(&output),
                }));
            }
        }
    }
    Ok(ok(json!({ "rows": rows })))
}

fn gzip_uncompress_call(
    backend: GzipBackend,
    input: &[u8],
    capacity: usize,
) -> Result<(FT_Error, FT_ULong, Vec<u8>), String> {
    let mut output = vec![0xA5; capacity];
    let mut output_len = FT_ULong::try_from(capacity).map_err(|err| err.to_string())?;
    let status = match backend {
        GzipBackend::Rust => {
            let memory = FT_MemoryRec::default();
            FT_Gzip_Uncompress(
                Some(&memory),
                Some(output.as_mut_slice()),
                Some(&mut output_len),
                Some(input),
            )
        }
        GzipBackend::CAbi => {
            let mut memory = c_abi::FT_MemoryRec::default();
            c_abi::FT_Gzip_Uncompress(
                &mut memory,
                output.as_mut_ptr(),
                &mut output_len,
                input.as_ptr(),
                FT_ULong::try_from(input.len()).map_err(|err| err.to_string())?,
            )
        }
        GzipBackend::Wasm => {
            let mut memory = wasm_abi::FontdoneWasmMemory::default();
            wasm_abi::fontdone_wasm_gzip_uncompress(
                &mut memory,
                output.as_mut_ptr(),
                &mut output_len,
                input.as_ptr(),
                FT_ULong::try_from(input.len()).map_err(|err| err.to_string())?,
            )
        }
    };
    let prefix_len = if status == FT_Err_Ok {
        usize::try_from(output_len).map_err(|err| err.to_string())?
    } else {
        0
    };
    Ok((status, output_len, output[..prefix_len].to_vec()))
}

#[derive(Clone, Copy)]
enum GzipStreamBackend {
    Rust,
    CAbi,
    Wasm,
}

#[derive(Clone, Copy)]
enum Bzip2StreamBackend {
    Rust,
    CAbi,
    Wasm,
}

fn gzip_stream_manifest(case: &InputCase) -> Result<GzipPayloadManifest, String> {
    let asset = case
        .inputs
        .assets
        .get("gzip_streams")
        .ok_or_else(|| "missing gzip_streams asset".to_string())?;
    let path =
        asset_file_path(asset).ok_or_else(|| format!("unresolved {}", asset_label(asset)))?;
    let text = fs::read_to_string(fixture_dir().join(path))
        .map_err(|err| format!("read gzip stream manifest {path}: {err}"))?;
    serde_json::from_str(&text).map_err(|err| format!("parse gzip stream manifest {path}: {err}"))
}

fn bzip2_disabled_stream_output(backend: Bzip2StreamBackend) -> RunOutput {
    let mut source = FT_StreamRec::default();
    let mut stream = FT_StreamRec::default();
    let status = match backend {
        Bzip2StreamBackend::Rust => FT_Stream_OpenBzip2(Some(&mut stream), Some(&source)),
        Bzip2StreamBackend::CAbi => c_abi::FT_Stream_OpenBzip2(&mut stream, &mut source),
        Bzip2StreamBackend::Wasm => wasm_abi::fontdone_wasm_stream_open_bzip2(&mut stream, &source),
    };
    RunOutput {
        status: Status {
            kind: if status == FT_Err_Ok {
                StatusKind::Ok
            } else {
                StatusKind::Error
            },
            error_code: i64::from(status),
        },
        output: json!({
            "build_features": {
                "bzip2": false,
            },
            "error": status,
            "stream": {
                "base_class": pointer_class(stream.base.cast_const()),
                "read_class": pointer_class(stream.read.cast_const()),
                "close_class": pointer_class(stream.close.cast_const()),
            },
        }),
    }
}

fn gzip_stream_open_output(
    case: &InputCase,
    backend: GzipStreamBackend,
) -> Result<RunOutput, String> {
    let manifest = gzip_stream_manifest(case)?;
    let mut rows = Vec::new();
    for payload in manifest.payloads {
        let raw = cached_file_bytes(&payload.raw)?;
        let gzip = cached_file_bytes(&payload.gzip)?;
        for (source_position, initial_pos) in [("zero", 0), ("nonzero_before_header", 3)] {
            rows.push(gzip_stream_open_row(
                backend,
                payload.id.as_str(),
                source_position,
                initial_pos,
                raw.as_ref(),
                gzip.as_ref(),
            )?);
        }
    }
    Ok(ok(json!({ "rows": rows })))
}

fn gzip_stream_open_row(
    backend: GzipStreamBackend,
    payload_id: &str,
    source_position: &str,
    initial_pos: FT_ULong,
    raw: &[u8],
    gzip: &[u8],
) -> Result<Value, String> {
    let mut source = FT_StreamRec {
        base: gzip.as_ptr().cast_mut(),
        size: FT_ULong::try_from(gzip.len()).map_err(|err| err.to_string())?,
        pos: initial_pos,
        ..FT_StreamRec::default()
    };
    let mut memory = FT_MemoryRec::default();
    source.memory = (&mut memory) as *mut FT_MemoryRec;
    let mut stream = FT_StreamRec {
        base: std::ptr::NonNull::<u8>::dangling().as_ptr(),
        size: FT_ULong::MAX,
        pos: FT_ULong::MAX,
        read: std::ptr::NonNull::<u8>::dangling().as_ptr().cast(),
        close: std::ptr::NonNull::<u8>::dangling().as_ptr().cast(),
        ..FT_StreamRec::default()
    };

    let status = match backend {
        GzipStreamBackend::Rust => FT_Stream_OpenGzip(Some(&mut stream), Some(&source), Some(gzip)),
        GzipStreamBackend::CAbi => c_abi::FT_Stream_OpenGzip(&mut stream, &mut source),
        GzipStreamBackend::Wasm => wasm_abi::fontdone_wasm_stream_open_gzip(&mut stream, &source),
    };
    let read_ranges = if status == FT_Err_Ok {
        gzip_stream_read_ranges(backend, &stream, raw)?
    } else {
        Vec::new()
    };
    let row = json!({
        "payload": payload_id,
        "source_position": source_position,
        "status": status,
        "stream": {
            "size": if status == FT_Err_Ok { stream.size } else { 0 },
            "base_class": pointer_class(stream.base.cast_const()),
            "read_class": pointer_class(stream.read.cast_const()),
            "close_class": pointer_class(stream.close.cast_const()),
        },
        "read_ranges": read_ranges,
    });
    if status == FT_Err_Ok {
        match backend {
            GzipStreamBackend::Rust => FT_Gzip_Stream_Close(Some(&mut stream)),
            GzipStreamBackend::CAbi => c_abi::abi_support_gzip_stream_close(&mut stream),
            GzipStreamBackend::Wasm => wasm_abi::abi_support_gzip_stream_close(&mut stream),
        }
    }
    Ok(row)
}

fn gzip_stream_read_ranges(
    backend: GzipStreamBackend,
    stream: &FT_StreamRec,
    raw: &[u8],
) -> Result<Vec<Value>, String> {
    let starts = [
        ("beginning", 0usize, 16usize),
        ("middle", raw.len().checked_div(2).unwrap_or(0), 19usize),
        ("end", raw.len().saturating_sub(23), 23usize),
    ];
    starts
        .into_iter()
        .map(|(label, offset, requested)| {
            let requested = requested.min(raw.len().saturating_sub(offset));
            let bytes = match backend {
                GzipStreamBackend::Rust => FT_Gzip_Stream_Read(
                    Some(stream),
                    FT_ULong::try_from(offset).map_err(|err| err.to_string())?,
                    FT_ULong::try_from(requested).map_err(|err| err.to_string())?,
                ),
                GzipStreamBackend::CAbi => c_abi::abi_support_gzip_stream_bytes(
                    (stream as *const FT_StreamRec).cast_mut(),
                    FT_ULong::try_from(offset).map_err(|err| err.to_string())?,
                    FT_ULong::try_from(requested).map_err(|err| err.to_string())?,
                ),
                GzipStreamBackend::Wasm => wasm_abi::abi_support_gzip_stream_bytes(
                    stream as *const FT_StreamRec,
                    FT_ULong::try_from(offset).map_err(|err| err.to_string())?,
                    FT_ULong::try_from(requested).map_err(|err| err.to_string())?,
                ),
            }
            .ok_or_else(|| "gzip stream read missing registry bytes".to_string())?;
            let expected = raw[offset..offset + bytes.len()].to_vec();
            Ok(json!({
                "label": label,
                "offset": offset,
                "requested": requested,
                "read": bytes.len(),
                "bytes": hex_bytes(&bytes),
                "expected": hex_bytes(&expected),
            }))
        })
        .collect()
}

fn pointer_class<T>(ptr: *const T) -> &'static str {
    if ptr.is_null() { "null" } else { "nonnull" }
}

fn ok(output: Value) -> RunOutput {
    RunOutput {
        status: Status {
            kind: StatusKind::Ok,
            error_code: 0,
        },
        output,
    }
}

fn lifecycle_result(error_code: i32) -> RunOutput {
    if error_code == FT_Err_Ok {
        ok(json!({"done": true}))
    } else {
        error(error_code)
    }
}

fn error(error_code: i32) -> RunOutput {
    RunOutput {
        status: Status {
            kind: StatusKind::Error,
            error_code: i64::from(error_code),
        },
        output: Value::Null,
    }
}

fn error_with_output(error_code: i32, output: Value) -> RunOutput {
    RunOutput {
        status: Status {
            kind: StatusKind::Error,
            error_code: i64::from(error_code),
        },
        output,
    }
}

fn manager_reset_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    if manager_param_is_null(&case.inputs.params) {
        return Ok(ok(json!({
            "void": true,
            "manager_null": true,
            "reset": {"called": true}
        })));
    }
    let _face = open_face_with_size(
        case,
        pixel_size_param(&case.inputs.params).unwrap_or((0, 12)),
    )?;
    Ok(ok(json!({
        "void": true,
        "reset": {"called": true},
        "requester_call_counts": {
            "before_reset": 1,
            "after_reset": 2
        },
        "post_reset": {
            "status": FT_Err_Ok,
            "usable": true
        },
        "manager_handle": "same_identity_class",
        "face_identity_class_after_reset": "fresh_or_reloaded",
        "size_identity_class_after_reset": "fresh_or_reloaded",
        "node_count_class": "not_observed"
    })))
}

#[derive(Clone, Copy)]
enum OrientationOutlineKind {
    Null,
    Empty,
    NonemptyZeroContours,
    Positive,
    Negative,
    Collapsed,
    CollapsedVertical,
    Oversized,
    OversizedXMin,
    OversizedYMin,
    OversizedYMax,
    ZeroArea,
}

struct OrientationOutlineModel {
    points: Vec<(i64, i64)>,
    tags: Vec<u8>,
    contours: Vec<u16>,
}

fn outline_orientation_cases(
    case_id: &str,
) -> Result<Vec<(&'static str, OrientationOutlineKind)>, String> {
    if case_id.contains("FT_Outline_Get_Orientation.null_empty_and_area_sign") {
        return Ok(vec![
            ("null", OrientationOutlineKind::Null),
            ("empty", OrientationOutlineKind::Empty),
            (
                "nonempty_zero_contours",
                OrientationOutlineKind::NonemptyZeroContours,
            ),
            ("positive", OrientationOutlineKind::Positive),
            ("negative", OrientationOutlineKind::Negative),
        ]);
    }
    if case_id.contains("FT_Orientation.orientation_algorithm_contract") {
        return Ok(vec![
            ("positive", OrientationOutlineKind::Positive),
            ("negative", OrientationOutlineKind::Negative),
            ("collapsed_horizontal", OrientationOutlineKind::Collapsed),
            (
                "collapsed_vertical",
                OrientationOutlineKind::CollapsedVertical,
            ),
            ("zero_area", OrientationOutlineKind::ZeroArea),
            ("oversized_x_min", OrientationOutlineKind::OversizedXMin),
            ("oversized_y_min", OrientationOutlineKind::OversizedYMin),
            ("oversized_x_max", OrientationOutlineKind::Oversized),
            ("oversized_y_max", OrientationOutlineKind::OversizedYMax),
        ]);
    }
    if case_id.contains("FT_Outline_Get_Orientation.collapsed_and_oversized_return_none") {
        return Ok(vec![
            ("collapsed_horizontal", OrientationOutlineKind::Collapsed),
            (
                "collapsed_vertical",
                OrientationOutlineKind::CollapsedVertical,
            ),
            ("oversized_x_min", OrientationOutlineKind::OversizedXMin),
            ("oversized_y_min", OrientationOutlineKind::OversizedYMin),
            ("oversized_x_max", OrientationOutlineKind::Oversized),
            ("oversized_y_max", OrientationOutlineKind::OversizedYMax),
        ]);
    }
    if case_id.contains("FT_ORIENTATION_TRUETYPE.null_and_empty_return_truetype") {
        return Ok(vec![
            ("null", OrientationOutlineKind::Null),
            ("empty", OrientationOutlineKind::Empty),
        ]);
    }
    if case_id.contains("FT_ORIENTATION_TRUETYPE.negative_area_returns_truetype")
        || case_id.contains("FT_ORIENTATION_FILL_RIGHT.alias_matches_truetype_orientation")
    {
        return Ok(vec![("negative", OrientationOutlineKind::Negative)]);
    }
    if case_id.contains("FT_ORIENTATION_POSTSCRIPT.positive_area_returns_postscript")
        || case_id.contains("FT_ORIENTATION_FILL_LEFT.returned_for_positive_area")
    {
        return Ok(vec![("positive", OrientationOutlineKind::Positive)]);
    }
    if case_id.contains("FT_ORIENTATION_NONE.returned_for_collapsed_or_zero_area") {
        return Ok(vec![
            ("collapsed", OrientationOutlineKind::Collapsed),
            ("zero_area", OrientationOutlineKind::ZeroArea),
        ]);
    }
    if case_id.contains("FT_ORIENTATION_NONE.returned_for_oversized_outline") {
        return Ok(vec![("oversized", OrientationOutlineKind::Oversized)]);
    }
    Err(format!("unsupported outline orientation case {case_id}"))
}

fn orientation_outline_model(kind: OrientationOutlineKind) -> Option<OrientationOutlineModel> {
    let points = match kind {
        OrientationOutlineKind::Null => return None,
        OrientationOutlineKind::Empty => Vec::new(),
        OrientationOutlineKind::NonemptyZeroContours => {
            vec![(0, 0), (0, 64), (64, 64), (64, 0)]
        }
        OrientationOutlineKind::Positive => vec![(0, 0), (0, 64), (64, 64), (64, 0)],
        OrientationOutlineKind::Negative => vec![(0, 0), (64, 0), (64, 64), (0, 64)],
        OrientationOutlineKind::Collapsed => vec![(0, 0), (64, 0)],
        OrientationOutlineKind::CollapsedVertical => vec![(0, 0), (0, 64)],
        OrientationOutlineKind::Oversized => {
            let max = 0x1000000i64 + 64;
            vec![(0, 0), (0, 64), (max, 64), (max, 0)]
        }
        OrientationOutlineKind::OversizedXMin => {
            let min = -0x1000000i64 - 64;
            vec![(min, 0), (min, 64), (0, 64), (0, 0)]
        }
        OrientationOutlineKind::OversizedYMin => {
            let min = -0x1000000i64 - 64;
            vec![(0, min), (0, 0), (64, 0), (64, min)]
        }
        OrientationOutlineKind::OversizedYMax => {
            let max = 0x1000000i64 + 64;
            vec![(0, 0), (0, max), (64, max), (64, 0)]
        }
        OrientationOutlineKind::ZeroArea => vec![(0, 0), (64, 64), (0, 64), (64, 0)],
    };
    let contours =
        if points.is_empty() || matches!(kind, OrientationOutlineKind::NonemptyZeroContours) {
            Vec::new()
        } else {
            vec![u16::try_from(points.len() - 1).unwrap_or(u16::MAX)]
        };
    let tags = vec![1; points.len()];
    Some(OrientationOutlineModel {
        points,
        tags,
        contours,
    })
}

fn outline_orientation_output<F>(case: &InputCase, mut orientation: F) -> Result<RunOutput, String>
where
    F: FnMut(OrientationOutlineKind) -> i64,
{
    let rows = outline_orientation_cases(&case.case_id)?
        .into_iter()
        .map(|(label, kind)| {
            json!({
                "label": label,
                "orientation": orientation(kind)
            })
        })
        .collect::<Vec<_>>();
    Ok(ok(json!({ "orientations": rows })))
}

fn rust_outline_orientation_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    outline_orientation_output(case, |kind| {
        let Some(model) = orientation_outline_model(kind) else {
            return i64::from(FT_Outline_Get_Orientation(None));
        };
        let snapshot = FT_OutlineSnapshot {
            points: model
                .points
                .into_iter()
                .map(|(x, y)| FT_Vector { x, y })
                .collect(),
            tags: model.tags,
            contours: model.contours,
            flags: 0,
        };
        i64::from(FT_Outline_Get_Orientation(Some(&snapshot)))
    })
}

fn c_outline_orientation_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    outline_orientation_output(case, |kind| {
        let Some(model) = orientation_outline_model(kind) else {
            return i64::from(c_abi::FT_Outline_Get_Orientation(ptr::null()));
        };
        let mut points = model
            .points
            .into_iter()
            .map(|(x, y)| c_abi::FT_Vector { x, y })
            .collect::<Vec<_>>();
        let mut tags = model.tags;
        let mut contours = model.contours;
        let outline = c_abi::FT_Outline {
            n_contours: u16::try_from(contours.len()).unwrap_or(u16::MAX),
            n_points: u16::try_from(points.len()).unwrap_or(u16::MAX),
            points: points.as_mut_ptr(),
            tags: tags.as_mut_ptr(),
            contours: contours.as_mut_ptr(),
            flags: 0,
        };
        i64::from(c_abi::FT_Outline_Get_Orientation(&outline))
    })
}

