#[derive(Clone)]
struct MutableOutlineModel {
    points: Vec<(i64, i64)>,
    tags: Vec<u8>,
    contours: Vec<u16>,
    flags: i32,
}

#[derive(Clone, Copy)]
enum OutlineTransformScenario {
    Outline,
    NullOutline,
    NullMatrix,
}

fn reverse_outline_model() -> MutableOutlineModel {
    MutableOutlineModel {
        points: vec![
            (0, 0),
            (64, 0),
            (64, 64),
            (0, 64),
            (128, 0),
            (192, 0),
            (192, 64),
            (128, 64),
        ],
        tags: vec![1, 0, 1, 2, 1, 2, 0, 1],
        contours: vec![3, 7],
        flags: 2,
    }
}

fn transform_outline_model() -> MutableOutlineModel {
    MutableOutlineModel {
        points: vec![(-96, -32), (128, -64), (160, 96), (-64, 128)],
        tags: vec![1; 4],
        contours: vec![3],
        flags: 0,
    }
}

fn translate_outline_model() -> MutableOutlineModel {
    MutableOutlineModel {
        points: vec![(-96, -32), (128, -64), (160, 96), (-64, 128)],
        tags: vec![1; 4],
        contours: vec![3],
        flags: 0,
    }
}

fn outline_points_json(points: &[(i64, i64)]) -> Value {
    json!(
        points
            .iter()
            .map(|&(x, y)| json!({"x": x, "y": y}))
            .collect::<Vec<_>>()
    )
}

fn mutable_outline_json(model: &MutableOutlineModel) -> Value {
    json!({
        "points": outline_points_json(&model.points),
        "tags": model.tags,
        "contours": model.contours,
        "flags": model.flags
    })
}

fn rust_snapshot_from_mutable(model: &MutableOutlineModel) -> FT_OutlineSnapshot {
    FT_OutlineSnapshot {
        points: model
            .points
            .iter()
            .map(|&(x, y)| FT_Vector { x, y })
            .collect(),
        tags: model.tags.clone(),
        contours: model.contours.clone(),
        flags: model.flags,
    }
}

fn update_mutable_from_rust_snapshot(
    model: &mut MutableOutlineModel,
    snapshot: FT_OutlineSnapshot,
) {
    model.points = snapshot
        .points
        .into_iter()
        .map(|point| (point.x, point.y))
        .collect();
    model.tags = snapshot.tags;
    model.flags = snapshot.flags;
}

struct CMutableOutlineStorage {
    points: Vec<c_abi::FT_Vector>,
    tags: Vec<u8>,
    contours: Vec<u16>,
    outline: c_abi::FT_Outline,
}

impl CMutableOutlineStorage {
    fn new(model: MutableOutlineModel) -> Self {
        let mut points = model
            .points
            .iter()
            .map(|&(x, y)| c_abi::FT_Vector { x, y })
            .collect::<Vec<_>>();
        let mut tags = model.tags;
        let mut contours = model.contours;
        let outline = c_abi::FT_Outline {
            n_contours: u16::try_from(contours.len()).unwrap_or(u16::MAX),
            n_points: u16::try_from(points.len()).unwrap_or(u16::MAX),
            points: points.as_mut_ptr(),
            tags: tags.as_mut_ptr(),
            contours: contours.as_mut_ptr(),
            flags: model.flags,
        };
        Self {
            points,
            tags,
            contours,
            outline,
        }
    }

    fn as_const_ptr(&mut self) -> *const c_abi::FT_Outline {
        &self.outline
    }

    fn as_mut_ptr(&mut self) -> *mut c_abi::FT_Outline {
        &mut self.outline
    }

    fn copy_back(self, model: &mut MutableOutlineModel) {
        model.points = self
            .points
            .into_iter()
            .map(|point| (point.x, point.y))
            .collect();
        model.tags = self.tags;
        model.contours = self.contours;
        model.flags = self.outline.flags;
    }
}

