#[derive(Clone, Copy)]
enum BorderOutlineKind {
    Null,
    Empty,
    TrueType,
    PostScript,
}

fn outline_border_rows(case_id: &str) -> Result<Vec<(&'static str, BorderOutlineKind)>, String> {
    if case_id.contains(".truetype_orientation_returns_") {
        return Ok(vec![
            ("null", BorderOutlineKind::Null),
            ("empty", BorderOutlineKind::Empty),
            ("truetype", BorderOutlineKind::TrueType),
        ]);
    }
    if case_id.contains(".non_truetype_orientation_returns_") {
        return Ok(vec![("postscript", BorderOutlineKind::PostScript)]);
    }
    if case_id.contains(".orientation_delegation") {
        return Ok(vec![
            ("null", BorderOutlineKind::Null),
            ("empty", BorderOutlineKind::Empty),
            ("truetype", BorderOutlineKind::TrueType),
            ("postscript", BorderOutlineKind::PostScript),
        ]);
    }
    Err(format!("unsupported outline border case {case_id}"))
}

fn border_outline_model(kind: BorderOutlineKind) -> Option<MutableOutlineModel> {
    match kind {
        BorderOutlineKind::Null => None,
        BorderOutlineKind::Empty => Some(MutableOutlineModel {
            points: Vec::new(),
            tags: Vec::new(),
            contours: Vec::new(),
            flags: 0,
        }),
        BorderOutlineKind::TrueType => Some(MutableOutlineModel {
            points: vec![(0, 0), (64, 0), (64, 64), (0, 64)],
            tags: vec![1; 4],
            contours: vec![3],
            flags: 0,
        }),
        BorderOutlineKind::PostScript => Some(MutableOutlineModel {
            points: vec![(0, 0), (0, 64), (64, 64), (64, 0)],
            tags: vec![1; 4],
            contours: vec![3],
            flags: 0,
        }),
    }
}

fn outline_border_runtime_output<F>(case: &InputCase, mut observe: F) -> Result<RunOutput, String>
where
    F: FnMut(Option<&MutableOutlineModel>) -> (i64, i64),
{
    let rows = outline_border_rows(&case.case_id)?
        .into_iter()
        .map(|(label, kind)| {
            let model = border_outline_model(kind);
            let (orientation, border) = observe(model.as_ref());
            json!({
                "label": label,
                "orientation": orientation,
                "border": border
            })
        })
        .collect::<Vec<_>>();
    Ok(ok(json!({ "rows": rows })))
}

fn rust_outline_border_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    outline_border_runtime_output(case, |model| {
        let snapshot = model.map(rust_snapshot_from_mutable);
        let orientation = i64::from(FT_Outline_Get_Orientation(snapshot.as_ref()));
        let border = if outline_border_case_is_outside(case) {
            i64::from(FT_Outline_GetOutsideBorder(snapshot.as_ref()))
        } else {
            i64::from(FT_Outline_GetInsideBorder(snapshot.as_ref()))
        };
        (orientation, border)
    })
}

fn c_outline_border_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    outline_border_runtime_output(case, |model| {
        let mut storage = model.cloned().map(CMutableOutlineStorage::new);
        let ptr = storage
            .as_mut()
            .map_or(ptr::null(), CMutableOutlineStorage::as_const_ptr);
        let orientation = i64::from(c_abi::FT_Outline_Get_Orientation(ptr));
        let border = if outline_border_case_is_outside(case) {
            i64::from(c_abi::FT_Outline_GetOutsideBorder(ptr))
        } else {
            i64::from(c_abi::FT_Outline_GetInsideBorder(ptr))
        };
        (orientation, border)
    })
}

fn wasm_outline_border_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    outline_border_runtime_output(case, |model| {
        let mut storage = model.cloned().map(WasmMutableOutlineStorage::new);
        let ptr = storage
            .as_mut()
            .map_or(ptr::null(), WasmMutableOutlineStorage::as_const_ptr);
        let orientation = i64::from(wasm_abi::fontdone_wasm_outline_get_orientation(ptr));
        let border = if outline_border_case_is_outside(case) {
            i64::from(wasm_abi::fontdone_wasm_outline_get_outside_border(ptr))
        } else {
            i64::from(wasm_abi::fontdone_wasm_outline_get_inside_border(ptr))
        };
        (orientation, border)
    })
}

fn outline_border_case_is_outside(case: &InputCase) -> bool {
    case.subject == "ftstroke.FT_Outline_GetOutsideBorder"
        || case.case_id.contains("FT_Outline_GetOutsideBorder")
        || case.operation == "ftstroke.outline_get_outside_border"
}

fn outline_translate_offsets(case: &InputCase) -> (i64, i64) {
    let params = &case.inputs.params;
    (
        i64_param(params, "xOffset").unwrap_or(17),
        i64_param(params, "yOffset").unwrap_or(-33),
    )
}

fn outline_translate_runtime_output<F, G>(
    case: &InputCase,
    mut translate: F,
    mut observe: G,
) -> Result<RunOutput, String>
where
    F: FnMut(Option<&mut MutableOutlineModel>, i64, i64),
    G: FnMut(&MutableOutlineModel) -> ([i64; 4], i64),
{
    let (x_offset, y_offset) = outline_translate_offsets(case);
    if case.case_id.ends_with(".null_outline_noop") {
        translate(None, x_offset, y_offset);
        return Ok(ok(json!({"sentinel_memory_changed": false})));
    }

    let mut model = if case.case_id.ends_with(".empty_outline_success_noop") {
        MutableOutlineModel {
            points: Vec::new(),
            tags: Vec::new(),
            contours: Vec::new(),
            flags: 0,
        }
    } else {
        translate_outline_model()
    };
    let points_before = outline_points_json(&model.points);
    translate(Some(&mut model), x_offset, y_offset);
    if case.case_id.ends_with(".offsets_all_points") {
        let (cbox, _) = observe(&model);
        return Ok(ok(json!({
            "points_before": points_before,
            "points_after": outline_points_json(&model.points),
            "cbox_after": {
                "xMin": cbox[0],
                "yMin": cbox[1],
                "xMax": cbox[2],
                "yMax": cbox[3]
            }
        })));
    }
    if case.case_id.ends_with(".empty_outline_success_noop") {
        return Ok(ok(json!({
            "n_points": model.points.len(),
            "points_after": outline_points_json(&model.points)
        })));
    }
    Err(format!(
        "unsupported outline translate case {}",
        case.case_id
    ))
}

fn rust_translate_mutable_outline(
    model: Option<&mut MutableOutlineModel>,
    x_offset: i64,
    y_offset: i64,
) {
    let Some(model) = model else {
        FT_Outline_Translate(None, x_offset, y_offset);
        return;
    };
    let mut snapshot = rust_snapshot_from_mutable(model);
    FT_Outline_Translate(Some(&mut snapshot), x_offset, y_offset);
    update_mutable_from_rust_snapshot(model, snapshot);
}

fn rust_outline_translate_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    outline_translate_runtime_output(
        case,
        rust_translate_mutable_outline,
        rust_observe_mutable_outline,
    )
}

fn c_translate_mutable_outline(
    model: Option<&mut MutableOutlineModel>,
    x_offset: i64,
    y_offset: i64,
) {
    let Some(model) = model else {
        c_abi::FT_Outline_Translate(ptr::null(), x_offset, y_offset);
        return;
    };
    let mut points = model
        .points
        .iter()
        .map(|&(x, y)| c_abi::FT_Vector { x, y })
        .collect::<Vec<_>>();
    let mut tags = model.tags.clone();
    let mut contours = model.contours.clone();
    let outline = c_abi::FT_Outline {
        n_contours: u16::try_from(contours.len()).unwrap_or(u16::MAX),
        n_points: u16::try_from(points.len()).unwrap_or(u16::MAX),
        points: points.as_mut_ptr(),
        tags: tags.as_mut_ptr(),
        contours: contours.as_mut_ptr(),
        flags: model.flags,
    };
    c_abi::FT_Outline_Translate(&outline, x_offset, y_offset);
    model.points = points.into_iter().map(|point| (point.x, point.y)).collect();
}

fn c_outline_translate_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    outline_translate_runtime_output(case, c_translate_mutable_outline, c_observe_mutable_outline)
}

fn wasm_translate_mutable_outline(
    model: Option<&mut MutableOutlineModel>,
    x_offset: i64,
    y_offset: i64,
) {
    let Some(model) = model else {
        wasm_abi::fontdone_wasm_outline_translate(ptr::null(), x_offset, y_offset);
        return;
    };
    let mut points = model
        .points
        .iter()
        .map(|&(x, y)| wasm_abi::FontdoneWasmVector { x, y })
        .collect::<Vec<_>>();
    let mut tags = model.tags.clone();
    let mut contours = model.contours.clone();
    let outline = wasm_abi::FontdoneWasmOutline {
        n_contours: u16::try_from(contours.len()).unwrap_or(u16::MAX),
        n_points: u16::try_from(points.len()).unwrap_or(u16::MAX),
        points: points.as_mut_ptr(),
        tags: tags.as_mut_ptr(),
        contours: contours.as_mut_ptr(),
        flags: model.flags,
    };
    wasm_abi::fontdone_wasm_outline_translate(&outline, x_offset, y_offset);
    model.points = points.into_iter().map(|point| (point.x, point.y)).collect();
}

fn wasm_outline_translate_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    outline_translate_runtime_output(
        case,
        wasm_translate_mutable_outline,
        wasm_observe_mutable_outline,
    )
}

fn rust_outline_decompose_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    if case.case_id == "ftoutln.FT_Outline_Decompose.invalid_outline_or_interface_errors" {
        return rust_outline_decompose_invalid_runtime_output(case);
    }
    if case.case_id == "ftimage.FT_CURVE_TAG_CUBIC.cubic_decomposition_matches_c" {
        return rust_cubic_outline_decompose_runtime_output(case);
    }
    let outline_model = outline_render_outline(case)?;
    let masked_tags = outline_decompose_masked_tags(&outline_model);
    let outline = outline_render_snapshot(&outline_model);
    match FT_Outline_Decompose_Trace(Some(&outline), &outline_decompose_transforms(case)?) {
        Ok(runs) if case.case_id == "ftimage.FT_Outline_Funcs.callback_error_propagates" => {
            outline_funcs_callback_error_output(case, runs)
        }
        Ok(runs)
            if case.case_id
                == "ftimage.FT_Outline_MoveTo_Func.decompose_propagates_callback_error" =>
        {
            outline_moveto_callback_error_output(case, runs)
        }
        Ok(runs) if outline_callback_return_matrix_case(&case.case_id) => {
            outline_callback_return_matrix_output(case, runs)
        }
        Ok(runs) if case.case_id == "ftoutln.FT_Outline_Decompose.callback_error_propagates" => {
            outline_decompose_callback_error_output(case, runs)
        }
        Ok(runs) if case.case_id == "ftimage.FT_CURVE_TAG.classifies_outline_tags" => Ok(ok(
            outline_decompose_trace_payload_with_masked_tags(runs, masked_tags),
        )),
        Ok(runs) => Ok(ok(outline_decompose_trace_payload(runs))),
        Err(err) => Ok(error(err)),
    }
}

