fn outline_decompose_runtime_case_supported(case_id: &str) -> bool {
    matches!(
        case_id,
        "ftimage.FT_Outline_Funcs.shift_delta_transform_matches_c"
            | "ftimage.FT_Outline_Funcs.callback_order_matches_c"
            | "ftimage.FT_Outline_Funcs.callback_error_propagates"
            | "ftimage.FT_Outline_MoveTo_Func.decompose_propagates_callback_error"
            | "ftimage.FT_CURVE_TAG.classifies_outline_tags"
            | "ftimage.FT_Curve_Tag_Touch_X.ignored_by_curve_tag_mask"
            | "ftimage.FT_Curve_Tag_Touch_Y.ignored_by_curve_tag_mask"
            | "ftimage.FT_CURVE_TAG_ON.on_curve_decomposition_matches_c"
            | "ftimage.FT_Curve_Tag_On.curve_tag_classifies_on_curve_points"
            | "ftimage.FT_Outline_LineTo_Func.callback_abi_matches_c"
            | "ftimage.FT_CURVE_TAG_CONIC.conic_decomposition_matches_c"
            | "ftimage.FT_Curve_Tag_Conic.curve_tag_classifies_conic_points"
            | "ftimage.FT_Outline_ConicTo_Func.callback_abi_matches_c"
            | "ftimage.FT_Outline_ConicTo_Func.decompose_propagates_callback_error"
            | "ftimage.FT_CURVE_TAG_CUBIC.cubic_decomposition_matches_c"
            | "ftimage.FT_Curve_Tag_Cubic.curve_tag_classifies_cubic_points"
            | "ftimage.FT_Outline_CubicTo_Func.callback_abi_matches_c"
            | "ftimage.FT_Outline_CubicTo_Func.decompose_propagates_callback_error"
            | "ftimage.FT_Outline_LineTo_Func.decompose_propagates_callback_error"
            | "ftoutln.FT_Outline_Decompose.line_conic_cubic_event_order"
            | "ftoutln.FT_Outline_Decompose.shift_delta_applied_to_callbacks"
            | "ftoutln.FT_Outline_Decompose.callback_error_propagates"
            | "ftoutln.FT_Outline_Decompose.invalid_outline_or_interface_errors"
    ) || case_id.split_once('@').map_or(case_id, |(base, _)| base)
        == "ftimage.FT_Outline_MoveTo_Func.decompose_starts_each_contour"
}

fn outline_decompose_invalid_output(
    null_outline: FT_Error,
    null_func_interface: FT_Error,
    bad_cubic: FT_Error,
    bad_contour: FT_Error,
) -> RunOutput {
    ok(json!({
        "results": [
            {"scenario": "null_outline", "return": null_outline},
            {"scenario": "null_func_interface", "return": null_func_interface},
            {"scenario": "bad_cubic", "return": bad_cubic},
            {"scenario": "bad_contour", "return": bad_contour}
        ]
    }))
}

fn rust_outline_decompose_invalid_runtime_output(case: &InputCase) -> Result<RunOutput, String> {
    let bad_cubic = outline_from_asset_key(case, "bad_cubic")?;
    let bad_contour = outline_from_asset_key(case, "bad_contour")?;
    let bad_cubic_status =
        match FT_Outline_Decompose_Trace(Some(&outline_render_snapshot(&bad_cubic)), &[(0, 0)]) {
            Ok(_) => FT_Err_Ok,
            Err(err) => err,
        };
    let bad_contour_status =
        match FT_Outline_Decompose_Trace(Some(&outline_render_snapshot(&bad_contour)), &[(0, 0)]) {
            Ok(_) => FT_Err_Ok,
            Err(err) => err,
        };
    Ok(outline_decompose_invalid_output(
        FT_Err_Invalid_Outline,
        FT_Err_Invalid_Argument,
        bad_cubic_status,
        bad_contour_status,
    ))
}

