fn outline_render_outline(case: &InputCase) -> Result<fontdone::outline::Outline, String> {
    if let Some(outline) = outline_render_fixture_outline(case)? {
        return Ok(outline);
    }
    match outline_asset_id(case).unwrap_or("outlines/render/simple-filled-square.json") {
        "outlines/render/simple-filled-square.json" => Ok(outline_render_square()),
        "outlines/render/direct-spans-clipped.json" => Ok(outline_render_square()),
        "outlines/render/even-odd-overlap.json" => Ok(outline_render_even_odd_overlap()),
        "outlines/render/even-odd-double-wind.json" => Ok(outline_render_even_odd_double_wind()),
        "outlines/render/even-odd-quad-wind.json" => Ok(outline_render_even_odd_quad_wind()),
        "outlines/render/clipped-crossing-lines.json" => Ok(outline_render_clipped_crossing()),
        "outlines/render/right-edge-clip-outside-target.json" => {
            Ok(outline_render_right_edge_clip_outside_target())
        }
        "outlines/render/cubic-closed-loop.json" => Ok(outline_render_cubic_loop()),
        "outlines/render/cubic-default-tag3.json" => Ok(outline_render_cubic_default_tag3()),
        "outlines/render/empty-outline.json" => Ok(outline_render_empty()),
        "outlines/render/zero-contours-nonempty-points.json" => {
            Ok(outline_render_zero_contours_nonempty_points())
        }
        "outlines/render/line-above-clip.json" => Ok(outline_render_line_above_clip()),
        "outlines/render/line-below-clip.json" => Ok(outline_render_line_below_clip()),
        "outlines/render/line-partial-above-clip.json" => {
            Ok(outline_render_line_partial_above_clip())
        }
        "outlines/render/line-partial-below-clip.json" => {
            Ok(outline_render_line_partial_below_clip())
        }
        "outlines/render/conic-below-clip.json" => Ok(outline_render_conic_below_clip()),
        "outlines/render/conic-partial-above-clip.json" => {
            Ok(outline_render_conic_partial_above_clip())
        }
        "outlines/render/conic-partial-below-clip.json" => {
            Ok(outline_render_conic_partial_below_clip())
        }
        "outlines/render/conic-above-control-inside.json" => Ok(outline_render_conic_with_points(
            (8, 40),
            (16, 16),
            (24, 40),
        )),
        "outlines/render/conic-above-to-inside.json" => Ok(outline_render_conic_with_points(
            (8, 40),
            (16, 40),
            (24, 16),
        )),
        "outlines/render/conic-below-control-inside.json" => Ok(outline_render_conic_with_points(
            (8, -16),
            (16, 16),
            (24, -16),
        )),
        "outlines/render/conic-below-to-inside.json" => Ok(outline_render_conic_with_points(
            (8, -16),
            (16, -16),
            (24, 16),
        )),
        "outlines/render/cubic-above-clip.json" => Ok(outline_render_cubic_above_clip()),
        "outlines/render/cubic-below-clip.json" => Ok(outline_render_cubic_below_clip()),
        "outlines/render/cubic-partial-above-clip.json" => {
            Ok(outline_render_cubic_partial_above_clip())
        }
        "outlines/render/cubic-partial-below-clip.json" => {
            Ok(outline_render_cubic_partial_below_clip())
        }
        "outlines/render/cubic-above-c2-inside.json" => Ok(outline_render_cubic_with_points(
            (8, 40),
            (8, 40),
            (24, 16),
            (24, 40),
        )),
        "outlines/render/cubic-above-c1-inside.json" => Ok(outline_render_cubic_with_points(
            (8, 40),
            (8, 16),
            (24, 40),
            (24, 40),
        )),
        "outlines/render/cubic-above-start-inside.json" => Ok(outline_render_cubic_with_points(
            (8, 16),
            (8, 40),
            (24, 40),
            (24, 40),
        )),
        "outlines/render/cubic-below-c2-inside.json" => Ok(outline_render_cubic_with_points(
            (8, -16),
            (8, -16),
            (24, 16),
            (24, -16),
        )),
        "outlines/render/cubic-below-c1-inside.json" => Ok(outline_render_cubic_with_points(
            (8, -16),
            (8, 16),
            (24, -16),
            (24, -16),
        )),
        "outlines/render/cubic-below-start-inside.json" => Ok(outline_render_cubic_with_points(
            (8, 16),
            (8, -16),
            (24, -16),
            (24, -16),
        )),
        "outlines/render/cubic-third-flatness.json" => Ok(outline_render_cubic_third_flatness()),
        "outlines/render/cubic-fourth-flatness.json" => Ok(outline_render_cubic_fourth_flatness()),
        "outlines/render/cubic-close-to-start.json" => Ok(outline_render_cubic_close_to_start()),
        "outlines/render/invalid-contour-order.json" => Ok(outline_render_invalid_contour_order()),
        "outlines/render/invalid-starts-cubic.json" => Ok(outline_render_invalid_starts_cubic()),
        "outlines/render/invalid-conic-bad-tag.json" => Ok(outline_render_invalid_conic_bad_tag()),
        "outlines/render/invalid-cubic-single-control.json" => {
            Ok(outline_render_invalid_cubic_single_control())
        }
        "outlines/render/invalid-cubic-second-not-cubic.json" => {
            Ok(outline_render_invalid_cubic_second_not_cubic())
        }
        _ => Ok(outline_render_square()),
    }
}

fn outline_render_fixture_outline(
    case: &InputCase,
) -> Result<Option<fontdone::outline::Outline>, String> {
    let Some(asset) = case
        .inputs
        .assets
        .get("outline")
        .or_else(|| case.inputs.assets.get("wide_outline"))
        .or_else(|| case.inputs.assets.get("oversized"))
        .or_else(|| case.inputs.assets.get("outline_fixture"))
        .or_else(|| case.inputs.assets.get("synthetic_outline"))
        .or_else(|| case.inputs.assets.get("synthetic_outlines"))
    else {
        return Ok(None);
    };
    let Some(path) = asset_file_path(asset) else {
        return Ok(None);
    };
    let bytes = cached_file_bytes(path)?;
    let value: Value =
        serde_json::from_slice(&bytes).map_err(|err| format!("parse {path}: {err}"))?;
    if value.get("kind").and_then(Value::as_str) != Some("outline_model") {
        return Ok(None);
    }
    parse_outline_model_fixture(path, &value).map(Some)
}

fn outline_from_asset_key(
    case: &InputCase,
    asset_key: &str,
) -> Result<fontdone::outline::Outline, String> {
    let asset = case
        .inputs
        .assets
        .get(asset_key)
        .ok_or_else(|| format!("{asset_key} asset is required"))?;
    let path = asset_file_path(asset).ok_or_else(|| format!("{asset_key} asset is unresolved"))?;
    let bytes = cached_file_bytes(path)?;
    let value: Value =
        serde_json::from_slice(&bytes).map_err(|err| format!("parse {path}: {err}"))?;
    if value.get("kind").and_then(Value::as_str) != Some("outline_model") {
        return Err(format!("{path} must be an outline_model fixture"));
    }
    parse_outline_model_fixture(path, &value)
}

fn cubic_malformed_statuses(
    case: &InputCase,
) -> Result<Vec<(String, fontdone::outline::Outline)>, String> {
    let asset = case
        .inputs
        .assets
        .get("malformed_outline")
        .ok_or_else(|| "malformed_outline asset is required".to_string())?;
    let path = asset_file_path(asset)
        .ok_or_else(|| "malformed_outline asset is unresolved".to_string())?;
    let bytes = cached_file_bytes(path)?;
    let value: Value =
        serde_json::from_slice(&bytes).map_err(|err| format!("parse {path}: {err}"))?;
    if value.get("kind").and_then(Value::as_str) != Some("outline_model_set") {
        return Err(format!("{path} must be an outline_model_set fixture"));
    }
    let cases = value
        .get("cases")
        .and_then(Value::as_array)
        .ok_or_else(|| format!("{path} cases must be an array"))?;
    cases
        .iter()
        .enumerate()
        .map(|(index, item)| {
            let id = item
                .get("id")
                .and_then(Value::as_str)
                .ok_or_else(|| format!("{path} cases[{index}].id must be a string"))?;
            let mut outline_value = item.clone();
            let object = outline_value
                .as_object_mut()
                .ok_or_else(|| format!("{path} cases[{index}] must be an object"))?;
            object.insert(
                "kind".to_string(),
                Value::String("outline_model".to_string()),
            );
            parse_outline_model_fixture(&format!("{path}#{id}"), &outline_value)
                .map(|outline| (id.to_string(), outline))
        })
        .collect()
}

fn parse_outline_model_fixture(
    path: &str,
    value: &Value,
) -> Result<fontdone::outline::Outline, String> {
    let points_value = value
        .get("points")
        .and_then(Value::as_array)
        .ok_or_else(|| format!("{path} points must be an array"))?;
    let mut points = Vec::with_capacity(points_value.len());
    for (index, point) in points_value.iter().enumerate() {
        let x = outline_fixture_i32(path, point, "x")?;
        let y = outline_fixture_i32(path, point, "y")?;
        points.push(fontdone::outline::OutlinePoint {
            x,
            y,
            on_curve: true,
        });
        if point.get("on_curve").is_some() {
            points[index].on_curve = point
                .get("on_curve")
                .and_then(Value::as_bool)
                .ok_or_else(|| format!("{path} points[{index}].on_curve must be a bool"))?;
        }
    }

    let tags = outline_fixture_u8_array(path, value, "tags")?;
    if !tags.is_empty() && tags.len() != points.len() {
        return Err(format!(
            "{path} tags length {} must match points length {}",
            tags.len(),
            points.len()
        ));
    }
    if !tags.is_empty() {
        for (point, tag) in points.iter_mut().zip(tags.iter().copied()) {
            point.on_curve = tag & 1 != 0;
        }
    }

    let contours = outline_fixture_i16_array(path, value, "contours")?;
    let contour_dropouts = outline_fixture_u8_array(path, value, "contour_dropouts")?;
    let flags = value
        .get("flags")
        .and_then(Value::as_i64)
        .map_or(Ok(0), |raw| {
            u32::try_from(raw).map_err(|err| format!("{path} flags out of range: {err}"))
        })?;
    let (cbox_x_min, cbox_y_min, cbox_x_max, cbox_y_max) =
        outline_fixture_cbox(value).unwrap_or_else(|| derive_outline_fixture_cbox(&points));

    Ok(fontdone::outline::Outline {
        n_contours: i32::try_from(contours.len())
            .map_err(|err| format!("{path} contour count out of range: {err}"))?,
        contours,
        points,
        tags,
        contour_dropouts,
        flags,
        cbox_x_min,
        cbox_y_min,
        cbox_x_max,
        cbox_y_max,
    })
}

fn outline_fixture_i32(path: &str, value: &Value, field: &str) -> Result<i32, String> {
    let raw = value
        .get(field)
        .and_then(Value::as_i64)
        .ok_or_else(|| format!("{path} point.{field} must be an integer"))?;
    i32::try_from(raw).map_err(|err| format!("{path} point.{field} out of range: {err}"))
}

fn outline_fixture_i16_array(path: &str, value: &Value, field: &str) -> Result<Vec<i16>, String> {
    let Some(items) = value.get(field).and_then(Value::as_array) else {
        return Ok(Vec::new());
    };
    items
        .iter()
        .enumerate()
        .map(|(index, item)| {
            let raw = item
                .as_i64()
                .ok_or_else(|| format!("{path} {field}[{index}] must be an integer"))?;
            i16::try_from(raw).map_err(|err| format!("{path} {field}[{index}] out of range: {err}"))
        })
        .collect()
}

fn outline_fixture_u8_array(path: &str, value: &Value, field: &str) -> Result<Vec<u8>, String> {
    let Some(items) = value.get(field).and_then(Value::as_array) else {
        return Ok(Vec::new());
    };
    items
        .iter()
        .enumerate()
        .map(|(index, item)| {
            let raw = item
                .as_u64()
                .ok_or_else(|| format!("{path} {field}[{index}] must be an unsigned integer"))?;
            u8::try_from(raw).map_err(|err| format!("{path} {field}[{index}] out of range: {err}"))
        })
        .collect()
}

fn outline_fixture_cbox(value: &Value) -> Option<(i32, i32, i32, i32)> {
    let cbox = value.get("cbox")?;
    Some((
        i32::try_from(cbox.get("x_min")?.as_i64()?).ok()?,
        i32::try_from(cbox.get("y_min")?.as_i64()?).ok()?,
        i32::try_from(cbox.get("x_max")?.as_i64()?).ok()?,
        i32::try_from(cbox.get("y_max")?.as_i64()?).ok()?,
    ))
}

fn derive_outline_fixture_cbox(points: &[fontdone::outline::OutlinePoint]) -> (i32, i32, i32, i32) {
    let Some(first) = points.first() else {
        return (0, 0, 0, 0);
    };
    let (mut x_min, mut y_min, mut x_max, mut y_max) = (first.x, first.y, first.x, first.y);
    for point in points.iter().skip(1) {
        x_min = x_min.min(point.x);
        y_min = y_min.min(point.y);
        x_max = x_max.max(point.x);
        y_max = y_max.max(point.y);
    }
    (
        floor_26_6(x_min),
        floor_26_6(y_min),
        ceil_26_6(x_max),
        ceil_26_6(y_max),
    )
}

fn floor_26_6(value: i32) -> i32 {
    value.div_euclid(64)
}

fn ceil_26_6(value: i32) -> i32 {
    let floor = value.div_euclid(64);
    if value.rem_euclid(64) == 0 {
        floor
    } else {
        floor.saturating_add(1)
    }
}

fn outline_asset_id(case: &InputCase) -> Option<&str> {
    case.inputs
        .assets
        .get("outline")
        .or_else(|| case.inputs.assets.get("synthetic_outline"))
        .and_then(|asset| match asset {
            Asset::Ref { id: Some(id), .. } => Some(id.as_str()),
            Asset::File { path, .. } => Some(path.as_str()),
            Asset::Other(value) => value.get("id").and_then(Value::as_str),
            _ => None,
        })
}

fn outline_render_target_box(case: &InputCase) -> Result<(usize, usize), String> {
    if let Some(Asset::Other(bitmap)) = case.inputs.assets.get("bitmap") {
        if bitmap.get("kind").and_then(Value::as_str) == Some("bitmap_target") {
            let width = bitmap
                .get("width")
                .and_then(Value::as_u64)
                .ok_or_else(|| "bitmap_target.width must be an unsigned integer".to_string())?;
            let rows = bitmap
                .get("rows")
                .and_then(Value::as_u64)
                .ok_or_else(|| "bitmap_target.rows must be an unsigned integer".to_string())?;
            return Ok((
                usize::try_from(width).map_err(|err| err.to_string())?,
                usize::try_from(rows).map_err(|err| err.to_string())?,
            ));
        }
    }
    let Some(box_value) = case.inputs.params.get("target_box") else {
        return Ok((32, 32));
    };
    let width = box_value
        .get("width")
        .and_then(Value::as_u64)
        .ok_or_else(|| "target_box.width must be an unsigned integer".to_string())?;
    let height = box_value
        .get("height")
        .and_then(Value::as_u64)
        .ok_or_else(|| "target_box.height must be an unsigned integer".to_string())?;
    Ok((
        usize::try_from(width).map_err(|err| err.to_string())?,
        usize::try_from(height).map_err(|err| err.to_string())?,
    ))
}

fn outline_render_target_pitch(case: &InputCase, width: usize) -> Result<i32, String> {
    if let Some(Asset::Other(bitmap)) = case.inputs.assets.get("bitmap") {
        if bitmap.get("kind").and_then(Value::as_str) == Some("bitmap_target") {
            let pitch = bitmap
                .get("pitch")
                .and_then(Value::as_i64)
                .ok_or_else(|| "bitmap_target.pitch must be an integer".to_string())?;
            return i32::try_from(pitch).map_err(|err| err.to_string());
        }
    }
    i32::try_from(width).map_err(|err| err.to_string())
}

fn outline_render_clip_box(params: &Value) -> Result<Option<(i32, i32, i32, i32)>, String> {
    let raster_params = params.get("raster_params");
    let Some(clip_box) = params
        .get("clip_box")
        .or_else(|| params.get("initial_clip_box"))
        .or_else(|| raster_params.and_then(|raster_params| raster_params.get("clip_box")))
        .or_else(|| raster_params.and_then(|raster_params| raster_params.get("initial_clip_box")))
    else {
        return Ok(None);
    };
    let field = |name: &str| -> Result<i32, String> {
        let value = clip_box
            .get(name)
            .and_then(Value::as_i64)
            .ok_or_else(|| format!("clip_box.{name} must be an integer"))?;
        i32::try_from(value).map_err(|err| err.to_string())
    };
    Ok(Some((
        field("xMin")?,
        field("xMax")?,
        field("yMin")?,
        field("yMax")?,
    )))
}

