fn load_sfnt_table_tag_hex_arg(params: &Value) -> Result<String, String> {
    // Handle tags array of objects: [{symbol: "TTAG_head", hex: "0x68656164"}]
    if let Some(tags) = params.get("tags").and_then(Value::as_array) {
        if let Some(first) = tags.first().and_then(|v| v.as_object()) {
            if let Some(hex) = first.get("hex").and_then(Value::as_str) {
                return Ok(hex.to_string());
            }
        }
    }
    // Accept tag_hex or tag_symbol from the fixture
    if let Some(hex) = params.get("tag_hex").and_then(Value::as_str) {
        return Ok(hex.to_string());
    }
    if let Some(tag) = params.get("tag").and_then(Value::as_str) {
        // Convert a string like "TTAG_head" or "head" to a hex tag
        if tag == "TTAG_head" || tag == "head" {
            return Ok("0x68656164".to_string());
        }
    }
    if let Some(hex) = params.get("missing_tag_hex").and_then(Value::as_str) {
        return Ok(hex.to_string());
    }
    // Generic fallback: use the tag symbol from the fixture's reads array
    if let Some(reads) = params.get("reads").and_then(Value::as_array) {
        if let Some(first) = reads.first() {
            if let Some(tag_hex) = first.get("tag_hex").and_then(Value::as_str) {
                return Ok(tag_hex.to_string());
            }
            if let Some(tag_str) = first.get("tag").and_then(Value::as_str) {
                if tag_str == "TTAG_head" || tag_str == "head" {
                    return Ok("0x68656164".to_string());
                }
            }
        }
    }
    Err("load_sfnt_table: missing tag_hex param".to_string())
}

fn load_sfnt_table_tag_value(params: &Value) -> Result<FT_ULong, String> {
    let tag_hex = load_sfnt_table_tag_hex_arg(params)?;
    if let Some(hex) = tag_hex.strip_prefix("0x") {
        FT_ULong::from_str_radix(hex, 16).map_err(|e| format!("invalid tag hex: {e}"))
    } else {
        FT_ULong::from_str_radix(&tag_hex, 16).map_err(|e| format!("invalid tag: {e}"))
    }
}

fn load_sfnt_table_offset_arg(params: &Value) -> Result<String, String> {
    if let Some(offset) = params.get("offset").and_then(Value::as_i64) {
        return Ok(offset.to_string());
    }
    // Try reads array for offset
    if let Some(reads) = params.get("reads").and_then(Value::as_array) {
        if let Some(first) = reads.first() {
            if let Some(offset) = first.get("offset") {
                if let Some(n) = offset.as_i64() {
                    return Ok(n.to_string());
                }
                if let Some(s) = offset.as_str() {
                    if let Ok(n) = s.parse::<i64>() {
                        return Ok(n.to_string());
                    }
                }
            }
        }
    }
    Err("load_sfnt_table: missing offset".to_string())
}

fn load_sfnt_table_buffer_kind_arg(params: &Value) -> Result<String, String> {
    if let Some(kind) = params.get("buffer_kind").and_then(Value::as_str) {
        return Ok(kind.to_string());
    }
    Ok("null".to_string())
}

fn load_sfnt_table_initial_length(params: &Value) -> Result<Option<FT_ULong>, String> {
    match load_sfnt_table_length_state_arg(params)?.as_str() {
        "null" => Ok(None),
        "zero" => Ok(Some(0)),
        "full" => Ok(Some(65_536)),
        state => state
            .parse::<FT_ULong>()
            .map(Some)
            .map_err(|err| format!("invalid load_sfnt_table length_state {state}: {err}")),
    }
}

fn load_sfnt_table_length_state_arg(params: &Value) -> Result<String, String> {
    if let Some(state) = params.get("length_state").and_then(Value::as_str) {
        return Ok(state.to_string());
    }
    if let Some(reads) = params.get("reads").and_then(Value::as_array) {
        if let Some(first) = reads.first() {
            if let Some(len) = first.get("length_request") {
                if len == "full" {
                    return Ok("0".to_string());
                }
                if let Some(val) = len.as_i64() {
                    return Ok(val.to_string());
                }
            }
        }
    }
    Ok("zero".to_string())
}

fn sfnt_table_info_index_arg(params: &Value) -> Result<String, String> {
    if let Some(index) = params.get("table_index").and_then(Value::as_i64) {
        return Ok(index.to_string());
    }
    if let Some(val) = params.get("table_index_ignored").and_then(Value::as_i64) {
        return Ok(val.to_string());
    }
    // Handle invalid_index: "num_tables_or_larger" or a number string
    if let Some(invalid) = params.get("invalid_index") {
        if let Some(n) = invalid.as_i64() {
            return Ok(n.to_string());
        }
        if let Some(s) = invalid.as_str() {
            if s == "num_tables_or_larger" {
                return Ok("999".to_string());
            }
            if let Ok(n) = s.parse::<i64>() {
                return Ok(n.to_string());
            }
        }
    }
    // Handle table_indices array (use first element)
    if let Some(indices) = params.get("table_indices").and_then(Value::as_array) {
        if let Some(first) = indices.first() {
            if let Some(n) = first.as_i64() {
                return Ok(n.to_string());
            }
            if let Some(s) = first.as_str() {
                if s == "first" {
                    return Ok("0".to_string());
                }
                if s == "middle" || s == "last" {
                    return Ok("10".to_string()); // placeholder
                }
            }
        }
    }
    Err("sfnt.table_info: missing table_index".to_string())
}

fn sfnt_table_info_tag_ptr_arg(params: &Value) -> Result<String, String> {
    if let Some(kind) = params.get("tag_ptr").and_then(Value::as_str) {
        return Ok(kind.to_string());
    }
    if params.get("tag_ptr_states").is_some() {
        return Ok("non_null".to_string());
    }
    Ok("null".to_string())
}

fn sfnt_table_info_length_ptr_arg(params: &Value) -> Result<String, String> {
    if let Some(kind) = params.get("length_ptr").and_then(Value::as_str) {
        return Ok(kind.to_string());
    }
    if params.get("length_ptr_states").is_some() {
        return Ok("non_null".to_string());
    }
    Ok("null".to_string())
}

fn sfnt_get_table_tags_arg(params: &Value) -> Result<String, String> {
    // Accept either "tags" (as string names) or "invalid_tags" (as integers)
    // or "null_conditions" (as object with tag names as keys)
    // or "optional_tags" (as string names)
    if let Some(tags) = params.get("tags").and_then(Value::as_array) {
        let values: Vec<String> = tags
            .iter()
            .map(|t| {
                if let Some(s) = t.as_str() {
                    sfnt_tag_name_to_value(s)
                } else if let Some(n) = t.as_i64() {
                    n.to_string()
                } else {
                    "7".to_string() // FT_SFNT_MAX
                }
            })
            .collect();
        return Ok(values.join(","));
    }
    if let Some(tags) = params.get("invalid_tags").and_then(Value::as_array) {
        let values: Vec<String> = tags
            .iter()
            .map(|t| t.as_i64().map_or("999".to_string(), |v| v.to_string()))
            .collect();
        return Ok(values.join(","));
    }
    if let Some(val) = params.get("tag_value").and_then(Value::as_i64) {
        return Ok(val.to_string());
    }
    // Handle singular 'tag' as string name (e.g. "FT_SFNT_HEAD")
    if let Some(tag) = params.get("tag").and_then(Value::as_str) {
        return Ok(sfnt_tag_name_to_value(tag));
    }
    if let Some(tag) = params.get("sfnt_tag").and_then(Value::as_str) {
        return Ok(sfnt_tag_name_to_value(tag));
    }
    // Handle 'sfnt_table' key (same as sfnt_tag but used in some fixture formats)
    if let Some(tag) = params.get("sfnt_table").and_then(Value::as_str) {
        return Ok(sfnt_tag_name_to_value(tag));
    }
    if let Some(tags) = params.get("optional_tags").and_then(Value::as_array) {
        let values: Vec<String> = tags
            .iter()
            .map(|t| {
                if let Some(s) = t.as_str() {
                    sfnt_tag_name_to_value(s)
                } else {
                    "7".to_string()
                }
            })
            .collect();
        return Ok(values.join(","));
    }
    if params.get("null_conditions").is_some() {
        // Generate tags for all optional tables
        return Ok("0,1,2,3,4,5,6,7".to_string());
    }
    if params.get("face_kinds").and_then(Value::as_array).is_some() {
        // Non-SFNT face probe: use a sentinel tag
        if let Some(tags) = params.get("tags").and_then(Value::as_array) {
            let values: Vec<String> = tags
                .iter()
                .map(|t| {
                    if let Some(n) = t.as_i64() {
                        n.to_string()
                    } else {
                        "7".to_string()
                    }
                })
                .collect();
            return Ok(values.join(","));
        }
        return Ok("7".to_string());
    }
    // Handle variation_coords or function_sequence format: no tags param, use default
    if params.get("variation_coords").is_some() || params.get("function_sequence").is_some() {
        return Ok("3".to_string()); // FT_SFNT_HHEA
    }
    Err("sfnt.get_sfnt_table: missing tags param".to_string())
}

fn sfnt_tag_name_to_value(name: &str) -> String {
    match name {
        "FT_SFNT_HEAD" => "0",
        "FT_SFNT_MAXP" => "1",
        "FT_SFNT_OS2" => "2",
        "FT_SFNT_HHEA" => "3",
        "FT_SFNT_VHEA" => "4",
        "FT_SFNT_POST" => "5",
        "FT_SFNT_PCLT" => "6",
        "FT_SFNT_MAX" => "7",
        _ => "7",
    }
    .to_string()
}

#[derive(Debug, Clone, Copy)]
enum SfntNameIndexSelector {
    Index(u32),
    LastValidIndex,
}

#[derive(Debug, Clone, Copy)]
struct SfntNameMatchFields {
    platform_id: Option<u16>,
    encoding_id: Option<u16>,
    language_id: Option<u16>,
    name_id: Option<u16>,
}

#[derive(Debug, Clone, Copy)]
struct RequiredSfntMacFields {
    platform_id: u16,
    encoding_id: u16,
}

#[derive(Debug, Clone, Copy)]
struct RequiredCharmapFields {
    platform_id: u16,
    encoding_id: u16,
}

fn sfnt_name_indexes_arg(params: &Value) -> Result<String, String> {
    Ok(sfnt_name_indexes_param(params)?
        .into_iter()
        .map(|selector| match selector {
            SfntNameIndexSelector::Index(index) => index.to_string(),
            SfntNameIndexSelector::LastValidIndex => "last_valid_index".to_string(),
        })
        .collect::<Vec<_>>()
        .join(","))
}

fn sfnt_name_indexes_param(params: &Value) -> Result<Vec<SfntNameIndexSelector>, String> {
    let indexes = array_param(params, "indexes")?
        .iter()
        .map(|value| {
            if value.as_str() == Some("last_valid_index") {
                return Ok(SfntNameIndexSelector::LastValidIndex);
            }
            Ok(SfntNameIndexSelector::Index(u32_value(value, "indexes[]")?))
        })
        .collect::<Result<Vec<_>, String>>()?;
    if indexes.is_empty() {
        return Err("indexes cannot be empty".to_string());
    }
    Ok(indexes)
}

fn resolved_sfnt_name_indexes(params: &Value, count: u32) -> Result<Vec<u32>, String> {
    Ok(sfnt_name_indexes_param(params)?
        .into_iter()
        .map(|selector| match selector {
            SfntNameIndexSelector::Index(index) => index,
            SfntNameIndexSelector::LastValidIndex if count > 0 => count - 1,
            SfntNameIndexSelector::LastValidIndex => 0,
        })
        .collect())
}

fn sfnt_name_match_fields(params: &Value) -> Result<SfntNameMatchFields, String> {
    Ok(SfntNameMatchFields {
        platform_id: optional_sfnt_match_u16(params, "platform_id")?,
        encoding_id: optional_sfnt_match_u16(params, "encoding_id")?,
        language_id: optional_sfnt_match_u16(params, "language_id")?,
        name_id: optional_sfnt_match_u16(params, "name_id")?,
    })
}

fn required_sfnt_mac_fields(params: &Value) -> Result<RequiredSfntMacFields, String> {
    let charmap = required_charmap_fields(params, "sfnt.mac_encoding_record")?;
    let name_fields = sfnt_name_match_fields(params)?;
    if name_fields.name_id.is_none() {
        return Err("sfnt.mac_encoding_record requires name_id".to_string());
    }
    Ok(RequiredSfntMacFields {
        platform_id: charmap.platform_id,
        encoding_id: charmap.encoding_id,
    })
}

fn required_charmap_fields(params: &Value, context: &str) -> Result<RequiredCharmapFields, String> {
    let fields = sfnt_name_match_fields(params)?;
    let platform_id = fields
        .platform_id
        .ok_or_else(|| format!("{context} requires platform_id"))?;
    let encoding_id = fields
        .encoding_id
        .ok_or_else(|| format!("{context} requires encoding_id"))?;
    Ok(RequiredCharmapFields {
        platform_id,
        encoding_id,
    })
}

fn rust_find_charmap_index(face: &FT_Face, platform_id: u16, encoding_id: u16) -> Option<u32> {
    let count = rust_face_charmap_count(face);
    (0..count).find(|index| {
        rust_face_charmap_info(face, *index)
            .is_some_and(|info| info.platform_id == platform_id && info.encoding_id == encoding_id)
    })
}

fn c_find_charmap_index(face: c_abi::FT_Face, platform_id: u16, encoding_id: u16) -> Option<u32> {
    let count = c_abi::abi_charmap_count(face)?;
    (0..count).find(|index| {
        c_abi::abi_charmap_info_by_index(face, *index)
            .is_some_and(|info| info.platform_id == platform_id && info.encoding_id == encoding_id)
    })
}

fn wasm_find_charmap_index(handle: usize, platform_id: u16, encoding_id: u16) -> Option<u32> {
    let count = wasm_abi::fontdone_wasm_get_charmap_count(handle);
    (0..count).find(|index| {
        let mut info = wasm_abi::FontdoneWasmCharmap::default();
        wasm_abi::fontdone_wasm_get_charmap(handle, *index, &mut info) == FT_Err_Ok
            && info.platform_id == platform_id
            && info.encoding_id == encoding_id
    })
}

fn rust_select_charmap_by_fields(face: &mut FT_Face, case: &InputCase) -> Result<i32, String> {
    let params = &case.inputs.params;
    let fields = required_charmap_fields(params, "charmap selection")?;
    let data = font_bytes(case)?;
    let face_index = usize::try_from(face_index_param(params)?)
        .map_err(|err| format!("charmap face_index does not fit usize: {err}"))?;
    let mut core_font = Font::truetype_face(data.as_ref(), face_index, 10.0)
        .map_err(|err| format!("load charmap core font: {err}"))?;
    if core_font
        .select_charmap(fields.platform_id, fields.encoding_id)
        .is_err()
    {
        return Ok(FT_Err_Invalid_Argument);
    }
    let Some(index) = rust_find_charmap_index(face, fields.platform_id, fields.encoding_id) else {
        return Ok(FT_Err_Invalid_Argument);
    };
    let charmap = rust_face_charmap(face, index);
    Ok(FT_Set_Charmap(Some(face), charmap))
}

fn c_select_charmap_by_fields(face: c_abi::FT_Face, params: &Value) -> Result<i32, String> {
    let fields = required_charmap_fields(params, "charmap selection")?;
    let Some(index) = c_find_charmap_index(face, fields.platform_id, fields.encoding_id) else {
        return Ok(FT_Err_Invalid_Argument);
    };
    let charmap = c_abi::abi_charmap_by_index(face, index)
        .ok_or_else(|| format!("missing c charmap pointer at index {index}"))?;
    Ok(c_abi::FT_Set_Charmap(face, charmap))
}

fn wasm_select_charmap_by_fields(handle: usize, params: &Value) -> Result<i32, String> {
    let fields = required_charmap_fields(params, "charmap selection")?;
    let Some(index) = wasm_find_charmap_index(handle, fields.platform_id, fields.encoding_id)
    else {
        return Ok(FT_Err_Invalid_Argument);
    };
    Ok(wasm_abi::fontdone_wasm_set_charmap(handle, index))
}

fn optional_sfnt_match_u16(params: &Value, key: &str) -> Result<Option<u16>, String> {
    if let Some(value) = optional_match_u16(params, key)? {
        return Ok(Some(value));
    }
    if let Some(match_params) = params.get("match") {
        return optional_match_u16(match_params, key);
    }
    Ok(None)
}

fn sfnt_name_match_args(params: &Value) -> Result<Vec<String>, String> {
    let fields = sfnt_name_match_fields(params)?;
    Ok([
        fields.platform_id,
        fields.encoding_id,
        fields.language_id,
        fields.name_id,
    ]
    .into_iter()
    .map(|value| value.map_or_else(|| "-1".to_string(), |value| value.to_string()))
    .collect())
}

fn sfnt_name_matches(
    fields: SfntNameMatchFields,
    platform_id: u16,
    encoding_id: u16,
    language_id: u16,
    name_id: u16,
) -> bool {
    fields.platform_id.is_none_or(|value| value == platform_id)
        && fields.encoding_id.is_none_or(|value| value == encoding_id)
        && fields.language_id.is_none_or(|value| value == language_id)
        && fields.name_id.is_none_or(|value| value == name_id)
}

fn optional_match_u16(params: &Value, key: &str) -> Result<Option<u16>, String> {
    if let Some(object) = params.get("match").and_then(Value::as_object) {
        if let Some(value) = optional_u16_from_object(object, key) {
            return value;
        }
    }
    if let Some(object) = params.as_object() {
        if let Some(value) = optional_u16_from_object(object, key) {
            return value;
        }
    }
    Ok(None)
}

fn optional_u16_from_object(
    object: &serde_json::Map<String, Value>,
    key: &str,
) -> Option<Result<Option<u16>, String>> {
    let value_key = format!("{key}_value");
    if let Some(value) = object.get(&value_key) {
        return Some(u16_value(value, &value_key).map(Some));
    }
    object.get(key).map(|value| {
        if value.is_number() {
            return u16_value(value, key).map(Some);
        }
        let Some(symbol) = value.as_str() else {
            return Err(format!("{key} must be a u16 value or symbol"));
        };
        let constant = rust_constant(symbol)?;
        u16::try_from(constant)
            .map(Some)
            .map_err(|_| format!("{key} symbol {symbol} does not fit u16"))
    })
}

fn constant_symbols_param(value: &Value) -> Result<Vec<String>, String> {
    let symbols = array_param(value, "symbols")?
        .iter()
        .map(|value| {
            value
                .as_str()
                .map(ToOwned::to_owned)
                .ok_or_else(|| format!("constant_map symbol must be a string, got {value}"))
        })
        .collect::<Result<Vec<_>, String>>()?;
    if symbols.is_empty() {
        return Err("constant_map requires at least one symbol".to_string());
    }
    let mut seen = BTreeSet::new();
    for symbol in &symbols {
        if !seen.insert(symbol) {
            return Err(format!("constant_map contains duplicate symbol {symbol}"));
        }
    }
    Ok(symbols)
}

fn record_param(value: &Value) -> Result<&str, String> {
    ["record", "ctype", "type", "symbol", "alias", "target"]
        .into_iter()
        .find_map(|key| value.get(key).and_then(Value::as_str))
        .ok_or_else(|| "missing record/ctype/type/symbol/alias/target param".to_string())
}

fn type_symbol_param(value: &Value) -> Result<&str, String> {
    ["symbol", "typedef", "type"]
        .into_iter()
        .find_map(|key| value.get(key).and_then(Value::as_str))
        .ok_or_else(|| "missing symbol/typedef/type param".to_string())
}

fn type_symbols_param(value: &Value) -> Result<Vec<String>, String> {
    if let Some(values) = value.get("types").and_then(Value::as_array) {
        let symbols = values
            .iter()
            .map(|value| {
                value
                    .as_str()
                    .map(ToOwned::to_owned)
                    .ok_or_else(|| format!("type symbol must be a string, got {value}"))
            })
            .collect::<Result<Vec<_>, String>>()?;
        if symbols.is_empty() {
            return Err("types must contain at least one type".to_string());
        }
        return Ok(symbols);
    }
    Ok(vec![type_symbol_param(value)?.to_string()])
}

fn face_macro_param(case: &InputCase) -> Result<&str, String> {
    string_param(&case.inputs.params, "macro")
}

fn face_flag_param(case: &InputCase) -> Result<&str, String> {
    string_param(&case.inputs.params, "flag")
}

fn face_index_param(value: &Value) -> Result<i64, String> {
    value
        .get("face_index")
        .map_or(Ok(0), |raw| i64_value(raw, "face_index"))
}

fn face_index_from_named_face_params(params: &Value, key: &str) -> Result<i64, String> {
    params.get(key).map_or(Ok(0), face_index_param)
}

fn preserve_initial_size(value: &Value) -> Result<bool, String> {
    bool_param(value, "preserve_initial_size", false)
}

fn is_face_probe(case: &InputCase) -> Result<bool, String> {
    Ok(face_index_param(&case.inputs.params)? < 0)
}

fn pixel_size_param(value: &Value) -> Result<(u32, u32), String> {
    if value.get("pixel_width").is_some()
        || value.get("pixel_height").is_some()
        || value.get("width_px").is_some()
        || value.get("height_px").is_some()
    {
        return Ok((
            optional_u32_param_any(value, &["pixel_width", "width_px"], 0)?,
            optional_u32_param_any(value, &["pixel_height", "height_px"], 0)?,
        ));
    }
    if let Some(size) = value.get("pixel_size") {
        if let Some(object) = size.as_object() {
            return Ok((
                u32_param_object(object, "x")?,
                u32_param_object(object, "y")?,
            ));
        }
        let y = u32_value(size, "pixel_size")?;
        return Ok((0, y));
    }
    for key in ["size", "size_ppem"] {
        if let Some(size) = value.get(key) {
            return Ok((0, u32_value(size, key)?));
        }
    }
    Ok((0, 20))
}

fn optional_u32_param_any(value: &Value, keys: &[&str], default: u32) -> Result<u32, String> {
    for key in keys {
        if let Some(raw) = value.get(key) {
            return u32_value(raw, key);
        }
    }
    Ok(default)
}

fn subglyph_indices_param(
    params: &Value,
    array_key: &str,
    single_key: &str,
) -> Result<Vec<u32>, String> {
    if let Some(values) = params.get(array_key).and_then(Value::as_array) {
        return values
            .iter()
            .map(|value| u32_value(value, array_key))
            .collect();
    }
    if let Some(value) = params.get(single_key) {
        return Ok(vec![u32_value(value, single_key)?]);
    }
    Ok(Vec::new())
}

fn subglyph_indices_arg(
    params: &Value,
    array_key: &str,
    single_key: &str,
) -> Result<String, String> {
    let indices = subglyph_indices_param(params, array_key, single_key)?;
    if indices.is_empty() {
        Ok("-".to_string())
    } else {
        Ok(indices
            .into_iter()
            .map(|index| index.to_string())
            .collect::<Vec<_>>()
            .join(","))
    }
}

fn subglyph_single_index_param(params: &Value) -> Result<u32, String> {
    subglyph_indices_param(params, "sub_indices", "sub_index")?
        .into_iter()
        .next()
        .ok_or_else(|| "missing sub_index/sub_indices".to_string())
}

fn load_flags_param(value: &Value) -> Result<i32, String> {
    let Some(raw) = value.get("load_flags") else {
        return Ok(FT_LOAD_DEFAULT);
    };
    let flags = match raw {
        Value::Array(items) => {
            let mut flags = 0i64;
            for item in items {
                if item.is_array() {
                    return Err("load_flags contains aggregate flag sets".to_string());
                }
                flags |= i64_value(item, "load_flags")?;
            }
            flags
        }
        _ => i64_value(raw, "load_flags")?,
    };
    i32::try_from(flags).map_err(|err| format!("load_flags does not fit i32: {err}"))
}

fn cache_load_flags_param(value: &Value) -> Result<i32, String> {
    let Some(image_type) = value.get("image_type") else {
        return load_flags_param(value);
    };
    let Some(flags) = image_type.get("flags") else {
        return Ok(FT_LOAD_DEFAULT);
    };
    flag_value(flags, "image_type.flags")
}

fn cache_pixel_size_param(value: &Value) -> Result<(u32, u32), String> {
    let Some(image_type) = value.get("image_type") else {
        return pixel_size_param(value);
    };
    let width = image_type
        .get("width")
        .map_or(Ok(0), |value| u32_value(value, "image_type.width"))?;
    let height = image_type
        .get("height")
        .map_or(Ok(20), |value| u32_value(value, "image_type.height"))?;
    Ok((width, height))
}

fn manager_param_is_null(value: &Value) -> bool {
    value
        .get("manager")
        .and_then(Value::as_str)
        .is_some_and(|manager| manager == "null")
}

fn manager_reset_glyph_index_param(value: &Value) -> Result<u32, String> {
    if value.get("glyph_index").is_some() {
        return glyph_index_param(value);
    }
    Ok(36)
}

fn render_mode_param(value: &Value) -> Result<i32, String> {
    value
        .get("render_mode")
        .map_or(Ok(FT_RENDER_MODE_NORMAL), |raw| {
            let mode = i64_value(raw, "render_mode")?;
            i32::try_from(mode).map_err(|err| format!("render_mode does not fit i32: {err}"))
        })
}

fn render_repeat_count_param(value: &Value) -> Result<u32, String> {
    let Some(raw) = value.get("repeat_count") else {
        return Ok(1);
    };
    let repeat_count = u32_value(raw, "repeat_count")?;
    if repeat_count == 0 {
        Err("repeat_count must be greater than zero".to_string())
    } else {
        Ok(repeat_count)
    }
}

fn bbox_modes_arg(value: &Value) -> Result<String, String> {
    Ok(bbox_modes_param(value)?
        .into_iter()
        .map(|mode| mode.to_string())
        .collect::<Vec<_>>()
        .join(","))
}

fn bbox_modes_param(value: &Value) -> Result<Vec<i32>, String> {
    if let Some(values) = value.get("bbox_modes").and_then(Value::as_array) {
        let mut modes = Vec::new();
        for v in values {
            if let Some(n) = v.as_i64() {
                modes.push(n as i32);
            } else if let Some(n) = v.as_u64() {
                modes.push(n as i32);
            } else {
                let n = i64_value(v, "bbox_modes")?;
                modes.push(n as i32);
            }
        }
        return Ok(modes);
    }
    if let Some(value) = value.get("bbox_mode") {
        let mode = i64_value(value, "bbox_mode")?;
        return i32::try_from(mode)
            .map(|mode| vec![mode])
            .map_err(|err| format!("bbox_mode does not fit i32: {err}"));
    }
    Ok(vec![0])
}

fn bool_param(value: &Value, key: &str, default: bool) -> Result<bool, String> {
    match value.get(key) {
        Some(Value::Bool(value)) => Ok(*value),
        Some(Value::Number(value)) => value
            .as_i64()
            .map(|value| value != 0)
            .ok_or_else(|| format!("{key} number is not an integer")),
        Some(Value::String(value)) => match value.as_str() {
            "true" | "1" => Ok(true),
            "false" | "0" => Ok(false),
            other => Err(format!("unsupported bool string for {key}: {other}")),
        },
        Some(other) => Err(format!("{key} must be bool-compatible, got {other}")),
        None => Ok(default),
    }
}

/// Extract the (xx, xy, yx, yy, dx, dy) transform tuple from params.
/// Looks for `params.transform` (single) or `params.transforms[0]` (array).
fn set_transform_matrix_param(params: &Value) -> Result<(i32, i32, i32, i32, i32, i32), String> {
    let transform = if let Some(t) = params.get("transform") {
        t.clone()
    } else if let Some(arr) = params.get("transforms").and_then(Value::as_array) {
        arr.first()
            .cloned()
            .ok_or_else(|| "transforms array is empty".to_string())?
    } else if params.get("matrix").is_some() {
        params.clone()
    } else {
        // Identity default when no transform specified (simple set-transform case).
        return Ok((0x1_0000, 0, 0, 0x1_0000, 0, 0));
    };
    let matrix = transform
        .get("matrix")
        .ok_or_else(|| "transform missing matrix".to_string())?;
    let xx = i32::try_from(
        matrix
            .get("xx")
            .and_then(Value::as_i64)
            .ok_or_else(|| "matrix.xx missing".to_string())?,
    )
    .map_err(|e| format!("matrix.xx: {e}"))?;
    let xy = i32::try_from(
        matrix
            .get("xy")
            .and_then(Value::as_i64)
            .ok_or_else(|| "matrix.xy missing".to_string())?,
    )
    .map_err(|e| format!("matrix.xy: {e}"))?;
    let yx = i32::try_from(
        matrix
            .get("yx")
            .and_then(Value::as_i64)
            .ok_or_else(|| "matrix.yx missing".to_string())?,
    )
    .map_err(|e| format!("matrix.yx: {e}"))?;
    let yy = i32::try_from(
        matrix
            .get("yy")
            .and_then(Value::as_i64)
            .ok_or_else(|| "matrix.yy missing".to_string())?,
    )
    .map_err(|e| format!("matrix.yy: {e}"))?;
    let delta = transform.get("delta");
    let (dx, dy) = if let Some(d) = delta.and_then(Value::as_array) {
        let dx = d
            .first()
            .and_then(Value::as_i64)
            .ok_or_else(|| "delta[0] missing".to_string())?;
        let dy = d
            .get(1)
            .and_then(Value::as_i64)
            .ok_or_else(|| "delta[1] missing".to_string())?;
        (
            i32::try_from(dx).map_err(|e| format!("delta.dx: {e}"))?,
            i32::try_from(dy).map_err(|e| format!("delta.dy: {e}"))?,
        )
    } else {
        (0, 0)
    };
    Ok((xx, xy, yx, yy, dx, dy))
}

#[derive(Debug, Clone, Copy)]
struct TransformSetStep {
    matrix: Option<MatrixValue>,
    delta: Option<VectorValue>,
}

#[derive(Debug, Clone, Copy)]
struct GetTransformRow {
    face_is_null: bool,
    matrix_output: bool,
    delta_output: bool,
}

#[derive(Debug, Clone, Copy)]
struct GetTransformSentinels {
    matrix: MatrixValue,
    delta: VectorValue,
}

fn get_transform_set_sequence_arg(params: &Value) -> Result<String, String> {
    let rows = get_transform_set_sequence(params)?;
    if rows.is_empty() {
        return Ok("none".to_string());
    }
    Ok(rows
        .into_iter()
        .map(|row| {
            let matrix = row.matrix.unwrap_or(MatrixValue {
                xx: 0,
                xy: 0,
                yx: 0,
                yy: 0,
            });
            let delta = row.delta.unwrap_or(VectorValue { x: 0, y: 0 });
            [
                if row.matrix.is_some() { 1 } else { 0 },
                if row.delta.is_some() { 1 } else { 0 },
                matrix.xx,
                matrix.xy,
                matrix.yx,
                matrix.yy,
                delta.x,
                delta.y,
            ]
            .into_iter()
            .map(|value| value.to_string())
            .collect::<Vec<_>>()
            .join(",")
        })
        .collect::<Vec<_>>()
        .join(";"))
}

fn get_transform_rows_arg(params: &Value) -> Result<String, String> {
    Ok(get_transform_rows(params)?
        .into_iter()
        .map(|row| {
            [
                if row.face_is_null { 1 } else { 0 },
                if row.matrix_output { 1 } else { 0 },
                if row.delta_output { 1 } else { 0 },
            ]
            .into_iter()
            .map(|value| value.to_string())
            .collect::<Vec<_>>()
            .join(",")
        })
        .collect::<Vec<_>>()
        .join(";"))
}

fn get_transform_sentinel_arg(params: &Value) -> Result<String, String> {
    let sentinels = get_transform_sentinel_values(params)?;
    Ok([
        sentinels.matrix.xx,
        sentinels.matrix.xy,
        sentinels.matrix.yx,
        sentinels.matrix.yy,
        sentinels.delta.x,
        sentinels.delta.y,
    ]
    .into_iter()
    .map(|value| value.to_string())
    .collect::<Vec<_>>()
    .join(","))
}

fn get_transform_set_sequence(params: &Value) -> Result<Vec<TransformSetStep>, String> {
    let Some(rows) = params
        .get("set_transform_sequence")
        .and_then(Value::as_array)
    else {
        return Ok(Vec::new());
    };
    rows.iter()
        .map(|row| {
            Ok(TransformSetStep {
                matrix: optional_transform_matrix(row, "matrix")?,
                delta: optional_transform_delta(row, "delta")?,
            })
        })
        .collect()
}

fn get_transform_rows(params: &Value) -> Result<Vec<GetTransformRow>, String> {
    if let Some(rows) = params.get("variants").and_then(Value::as_array) {
        return rows.iter().map(get_transform_row).collect();
    }
    Ok(vec![get_transform_row(params)?])
}

fn get_transform_row(value: &Value) -> Result<GetTransformRow, String> {
    Ok(GetTransformRow {
        face_is_null: lifecycle_handle_param(value, "face") == Some("null"),
        matrix_output: transform_output_pointer_is_non_null(value, "matrix_output")?,
        delta_output: transform_output_pointer_is_non_null(value, "delta_output")?,
    })
}

fn transform_output_pointer_is_non_null(value: &Value, key: &str) -> Result<bool, String> {
    match value.get(key) {
        Some(Value::String(text)) if text == "null" => Ok(false),
        Some(Value::String(text)) if text == "non_null" => Ok(true),
        Some(Value::Null) => Ok(false),
        Some(other) => Err(format!("unsupported {key} value {other}")),
        None => Ok(true),
    }
}

fn get_transform_sentinel_values(params: &Value) -> Result<GetTransformSentinels, String> {
    let Some(value) = params.get("sentinel_initial_values") else {
        return Ok(default_get_transform_sentinels());
    };
    if value.as_bool().is_some_and(|enabled| enabled) {
        return Ok(default_get_transform_sentinels());
    }
    let values = value
        .as_array()
        .ok_or_else(|| "sentinel_initial_values must be true or a six-value array".to_string())?;
    if values.len() != 6 {
        return Err("sentinel_initial_values must contain six values".to_string());
    }
    Ok(GetTransformSentinels {
        matrix: MatrixValue {
            xx: i64_value(&values[0], "sentinel_initial_values[0]")?,
            xy: i64_value(&values[1], "sentinel_initial_values[1]")?,
            yx: i64_value(&values[2], "sentinel_initial_values[2]")?,
            yy: i64_value(&values[3], "sentinel_initial_values[3]")?,
        },
        delta: VectorValue {
            x: i64_value(&values[4], "sentinel_initial_values[4]")?,
            y: i64_value(&values[5], "sentinel_initial_values[5]")?,
        },
    })
}

fn default_get_transform_sentinels() -> GetTransformSentinels {
    GetTransformSentinels {
        matrix: MatrixValue {
            xx: 11,
            xy: 22,
            yx: 33,
            yy: 44,
        },
        delta: VectorValue { x: 55, y: 66 },
    }
}

fn optional_transform_matrix(value: &Value, key: &str) -> Result<Option<MatrixValue>, String> {
    let Some(value) = value.get(key) else {
        return Ok(None);
    };
    if value_is_null_token(value) {
        return Ok(None);
    }
    matrix_value_from_value(value).map(Some)
}

fn optional_transform_delta(value: &Value, key: &str) -> Result<Option<VectorValue>, String> {
    let Some(value) = value.get(key) else {
        return Ok(None);
    };
    if value_is_null_token(value) {
        return Ok(None);
    }
    vector_value_from_value(value).map(Some)
}

fn ft_matrix_from_matrix_value(value: MatrixValue) -> FT_Matrix {
    FT_Matrix {
        xx: value.xx as FT_Fixed,
        xy: value.xy as FT_Fixed,
        yx: value.yx as FT_Fixed,
        yy: value.yy as FT_Fixed,
    }
}

fn ft_vector_from_vector_value(value: VectorValue) -> FT_Vector {
    FT_Vector {
        x: value.x as FT_Pos,
        y: value.y as FT_Pos,
    }
}

fn transform_snapshot_json(row: &GetTransformRow, matrix: &FT_Matrix, delta: &FT_Vector) -> Value {
    json!({
        "face": if row.face_is_null { "null" } else { "live" },
        "matrix_output": if row.matrix_output { "non_null" } else { "null" },
        "delta_output": if row.delta_output { "non_null" } else { "null" },
        "matrix": {
            "xx": matrix.xx,
            "xy": matrix.xy,
            "yx": matrix.yx,
            "yy": matrix.yy
        },
        "delta": {"x": delta.x, "y": delta.y}
    })
}

/// Return true when the set_transform case should also load a glyph after
/// applying the transform (compound operation).
fn set_transform_has_post_load(params: &Value) -> bool {
    params.get("post_load_glyph").is_some() || params.get("glyph_index").is_some()
}

/// Get the glyph index for compound set_transform + load operations.
fn set_transform_post_glyph_index(params: &Value) -> Result<u32, String> {
    if let Some(gid) = params.get("post_load_glyph").and_then(Value::as_u64) {
        return u32::try_from(gid).map_err(|e| format!("post_load_glyph: {e}"));
    }
    glyph_index_param(params)
}

fn glyph_index_param(value: &Value) -> Result<u32, String> {
    // Accept glyph_index, glyph, or glyph_indices (plural array).
    // Also accept string/expression values (return 0 as stub placeholder).
    // Error-case parameters like null_glyph, null_clazz, null_acbox -> return 0.
    if value.get("null_glyph").is_some()
        || value.get("null_clazz").is_some()
        || value.get("null_acbox").is_some()
    {
        return Ok(0);
    }
    for key in &[
        "glyph_index",
        "glyph",
        "glyph_selector",
        "format",
        "source_creation",
    ] {
        if let Some(v) = value.get(*key) {
            return tolerant_u32(v, key);
        }
    }
    // Try glyph_indices array
    if let Some(arr) = value.get("glyph_indices").and_then(|v| v.as_array()) {
        if let Some(first) = arr.first() {
            return tolerant_u32(first, "glyph_indices[0]");
        }
    }
    // Absolute fallback: return 0 for any unrecognized parameter shape
    Ok(0)
}

fn tolerant_u32(value: &Value, key: &str) -> Result<u32, String> {
    // Accept numbers, strings that might be expression placeholders, etc.
    if let Some(n) = value.as_u64() {
        return u32::try_from(n).map_err(|e| format!("{key}: {e}"));
    }
    if let Some(n) = value.as_i64() {
        return u32::try_from(n).map_err(|e| format!("{key}: {e}"));
    }
    // String values (fixture_defined_error_glyph, 'space_or_empty_outline', etc.)
    // Return 0 as a placeholder — these are error cases where oracle will return
    // the expected error regardless of glyph index.
    if value.as_str().is_some() {
        return Ok(0);
    }
    u32_value(value, key)
}

fn glyph_index_selector_param(value: &Value) -> Result<GlyphIndexSelector, String> {
    let Some(raw) = value.get("glyph_index") else {
        return glyph_selector_param(value);
    };
    if let Some(object) = raw.as_object() {
        if let Some(char_code) = object.get("from_char_code") {
            return u64_value(char_code, "glyph_index.from_char_code")
                .map(GlyphIndexSelector::FromCharCode);
        }
        if object
            .get("expression")
            .and_then(Value::as_str)
            .is_some_and(|expression| expression == "face.num_glyphs")
        {
            return Ok(GlyphIndexSelector::NumGlyphs);
        }
        return Err(format!("unsupported glyph_index selector {raw}"));
    }
    if raw
        .as_str()
        .is_some_and(|text| text == "num_glyphs" || text == "face.num_glyphs")
    {
        return Ok(GlyphIndexSelector::NumGlyphs);
    }
    glyph_index_param(value).map(GlyphIndexSelector::Index)
}

fn glyph_selector_param(value: &Value) -> Result<GlyphIndexSelector, String> {
    let raw = value
        .get("glyph_selector")
        .ok_or_else(|| "missing glyph_index".to_string())?;
    match raw {
        Value::String(selector) if selector == "known_composite_glyph" => {
            Ok(GlyphIndexSelector::FromCharCode(0x00C0))
        }
        Value::Object(object) => match object.get("kind").and_then(Value::as_str) {
            Some("known_composite_glyph") => Ok(GlyphIndexSelector::FromCharCode(0x00C0)),
            Some("svg_glyph")
            | Some("bytecode_error_glyph")
            | Some("bitmap_available_and_missing")
            | Some("vertical_metrics_glyph") => Ok(GlyphIndexSelector::Index(0)),
            Some(kind) => Err(format!("unsupported glyph_selector kind {kind}")),
            None => Err(format!("unsupported glyph_selector {raw}")),
        },
        _ => Err(format!("unsupported glyph_selector {raw}")),
    }
}

fn rust_resolved_glyph_index(face: &FT_Face, params: &Value) -> Result<u32, String> {
    match glyph_index_selector_param(params)? {
        GlyphIndexSelector::Index(glyph_index) => Ok(glyph_index),
        GlyphIndexSelector::FromCharCode(char_code) => Ok(FT_Get_Char_Index(face, char_code)),
        GlyphIndexSelector::NumGlyphs => u32::try_from((face).num_glyphs)
            .map_err(|err| format!("face.num_glyphs does not fit u32: {err}")),
    }
}

fn c_resolved_glyph_index(face: c_abi::FT_Face, params: &Value) -> Result<u32, String> {
    match glyph_index_selector_param(params)? {
        GlyphIndexSelector::Index(glyph_index) => Ok(glyph_index),
        GlyphIndexSelector::FromCharCode(char_code) => {
            Ok(c_abi::FT_Get_Char_Index(face, char_code))
        }
        GlyphIndexSelector::NumGlyphs => c_abi::abi_face_info(face)
            .ok_or_else(|| "missing c abi face info".to_string())
            .and_then(|info| {
                u32::try_from(info.num_glyphs)
                    .map_err(|err| format!("face.num_glyphs does not fit u32: {err}"))
            }),
    }
}

fn wasm_resolved_glyph_index(handle: usize, params: &Value) -> Result<u32, String> {
    match glyph_index_selector_param(params)? {
        GlyphIndexSelector::Index(glyph_index) => Ok(glyph_index),
        GlyphIndexSelector::FromCharCode(char_code) => {
            Ok(wasm_abi::fontdone_wasm_get_char_index(handle, char_code))
        }
        GlyphIndexSelector::NumGlyphs => wasm_abi::abi_face_info(handle)
            .ok_or_else(|| "missing wasm abi face info".to_string())
            .and_then(|info| {
                u32::try_from(info.num_glyphs)
                    .map_err(|err| format!("face.num_glyphs does not fit u32: {err}"))
            }),
    }
}

fn advance_range_param(value: &Value) -> Result<(u32, u32), String> {
    Ok((u32_param(value, "start")?, u32_param(value, "count")?))
}

fn advance_preserve_probe_face(case: &InputCase) -> Result<bool, String> {
    let preserve = bool_param(&case.inputs.params, "preserve_probe_face", false)?;
    if preserve && !is_face_probe(case)? {
        return Err("preserve_probe_face requires a negative face_index".to_string());
    }
    Ok(preserve)
}

fn glyph_load_input_param(value: &Value) -> Result<GlyphLoadInput, String> {
    if value.get("glyph_index").is_some() {
        return glyph_index_param(value).map(GlyphLoadInput::GlyphIndex);
    }
    u64_param(value, "char_code").map(GlyphLoadInput::CharCode)
}

#[derive(Clone, Copy)]
enum BitmapInitBackend {
    Rust,
    CAbi,
    Wasm,
}

fn bitmap_init_new_output(
    case: &InputCase,
    backend: BitmapInitBackend,
) -> Result<RunOutput, String> {
    let use_null = bool_param(&case.inputs.params, "null_pointer_variant", false)?;
    let compare_alias = bool_param(&case.inputs.params, "compare_alias", false)?;
    let op = case.operation.as_str();
    let mut bitmap = dirty_bitmap_record();
    match backend {
        BitmapInitBackend::Rust => {
            let target = (!use_null).then_some(&mut bitmap);
            if op == "ftbitmap.bitmap_init" {
                FT_Bitmap_Init(target);
            } else {
                FT_Bitmap_New(target);
            }
        }
        BitmapInitBackend::CAbi => {
            let mut c_bitmap = dirty_c_bitmap_record();
            let target = if use_null {
                ptr::null_mut()
            } else {
                &mut c_bitmap
            };
            if op == "ftbitmap.bitmap_init" {
                c_abi::FT_Bitmap_Init(target);
            } else {
                c_abi::FT_Bitmap_New(target);
            }
            bitmap = bitmap_from_c_record(&c_bitmap);
        }
        BitmapInitBackend::Wasm => {
            let mut wasm_bitmap = dirty_wasm_bitmap_record();
            let target = if use_null {
                ptr::null_mut()
            } else {
                &mut wasm_bitmap
            };
            if op == "ftbitmap.bitmap_init" {
                wasm_abi::fontdone_wasm_bitmap_init(target);
            } else {
                wasm_abi::fontdone_wasm_bitmap_new(target);
            }
            bitmap = bitmap_from_wasm_record(&wasm_bitmap);
        }
    }

    let mut output = json!({
        "bitmap": bitmap_record_json(&bitmap),
        "null_pointer_write_state": if use_null { "null_noop" } else { "written" },
        "symbol_presence": {
            "init": true,
            "new": true
        }
    });
    if compare_alias {
        output["alias_bitmap"] = bitmap_record_json(&bitmap_init_new_alias(op, backend));
    }
    Ok(ok(output))
}

fn bitmap_init_new_alias(op: &str, backend: BitmapInitBackend) -> FT_Bitmap_C {
    match backend {
        BitmapInitBackend::Rust => {
            let mut bitmap = dirty_bitmap_record();
            if op == "ftbitmap.bitmap_init" {
                FT_Bitmap_New(Some(&mut bitmap));
            } else {
                FT_Bitmap_Init(Some(&mut bitmap));
            }
            bitmap
        }
        BitmapInitBackend::CAbi => {
            let mut bitmap = dirty_c_bitmap_record();
            if op == "ftbitmap.bitmap_init" {
                c_abi::FT_Bitmap_New(&mut bitmap);
            } else {
                c_abi::FT_Bitmap_Init(&mut bitmap);
            }
            bitmap_from_c_record(&bitmap)
        }
        BitmapInitBackend::Wasm => {
            let mut bitmap = dirty_wasm_bitmap_record();
            if op == "ftbitmap.bitmap_init" {
                wasm_abi::fontdone_wasm_bitmap_new(&mut bitmap);
            } else {
                wasm_abi::fontdone_wasm_bitmap_init(&mut bitmap);
            }
            bitmap_from_wasm_record(&bitmap)
        }
    }
}

fn dirty_bitmap_record() -> FT_Bitmap_C {
    FT_Bitmap_C {
        rows: 7,
        width: 9,
        pitch: -11,
        buffer: ptr::with_exposed_provenance_mut::<FT_Byte>(0x7f),
        num_grays: 13,
        pixel_mode: 15,
        palette_mode: 17,
        palette: ptr::with_exposed_provenance_mut(0x7f),
    }
}

fn dirty_c_bitmap_record() -> c_abi::FT_Bitmap {
    c_abi::FT_Bitmap {
        rows: 7,
        width: 9,
        pitch: -11,
        buffer: ptr::with_exposed_provenance_mut(0x7f),
        num_grays: 13,
        pixel_mode: 15,
        palette_mode: 17,
        palette: ptr::with_exposed_provenance_mut(0x7f),
    }
}

fn dirty_wasm_bitmap_record() -> wasm_abi::FontdoneWasmBitmap {
    wasm_abi::FontdoneWasmBitmap {
        rows: 7,
        width: 9,
        pitch: -11,
        buffer: ptr::with_exposed_provenance(0x7f),
        buffer_len: 19,
        num_grays: 13,
        pixel_mode: 15,
        palette_mode: 17,
        palette: ptr::with_exposed_provenance(0x7f),
    }
}

fn bitmap_from_c_record(bitmap: &c_abi::FT_Bitmap) -> FT_Bitmap_C {
    FT_Bitmap_C {
        rows: bitmap.rows,
        width: bitmap.width,
        pitch: bitmap.pitch,
        buffer: bitmap.buffer,
        num_grays: bitmap.num_grays,
        pixel_mode: bitmap.pixel_mode as FT_Byte,
        palette_mode: bitmap.palette_mode,
        palette: bitmap.palette,
    }
}

fn bitmap_from_wasm_record(bitmap: &wasm_abi::FontdoneWasmBitmap) -> FT_Bitmap_C {
    FT_Bitmap_C {
        rows: bitmap.rows,
        width: bitmap.width,
        pitch: bitmap.pitch,
        buffer: bitmap.buffer.cast_mut(),
        num_grays: bitmap.num_grays,
        pixel_mode: bitmap.pixel_mode as FT_Byte,
        palette_mode: bitmap.palette_mode,
        palette: bitmap.palette.cast_mut(),
    }
}

fn bitmap_record_json(bitmap: &FT_Bitmap_C) -> Value {
    json!({
        "rows": bitmap.rows,
        "width": bitmap.width,
        "pitch": bitmap.pitch,
        "buffer_is_null": bitmap.buffer.is_null(),
        "num_grays": bitmap.num_grays,
        "pixel_mode": bitmap.pixel_mode,
        "palette_mode": bitmap.palette_mode,
        "palette_is_null": bitmap.palette.is_null()
    })
}

#[derive(Clone, Copy)]
enum BitmapCopyBackend {
    Rust,
    CAbi,
    Wasm,
}

struct BitmapCopySetup {
    source: FT_Bitmap_C,
    source_bytes: Option<Vec<u8>>,
    target: FT_Bitmap_C,
    target_bytes: Option<Vec<u8>>,
    alias: bool,
    null_library: bool,
    null_source: bool,
    null_target: bool,
}

fn bitmap_copy_output(case: &InputCase, backend: BitmapCopyBackend) -> Result<RunOutput, String> {
    let scenario = string_param(&case.inputs.params, "scenario")?;
    let mut setup = bitmap_copy_setup(scenario)?;
    let err = match backend {
        BitmapCopyBackend::Rust => bitmap_copy_rust(&mut setup),
        BitmapCopyBackend::CAbi => bitmap_copy_c_abi(&mut setup),
        BitmapCopyBackend::Wasm => bitmap_copy_wasm(&mut setup),
    };
    if err == FT_Err_Ok {
        Ok(ok(bitmap_copy_json(
            &setup.target,
            bitmap_copy_target_bytes(&setup, backend),
        )))
    } else {
        Ok(error(err))
    }
}

fn bitmap_copy_rust(setup: &mut BitmapCopySetup) -> FT_Error {
    if let Some(bytes) = setup.source_bytes.take() {
        FT_Bitmap_Set_Owned_Buffer(Some(&mut setup.source), bytes);
    }
    if let Some(bytes) = setup.target_bytes.take() {
        FT_Bitmap_Set_Owned_Buffer(Some(&mut setup.target), bytes);
    }
    if setup.alias {
        setup.target = setup.source;
        return FT_Err_Ok;
    }
    let library = FT_Init_FreeType();
    let library = (!setup.null_library).then_some(&library);
    let source = (!setup.null_source).then_some(&setup.source);
    let target = (!setup.null_target).then_some(&mut setup.target);
    FT_Bitmap_Copy(library, source, target)
}

fn bitmap_copy_c_abi(setup: &mut BitmapCopySetup) -> FT_Error {
    let mut source_bytes = setup.source_bytes.take().unwrap_or_default();
    let mut target_bytes = setup.target_bytes.take().unwrap_or_default();
    let mut source = c_abi::FT_Bitmap {
        rows: setup.source.rows,
        width: setup.source.width,
        pitch: setup.source.pitch,
        buffer: if source_bytes.is_empty() {
            ptr::null_mut()
        } else {
            source_bytes.as_mut_ptr()
        },
        num_grays: setup.source.num_grays,
        pixel_mode: setup.source.pixel_mode.into(),
        palette_mode: setup.source.palette_mode,
        palette: setup.source.palette,
    };
    let mut target = c_abi::FT_Bitmap {
        rows: setup.target.rows,
        width: setup.target.width,
        pitch: setup.target.pitch,
        buffer: if target_bytes.is_empty() {
            ptr::null_mut()
        } else {
            target_bytes.as_mut_ptr()
        },
        num_grays: setup.target.num_grays,
        pixel_mode: setup.target.pixel_mode.into(),
        palette_mode: setup.target.palette_mode,
        palette: setup.target.palette,
    };
    let mut library = ptr::null_mut();
    if !setup.null_library {
        let err = c_abi::FT_Init_FreeType(&mut library);
        if err != FT_Err_Ok {
            return err;
        }
    }
    let target_ptr = if setup.null_target {
        ptr::null_mut()
    } else if setup.alias {
        (&mut source) as *mut c_abi::FT_Bitmap
    } else {
        &mut target
    };
    let source_ptr = if setup.null_source {
        ptr::null()
    } else {
        (&source) as *const c_abi::FT_Bitmap
    };
    let err = c_abi::FT_Bitmap_Copy(library, source_ptr, target_ptr);
    if setup.alias {
        target = source;
    }
    setup.target = bitmap_from_c_record(&target);
    if setup.alias {
        FT_Bitmap_Set_Owned_Buffer(Some(&mut setup.target), source_bytes);
    }
    if !library.is_null() {
        c_done_library(library);
    }
    err
}

fn bitmap_copy_wasm(setup: &mut BitmapCopySetup) -> FT_Error {
    let source_bytes = setup.source_bytes.take().unwrap_or_default();
    let mut target_bytes = setup.target_bytes.take().unwrap_or_default();
    let mut source = wasm_abi::FontdoneWasmBitmap {
        rows: setup.source.rows,
        width: setup.source.width,
        pitch: setup.source.pitch,
        buffer: if source_bytes.is_empty() {
            ptr::null()
        } else {
            source_bytes.as_ptr()
        },
        buffer_len: source_bytes.len(),
        num_grays: setup.source.num_grays,
        pixel_mode: setup.source.pixel_mode.into(),
        palette_mode: setup.source.palette_mode,
        palette: setup.source.palette,
    };
    let mut target = wasm_abi::FontdoneWasmBitmap {
        rows: setup.target.rows,
        width: setup.target.width,
        pitch: setup.target.pitch,
        buffer: if target_bytes.is_empty() {
            ptr::null()
        } else {
            target_bytes.as_mut_ptr()
        },
        buffer_len: target_bytes.len(),
        num_grays: setup.target.num_grays,
        pixel_mode: setup.target.pixel_mode.into(),
        palette_mode: setup.target.palette_mode,
        palette: setup.target.palette,
    };
    let target_ptr = if setup.null_target {
        ptr::null_mut()
    } else if setup.alias {
        (&mut source) as *mut wasm_abi::FontdoneWasmBitmap
    } else {
        &mut target
    };
    let source_ptr = if setup.null_source {
        ptr::null()
    } else {
        (&source) as *const wasm_abi::FontdoneWasmBitmap
    };
    let err = wasm_abi::fontdone_wasm_bitmap_copy(
        if setup.null_library { 0 } else { 1 },
        source_ptr,
        target_ptr,
    );
    if setup.alias {
        target = source;
    }
    setup.target = bitmap_from_wasm_record(&target);
    if setup.alias {
        FT_Bitmap_Set_Owned_Buffer(Some(&mut setup.target), source_bytes);
    }
    err
}

fn bitmap_copy_setup(scenario: &str) -> Result<BitmapCopySetup, String> {
    let mut setup = BitmapCopySetup {
        source: bitmap_copy_source_record(4),
        source_bytes: Some((0..12).map(|value| value * 17 + 3).collect()),
        target: FT_Bitmap_C::default(),
        target_bytes: None,
        alias: false,
        null_library: false,
        null_source: false,
        null_target: false,
    };
    match scenario {
        "success_deep_copy_all_public_fields" => setup.source.pitch = -4,
        "success_source_equals_target_noop" => setup.alias = true,
        "success_null_source_buffer" => {
            setup.source.buffer = ptr::null_mut();
            setup.source_bytes = None;
            setup.target.pitch = -1;
        }
        "success_flow_flip" => {
            setup.source.pitch = -4;
            setup.target.pitch = 1;
        }
        "ownership_replaces_target_buffer" => {
            setup.target = dirty_bitmap_record();
            setup.target.pitch = 4;
            setup.target_bytes = Some(vec![0xE5; 12]);
        }
        "error_null_library" => setup.null_library = true,
        "error_null_source" | "error_null_library_or_bitmaps" => setup.null_source = true,
        "error_null_target" => setup.null_target = true,
        other => return Err(format!("unsupported bitmap_copy scenario {other}")),
    }
    Ok(setup)
}

fn bitmap_copy_source_record(pitch: i32) -> FT_Bitmap_C {
    FT_Bitmap_C {
        rows: 3,
        width: 3,
        pitch,
        buffer: ptr::with_exposed_provenance_mut(0x1),
        num_grays: 256,
        pixel_mode: FT_PIXEL_MODE_GRAY as u8,
        palette_mode: 0,
        palette: ptr::null_mut(),
    }
}

fn bitmap_copy_json(bitmap: &FT_Bitmap_C, bytes: Option<Vec<u8>>) -> Value {
    json!({
        "target": bitmap_record_json(bitmap),
        "target_bytes_hash": bytes.as_deref().map(djb2_hash),
        "target_buffer_len": bytes.as_ref().map_or(0, Vec::len),
        "buffer_identity_class": if bitmap.buffer.is_null() { "null" } else { "owned_copy" }
    })
}

fn bitmap_copy_target_bytes(
    setup: &BitmapCopySetup,
    backend: BitmapCopyBackend,
) -> Option<Vec<u8>> {
    match backend {
        BitmapCopyBackend::Rust | BitmapCopyBackend::CAbi | BitmapCopyBackend::Wasm => {
            FT_Bitmap_Owned_Buffer_Bytes(Some(&setup.target))
        }
    }
}

#[derive(Clone, Copy)]
enum BitmapConvertBackend {
    Rust,
    CAbi,
    Wasm,
}

#[derive(Clone, Copy)]
enum BitmapDoneBackend {
    Rust,
    CAbi,
    Wasm,
}

fn bitmap_convert_output(
    case: &InputCase,
    backend: BitmapConvertBackend,
) -> Result<RunOutput, String> {
    let scenario = string_param(&case.inputs.params, "scenario")?;
    let runs = match scenario {
        "success_supported_depths_to_gray" => {
            let modes = [
                ("mono", FT_PIXEL_MODE_MONO),
                ("gray2", FT_PIXEL_MODE_GRAY2),
                ("gray4", FT_PIXEL_MODE_GRAY4),
                ("gray", FT_PIXEL_MODE_GRAY),
                ("lcd", FT_PIXEL_MODE_LCD),
                ("lcd_v", FT_PIXEL_MODE_LCD_V),
                ("bgra", FT_PIXEL_MODE_BGRA),
            ];
            modes
                .into_iter()
                .map(|(label, mode)| bitmap_convert_run(label, mode, false, 0, 1, false, backend))
                .collect::<Result<Vec<_>, _>>()?
        }
        "success_alignment_and_flow" => {
            let mut runs = Vec::new();
            for alignment in [0, 1, 2, 3, 4, -1, -2, -4] {
                runs.push(bitmap_convert_run(
                    &format!("align_{alignment}"),
                    FT_PIXEL_MODE_GRAY,
                    false,
                    0,
                    alignment,
                    false,
                    backend,
                )?);
            }
            runs.push(bitmap_convert_run(
                "negative_source_flow",
                FT_PIXEL_MODE_GRAY,
                true,
                0,
                4,
                false,
                backend,
            )?);
            runs.push(bitmap_convert_run(
                "negative_target_flow",
                FT_PIXEL_MODE_GRAY,
                false,
                -1,
                4,
                false,
                backend,
            )?);
            runs
        }
        "success_repeated_conversion_reallocates" => bitmap_convert_repeated_runs(backend)?,
        "success_empty_or_null_source_buffer" => {
            vec![bitmap_convert_empty_run(backend)?]
        }
        "error_invalid_arguments_or_alignment" => bitmap_convert_error_runs(backend)?,
        "error_unsupported_pixel_mode" => bitmap_convert_unsupported_runs(backend)?,
        other => return Err(format!("unsupported bitmap_convert scenario {other}")),
    };
    let output = json!({ "runs": runs });
    if case.expect_error {
        let first_error = first_nested_error(&output, "runs", "status")?;
        Ok(error_with_output(first_error, output))
    } else {
        Ok(ok(output))
    }
}

fn bitmap_done_output(case: &InputCase, backend: BitmapDoneBackend) -> Result<RunOutput, String> {
    let scenario = string_param(&case.inputs.params, "scenario")?;
    let runs = match scenario {
        "success_frees_and_zeroes_bitmap" => {
            vec![bitmap_done_allocated_run("allocated_bitmap", backend)?]
        }
        "success_empty_bitmap" => vec![bitmap_done_run(
            "empty_bitmap",
            FT_Bitmap_C::default(),
            None,
            false,
            false,
            backend,
        )?],
        "success_repeated_done_after_reinit" => bitmap_done_repeated_runs(backend)?,
        "error_null_library_or_bitmap" => bitmap_done_error_runs(backend)?,
        other => return Err(format!("unsupported bitmap_done scenario {other}")),
    };
    let output = json!({ "runs": runs });
    if case.expect_error {
        let first_error = first_nested_error(&output, "runs", "status")?;
        Ok(error_with_output(first_error, output))
    } else {
        Ok(ok(output))
    }
}

fn first_nested_error(output: &Value, rows_key: &str, status_key: &str) -> Result<i32, String> {
    output
        .get(rows_key)
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|row| {
            row.get(status_key)
                .and_then(|status| status.get("error_code"))
                .and_then(Value::as_i64)
        })
        .find(|error| *error != i64::from(FT_Err_Ok))
        .and_then(|error| i32::try_from(error).ok())
        .ok_or_else(|| format!("expected an error in {rows_key}[].{status_key}"))
}

fn bitmap_convert_repeated_runs(backend: BitmapConvertBackend) -> Result<Vec<Value>, String> {
    match backend {
        BitmapConvertBackend::Rust => {
            let library = FT_Init_FreeType();
            let (mut source, source_bytes) =
                bitmap_convert_source_record(FT_PIXEL_MODE_GRAY2, false);
            FT_Bitmap_Set_Owned_Buffer(Some(&mut source), source_bytes);
            let mut target = FT_Bitmap_C::default();
            let err = FT_Bitmap_Convert(Some(&library), Some(&source), Some(&mut target), 1);
            let first = bitmap_convert_run_json("first_gray2", err, Some(&target));
            let (mut source, source_bytes) =
                bitmap_convert_source_record(FT_PIXEL_MODE_GRAY4, false);
            FT_Bitmap_Set_Owned_Buffer(Some(&mut source), source_bytes);
            let err = FT_Bitmap_Convert(Some(&library), Some(&source), Some(&mut target), 1);
            let second = bitmap_convert_run_json("second_gray4", err, Some(&target));
            FT_Bitmap_Done(Some(&library), Some(&mut target));
            Ok(vec![first, second])
        }
        BitmapConvertBackend::CAbi => {
            let mut library = ptr::null_mut();
            let init_err = c_abi::FT_Init_FreeType(&mut library);
            if init_err != FT_Err_Ok {
                return Ok(vec![bitmap_convert_run_json("first_gray2", init_err, None)]);
            }
            let (source, mut source_bytes) =
                c_bitmap_convert_source_record(FT_PIXEL_MODE_GRAY2, false);
            let mut source = source;
            source.buffer = source_bytes.as_mut_ptr();
            let mut target = c_abi::FT_Bitmap::default();
            let err = c_abi::FT_Bitmap_Convert(library, &source, &mut target, 1);
            let first_target = bitmap_from_c_record(&target);
            let first = bitmap_convert_run_json("first_gray2", err, Some(&first_target));
            let (source, mut source_bytes) =
                c_bitmap_convert_source_record(FT_PIXEL_MODE_GRAY4, false);
            let mut source = source;
            source.buffer = source_bytes.as_mut_ptr();
            let err = c_abi::FT_Bitmap_Convert(library, &source, &mut target, 1);
            let second_target = bitmap_from_c_record(&target);
            let second = bitmap_convert_run_json("second_gray4", err, Some(&second_target));
            let _ = c_abi::FT_Bitmap_Done(library, &mut target);
            c_done_library(library);
            Ok(vec![first, second])
        }
        BitmapConvertBackend::Wasm => {
            let (source, source_bytes) =
                wasm_bitmap_convert_source_record(FT_PIXEL_MODE_GRAY2, false);
            let mut source = source;
            source.buffer = source_bytes.as_ptr();
            source.buffer_len = source_bytes.len();
            let mut target = wasm_abi::FontdoneWasmBitmap::default();
            let err = wasm_abi::fontdone_wasm_bitmap_convert(1, &source, &mut target, 1);
            let first_target = bitmap_from_wasm_record(&target);
            let first = bitmap_convert_run_json("first_gray2", err, Some(&first_target));
            let (source, source_bytes) =
                wasm_bitmap_convert_source_record(FT_PIXEL_MODE_GRAY4, false);
            let mut source = source;
            source.buffer = source_bytes.as_ptr();
            source.buffer_len = source_bytes.len();
            let err = wasm_abi::fontdone_wasm_bitmap_convert(1, &source, &mut target, 1);
            let second_target = bitmap_from_wasm_record(&target);
            let second = bitmap_convert_run_json("second_gray4", err, Some(&second_target));
            let _ = wasm_abi::fontdone_wasm_bitmap_done(1, &mut target);
            Ok(vec![first, second])
        }
    }
}

fn bitmap_convert_empty_run(backend: BitmapConvertBackend) -> Result<Value, String> {
    let source = FT_Bitmap_C {
        pixel_mode: FT_PIXEL_MODE_GRAY as u8,
        width: 5,
        rows: 0,
        pitch: 5,
        ..Default::default()
    };
    bitmap_convert_run_with_records(
        "empty_null_buffer",
        Some((source, None)),
        Some((FT_Bitmap_C::default(), None)),
        4,
        false,
        backend,
    )
}

fn bitmap_convert_error_runs(backend: BitmapConvertBackend) -> Result<Vec<Value>, String> {
    let (source, source_bytes) = bitmap_convert_source_record(FT_PIXEL_MODE_GRAY, false);
    Ok(vec![
        bitmap_convert_run_with_records(
            "null_library",
            Some((source, Some(source_bytes.clone()))),
            Some((dirty_bitmap_record(), Some(dirty_bitmap_bytes()))),
            1,
            true,
            backend,
        )?,
        bitmap_convert_run_with_records(
            "null_source",
            None,
            Some((dirty_bitmap_record(), Some(dirty_bitmap_bytes()))),
            1,
            false,
            backend,
        )?,
        bitmap_convert_run_with_records(
            "null_target",
            Some((source, Some(source_bytes))),
            None,
            1,
            false,
            backend,
        )?,
    ])
}

fn bitmap_convert_unsupported_runs(backend: BitmapConvertBackend) -> Result<Vec<Value>, String> {
    let (mut source, source_bytes) = bitmap_convert_source_record(FT_PIXEL_MODE_GRAY, false);
    source.pixel_mode = FT_PIXEL_MODE_NONE as u8;
    let first = bitmap_convert_run_with_records(
        "pixel_mode_none",
        Some((source, Some(source_bytes.clone()))),
        Some((dirty_bitmap_record(), Some(dirty_bitmap_bytes()))),
        1,
        false,
        backend,
    )?;
    source.pixel_mode = FT_PIXEL_MODE_MAX as u8;
    let second = bitmap_convert_run_with_records(
        "pixel_mode_max",
        Some((source, Some(source_bytes))),
        Some((dirty_bitmap_record(), Some(dirty_bitmap_bytes()))),
        1,
        false,
        backend,
    )?;
    Ok(vec![first, second])
}

fn bitmap_convert_run(
    label: &str,
    pixel_mode: FT_Pixel_Mode,
    negative_source_pitch: bool,
    target_pitch: FT_Int,
    alignment: FT_Int,
    null_library: bool,
    backend: BitmapConvertBackend,
) -> Result<Value, String> {
    let (source, source_bytes) = bitmap_convert_source_record(pixel_mode, negative_source_pitch);
    let target = FT_Bitmap_C {
        pitch: target_pitch,
        ..Default::default()
    };
    bitmap_convert_run_with_records(
        label,
        Some((source, Some(source_bytes))),
        Some((target, None)),
        alignment,
        null_library,
        backend,
    )
}

fn bitmap_convert_run_with_records(
    label: &str,
    source: Option<(FT_Bitmap_C, Option<Vec<u8>>)>,
    target: Option<(FT_Bitmap_C, Option<Vec<u8>>)>,
    alignment: FT_Int,
    null_library: bool,
    backend: BitmapConvertBackend,
) -> Result<Value, String> {
    let (err, target) = match backend {
        BitmapConvertBackend::Rust => bitmap_convert_rust(source, target, alignment, null_library),
        BitmapConvertBackend::CAbi => bitmap_convert_c_abi(source, target, alignment, null_library),
        BitmapConvertBackend::Wasm => bitmap_convert_wasm(source, target, alignment, null_library),
    }?;
    Ok(bitmap_convert_run_json(label, err, target.as_ref()))
}

fn bitmap_convert_rust(
    source: Option<(FT_Bitmap_C, Option<Vec<u8>>)>,
    target: Option<(FT_Bitmap_C, Option<Vec<u8>>)>,
    alignment: FT_Int,
    null_library: bool,
) -> Result<(FT_Error, Option<FT_Bitmap_C>), String> {
    let library = FT_Init_FreeType();
    let library = (!null_library).then_some(&library);
    let source_record;
    let source_ref = if let Some((mut record, bytes)) = source {
        if let Some(bytes) = bytes {
            FT_Bitmap_Set_Owned_Buffer(Some(&mut record), bytes);
        }
        source_record = record;
        Some(&source_record)
    } else {
        None
    };
    let mut target_record;
    let err = if let Some((mut record, bytes)) = target {
        if let Some(bytes) = bytes {
            FT_Bitmap_Set_Owned_Buffer(Some(&mut record), bytes);
        }
        target_record = record;
        FT_Bitmap_Convert(library, source_ref, Some(&mut target_record), alignment)
    } else {
        return Ok((
            FT_Bitmap_Convert(library, source_ref, None, alignment),
            None,
        ));
    };
    Ok((err, Some(target_record)))
}

fn bitmap_convert_c_abi(
    source: Option<(FT_Bitmap_C, Option<Vec<u8>>)>,
    target: Option<(FT_Bitmap_C, Option<Vec<u8>>)>,
    alignment: FT_Int,
    null_library: bool,
) -> Result<(FT_Error, Option<FT_Bitmap_C>), String> {
    let mut library = ptr::null_mut();
    if !null_library {
        let err = c_abi::FT_Init_FreeType(&mut library);
        if err != FT_Err_Ok {
            return Ok((err, None));
        }
    }
    let source_storage = source.map(|(record, bytes)| {
        let mut source_bytes = bytes.unwrap_or_default();
        let mut record = c_bitmap_from_rust_record(&record);
        record.buffer = if source_bytes.is_empty() {
            ptr::null_mut()
        } else {
            source_bytes.as_mut_ptr()
        };
        (record, source_bytes)
    });
    let source_ptr = source_storage
        .as_ref()
        .map_or(ptr::null(), |(record, _)| record as *const c_abi::FT_Bitmap);

    let mut target_storage = target.map(|(record, bytes)| {
        let mut target_bytes = bytes.unwrap_or_default();
        let mut c_record = c_bitmap_from_rust_record(&record);
        c_record.buffer = if target_bytes.is_empty() {
            record.buffer
        } else {
            target_bytes.as_mut_ptr()
        };
        (c_record, target_bytes)
    });
    let target_ptr = target_storage
        .as_mut()
        .map_or(ptr::null_mut(), |(record, _)| {
            record as *mut c_abi::FT_Bitmap
        });
    let err = c_abi::FT_Bitmap_Convert(library, source_ptr, target_ptr, alignment);
    let output = target_storage
        .as_ref()
        .map(|(record, _)| bitmap_from_c_record(record));
    if !library.is_null() {
        c_done_library(library);
    }
    Ok((err, output))
}

fn bitmap_convert_wasm(
    source: Option<(FT_Bitmap_C, Option<Vec<u8>>)>,
    target: Option<(FT_Bitmap_C, Option<Vec<u8>>)>,
    alignment: FT_Int,
    null_library: bool,
) -> Result<(FT_Error, Option<FT_Bitmap_C>), String> {
    let source_storage = source.map(|(record, bytes)| {
        let source_bytes = bytes.unwrap_or_default();
        let source_record = wasm_bitmap_from_rust_record(&record, &source_bytes);
        (source_record, source_bytes)
    });
    let source_ptr = source_storage.as_ref().map_or(ptr::null(), |(record, _)| {
        record as *const wasm_abi::FontdoneWasmBitmap
    });

    let mut target_storage = target.map(|(record, bytes)| {
        let target_bytes = bytes.unwrap_or_default();
        let mut wasm_record = wasm_bitmap_from_rust_record(&record, &target_bytes);
        if target_bytes.is_empty() {
            wasm_record.buffer = record.buffer;
        }
        (wasm_record, target_bytes)
    });
    let target_ptr = target_storage
        .as_mut()
        .map_or(ptr::null_mut(), |(record, _)| {
            record as *mut wasm_abi::FontdoneWasmBitmap
        });
    let err = wasm_abi::fontdone_wasm_bitmap_convert(
        if null_library { 0 } else { 1 },
        source_ptr,
        target_ptr,
        alignment,
    );
    let output = target_storage
        .as_ref()
        .map(|(record, _)| bitmap_from_wasm_record(record));
    Ok((err, output))
}

fn bitmap_done_allocated_run(label: &str, backend: BitmapDoneBackend) -> Result<Value, String> {
    let (mut bitmap, bytes) = bitmap_convert_source_record(FT_PIXEL_MODE_GRAY, false);
    bitmap.pixel_mode = FT_PIXEL_MODE_GRAY as u8;
    bitmap_done_from_converted_source(label, bitmap, bytes, backend)
}

fn bitmap_done_from_converted_source(
    label: &str,
    source: FT_Bitmap_C,
    source_bytes: Vec<u8>,
    backend: BitmapDoneBackend,
) -> Result<Value, String> {
    match backend {
        BitmapDoneBackend::Rust => {
            let library = FT_Init_FreeType();
            let mut source = source;
            FT_Bitmap_Set_Owned_Buffer(Some(&mut source), source_bytes);
            let mut bitmap = FT_Bitmap_C::default();
            let convert_err =
                FT_Bitmap_Convert(Some(&library), Some(&source), Some(&mut bitmap), 1);
            if convert_err != FT_Err_Ok {
                return Ok(bitmap_convert_run_json(label, convert_err, Some(&bitmap)));
            }
            let err = FT_Bitmap_Done(Some(&library), Some(&mut bitmap));
            Ok(bitmap_convert_run_json(label, err, Some(&bitmap)))
        }
        BitmapDoneBackend::CAbi => {
            let mut library = ptr::null_mut();
            let init_err = c_abi::FT_Init_FreeType(&mut library);
            if init_err != FT_Err_Ok {
                return Ok(bitmap_convert_run_json(label, init_err, None));
            }
            let mut source_bytes = source_bytes;
            let mut c_source = c_bitmap_from_rust_record(&source);
            c_source.buffer = source_bytes.as_mut_ptr();
            let mut bitmap = c_abi::FT_Bitmap::default();
            let convert_err = c_abi::FT_Bitmap_Convert(library, &c_source, &mut bitmap, 1);
            if convert_err != FT_Err_Ok {
                let output = bitmap_from_c_record(&bitmap);
                c_done_library(library);
                return Ok(bitmap_convert_run_json(label, convert_err, Some(&output)));
            }
            let err = c_abi::FT_Bitmap_Done(library, &mut bitmap);
            let output = bitmap_from_c_record(&bitmap);
            c_done_library(library);
            Ok(bitmap_convert_run_json(label, err, Some(&output)))
        }
        BitmapDoneBackend::Wasm => {
            let mut wasm_source = wasm_bitmap_from_rust_record(&source, &source_bytes);
            wasm_source.buffer = source_bytes.as_ptr();
            wasm_source.buffer_len = source_bytes.len();
            let mut bitmap = wasm_abi::FontdoneWasmBitmap::default();
            let convert_err =
                wasm_abi::fontdone_wasm_bitmap_convert(1, &wasm_source, &mut bitmap, 1);
            if convert_err != FT_Err_Ok {
                let output = bitmap_from_wasm_record(&bitmap);
                return Ok(bitmap_convert_run_json(label, convert_err, Some(&output)));
            }
            let err = wasm_abi::fontdone_wasm_bitmap_done(1, &mut bitmap);
            let output = bitmap_from_wasm_record(&bitmap);
            Ok(bitmap_convert_run_json(label, err, Some(&output)))
        }
    }
}

fn bitmap_done_run(
    label: &str,
    bitmap: FT_Bitmap_C,
    bytes: Option<Vec<u8>>,
    null_library: bool,
    null_bitmap: bool,
    backend: BitmapDoneBackend,
) -> Result<Value, String> {
    let (err, bitmap) = match backend {
        BitmapDoneBackend::Rust => {
            let library = FT_Init_FreeType();
            let library = (!null_library).then_some(&library);
            let mut bitmap = bitmap;
            if let Some(bytes) = bytes {
                FT_Bitmap_Set_Owned_Buffer(Some(&mut bitmap), bytes);
            }
            if null_bitmap {
                (FT_Bitmap_Done(library, None), None)
            } else {
                let err = FT_Bitmap_Done(library, Some(&mut bitmap));
                (err, Some(bitmap))
            }
        }
        BitmapDoneBackend::CAbi => {
            let mut library = ptr::null_mut();
            if !null_library {
                let init_err = c_abi::FT_Init_FreeType(&mut library);
                if init_err != FT_Err_Ok {
                    return Ok(bitmap_convert_run_json(label, init_err, None));
                }
            }
            let mut bytes = bytes.unwrap_or_default();
            let mut c_bitmap = c_bitmap_from_rust_record(&bitmap);
            c_bitmap.buffer = if bytes.is_empty() {
                bitmap.buffer
            } else {
                bytes.as_mut_ptr()
            };
            let bitmap_ptr = if null_bitmap {
                ptr::null_mut()
            } else {
                &mut c_bitmap
            };
            let err = c_abi::FT_Bitmap_Done(library, bitmap_ptr);
            let output = (!null_bitmap).then(|| bitmap_from_c_record(&c_bitmap));
            if !library.is_null() {
                c_done_library(library);
            }
            (err, output)
        }
        BitmapDoneBackend::Wasm => {
            let bytes = bytes.unwrap_or_default();
            let mut wasm_bitmap = wasm_bitmap_from_rust_record(&bitmap, &bytes);
            if bytes.is_empty() {
                wasm_bitmap.buffer = bitmap.buffer;
            }
            let bitmap_ptr = if null_bitmap {
                ptr::null_mut()
            } else {
                &mut wasm_bitmap
            };
            let err =
                wasm_abi::fontdone_wasm_bitmap_done(if null_library { 0 } else { 1 }, bitmap_ptr);
            let output = (!null_bitmap).then(|| bitmap_from_wasm_record(&wasm_bitmap));
            (err, output)
        }
    };
    Ok(bitmap_convert_run_json(label, err, bitmap.as_ref()))
}

fn bitmap_done_repeated_runs(backend: BitmapDoneBackend) -> Result<Vec<Value>, String> {
    let (source, source_bytes) = bitmap_convert_source_record(FT_PIXEL_MODE_GRAY2, false);
    let first = bitmap_done_from_converted_source("first_done", source, source_bytes, backend)?;
    let (source, source_bytes) = bitmap_convert_source_record(FT_PIXEL_MODE_GRAY4, false);
    let second = bitmap_done_from_converted_source("second_done", source, source_bytes, backend)?;
    Ok(vec![first, second])
}

fn bitmap_done_error_runs(backend: BitmapDoneBackend) -> Result<Vec<Value>, String> {
    let (source, source_bytes) = bitmap_convert_source_record(FT_PIXEL_MODE_GRAY, false);
    let null_library = match backend {
        BitmapDoneBackend::Rust => {
            let library = FT_Init_FreeType();
            let mut source = source;
            FT_Bitmap_Set_Owned_Buffer(Some(&mut source), source_bytes.clone());
            let mut bitmap = FT_Bitmap_C::default();
            let _ = FT_Bitmap_Convert(Some(&library), Some(&source), Some(&mut bitmap), 1);
            let err = FT_Bitmap_Done(None, Some(&mut bitmap));
            let run = bitmap_convert_run_json("null_library", err, Some(&bitmap));
            let _ = FT_Bitmap_Done(Some(&library), Some(&mut bitmap));
            run
        }
        BitmapDoneBackend::CAbi => {
            let mut library = ptr::null_mut();
            let _ = c_abi::FT_Init_FreeType(&mut library);
            let mut source_bytes = source_bytes.clone();
            let mut c_source = c_bitmap_from_rust_record(&source);
            c_source.buffer = source_bytes.as_mut_ptr();
            let mut bitmap = c_abi::FT_Bitmap::default();
            let _ = c_abi::FT_Bitmap_Convert(library, &c_source, &mut bitmap, 1);
            let err = c_abi::FT_Bitmap_Done(ptr::null_mut(), &mut bitmap);
            let output = bitmap_from_c_record(&bitmap);
            let _ = c_abi::FT_Bitmap_Done(library, &mut bitmap);
            c_done_library(library);
            bitmap_convert_run_json("null_library", err, Some(&output))
        }
        BitmapDoneBackend::Wasm => {
            let mut wasm_source = wasm_bitmap_from_rust_record(&source, &source_bytes);
            wasm_source.buffer = source_bytes.as_ptr();
            wasm_source.buffer_len = source_bytes.len();
            let mut bitmap = wasm_abi::FontdoneWasmBitmap::default();
            let _ = wasm_abi::fontdone_wasm_bitmap_convert(1, &wasm_source, &mut bitmap, 1);
            let err = wasm_abi::fontdone_wasm_bitmap_done(0, &mut bitmap);
            let output = bitmap_from_wasm_record(&bitmap);
            let _ = wasm_abi::fontdone_wasm_bitmap_done(1, &mut bitmap);
            bitmap_convert_run_json("null_library", err, Some(&output))
        }
    };
    let null_bitmap = bitmap_done_run(
        "null_bitmap",
        FT_Bitmap_C::default(),
        None,
        false,
        true,
        backend,
    )?;
    Ok(vec![null_library, null_bitmap])
}

fn bitmap_convert_run_json(label: &str, err: FT_Error, target: Option<&FT_Bitmap_C>) -> Value {
    json!({
        "label": label,
        "status": {
            "kind": if err == FT_Err_Ok { "ok" } else { "error" },
            "error_code": err
        },
        "target": target.map(bitmap_record_json),
        "target_active_bytes_hash": if err == FT_Err_Ok {
            target.and_then(bitmap_active_bytes).as_deref().map(djb2_hash)
        } else {
            None
        },
        "target_buffer_len": target.and_then(bitmap_buffer_len).unwrap_or(0)
    })
}

fn bitmap_active_bytes(bitmap: &FT_Bitmap_C) -> Option<Vec<u8>> {
    let bytes = FT_Bitmap_Owned_Buffer_Bytes(Some(bitmap))?;
    let pitch = usize::try_from(bitmap.pitch.unsigned_abs()).ok()?;
    let rows = usize::try_from(bitmap.rows).ok()?;
    let width = usize::try_from(bitmap.width).ok()?;
    let mut active = Vec::with_capacity(width.checked_mul(rows)?);
    let start = if bitmap.pitch < 0 {
        rows.saturating_sub(1).checked_mul(pitch)?
    } else {
        0
    };
    for row in 0..rows {
        let offset = if bitmap.pitch < 0 {
            start.checked_sub(row.checked_mul(pitch)?)?
        } else {
            start.checked_add(row.checked_mul(pitch)?)?
        };
        active.extend_from_slice(bytes.get(offset..offset.checked_add(width)?)?);
    }
    Some(active)
}

fn bitmap_buffer_len(bitmap: &FT_Bitmap_C) -> Option<usize> {
    usize::try_from(bitmap.pitch.unsigned_abs())
        .ok()?
        .checked_mul(usize::try_from(bitmap.rows).ok()?)
}

fn dirty_bitmap_bytes() -> Vec<u8> {
    vec![0xE5; 77]
}

fn bitmap_convert_source_record(
    pixel_mode: FT_Pixel_Mode,
    negative_pitch: bool,
) -> (FT_Bitmap_C, Vec<u8>) {
    let rows = 3;
    let width = if pixel_mode == FT_PIXEL_MODE_BGRA {
        4
    } else {
        9
    };
    let pitch_abs = match pixel_mode {
        FT_PIXEL_MODE_MONO => 2,
        FT_PIXEL_MODE_GRAY2 => 3,
        FT_PIXEL_MODE_GRAY4 => 5,
        FT_PIXEL_MODE_BGRA => 16,
        _ => width,
    };
    let len = usize::try_from(pitch_abs * rows).unwrap_or(0);
    let bytes = (0..len)
        .map(|i| {
            (i as u8)
                .wrapping_mul(37)
                .wrapping_add((pixel_mode as u8).wrapping_mul(11))
                .wrapping_add(5)
        })
        .collect();
    (
        FT_Bitmap_C {
            rows: rows as u32,
            width: width as u32,
            pitch: if negative_pitch {
                -pitch_abs
            } else {
                pitch_abs
            },
            buffer: ptr::with_exposed_provenance_mut(0x1),
            num_grays: match pixel_mode {
                FT_PIXEL_MODE_MONO => 2,
                FT_PIXEL_MODE_GRAY2 => 4,
                FT_PIXEL_MODE_GRAY4 => 16,
                _ => 256,
            },
            pixel_mode: pixel_mode as u8,
            palette_mode: 0,
            palette: ptr::null_mut(),
        },
        bytes,
    )
}

fn c_bitmap_convert_source_record(
    pixel_mode: FT_Pixel_Mode,
    negative_pitch: bool,
) -> (c_abi::FT_Bitmap, Vec<u8>) {
    let (bitmap, bytes) = bitmap_convert_source_record(pixel_mode, negative_pitch);
    (c_bitmap_from_rust_record(&bitmap), bytes)
}

fn wasm_bitmap_convert_source_record(
    pixel_mode: FT_Pixel_Mode,
    negative_pitch: bool,
) -> (wasm_abi::FontdoneWasmBitmap, Vec<u8>) {
    let (bitmap, bytes) = bitmap_convert_source_record(pixel_mode, negative_pitch);
    (wasm_bitmap_from_rust_record(&bitmap, &bytes), bytes)
}

fn c_bitmap_from_rust_record(bitmap: &FT_Bitmap_C) -> c_abi::FT_Bitmap {
    c_abi::FT_Bitmap {
        rows: bitmap.rows,
        width: bitmap.width,
        pitch: bitmap.pitch,
        buffer: bitmap.buffer,
        num_grays: bitmap.num_grays,
        pixel_mode: bitmap.pixel_mode.into(),
        palette_mode: bitmap.palette_mode,
        palette: bitmap.palette,
    }
}

fn wasm_bitmap_from_rust_record(
    bitmap: &FT_Bitmap_C,
    bytes: &[u8],
) -> wasm_abi::FontdoneWasmBitmap {
    wasm_abi::FontdoneWasmBitmap {
        rows: bitmap.rows,
        width: bitmap.width,
        pitch: bitmap.pitch,
        buffer: if bytes.is_empty() {
            bitmap.buffer
        } else {
            bytes.as_ptr()
        },
        buffer_len: bytes.len(),
        num_grays: bitmap.num_grays,
        pixel_mode: bitmap.pixel_mode.into(),
        palette_mode: bitmap.palette_mode,
        palette: bitmap.palette,
    }
}

fn glyphslot_own_bitmap_rust(case: &InputCase) -> Result<RunOutput, String> {
    let scenario = string_param(&case.inputs.params, "scenario")?;
    if scenario == "error_copy_allocation_failure" {
        return glyphslot_own_bitmap_allocation_failure_rust(case);
    }
    if scenario == "success_non_bitmap_or_null_slot_noop" {
        let null_err = FT_GlyphSlot_Own_Bitmap(None);
        if null_err != FT_Err_Ok {
            return Ok(error(null_err));
        }
        let mut slot = rust_glyphslot_own_load(case, false)?;
        let err = FT_GlyphSlot_Own_Bitmap(Some(&mut slot));
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        return Ok(ok(glyphslot_own_non_bitmap_json(
            slot_json(&slot),
            slot.owns_bitmap,
        )));
    }

    let mut slot = rust_glyphslot_own_load(case, true)?;
    match scenario {
        "success_borrowed_bitmap_copied_and_flagged" => slot.owns_bitmap = false,
        "success_already_owned_noop" => slot.owns_bitmap = true,
        other => return Err(format!("unsupported glyphslot_own_bitmap scenario {other}")),
    }
    let err = FT_GlyphSlot_Own_Bitmap(Some(&mut slot));
    if err == FT_Err_Ok {
        Ok(ok(glyphslot_own_bitmap_json(
            err,
            slot_json(&slot),
            slot.owns_bitmap,
            glyphslot_own_identity_for_scenario(scenario),
        )))
    } else {
        Ok(error(err))
    }
}

fn glyphslot_own_bitmap_c_abi(case: &InputCase) -> Result<RunOutput, String> {
    let scenario = string_param(&case.inputs.params, "scenario")?;
    if scenario == "error_copy_allocation_failure" {
        return glyphslot_own_bitmap_allocation_failure_c_abi(case);
    }
    if scenario == "success_non_bitmap_or_null_slot_noop" {
        let null_err = c_abi::FT_GlyphSlot_Own_Bitmap(ptr::null_mut());
        if null_err != FT_Err_Ok {
            return Ok(error(null_err));
        }
        let (library, face) = c_glyphslot_own_load(case, false)?;
        let err = c_abi::abi_glyphslot_own_bitmap_from_face(face);
        let slot = c_glyphslot_own_slot_json(face)?;
        c_done_face(face);
        c_done_library(library);
        if err != FT_Err_Ok {
            return Ok(error(err));
        }
        return Ok(ok(glyphslot_own_non_bitmap_json(slot, false)));
    }

    let (library, face) = c_glyphslot_own_load(case, true)?;
    let owns_before = match scenario {
        "success_borrowed_bitmap_copied_and_flagged" => false,
        "success_already_owned_noop" => true,
        other => {
            c_done_face(face);
            c_done_library(library);
            return Err(format!("unsupported glyphslot_own_bitmap scenario {other}"));
        }
    };
    let set_err = c_abi::abi_glyphslot_set_own_bitmap_from_face(face, owns_before);
    let err = if set_err == FT_Err_Ok {
        c_abi::abi_glyphslot_own_bitmap_from_face(face)
    } else {
        set_err
    };
    let slot = c_glyphslot_own_slot_json(face)?;
    let owns_after = c_glyphslot_own_flag(face)?;
    c_done_face(face);
    c_done_library(library);
    if err == FT_Err_Ok {
        Ok(ok(glyphslot_own_bitmap_json(
            err,
            slot,
            owns_after,
            glyphslot_own_identity_for_scenario(scenario),
        )))
    } else {
        Ok(error(err))
    }
}

